import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String PASSWORD = "bench";

    private static ChainBuilder refreshCsrf() {
        return exec(session -> {
            if (session.contains("csrf_resp")) {
                Object v = session.get("csrf_resp");
                if (v != null && !v.toString().isEmpty()) {
                    return session.set("csrf", v.toString()).remove("csrf_resp");
                }
                return session.remove("csrf_resp");
            }
            return session;
        });
    }

    private static ChainBuilder clearCsrf() {
        return exec(session -> session.remove("csrf_resp"));
    }

    public ModelSimulation() {
        String envBase = System.getenv("BASE_URL");
        final String base = (envBase == null || envBase.isEmpty()) ? "http://127.0.0.1:8000" : envBase;

        HttpProtocolBuilder httpProtocol = http.baseUrl(base);

        ChainBuilder journey = exec(session -> session
                .set("username", "bench-" + session.userId())
                .remove("csrf").remove("csrf_resp")
                .remove("login_location").remove("login_csrf")
                .remove("product_id").remove("variant_id")
                .remove("p0id").remove("p0v").remove("p1id").remove("p1v")
                .remove("p2id").remove("p2v").remove("p3id").remove("p3v")
                .remove("p4id").remove("p4v")
                .remove("challenge_action").remove("challenge").remove("challenge_location")
                .remove("grant_id").remove("cart_id").remove("cart_etag")
                .remove("status_url").remove("poll_status").remove("rid_raw")
                .remove("reservation_id").remove("order_id")
                .remove("csrf_json").remove("csrf_html"))
            .exec(http("login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(css("input[type=hidden][name=csrf]", "value").saveAs("login_csrf")))
            .exec(http("login")
                    .post("/v2/login")
                    .disableFollowRedirect()
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"" + PASSWORD + "\",\"csrf\":\"#{login_csrf}\"}"))
                    .asJson()
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("login_location"))
                    .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf_resp")))
            .exec(refreshCsrf())
            .doIf(session -> !session.contains("csrf")
                    && session.contains("login_location")
                    && session.get("login_location") != null
                    && !session.get("login_location").toString().isEmpty())
            .then(
                    exec(http("login-redirect")
                            .get("#{login_location}")
                            .check(status().is(200))
                            .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf_json"))
                            .check(regex("name=\"csrf\"[^>]*value=\"([^\"]+)\"").optional().saveAs("csrf_html")))
                    .exec(session -> {
                        String csrf = null;
                        if (session.contains("csrf_json") && session.get("csrf_json") != null) {
                            String v = session.get("csrf_json").toString();
                            if (!v.isEmpty()) csrf = v;
                        }
                        if (csrf == null && session.contains("csrf_html") && session.get("csrf_html") != null) {
                            String v = session.get("csrf_html").toString();
                            if (!v.isEmpty()) csrf = v;
                        }
                        session = session.remove("csrf_json").remove("csrf_html");
                        return csrf != null ? session.set("csrf", csrf) : session;
                    })
            )
            .exec(http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[0].id").optional().saveAs("p0id"))
                    .check(jsonPath("$.data.products[0].variants[?(@.in_stock == true)][0].id").optional().saveAs("p0v"))
                    .check(jsonPath("$.data.products[1].id").optional().saveAs("p1id"))
                    .check(jsonPath("$.data.products[1].variants[?(@.in_stock == true)][0].id").optional().saveAs("p1v"))
                    .check(jsonPath("$.data.products[2].id").optional().saveAs("p2id"))
                    .check(jsonPath("$.data.products[2].variants[?(@.in_stock == true)][0].id").optional().saveAs("p2v"))
                    .check(jsonPath("$.data.products[3].id").optional().saveAs("p3id"))
                    .check(jsonPath("$.data.products[3].variants[?(@.in_stock == true)][0].id").optional().saveAs("p3v"))
                    .check(jsonPath("$.data.products[4].id").optional().saveAs("p4id"))
                    .check(jsonPath("$.data.products[4].variants[?(@.in_stock == true)][0].id").optional().saveAs("p4v")))
            .exec(session -> {
                String[][] slots = {{"p0id","p0v"},{"p1id","p1v"},{"p2id","p2v"},{"p3id","p3v"},{"p4id","p4v"}};
                for (String[] s : slots) {
                    if (session.contains(s[1])) {
                        Object v = session.get(s[1]);
                        if (v != null && !v.toString().isEmpty() && session.contains(s[0])) {
                            Object pid = session.get(s[0]);
                            if (pid != null) {
                                return session.set("product_id", pid).set("variant_id", v);
                            }
                        }
                    }
                }
                return session;
            })
            .exec(http("challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().is(200))
                    .check(css("form[action*='challenges']", "action").saveAs("challenge_action"))
                    .check(css("input[name=challenge]", "value").saveAs("challenge")))
            .exec(http("challenge-submit")
                    .post("#{challenge_action}")
                    .disableFollowRedirect()
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"challenge\":\"#{challenge}\"}"))
                    .asJson()
                    .check(status().is(302))
                    .check(header("Location").saveAs("challenge_location")))
            .exec(clearCsrf())
