                    .check(status().is(200))
                    .check(jsonPath("$.grant_id").saveAs("grant_id"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf_resp")))
            .exec(refreshCsrf())
            .exec(clearCsrf())
