import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function safeJson(body) {
  try {
    return body ? JSON.parse(body) : null;
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const wanted = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === wanted) return res.headers[k];
  }
  return null;
}

function getError(res) {
  const j = safeJson(res.body);
  if (j && typeof j.error === 'string') return j.error;
  return null;
}

function htmlDecode(s) {
  return String(s)
    .replace(/&quot;/g, '"')
    .replace(/&#x27;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function attrValueFromTag(tag, name) {
  const re = new RegExp(
    "(?:^|\\s)" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+))",
    'i'
  );
  const m = tag.match(re);
  if (!m) return null;
  const v = m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
  return htmlDecode(v);
}

function extractInputValue(html, name, preferHidden) {
  let fallback = null;

  try {
    const doc = parseHTML(html);
    const inputs = doc.find('input');
    for (let i = 0; i < inputs.size(); i++) {
      const el = inputs.get(i);
      const n = el.attr('name');
      if (!n || n.toLowerCase() !== name.toLowerCase()) continue;
      const type = (el.attr('type') || '').toLowerCase();
      const val = el.attr('value');
      if (val === undefined || val === null) continue;

      if (preferHidden && type === 'hidden') return val;
      if (preferHidden) {
        if (fallback === null) fallback = val;
      } else {
        return val;
      }
    }
    if (preferHidden && fallback !== null) return fallback;
  } catch (e) {
    // fall through to regex extraction
  }

  const tags = html.match(/<input\b[^>]*>/gi) || [];
  fallback = null;
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    const n = attrValueFromTag(tag, 'name');
    if (!n || n.toLowerCase() !== name.toLowerCase()) continue;
    const type = (attrValueFromTag(tag, 'type') || '').toLowerCase();
    const val = attrValueFromTag(tag, 'value');
    if (val === null) continue;

    if (preferHidden && type === 'hidden') return val;
    if (preferHidden) {
      if (fallback === null) fallback = val;
    } else {
      return val;
    }
  }

  return preferHidden ? fallback : null;
}

function extractLoginCsrf(html) {
  const forms = html.match(/<form\b[^>]*>[\s\S]*?<\/form>/gi) || [];
  let any = null;

  for (let i = 0; i < forms.length; i++) {
    const form = forms[i];
    const v = extractInputValue(form, 'csrf', true);
    if (!v) continue;

    const open = form.match(/^<form\b[^>]*>/i);
    const action = open ? (attrValueFromTag(open[0], 'action') || '') : '';
    const lowerAction = action.toLowerCase();
    if (lowerAction.indexOf('/v2/login') >= 0 || lowerAction.indexOf('login') >= 0) {
      return v;
    }
    if (any === null) any = v;
  }

  if (any !== null) return any;
  return extractInputValue(html, 'csrf', true);
}

function extractChallengeForm(html) {
  let action = null;
  const formTags = html.match(/<form\b[^>]*>/gi) || [];

  for (let i = 0; i < formTags.length; i++) {
    const a = attrValueFromTag(formTags[i], 'action');
    if (a && a.indexOf('/v2/challenges/') >= 0) {
      action = a;
      break;
    }
  }

  if (!action) {
    const m = html.match(
      /action\s*=\s*(?:"([^"]*\/v2\/challenges\/[^"]*)"|'([^']*\/v2\/challenges\/[^']*)'|([^\s>]*\/v2\/challenges\/[^\s>]*))/i
    );
    if (m) action = htmlDecode(m[1] || m[2] || m[3]);
  }

  const challenge = extractInputValue(html, 'challenge', true);
  return { action: action, challenge: challenge };
}

function resolveUrl(baseUrl, loc) {
  if (!loc) return loc;
  if (/^https?:\/\//i.test(loc)) return loc;

  try {
    return new URL(loc, baseUrl).toString();
  } catch (e) {
    // fall through to simple resolution
  }

  const originMatch = baseUrl.match(/^https?:\/\/[^\/]+/);
  const origin = originMatch ? originMatch[0] : BASE;

  if (loc.charAt(0) === '/') return origin + loc;

  let path = baseUrl.replace(/^https?:\/\/[^\/]+/, '').split('?')[0].split('#')[0];
  path = path.substring(0, path.lastIndexOf('/') + 1);
  return origin + path + loc;
}

function rawRequest(method, url, body, params, csrf) {
  const p = Object.assign({}, params || {});
  p.headers = Object.assign({}, p.headers || {});
  if (csrf) p.headers['X-CSRF-Token'] = csrf;
  if (p.redirects === undefined) p.redirects = 0;

  if (method === 'GET') return http.get(url, p);
  if (method === 'POST') return http.post(url, body, p);
  if (method === 'PATCH') return http.patch(url, body, p);
  throw new Error('unsupported method ' + method);
}

function captureCsrf(state, res) {
  if (!res || res.status >= 400) return;
  const j = safeJson(res.body);
  if (j && typeof j.csrf === 'string' && j.csrf) state.csrf = j.csrf;
}

function performLogin(state) {
  let res = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login-form' },
  });

  if (res.status !== 200) {
    return { ok: false, res: res, loginCsrf: null };
  }

  const loginCsrf = extractLoginCsrf(res.body);
  if (!loginCsrf) {
    return { ok: false, res: res, loginCsrf: null };
  }

  let loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({
      username: state.username,
      password: state.password,
      csrf: loginCsrf,
    }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    if (!loc) {
      return { ok: false, res: loginRes, loginCsrf: loginCsrf };
    }
    const locUrl = resolveUrl(BASE + '/v2/login', loc);
    loginRes = http.get(locUrl, {
      redirects: 0,
      tags: { name: 'login-redirect' },
    });
  }

  const j = safeJson(loginRes.body) || {};
  if (j.csrf) {
    state.csrf = j.csrf;
  } else if (loginCsrf) {
    state.csrf = loginCsrf;
  }

  return {
    ok: loginRes.status === 200 && !!state.csrf,
    res: loginRes,
    loginCsrf: loginCsrf,
  };
}

function freshLogin(state) {
  try {
    http.cookieJar().clear(BASE);
  } catch (e) {}
  try {
    http.cookieJar().clear(BASE + '/');
  } catch (e) {}

  const lr = performLogin(state);
  return lr.ok;
}

function recoverExpired(state, cartId) {
  const renew = rawRequest(
    'POST',
    BASE + '/v2/session/renew',
    JSON.stringify({}),
    { headers: { 'Content-Type': 'application/json' } },
    state.csrf
  );
  captureCsrf(state, renew);

  if (renew.status < 200 || renew.status >= 300) return false;

  if (cartId) {
    const rec = rawRequest(
      'POST',
      BASE + '/v2/carts/' + cartId + '/recover',
      JSON.stringify({}),
      { headers: { 'Content-Type': 'application/json' } },
      state.csrf
    );
    captureCsrf(state, rec);
    if (rec.status < 200 || rec.status >= 300) return false;
  }

  return true;
}

function recoverSession(state, cartId) {
  if (!freshLogin(state)) return false;

  if (cartId) {
    const rec = rawRequest(
      'POST',
      BASE + '/v2/carts/' + cartId + '/recover',
      JSON.stringify({}),
      { headers: { 'Content-Type': 'application/json' } },
      state.csrf
    );
    captureCsrf(state, rec);
    if (rec.status < 200 || rec.status >= 300) return false;
  }

  return true;
}

function authedRequest(state, method, url, body, params, cartId) {
  const nonGet = method !== 'GET';
  let res = rawRequest(method, url, body, params, nonGet ? state.csrf : null);
  captureCsrf(state, res);

  if (res.status === 401) {
    const err = getError(res);

    if (err === 'expired') {
      if (recoverExpired(state, cartId)) {
        res = rawRequest(method, url, body, params, nonGet ? state.csrf : null);
        captureCsrf(state, res);
      }
    } else if (err === 'session') {
      if (recoverSession(state, cartId)) {
        res = rawRequest(method, url, body, params, nonGet ? state.csrf : null);
        captureCsrf(state, res);
      }
    }
  }

  return res;
}

function extractProducts(j) {
  if (!j) return [];
  if (j.data && Array.isArray(j.data.products)) return j.data.products;
  if (Array.isArray(j.products)) return j.products;
  if (j.data && j.data.product) return [j.data.product];
  if (j.data && j.data.id && j.data.variants) return [j.data];
  if (j.product) return [j.product];
  return [];
}

function pickVariant(product) {
  if (!product || !Array.isArray(product.variants)) return null;

  for (let i = 0; i < product.variants.length; i++) {
    const v = product.variants[i];
    if (!v) continue;
    if (v.in_stock === false || v.in_stock === 0 || v.in_stock === 'false') continue;
    return v;
  }

  return null;
}

function selectProduct(state) {
  let res = authedRequest(
    state,
    'GET',
    BASE + '/v2/catalog',
    null,
    {},
    state.cartId || null
  );

  let products = [];
  if (res.status === 200) {
    const j = safeJson(res.body) || {};
    products = extractProducts(j);
  }

  for (let i = 0; i < products.length; i++) {
    const v = pickVariant(products[i]);
    if (v) return { res: res, product: products[i], variant: v };
  }

  let pageUrl = BASE + '/v2/catalog/page';
  let lastRes = res;

  for (let p = 0; p < 3; p++) {
    const pageRes = authedRequest(
      state,
      'GET',
      pageUrl,
      null,
      {},
      state.cartId || null
    );
    lastRes = pageRes;

    if (pageRes.status !== 200) break;

    const j = safeJson(pageRes.body) || {};
    let pageProducts = extractProducts(j);
    if (pageProducts.length === 0 && j.id && j.variants) pageProducts = [j];

    for (let i = 0; i < pageProducts.length; i++) {
      const v = pickVariant(pageProducts[i]);
      if (v) return { res: pageRes, product: pageProducts[i], variant: v };
    }

    if (!j.next) break;
    pageUrl = resolveUrl(pageUrl, j.next);
  }

  return { res: lastRes, product: null, variant: null };
}

function getGrant(state) {
  let res = authedRequest(
    state,
    'GET',
    BASE + '/v2/challenge-form',
    null,
    {},
    null
  );

  if (res.status !== 200) return null;

  const c = extractChallengeForm(res.body);
  if (!c.action || !c.challenge) return null;

  const actionUrl = resolveUrl(BASE + '/v2/challenge-form', c.action);
  const postRes = authedRequest(
    state,
    'POST',
    actionUrl,
    JSON.stringify({ challenge: c.challenge }),
    { headers: { 'Content-Type': 'application/json' } },
    null
  );

  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location');
    if (!loc) return null;

    const grantRes = http.get(resolveUrl(actionUrl, loc), {
      redirects: 0,
      tags: { name: 'challenge-grant' },
    });
    captureCsrf(state, grantRes);

    if (grantRes.status >= 200 && grantRes.status < 300) {
      const j = safeJson(grantRes.body) || {};
      return j.grant_id || null;
    }
    return null;
  }

  if (postRes.status === 200) {
    captureCsrf(state, postRes);
    const j = safeJson(postRes.body) || {};
    return j.grant_id || null;
  }

  return null;
}

function patchCart(state, cartId, etag, quantity) {
  const body = JSON.stringify({ quantity: quantity });

  let headers = { 'Content-Type': 'application/json' };
  if (etag) headers['If-Match'] = etag;

  let res = authedRequest(
    state,
    'PATCH',
    BASE + '/v2/carts/' + cartId,
    body,
    { headers: headers },
    cartId
  );

  if (res.status === 412) {
    const g = authedRequest(
      state,
      'GET',
      BASE + '/v2/carts/' + cartId,
      null,
      {},
      cartId
    );
    const newEtag = getHeader(g, 'ETag');

    const headers2 = { 'Content-Type': 'application/json' };
    if (newEtag) headers2['If-Match'] = newEtag;

    res = authedRequest(
      state,
      'PATCH',
      BASE + '/v2/carts/' + cartId,
      body,
      { headers: headers2 },
      cartId
    );
  }

  return res;
}

function reserveAndWait(state, cartId) {
  const body = JSON.stringify({ cart_id: cartId });

  const res = authedRequest(
    state,
    'POST',
    BASE + '/v2/reservations',
    body,
    { headers: { 'Content-Type': 'application/json' } },
    cartId
  );
  captureCsrf(state, res);

  check(res, {
    'reservation accepted': (r) => r.status === 202,
  });

  if (res.status !== 202) return null;

  const j = safeJson(res.body) || {};
  if (!j.status_url) return null;

  const statusUrl = resolveUrl(BASE + '/v2/reservations', j.status_url);

  for (let i = 0; i < 5; i++) {
    sleep(0.05);

    const poll = authedRequest(
      state,
      'GET',
      statusUrl,
      null,
      {},
      cartId
    );
    captureCsrf(state, poll);

    const pj = safeJson(poll.body) || {};

    if (pj.status === 'ready') {
      check(poll, {
        'reservation ready': (r) =>
          r.status >= 200 && r.status < 300 && !!pj.reservation_id,
      });
      return pj.reservation_id || null;
    }

    if (pj.status === 'failed') {
      check(poll, {
        'reservation failed': () => false,
      });
      return null;
    }
  }

  check(null, {
    'reservation ready in <=5 polls': () => false,
  });

  return null;
}

function commitOrder(state, cartId, reservationId) {
  const g = authedRequest(
    state,
    'GET',
    BASE + '/v2/carts/' + cartId,
    null,
    {},
    cartId
  );
  let etag = getHeader(g, 'ETag');

  const bodyObj = { cart_id: cartId };
  if (reservationId) bodyObj.reservation_id = reservationId;
  const body = JSON.stringify(bodyObj);
  const idem = 'order-' + cartId;

  let headers = {
    'Content-Type': 'application/json',
    'Idempotency-Key': idem,
  };
  if (etag) headers['If-Match'] = etag;

  let res = authedRequest(
    state,
    'POST',
    BASE + '/v2/orders',
    body,
    { headers: headers },
    cartId
  );

  if (res.status === 412) {
    const g2 = authedRequest(
      state,
      'GET',
      BASE + '/v2/carts/' + cartId,
      null,
      {},
      cartId
    );
    const newEtag = getHeader(g2, 'ETag');

    const headers2 = {
      'Content-Type': 'application/json',
      'Idempotency-Key': idem,
    };
    if (newEtag) headers2['If-Match'] = newEtag;

    res = authedRequest(
      state,
      'POST',
      BASE + '/v2/orders',
      body,
      { headers: headers2 },
      cartId
    );
  }

  captureCsrf(state, res);
  return res;
}

export default function () {
