class CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.current_action = None
        self.current_method = None
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {k.lower(): (v if v is not None else "") for k, v in attrs}

        if tag == "form":
            self.current_action = attrs_dict.get("action", "")
            self.current_method = attrs_dict.get("method", "").lower()
        elif tag == "input":
            typ = attrs_dict.get("type", "").strip().lower()
            name = attrs_dict.get("name", "").strip().lower()
            if typ == "hidden" and name == "csrf":
                val = attrs_dict.get("value")
                if val is not None:
                    self.candidates.append(
                        (self.current_action, self.current_method, unescape(val))
                    )

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_action = None
            self.current_method = None

    def value(self):
        for action, _method, val in self.candidates:
            action_lower = (action or "").lower()
            if "login" in action_lower or action_lower.endswith("/v2/login"):
                return val

        for action, method, val in self.candidates:
            if method == "post" and (action is None or action == ""):
                return val

        if self.candidates:
            return self.candidates[0][2]
        return None


class ChallengeParser(HTMLParser):
    def __init__(self):
