# ---------------------------------------------------------------------------
# HTML parsing helpers
# ---------------------------------------------------------------------------

class FormParser(HTMLParser):
    """Collect every <form> and the inputs nested inside it."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self._stack = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        d = {}
        for k, v in attrs:
            d[k.lower()] = v if v is not None else ""

        if tag == "form":
            form = {
                "action": d.get("action", ""),
                "method": d.get("method", "").lower(),
                "inputs": {},
                "has_password": False,
            }
            self.forms.append(form)
            self._stack.append(form)
        elif tag == "input" and self._stack:
            form = self._stack[-1]
            name = d.get("name")
            val = d.get("value")
            if name is not None and val is not None:
                form["inputs"].setdefault(name.lower(), []).append(unescape(val))
            if d.get("type", "").lower() == "password":
                form["has_password"] = True

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form" and self._stack:
            self._stack.pop()


def extract_csrf_token(html):
    """Pick the real hidden csrf input out of the login page, ignoring decoys."""
    parser = FormParser()
    parser.feed(html or "")
    forms = parser.forms

    # 1. The login form typically also carries a password field.
    for f in forms:
        if f["has_password"] and "csrf" in f["inputs"]:
            return f["inputs"]["csrf"][0]

    # 2. Form whose action clearly points at a login endpoint.
    for f in forms:
        action = (f["action"] or "").lower()
        if "login" in action and "csrf" in f["inputs"]:
            return f["inputs"]["csrf"][0]

    # 3. Any form that carries a csrf input.
    for f in forms:
        if "csrf" in f["inputs"]:
            return f["inputs"]["csrf"][0]

    return None


def extract_challenge(html):
    """Return (action, challenge) from the challenge-form page."""
    parser = FormParser()
    parser.feed(html or "")
    for f in parser.forms:
        if "challenge" in f["inputs"]:
            return f["action"], f["inputs"]["challenge"][0]
    return None, None


