        node = data.get("data") if isinstance(data.get("data"), dict) else data
        nxt = node.get("next")
        if nxt is None:
            nxt = data.get("next")
        return nxt

    def _pick_product(self, products):
        for product in products:
            if not isinstance(product, dict):
                continue
            product_id = product.get("id")
            variants = product.get("variants") or []
            for variant in variants:
                if not isinstance(variant, dict):
                    continue
                if variant.get("in_stock") and variant.get("id") is not None:
                    return product_id, variant["id"]
        return None

    def choose_product(self):
        resp = self._request("GET", "/v2/catalog")
        if resp is not None:
            data = self._json_dict(resp)
            picked = self._pick_product(self._products_of(data))
            if picked:
                return picked

        url = "/v2/catalog/page"
        for _ in range(3):
            resp = self._request("GET", url)
            if resp is None:
                return None
            data = self._json_dict(resp)
            picked = self._pick_product(self._products_of(data))
            if picked:
                return picked
            nxt = self._next_of(data)
            if not nxt:
                break
            url = self._abs(nxt)

        return None

    # --------------------------------------------------------------- cart

    def create_cart(self, product_id, variant_id, grant_id):
        payload = {
            "product_id": product_id,
            "variant_id": variant_id,
            "grant_id": grant_id,
        }
        attempts = 0
        while True:
            action = None

            with self.client.post(
                "/v2/carts",
                json=payload,
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
            ) as resp:
                status = resp.status_code

                if status == 201:
                    data = self._json_dict(resp)
                    if not data or not data.get("id"):
                        resp.failure("cart creation missing id")
                        return False
                    self.cart_id = data["id"]
                    self.csrf = data.get("csrf") or self.csrf
                    self._update_etag(resp)
                    self.reservation_id = None
                    self.idempotency_key = None
                    resp.success()
                    return True
                elif status == 401:
                    err = self._error(resp)
                    if err == "denied":
                        resp.failure("cart 401 denied")
                        return False
                    if err in ("expired", "session") and attempts == 0:
                        resp.success()
                        action = err
                    else:
                        resp.failure("cart 401 {}".format(err))
                        return False
                else:
                    resp.failure("cart status {}".format(status))
                    return False

            attempts += 1
            if action == "expired":
                if not self.renew_session(None):
                    if not self.relogin_and_recover(None):
                        return False
                new_grant = self.obtain_grant()
                if not new_grant:
                    return False
                payload["grant_id"] = new_grant
            elif action == "session":
                if not self.relogin_and_recover(None):
                    return False
                new_grant = self.obtain_grant()
                if not new_grant:
                    return False
                payload["grant_id"] = new_grant
            else:
                return False

    def _refresh_etag(self):
        if not self.cart_id:
            return False
        resp = self._request("GET", "/v2/carts/{}".format(self.cart_id), cart_id=self.cart_id)
        if resp is None:
            return False
        self._update_etag(resp)
        self._update_csrf(resp)
        return self.cart_etag is not None

    def _ensure_etag(self):
        if self.cart_etag:
            return True
        return self._refresh_etag()

    def patch_cart_quantity(self, quantity):
        if not self._ensure_etag():
            return False

        payload = {"quantity": int(quantity)}
        retried_412 = False
        attempts_auth = 0

        while True:
            action = None
            headers = {
                "X-CSRF-Token": self.csrf,
                "If-Match": self.cart_etag,
            }

            with self.client.patch(
                "/v2/carts/{}".format(self.cart_id),
                json=payload,
                headers=headers,
                catch_response=True,
            ) as resp:
                status = resp.status_code

                if status == 401:
                    err = self._error(resp)
                    if err == "denied":
                        resp.failure("cart patch 401 denied")
                        return False
                    if err in ("expired", "session") and attempts_auth == 0:
                        resp.success()
                        action = err
                    else:
                        resp.failure("cart patch 401 {}".format(err))
                        return False
                elif status == 412:
                    if not retried_412:
                        resp.success()
                        action = "412"
                    else:
                        resp.failure("cart patch 412 after retry")
                        return False
                elif status >= 400:
                    resp.failure("cart patch unexpected {}".format(status))
                    return False
                else:
                    self._update_csrf(resp)
                    self._update_etag(resp)
                    resp.success()
                    return True

            if action == "412":
                retried_412 = True
                if not self._refresh_etag():
                    return False
                continue

            attempts_auth += 1
            if action == "expired":
                if not self.renew_session(self.cart_id):
                    if not self.relogin_and_recover(self.cart_id):
                        return False
            elif action == "session":
                if not self.relogin_and_recover(self.cart_id):
                    return False
            else:
                return False

            if not self._refresh_etag():
                return False

    # --------------------------------------------------------------- reservation

    def make_reservation(self):
        payload = {"cart_id": self.cart_id}
        attempts = 0
        status_url = None

        while True:
            action = None

            with self.client.post(
                "/v2/reservations",
                json=payload,
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
            ) as resp:
                status = resp.status_code

                if status == 202:
                    data = self._json_dict(resp)
                    if not data or not data.get("status_url"):
                        resp.failure("reservation missing status_url")
                        return None
                    self.csrf = data.get("csrf") or self.csrf
                    status_url = data["status_url"]
                    resp.success()
                    break
                elif status == 401:
                    err = self._error(resp)
                    if err == "denied":
                        resp.failure("reservation 401 denied")
                        return None
                    if err in ("expired", "session") and attempts == 0:
                        resp.success()
                        action = err
                    else:
                        resp.failure("reservation 401 {}".format(err))
                        return None
                else:
                    resp.failure("reservation status {}".format(status))
                    return None

            attempts += 1
            if action == "expired":
                if not self.renew_session(self.cart_id):
                    if not self.relogin_and_recover(self.cart_id):
                        return None
            elif action == "session":
                if not self.relogin_and_recover(self.cart_id):
                    return None
            else:
                return None

        status_url = self._abs(status_url)

        for _ in range(5):
            gevent.sleep(0.05)

            resp = self._request("GET", status_url, cart_id=self.cart_id)
            if resp is None:
                return None

            data = self._json_dict(resp)
            if not data:
                return None

            status = data.get("status")
            if status == "ready":
                reservation_id = data.get("reservation_id")
                if reservation_id is None:
                    return None
                return reservation_id
            elif status == "failed":
                return None
            elif status == "pending":
                continue
            else:
                return None

        return None

    # --------------------------------------------------------------- order

    def place_order(self, reservation_id):
        if not self._ensure_etag():
            return False

        payload = {
            "cart_id": self.cart_id,
            "reservation_id": reservation_id,
        }
        if not self.idempotency_key:
            self.idempotency_key = "order-{}".format(self.cart_id)

        attempts_auth = 0
        attempts_412 = 0

        while True:
            action = None
            headers = {
                "X-CSRF-Token": self.csrf,
                "Idempotency-Key": self.idempotency_key,
            }
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                catch_response=True,
            ) as resp:
                status = resp.status_code

                if status in (200, 201):
                    data = self._json_dict(resp)
                    if not data:
                        resp.failure("order empty response")
                        return False
                    if data.get("accepted") is not True:
                        resp.failure("order not accepted")
                        return False
                    self.csrf = data.get("csrf") or self.csrf
                    resp.success()
                    return True
                elif status == 401:
                    err = self._error(resp)
                    if err == "denied":
                        resp.failure("order 401 denied")
                        return False
                    if err in ("expired", "session") and attempts_auth == 0:
                        resp.success()
                        action = err
                    else:
                        resp.failure("order 401 {}".format(err))
                        return False
                elif status == 412:
                    if attempts_412 == 0:
                        resp.success()
                        action = "412"
                    else:
                        resp.failure("order 412 after retry")
                        return False
                else:
                    resp.failure("order status {}".format(status))
                    return False

            if action == "412":
                attempts_412 += 1
                if not self._refresh_etag():
                    return False
                continue

            attempts_auth += 1
            if action == "expired":
                if not self.renew_session(self.cart_id):
                    if not self.relogin_and_recover(self.cart_id):
                        return False
            elif action == "session":
                if not self.relogin_and_recover(self.cart_id):
                    return False
            else:
                return False

            if not self._refresh_etag():
                return False

    # --------------------------------------------------------------- journey

    def one_journey(self):
        if not self.fresh_login(clear_cart=True):
            return

        picked = self.choose_product()
        if not picked:
            return
        product_id, variant_id = picked

        grant_id = self.obtain_grant()
        if not grant_id:
            return

        if not self.create_cart(product_id, variant_id, grant_id):
            return

        if not self.patch_cart_quantity(1):
            return

        reservation_id = self.make_reservation()
        if reservation_id is None:
            return

        self.place_order(reservation_id)


