# Load test shape - spawn exactly EXPECTED_USERS, stop once all completed
# ---------------------------------------------------------------------------

class FlowShape(LoadTestShape):
    def tick(self):
        if RunState.completed >= RunState.expected_users:
            RunState.release = True
            return None
        return (RunState.expected_users, RunState.expected_users)
