import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;
import java.time.Duration;
import java.util.List;
import java.util.Map;

public class ModelSimulation extends Simulation {

  public ModelSimulation() {
    HttpProtocolBuilder httpProtocol = http
        .baseUrl(System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000")
        .disableAutoRedirects()
        .acceptHeader("application/json, text/html;q=0.9,*/*;q=0.8");

    ChainBuilder reset = exec(session -> session
        .remove("csrf")
        .remove("productId")
        .remove("variantId")
        .remove("products")
        .remove("challengeAction")
        .remove("challenge")
        .remove("challengeRedirect")
        .remove("grantId")
        .remove("cartId")
        .remove("cartEtag")
        .remove("patchStatus")
        .remove("statusUrl")
        .remove("reservationId")
        .remove("reservationIdMaybe")
        .remove("resStatus")
        .remove("pollCount")
        .remove("orderId")
        .remove("accepted")
        .remove("loginRedirect")
        .remove("loginStatus")
    );

    ChainBuilder login = exec(http("login form")
        .get("/v2/login-form")
        .check(status().is(200))
        .check(regex("(?i)<input\\b(?=[^>]*\\sname\\s*=\\s*[\"']?csrf[\"']?(?=[\\s/>]))(?=[^>]*\\svalue\\s*=\\s*[\"']?([^\"'\\s>]+))[^>]*>").saveAs("csrf"))
    ).exitHereIfFailed().exec(http("login")
        .post("/v2/login")
        .body(StringBody(session -> {
          String user = "bench-" + (((session.userId() % 16) + 1));
          return "{\"username\":" + jsonValue(user) + ",\"password\":\"bench\",\"csrf\":" + jsonValue(session.get("csrf")) + "}";
        })).asJson()
        .check(status().in(200, 302).saveAs("loginStatus"))
        .check(header("Location").optional().saveAs("loginRedirect"))
        .check(regex("(?i)\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
        .check(regex("(?i)\"user\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("user"))
    ).doIf(session -> session.contains("loginStatus") && session.getInt("loginStatus") == 302 && session.contains("loginRedirect")).then(
        exec(http("login redirect")
            .get(session -> session.getString("loginRedirect"))
            .check(status().is(200))
            .check(jsonPath("$.csrf").saveAs("csrf"))
            .check(jsonPath("$.user").optional().saveAs("user"))
        )
    ).exec(session -> {
      if (session.getString("csrf") == null) {
        return session.markAsFailed("missing csrf after login");
      }
      return session;
    });

    ChainBuilder selectProduct = exec(http("catalog")
        .get("/v2/catalog")
        .check(status().is(200))
        .check(jsonPath("$.data.products").saveAs("products"))
    ).exec(ModelSimulation::selectInStock);

    ChainBuilder challenge = exec(http("challenge form")
        .get("/v2/challenge-form")
        .check(status().is(200))
        .check(regex("(?i)<form\\b[^>]*\\saction\\s*=\\s*[\"']?([^\"'\\s>]*/v2/challenges/[^\"'\\s>]*)[\"']?[^>]*>").saveAs("challengeAction"))
        .check(regex("(?i)<input\\b(?=[^>]*\\sname\\s*=\\s*[\"']?challenge[\"']?(?=[\\s/>]))(?=[^>]*\\svalue\\s*=\\s*[\"']?([^\"'\\s>]+))[^>]*>").saveAs("challenge"))
    ).exitHereIfFailed().exec(http("challenge submit")
        .post(session -> session.getString("challengeAction"))
        .header("X-CSRF-Token", session -> session.getString("csrf"))
        .body(StringBody(session -> "{\"challenge\":" + jsonValue(session.get("challenge")) + "}")).asJson()
        .check(status().is(302))
        .check(header("Location").saveAs("challengeRedirect"))
    ).exitHereIfFailed().exec(http("challenge redirect")
        .get(session -> session.getString("challengeRedirect"))
        .check(status().is(200))
        .check(jsonPath("$.grant_id").saveAs("grantId"))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
    );

    ChainBuilder createCart = exec(http("create cart")
        .post("/v2/carts")
        .header("X-CSRF-Token", session -> session.getString("csrf"))
        .body(StringBody(session -> {
          Object grant = session.get("grantId");
          return "{\"product_id\":" + jsonValue(session.get("productId")) +
              ",\"variant_id\":" + jsonValue(session.get("variantId")) +
              (grant != null ? ",\"grant_id\":" + jsonValue(grant) : "") +
              "}";
        })).asJson()
        .check(status().is(201))
        .check(header("ETag").saveAs("cartEtag"))
        .check(jsonPath("$.id").saveAs("cartId"))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
    );

    ChainBuilder patchCart = exec(http("patch cart")
        .patch(session -> "/v2/carts/" + session.get("cartId"))
        .header("X-CSRF-Token", session -> session.getString("csrf"))
        .header("If-Match", session -> session.getString("cartEtag"))
        .body(StringBody("{\"quantity\":1}")).asJson()
        .check(status().in(200, 412).saveAs("patchStatus"))
        .check(regex("(?i)\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
    ).doIf(session -> session.contains("patchStatus") && session.getInt("patchStatus") == 412).then(
        exec(http("re-read cart after 412")
            .get(session -> "/v2/carts/" + session.get("cartId"))
            .check(status().is(200))
            .check(header("ETag").saveAs("cartEtag"))
        ).exitHereIfFailed().exec(http("retry patch cart")
            .patch(session -> "/v2/carts/" + session.get("cartId"))
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .header("If-Match", session -> session.getString("cartEtag"))
            .body(StringBody("{\"quantity\":1}")).asJson()
            .check(status().is(200))
            .check(regex("(?i)\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
        )
    );

    ChainBuilder reserve = exec(http("create reservation")
        .post("/v2/reservations")
        .header("X-CSRF-Token", session -> session.getString("csrf"))
        .body(StringBody(session -> "{\"cart_id\":" + jsonValue(session.get("cartId")) + "}")).asJson()
        .check(status().is(202))
        .check(jsonPath("$.status_url").saveAs("statusUrl"))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
    ).exitHereIfFailed().exec(session -> session.set("pollCount", 0).remove("reservationId"))
    .asLongAs(session -> session.getInt("pollCount") < 5 && !session.contains("reservationId")).on(
        pause(Duration.ofMillis(50))
        .exec(http("poll reservation")
            .get(session -> session.getString("statusUrl"))
            .check(status().is(200))
            .check(jsonPath("$.status").saveAs("resStatus"))
            .check(jsonPath("$.reservation_id").optional().saveAs("reservationIdMaybe"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        ).exitHereIfFailed()
        .exec(session -> {
          int count = session.getInt("pollCount");
          session = session.set("pollCount", count + 1);
          String status = session.getString("resStatus");
          Object resId = session.get("reservationIdMaybe");
          if ("ready".equals(status)) {
            if (resId != null) {
              session = session.set("reservationId", resId);
            } else {
              session = session.set("pollCount", 5).markAsFailed("reservation ready without id");
            }
          } else if ("failed".equals(status)) {
            session = session.set("pollCount", 5).markAsFailed("reservation failed");
          }
          return session.remove("reservationIdMaybe");
        })
    ).exec(session -> {
      if (session.get("reservationId") == null) {
        return session.markAsFailed("reservation not ready");
      }
      return session;
    }).exitHereIfFailed();

    ChainBuilder checkout = exec(http("read cart before order")
        .get(session -> "/v2/carts/" + session.get("cartId"))
        .check(status().is(200))
        .check(header("ETag").saveAs("cartEtag"))
    ).exitHereIfFailed().exec(http("checkout")
        .post("/v2/orders")
        .header("X-CSRF-Token", session -> session.getString("csrf"))
        .header("Idempotency-Key", session -> "order-" + session.get("cartId"))
        .header("If-Match", session -> session.getString("cartEtag"))
        .body(StringBody(session -> {
          Object res = session.get("reservationId");
          return "{\"cart_id\":" + jsonValue(session.get("cartId")) +
              (res != null ? ",\"reservation_id\":" + jsonValue(res) : "") +
              "}";
        })).asJson()
        .check(status().is(201))
        .check(jsonPath("$.accepted").is(true))
        .check(jsonPath("$.id").saveAs("orderId"))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
    );

    ChainBuilder journey = reset
        .exec(login)
        .exitHereIfFailed()
        .exec(selectProduct)
        .exitHereIfFailed()
        .exec(challenge)
        .exitHereIfFailed()
        .exec(createCart)
        .exitHereIfFailed()
        .exec(patchCart)
        .exitHereIfFailed()
        .exec(reserve)
        .exec(checkout);

    ScenarioBuilder scn = scenario("ModelSimulation").repeat(2).on(journey);
    setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }

  @SuppressWarnings("unchecked")
  private static Session selectInStock(Session session) {
    Object productsObj = session.get("products");
    if (!(productsObj instanceof List)) {
      return session.markAsFailed("catalog products missing");
    }
    for (Object pObj : (List<?>) productsObj) {
      if (!(pObj instanceof Map)) continue;
      Map<String, Object> p = (Map<String, Object>) pObj;
      Object variantsObj = p.get("variants");
      if (!(variantsObj instanceof List)) continue;
      for (Object vObj : (List<?>) variantsObj) {
        if (!(vObj instanceof Map)) continue;
        Map<String, Object> v = (Map<String, Object>) vObj;
        if (Boolean.TRUE.equals(v.get("in_stock"))) {
          session = session.set("productId", p.get("id"));
          session = session.set("variantId", v.get("id"));
          return session;
        }
      }
    }
    return session.markAsFailed("no in-stock variant");
  }

  private static String jsonValue(Object value) {
    if (value == null) return "null";
    if (value instanceof Number || value instanceof Boolean) {
      return value.toString();
    }
    String s = String.valueOf(value);
    return "\"" + s.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
  }
}
