import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function fullUrl(path) {
  if (!path) return BASE;
  if (path.indexOf('http') === 0) return path;
  if (path.charAt(0) === '/') return BASE + path;
  return BASE + '/' + path;
}

function jsonBody(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function getError(res) {
  const j = jsonBody(res);
  if (j && typeof j === 'object' && j.error) return j.error;
  return null;
}

function getLocation(res) {
  return res.headers['Location'] || res.headers['location'] || null;
}

function getEtag(res) {
  return res.headers['Etag'] || res.headers['ETag'] || res.headers['etag'] || null;
}

function updateCartEtag(state, res) {
  const etag = getEtag(res);
  if (etag) state.cartEtag = etag;
}

function updateCsrf(state, res) {
  const j = jsonBody(res);
  if (j && j.csrf) state.csrf = j.csrf;
}

function getAttr(tag, attrName) {
  const re = new RegExp(`(?:^|\\s)${attrName}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  if (m[3] !== undefined) return m[3];
  return null;
}

function extractInputValue(html, name) {
  if (!html) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const n = getAttr(tag, 'name');
    if (n && n.toLowerCase() === name.toLowerCase()) {
      const v = getAttr(tag, 'value');
      if (v !== null) return v;
    }
  }
  return null;
}

function csrfHeaders(csrf, extra) {
  const h = {};
  if (extra) {
    for (const k in extra) {
      if (Object.prototype.hasOwnProperty.call(extra, k)) h[k] = extra[k];
    }
  }
  if (csrf) h['X-CSRF-Token'] = csrf;
  return h;
}

function login(state, username) {
  const formRes = http.get(BASE + '/v2/login-form', { redirects: 0 });
  if (formRes.status !== 200) return false;

  const csrf = extractInputValue(formRes.body, 'csrf');
  if (!csrf) return false;

  state.csrf = csrf;
  state.username = username;

  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: PASSWORD, csrf: csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  let finalRes = loginRes;
  if (loginRes.status === 301 || loginRes.status === 302 || loginRes.status === 303 || loginRes.status === 307 || loginRes.status === 308) {
    const loc = getLocation(loginRes);
    if (!loc) return false;
    finalRes = http.get(fullUrl(loc), { redirects: 0 });
  }

  if (finalRes.status >= 200 && finalRes.status < 300) {
    updateCsrf(state, finalRes);
    return true;
  }

  if (loginRes.status >= 200 && loginRes.status < 300) {
    updateCsrf(state, loginRes);
    return true;
  }

  return false;
}

function recoverCart(state) {
  if (!state.cartId) return true;
  const res = http.post(
    BASE + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover',
    JSON.stringify({}),
    { headers: csrfHeaders(state.csrf, { 'Content-Type': 'application/json' }), redirects: 0 }
  );
  if (res.status >= 200 && res.status < 300) {
    updateCsrf(state, res);
    updateCartEtag(state, res);
    return true;
  }
  return false;
}

function loginFreshAndRecover(state) {
  if (!state.username) return false;
  const ok = login(state, state.username);
  if (!ok) return false;
  if (state.cartId) return recoverCart(state);
  return true;
}

function recoverSession(state, err) {
  if (err === 'expired') {
    const renewRes = http.post(
      BASE + '/v2/session/renew',
      JSON.stringify({}),
      { headers: csrfHeaders(state.csrf, { 'Content-Type': 'application/json' }), redirects: 0 }
    );

    if (renewRes.status >= 200 && renewRes.status < 300) {
      updateCsrf(state, renewRes);
      if (state.cartId) recoverCart(state);
      return true;
    }

    return loginFreshAndRecover(state);
  }

  if (err === 'session') {
    return loginFreshAndRecover(state);
  }

  return false;
}

function doRequest(state, method, path, body, extraHeaders) {
  let attempt = 0;
  let res = null;

  while (attempt < 2) {
    const headers = {};
    if (extraHeaders) {
      for (const k in extraHeaders) {
        if (Object.prototype.hasOwnProperty.call(extraHeaders, k)) headers[k] = extraHeaders[k];
      }
    }

    if (method !== 'GET') {
      if (!headers['Content-Type'] && body !== undefined) headers['Content-Type'] = 'application/json';
      if (state.csrf && !headers['X-CSRF-Token']) headers['X-CSRF-Token'] = state.csrf;
    }

    const params = { headers: headers, redirects: 0 };
    const url = fullUrl(path);
    const payload = body === undefined ? null : (typeof body === 'string' ? body : JSON.stringify(body));

    if (method === 'GET') res = http.get(url, params);
    else if (method === 'POST') res = http.post(url, payload, params);
    else if (method === 'PATCH') res = http.patch(url, payload, params);
    else if (method === 'PUT') res = http.put(url, payload, params);
    else if (method === 'DELETE') res = http.del(url, payload, params);
    else throw new Error('Unsupported method ' + method);

    if (res.status === 401) {
      const err = getError(res);
      if ((err === 'expired' || err === 'session') && attempt === 0) {
        if (recoverSession(state, err)) {
          attempt++;
          continue;
        }
      }
    }

    break;
  }

  return res;
}

function isInStock(v) {
  return v === true || v === 1 || v === 'true' || v === '1';
}

function pickVariantFromProduct(product) {
  if (!product || product.id === undefined || product.id === null) return null;

  let variants = product.variants;
  if (!Array.isArray(variants) && product.data && Array.isArray(product.data.variants)) {
    variants = product.data.variants;
  }
  if (!Array.isArray(variants)) return null;

  for (let i = 0; i < variants.length; i++) {
    const v = variants[i];
    if (!v || v.id === undefined || v.id === null) continue;
    if (isInStock(v.in_stock)) {
      return { product_id: product.id, variant_id: v.id, product: product, variant: v };
    }
  }

  return null;
}

function getProductsFromCatalog(j) {
  if (!j || typeof j !== 'object') return [];
  if (j.data && Array.isArray(j.data.products)) return j.data.products;
  if (Array.isArray(j.products)) return j.products;
  if (j.data && j.data.data && Array.isArray(j.data.data.products)) return j.data.data.products;
  return [];
}

function findEligible(products) {
  if (!Array.isArray(products)) return null;
  for (let i = 0; i < products.length; i++) {
    const sel = pickVariantFromProduct(products[i]);
    if (sel) return sel;
  }
  return null;
}

function getProductFromPage(j) {
  if (!j || typeof j !== 'object') return null;
  if (j.data && j.data.product) return j.data.product;
  if (j.product) return j.product;
  if (j.data && Array.isArray(j.data.products) && j.data.products.length > 0) return j.data.products[0];
  if (Array.isArray(j.products) && j.products.length > 0) return j.products[0];
  if (j.id !== undefined && j.variants) return j;
  return null;
}

function getNextFromPage(j) {
  if (!j || typeof j !== 'object') return null;
  if (j.next !== undefined && j.next !== null) return j.next;
  if (j.data && j.data.next !== undefined && j.data.next !== null) return j.data.next;
  return null;
}

function selectProductVariant(state) {
  const res = doRequest(state, 'GET', '/v2/catalog');
  if (res.status === 200) {
    const j = jsonBody(res);
    const products = getProductsFromCatalog(j);
    const selected = findEligible(products);
    if (selected) return selected;
  }

  let next = '/v2/catalog/page';
  for (let i = 0; i < 3 && next; i++) {
    const pageRes = doRequest(state, 'GET', next);
    if (pageRes.status !== 200) break;

    const j = jsonBody(pageRes);
    const product = getProductFromPage(j);
    const selected = product ? pickVariantFromProduct(product) : null;
    if (selected) return selected;

    next = getNextFromPage(j);
    if (next && typeof next !== 'string') break;
  }

  return null;
}

function createCart(state) {
  const res = doRequest(state, 'POST', '/v2/carts', {
    product_id: state.productId,
    variant_id: state.variantId,
  });

  if (res.status !== 201) return false;

  const j = jsonBody(res);
  if (!j || j.id === undefined || j.id === null) return false;

  state.cartId = j.id;
  if (j.csrf) state.csrf = j.csrf;
  updateCartEtag(state, res);

  state.idempotencyKey = 'idem-' + state.cartId + '-' + __VU + '-' + __ITER + '-' + Date.now();
  return true;
}

function reserveCart(state) {
  const res = doRequest(state, 'POST', '/v2/reservations', { cart_id: state.cartId });
  if (res.status !== 202) return null;

  const j = jsonBody(res);
  if (!j) return null;

  if (j.csrf) state.csrf = j.csrf;

  const statusUrl = j.status_url || (j.data && j.data.status_url);
  if (!statusUrl) return null;

  let reservationId = null;

  for (let i = 0; i < 5; i++) {
    if (i > 0) sleep(0.05);

    const pollRes = doRequest(state, 'GET', statusUrl);
    if (pollRes.status !== 200) break;

    const pj = jsonBody(pollRes);
    if (!pj) continue;

    if (pj.csrf) state.csrf = pj.csrf;

    const status = pj.status || (pj.data && pj.data.status);
    if (status === 'ready') {
      reservationId = pj.reservation_id || (pj.data && pj.data.reservation_id);
      break;
    }
    if (status === 'failed') {
      return null;
    }
  }

  return reservationId;
}

function checkout(state, reservationId) {
  if (!state.cartId) return false;

  if (!state.idempotencyKey) {
    state.idempotencyKey = 'idem-' + state.cartId + '-' + __VU + '-' + __ITER + '-' + Date.now();
  }

  const body = { cart_id: state.cartId };
  if (reservationId !== null && reservationId !== undefined) {
    body.reservation_id = reservationId;
  }

  let headers = {
    'Content-Type': 'application/json',
    'Idempotency-Key': state.idempotencyKey,
  };

  let res = doRequest(state, 'POST', '/v2/orders', body, headers);

  if (res.status === 412 || res.status === 428) {
    const cartRes = doRequest(state, 'GET', '/v2/carts/' + encodeURIComponent(state.cartId));
    if (cartRes.status === 200) updateCartEtag(state, cartRes);

    if (state.cartEtag) {
      headers = {
        'Content-Type': 'application/json',
        'Idempotency-Key': state.idempotencyKey,
        'If-Match': state.cartEtag,
      };
      res = doRequest(state, 'POST', '/v2/orders', body, headers);
    }
  }

  if (res.status !== 201) return false;

  const j = jsonBody(res);
  if (!j) return false;
  if (j.csrf) state.csrf = j.csrf;

  return j.accepted === true;
}

export default function () {
  const journeyIndex = (__VU - 1) * 2 + __ITER + 1;
  const username = journeyIndex <= 16 ? 'bench-' + journeyIndex : 'bench';

  const state = {
    username: username,
    csrf: null,
    cartId: null,
    cartEtag: null,
    idempotencyKey: null,
    productId: null,
    variantId: null,
  };

  try {
    http.cookieJar().clear(BASE);
  } catch (e) {}

  const loginOk = login(state, username);
  check(loginOk, { 'login successful': (v) => v === true });
  if (!loginOk) return;

  const selected = selectProductVariant(state);
  check(selected, { 'eligible parent/variant selected': (s) => s !== null && s !== undefined });
  if (!selected) return;

  state.productId = selected.product_id;
  state.variantId = selected.variant_id;

  const cartOk = createCart(state);
  check(cartOk, { 'cart created': (v) => v === true });
  if (!cartOk) return;

  const cartRes = doRequest(state, 'GET', '/v2/carts/' + encodeURIComponent(state.cartId));
  if (cartRes.status === 200) updateCartEtag(state, cartRes);

  const reservationId = reserveCart(state);
  check(reservationId, { 'reservation ready': (id) => id !== null && id !== undefined });
  if (!reservationId) return;

  const orderOk = checkout(state, reservationId);
  check(orderOk, { 'order committed': (v) => v === true });
}

import os
import uuid
import itertools
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

import gevent
from locust import HttpUser, LoadTestShape
from locust.exception import StopUser

_finished_users = 0
_user_counter = itertools.count(1)


def next_username():
    n = next(_user_counter)
    if n <= 16:
        return f"bench-{n}"
    return "bench"


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf_values = []
        self.challenge_values = []
        self.form_actions = []
        self._current_form_action = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_map = {}
        for k, v in attrs:
            attrs_map[k.lower()] = v if v is not None else ""

        if tag == "form":
            action = attrs_map.get("action")
            self._current_form_action = action
            if action:
                self.form_actions.append(action)
        elif tag == "input":
            name = attrs_map.get("name")
            value = attrs_map.get("value")
            typ = attrs_map.get("type")
            if name == "csrf" and value is not None:
                self.csrf_values.append((value, self._current_form_action, typ))
            if name == "challenge" and value is not None:
                self.challenge_values.append((value, self._current_form_action, typ))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form_action = None


def parse_csrf(html):
    parser = PageParser()
    parser.feed(html)
    if not parser.csrf_values:
        return None

    for value, action, _typ in parser.csrf_values:
        if action and "login" in action.lower():
            return value

    for value, _action, typ in parser.csrf_values:
        if typ and typ.lower() == "hidden":
            return value

    return parser.csrf_values[0][0]


def parse_challenge(html):
    parser = PageParser()
    parser.feed(html)

    action = None
    for form_action in parser.form_actions:
        if "/v2/challenges/" in form_action:
            action = form_action
            break
    if not action and parser.form_actions:
        action = parser.form_actions[0]

    challenge = parser.challenge_values[0][0] if parser.challenge_values else None
    return action, challenge


class FlowShape(LoadTestShape):
    def tick(self):
        if _finished_users >= 2:
            return None
        if self.get_run_time() > 120:
            return None
        return {"users": 2, "spawn_rate": 2}


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def on_start(self):
        self.username = next_username()
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.reservation_id = None
        self._status_url = None
        self.iterations_done = 0

    def run(self):
        global _finished_users
        try:
            for _ in range(2):
                try:
                    self._journey()
                except StopUser:
                    raise
                except Exception:
                    pass
                self.iterations_done += 1
        finally:
            _finished_users += 1
            while _finished_users < 2:
                gevent.sleep(0.05)
            raise StopUser()

    def _path_only(self, url):
        if not url:
            return url
        if url.startswith("http://") or url.startswith("https://"):
            parsed = urlparse(url)
            path = parsed.path
            if parsed.query:
                path += "?" + parsed.query
            return path
        return url

    def _resolve(self, base_path, rel):
        if not rel:
            return rel
        if rel.startswith("http://") or rel.startswith("https://"):
            return self._path_only(rel)
        base = self.host + (base_path if base_path.startswith("/") else "/" + base_path)
        return self._path_only(urljoin(base, rel))

    def _error(self, resp):
        try:
            data = resp.json()
        except Exception:
            data = None

        if isinstance(data, dict):
            err = data.get("error") or data.get("code")
            if isinstance(err, dict):
                err = err.get("error") or err.get("code")
            if err:
                return str(err)

        text = (resp.text or "").lower()
        for expected in ("denied", "expired", "session"):
            if expected in text:
                return expected
        return ""

    def _req(
        self,
        method,
        path,
        name=None,
        json_body=None,
        headers=None,
        allow_redirects=False,
        expected=(200,),
        validate=None,
        retry_401=True,
        cart_id=None,
    ):
        if cart_id is None:
            cart_id = self.cart_id

        req_headers = dict(headers or {})
        if self.csrf and method.upper() != "GET":
            req_headers.setdefault("X-CSRF-Token", self.csrf)

        path = self._path_only(path)
        kwargs = {}
        if json_body is not None:
            kwargs["json"] = json_body

        with self.client.request(
            method,
            path,
            name=name or path,
            catch_response=True,
            allow_redirects=allow_redirects,
            headers=req_headers,
            **kwargs,
        ) as resp:
            if resp.status_code == 401 and retry_401:
                err = self._error(resp)
                if err == "expired":
                    resp.success()
                    ok = self._renew_session()
                    if not ok:
                        ok = self._fresh_login()
                    if ok and self._recover_cart_if_needed(cart_id):
                        return self._req(
                            method,
                            path,
                            name=name,
                            json_body=json_body,
                            headers=headers,
                            allow_redirects=allow_redirects,
                            expected=expected,
                            validate=validate,
                            retry_401=False,
                            cart_id=cart_id,
                        )
                    return None
                if err == "session":
                    resp.success()
                    if self._fresh_login() and self._recover_cart_if_needed(cart_id):
                        return self._req(
                            method,
                            path,
                            name=name,
                            json_body=json_body,
                            headers=headers,
                            allow_redirects=allow_redirects,
                            expected=expected,
                            validate=validate,
                            retry_401=False,
                            cart_id=cart_id,
                        )
                    return None
                resp.failure(f"401 {err or 'unknown'}")
                return None

            if resp.status_code not in expected:
                resp.failure(
                    f"unexpected status {resp.status_code} for {method} {path}: {resp.text[:200]}"
                )
                return None

            if validate is not None:
                if validate(resp) is False:
                    return None

            resp.success()
            return resp

    def _renew_session(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            "/v2/session/renew",
            name="POST /v2/session/renew",
            json={},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                resp.success()
                return True

            if resp.status_code == 401 and self._error(resp) == "session":
                resp.success()
                return False

            resp.failure(f"renew failed {resp.status_code}: {resp.text[:200]}")
            return False

    def _recover_cart(self, cart_id):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            f"/v2/carts/{cart_id}/recover",
            name="POST /v2/carts/[id]/recover",
            json={},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (200, 201, 204):
                try:
                    data = resp.json()
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                resp.success()
                return True

            resp.failure(f"recover failed {resp.status_code}: {resp.text[:200]}")
            return False

    def _recover_cart_if_needed(self, cart_id):
        if not cart_id:
            return True
        return self._recover_cart(cart_id)

    def _handle_login_response(self, resp):
        if resp.status_code != 200:
            resp.failure(f"login status {resp.status_code}: {resp.text[:200]}")
            return False

        try:
            data = resp.json()
        except Exception as e:
            resp.failure(f"login invalid json: {e}")
            return False

        csrf = data.get("csrf") if isinstance(data, dict) else None
        if not csrf:
            resp.failure("login missing csrf")
            return False

        self.csrf = csrf
        resp.success()
        return True

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login form status {resp.status_code}: {resp.text[:200]}")
                return False

            csrf = parse_csrf(resp.text)
            if not csrf:
                resp.failure("login form missing csrf")
                return False
            resp.success()

        login_path = "/v2/login"
        with self.client.post(
            login_path,
            name="POST /v2/login",
            json={"username": self.username, "password": "bench", "csrf": csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 without Location")
                    return False
                resp.success()
                redirect_path = self._resolve(login_path, location)
                with self.client.get(
                    redirect_path,
                    name="GET /v2/login redirect",
                    catch_response=True,
                    allow_redirects=False,
                ) as resp2:
                    return self._handle_login_response(resp2)

            return self._handle_login_response(resp)

    def _fresh_login(self):
        return self._login()

    def _validate_catalog_json(self, resp):
        try:
            resp.json()
            return True
        except Exception as e:
            resp.failure(f"invalid catalog json: {e}")
            return False

    def _collect_products(self, obj, out):
        if isinstance(obj, dict):
            if "variants" in obj and "id" in obj:
                out.append(obj)
            for key in ("data", "products", "product", "items", "results"):
                if key in obj:
                    self._collect_products(obj[key], out)
        elif isinstance(obj, list):
            for item in obj:
                self._collect_products(item, out)

    def _find_in_stock(self, payload):
        products = []
        self._collect_products(payload, products)

        seen = set()
        for product in products:
            product_id = product.get("id")
            if product_id is None or product_id in seen:
                continue
            seen.add(product_id)

            variants = product.get("variants")
            if not isinstance(variants, list):
                continue

            for variant in variants:
                if (
                    isinstance(variant, dict)
                    and variant.get("in_stock") is True
                    and variant.get("id") is not None
                ):
                    return product_id, variant["id"]

        return None

    def _select_product(self):
        resp = self._req(
            "GET",
            "/v2/catalog",
            name="GET /v2/catalog",
            expected=(200,),
            validate=self._validate_catalog_json,
            cart_id=None,
        )
        if resp is not None:
            try:
                data = resp.json()
            except Exception:
                data = None
            found = self._find_in_stock(data)
            if found:
                return found

        current_path = "/v2/catalog/page"
        for _ in range(3):
            resp = self._req(
                "GET",
                current_path,
                name="GET /v2/catalog/page",
                expected=(200,),
                validate=self._validate_catalog_json,
                cart_id=None,
            )
            if resp is None:
                return None

            try:
                data = resp.json()
            except Exception:
                return None

            found = self._find_in_stock(data)
            if found:
                return found

            nxt = data.get("next") if isinstance(data, dict) else None
            if not nxt:
                break
            current_path = self._resolve(current_path, nxt)

        return None

    def _get_challenge_grant(self):
        with self.client.get(
            "/v2/challenge-form",
            name="GET /v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge form status {resp.status_code}: {resp.text[:200]}")
                return None

            action, challenge = parse_challenge(resp.text)
            if not action or not challenge:
                resp.failure("challenge form missing action or challenge")
                return None
            resp.success()

        action_path = self._resolve("/v2/challenge-form", action)

        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            action_path,
            name="POST /v2/challenges/[id]",
            json={"challenge": challenge},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 302:
                resp.failure(f"challenge status {resp.status_code}: {resp.text[:200]}")
                return None

            location = resp.headers.get("Location")
            if not location:
                resp.failure("challenge 302 without Location")
                return None
            resp.success()

        redirect_path = self._resolve(action_path, location)

        with self.client.get(
            redirect_path,
            name="GET /v2/challenges/[id] redirect",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge redirect status {resp.status_code}: {resp.text[:200]}")
                return None

            try:
                data = resp.json()
            except Exception as e:
                resp.failure(f"challenge invalid json: {e}")
                return None

            grant_id = data.get("grant_id") if isinstance(data, dict) else None
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]

            if not grant_id:
                resp.failure("challenge missing grant_id")
                return None

            resp.success()
            return grant_id

    def _create_cart(self, product_id, variant_id):
        self.cart_id = None
        self.cart_etag = None
        body = {"product_id": product_id, "variant_id": variant_id}

        def validate_cart(resp):
            if resp.status_code != 201:
                return True

            try:
                data = resp.json()
            except Exception as e:
                resp.failure(f"invalid cart json: {e}")
                return False

            cart_id = data.get("id") if isinstance(data, dict) else None
            if not cart_id:
                resp.failure("cart missing id")
                return False

            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]

            self.cart_id = cart_id
            self.cart_etag = resp.headers.get("ETag")
            return True

        resp = self._req(
            "POST",
            "/v2/carts",
            name="POST /v2/carts",
            json_body=body,
            expected=(201, 403, 409),
            validate=validate_cart,
            cart_id=None,
        )
        if resp is None:
            return False
        if resp.status_code == 201:
            return True

        grant_id = self._get_challenge_grant()
        if not grant_id:
            return False

        body_with_grant = dict(body)
        body_with_grant["grant_id"] = grant_id
        resp = self._req(
            "POST",
            "/v2/carts",
            name="POST /v2/carts with grant",
            json_body=body_with_grant,
            expected=(201,),
            validate=validate_cart,
            cart_id=None,
        )
        return resp is not None

    def _find_key(self, obj, key):
        if isinstance(obj, dict):
            if key in obj:
                return obj[key]
            for value in obj.values():
                found = self._find_key(value, key)
                if found is not None:
                    return found
        elif isinstance(obj, list):
            for item in obj:
                found = self._find_key(item, key)
                if found is not None:
                    return found
        return None

    def _get_cart_verify(self, product_id=None, variant_id=None):
        path = f"/v2/carts/{self.cart_id}"

        def validate(resp):
            etag = resp.headers.get("ETag")
            if etag:
                self.cart_etag = etag

            try:
                data = resp.json()
            except Exception:
                data = {}

            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]

            if product_id is not None:
                value = self._find_key(data, "product_id")
                if value is not None and value != product_id:
                    resp.failure(f"cart product mismatch {value} != {product_id}")
                    return False

            if variant_id is not None:
                value = self._find_key(data, "variant_id")
                if value is not None and value != variant_id:
                    resp.failure(f"cart variant mismatch {value} != {variant_id}")
                    return False

            return True

        resp = self._req(
            "GET",
            path,
            name="GET /v2/carts/[id]",
            expected=(200,),
            validate=validate,
            cart_id=self.cart_id,
        )
        return resp is not None

    def _patch_quantity(self):
        payload = {"quantity": 1}

        def validate(resp):
            if resp.status_code == 412:
                return True

            etag = resp.headers.get("ETag")
            if etag:
                self.cart_etag = etag

            try:
                data = resp.json()
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
            except Exception:
                pass

            return True

        headers = {}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        resp = self._req(
            "PATCH",
            f"/v2/carts/{self.cart_id}",
            name="PATCH /v2/carts/[id]",
            json_body=payload,
            headers=headers,
            expected=(200, 204, 412),
            validate=validate,
            cart_id=self.cart_id,
        )
        if resp is None:
            return False

        if resp.status_code == 412:
            if not self._get_cart_verify(None, None):
                return False

            headers = {}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            resp = self._req(
                "PATCH",
                f"/v2/carts/{self.cart_id}",
                name="PATCH /v2/carts/[id] retry",
                json_body=payload,
                headers=headers,
                expected=(200, 204),
                validate=validate,
                cart_id=self.cart_id,
            )
            if resp is None:
                return False

        return self._get_cart_verify(None, None)

    def _poll_reservation(self, status_url):
        for attempt in range(5):
            if attempt > 0:
                gevent.sleep(0.06)

            final_poll = attempt == 4

            def validate(resp, final=final_poll):
                try:
                    data = resp.json()
                except Exception as e:
                    resp.failure(f"invalid reservation status json: {e}")
                    return False

                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]

                status = data.get("status") if isinstance(data, dict) else None
                if status == "ready":
                    reservation_id = data.get("reservation_id")
                    if not reservation_id:
                        resp.failure("ready reservation missing reservation_id")
                        return False
                    self.reservation_id = reservation_id
                    return True

                if status == "failed":
                    resp.failure("reservation failed")
                    return False

                if status == "pending":
                    if final:
                        resp.failure("reservation still pending after 5 polls")
                        return False
                    return True

                resp.failure(f"unknown reservation status {status}")
                return False

            resp = self._req(
                "GET",
                status_url,
                name="GET /v2/reservations/status",
                expected=(200,),
                validate=validate,
                cart_id=self.cart_id,
            )
            if resp is None:
                return None

            if self.reservation_id:
                return self.reservation_id

        return None

    def _reserve_and_poll(self):
        self.reservation_id = None
        self._status_url = None

        def validate(resp):
            try:
                data = resp.json()
            except Exception as e:
                resp.failure(f"invalid reservation json: {e}")
                return False

            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]

            status_url = data.get("status_url") if isinstance(data, dict) else None
            if not status_url:
                resp.failure("reservation missing status_url")
                return False

            self._status_url = self._resolve("/v2/reservations", status_url)
            return True

        resp = self._req(
            "POST",
            "/v2/reservations",
            name="POST /v2/reservations",
            json_body={"cart_id": self.cart_id},
            expected=(202,),
            validate=validate,
            cart_id=self.cart_id,
        )
        if resp is None or not self._status_url:
            return False

        return self._poll_reservation(self._status_url) is not None

    def _place_order(self):
        if not self.cart_id or not self.reservation_id:
            return False

        idempotency_key = f"order-{self.cart_id}-{uuid.uuid4().hex}"
        payload = {
            "cart_id": self.cart_id,
            "reservation_id": self.reservation_id,
        }

        def validate(resp):
            if resp.status_code == 412:
                return True

            if resp.status_code == 200:
                resp.failure("order accepted:false")
                return False

            if resp.status_code == 201:
                try:
                    data = resp.json()
                except Exception as e:
                    resp.failure(f"invalid order json: {e}")
                    return False

                if not isinstance(data, dict) or data.get("accepted") is not True:
                    resp.failure(f"order not accepted: {data}")
                    return False

                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True

            return True

        headers = {"Idempotency-Key": idempotency_key}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        resp = self._req(
            "POST",
            "/v2/orders",
            name="POST /v2/orders",
            json_body=payload,
            headers=headers,
            expected=(201, 200, 412),
            validate=validate,
            cart_id=self.cart_id,
        )
        if resp is None:
            return False

        if resp.status_code == 412:
            if not self._get_cart_verify(None, None):
                return False

            headers = {"Idempotency-Key": idempotency_key}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            resp = self._req(
                "POST",
                "/v2/orders",
                name="POST /v2/orders retry",
                json_body=payload,
                headers=headers,
                expected=(201, 200),
                validate=validate,
                cart_id=self.cart_id,
            )
            if resp is None:
                return False

        return True

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.reservation_id = None
        self._status_url = None

        if not self._login():
            return False

        selected = self._select_product()
        if not selected:
            return False

        product_id, variant_id = selected

        if not self._create_cart(product_id, variant_id):
            return False

        if not self._get_cart_verify(product_id, variant_id):
            return False

        if not self._patch_quantity():
            return False

        if not self._reserve_and_poll():
            return False

        if not self._place_order():
            return False

        return True

