import os
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

import gevent
from locust import HttpUser, LoadTestShape
from locust.exception import StopUser

DEFAULT_HOST = "http://127.0.0.1:8000"
USERS = 2
ITERATIONS_PER_USER = 2
MAX_POLLS = 5
POLL_GAP = 0.06

_finished_users = 0
_account_seq = 0


def _next_account():
    global _account_seq
    _account_seq += 1
    if _account_seq <= 16:
        return "bench-%d" % _account_seq
    return "bench"


class _FormParser(HTMLParser):
    """Collects forms and their inputs, tolerant of attribute order/case/quoting."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.orphans = []
        self._stack = []

    def handle_starttag(self, tag, attrs):
        tag = (tag or "").lower()
        amap = {}
        for key, value in attrs:
            if key is None:
                continue
            amap[key.lower()] = "" if value is None else value
        if tag == "form":
            form = {"action": amap.get("action") or "", "inputs": []}
            self.forms.append(form)
            self._stack.append(form)
        elif tag == "input":
            entry = {
                "name": (amap.get("name") or "").strip().lower(),
                "value": amap.get("value"),
                "type": (amap.get("type") or "").strip().lower(),
            }
            if self._stack:
                self._stack[-1]["inputs"].append(entry)
            else:
                self.orphans.append(entry)

    def handle_endtag(self, tag):
        if (tag or "").lower() == "form" and self._stack:
            self._stack.pop()


def _csrf_candidates(html):
    parser = _FormParser()
    parser.feed(html or "")
    scored = []
    for form in parser.forms:
        action = (form["action"] or "").lower()
        names = {entry["name"] for entry in form["inputs"]}
        for entry in form["inputs"]:
            if entry["name"] != "csrf" or not entry["value"]:
                continue
            score = 0
            if "login" in action:
                score += 8
            if names & {"username", "password", "user", "pass", "email"}:
                score += 4
            if entry["type"] == "hidden":
                score += 2
            scored.append((score, entry["value"]))
    for entry in parser.orphans:
        if entry["name"] == "csrf" and entry["value"]:
            scored.append((1 if entry["type"] == "hidden" else 0, entry["value"]))
    scored.sort(key=lambda item: -item[0])
    result = []
    seen = set()
    for _, value in scored:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result


def _challenge_form(html):
    parser = _FormParser()
    parser.feed(html or "")
    best = None
    for form in parser.forms:
        values = {entry["name"]: entry["value"] for entry in form["inputs"] if entry["value"]}
        token = values.get("challenge")
        if not token:
            continue
        action = form["action"] or ""
        score = 2 if "challenge" in action.lower() else (1 if action else 0)
        if best is None or score > best[0]:
            best = (score, action, token)
    if best is not None and best[1]:
        return best[1], best[2]
    for form in parser.forms:
        for entry in form["inputs"]:
            if entry["name"] == "challenge" and entry["value"]:
                return form["action"] or "", entry["value"]
    for entry in parser.orphans:
        if entry["name"] == "challenge" and entry["value"]:
            return "", entry["value"]
    return None, None


def _in_stock(variant):
    value = variant.get("in_stock")
    if value is True:
        return True
    if isinstance(value, str) and value.strip().lower() in ("true", "1", "yes"):
        return True
    if isinstance(value, int) and not isinstance(value, bool) and value == 1:
        return True
    return False


def _iter_products(node):
    if isinstance(node, dict):
        if isinstance(node.get("variants"), list) and node.get("id") is not None:
            yield node
            return
        for value in node.values():
            if isinstance(value, (dict, list)):
                yield from _iter_products(value)
    elif isinstance(node, list):
        for item in node:
            yield from _iter_products(item)


def _pick_variant(payload):
    """Pair a product id with one of ITS OWN in-stock variant ids, order-independent."""
    for product in _iter_products(payload):
        product_id = product.get("id")
        if product_id is None:
            continue
        for variant in product.get("variants", []):
            if not isinstance(variant, dict):
                continue
            variant_id = variant.get("id")
            if variant_id is None:
                continue
            if _in_stock(variant):
                return product_id, variant_id
    return None


def _deep_get(node, key):
    if isinstance(node, dict):
        if key in node:
            return True, node[key]
        for value in node.values():
            if isinstance(value, (dict, list)):
                found, result = _deep_get(value, key)
                if found:
                    return found, result
    elif isinstance(node, list):
        for item in node:
            found, result = _deep_get(item, key)
            if found:
                return found, result
    return False, None


def _extract(node, key):
    if isinstance(node, dict):
        if key in node:
            return True, node[key]
        for container in ("reservation", "data", "result", "cart", "page"):
            inner = node.get(container)
            if isinstance(inner, dict):
                found, value = _extract(inner, key)
                if found:
                    return found, value
    return _deep_get(node, key)


def _next_ref(payload):
    if isinstance(payload, dict):
        value = payload.get("next")
        if isinstance(value, str) and value:
            return value
        for container in ("data", "page", "meta"):
            inner = payload.get(container)
            if isinstance(inner, dict):
                found = _next_ref(inner)
                if found:
                    return found
    return None


def _link_error(payload, product_id, variant_id):
    found, product = _extract(payload, "product_id")
    if not found:
        found, obj = _extract(payload, "product")
        if found and isinstance(obj, dict) and obj.get("id") is not None:
            product = obj["id"]
        else:
            found = False
    if found and product is not None and str(product) != str(product_id):
        return "product %s != %s" % (product, product_id)

    found, variant = _extract(payload, "variant_id")
    if not found:
        found, obj = _extract(payload, "variant")
        if found and isinstance(obj, dict) and obj.get("id") is not None:
            variant = obj["id"]
        else:
            found = False
    if found and variant is not None and str(variant) != str(variant_id):
        return "variant %s != %s" % (variant, variant_id)
    return None


class FlowShape(LoadTestShape):
    def tick(self):
        if _finished_users >= USERS:
            return None
        if self.get_run_time() > 120:
            return None
        return (USERS, 2.0)


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", DEFAULT_HOST)

    def on_start(self):
        self._account = _next_account()
        self._reset()

    def _reset(self):
        self._csrf = None
        self._cart_id = None
        self._cart_etag = None
        self._reservation_id = None
        self._status_path = None

    def run(self):
        global _finished_users
        try:
            for _ in range(ITERATIONS_PER_USER):
                try:
                    self._journey()
                except Exception:
                    pass
        finally:
            _finished_users += 1
        raise StopUser()

    @staticmethod
    def _as_path(url):
        if not url:
            return url
        if url.startswith("http://") or url.startswith("https://"):
            parsed = urlparse(url)
            path = parsed.path or "/"
            if parsed.query:
                path = path + "?" + parsed.query
            return path
        if not url.startswith("/"):
            return "/" + url
        return url

    def _absolute_path(self, base_path, ref):
        if not ref:
            return ref
        if ref.startswith("http://") or ref.startswith("https://") or ref.startswith("/"):
            return self._as_path(ref)
        base = self.host.rstrip("/") + (base_path if base_path.startswith("/") else "/" + base_path)
        return self._as_path(urljoin(base, ref))

    @staticmethod
    def _json(resp):
        try:
            return resp.json()
        except Exception:
            return None

    @staticmethod
    def _error_code(resp):
        data = ShopUser._json(resp)
        code = ""
        if isinstance(data, dict):
            err = data.get("error")
            if isinstance(err, dict):
                err = err.get("code") or err.get("id") or err.get("error")
            if isinstance(err, str):
                code = err
            elif isinstance(data.get("code"), str):
                code = data["code"]
        if not code:
            text = (resp.text or "").lower()
            for candidate in ("denied", "expired", "session"):
                if candidate in text:
                    code = candidate
                    break
        return code

    @staticmethod
    def _kind(code):
        text = (code or "").lower()
        if "denied" in text:
            return "denied"
        if "expired" in text:
            return "expired"
        if "session" in text:
            return "session"
        return text

    def _request(self, method, path, name=None, json_body=None, headers=None,
                 expected=(200,), validate=None, allow_redirects=False,
                 retry_auth=True, cart_id=None):
        path = self._as_path(path)
        hdrs = dict(headers or {})
        if self._csrf and method.upper() != "GET":
            hdrs.setdefault("X-CSRF-Token", self._csrf)
        kwargs = {}
        if json_body is not None:
            kwargs["json"] = json_body

        with self.client.request(method, path, name=name or path, headers=hdrs,
                                 catch_response=True,
                                 allow_redirects=allow_redirects,
                                 **kwargs) as resp:
            if resp.status_code == 401 and retry_auth:
                kind = self._kind(self._error_code(resp))
                if kind in ("expired", "session"):
                    if self._recover(kind, cart_id):
                        resp.success()
                        return self._request(method, path, name=name,
                                             json_body=json_body, headers=headers,
                                             expected=expected, validate=validate,
                                             allow_redirects=allow_redirects,
                                             retry_auth=False, cart_id=cart_id)
                    resp.failure("auth recovery failed (%s)" % kind)
                    return None
                resp.failure("401 %s" % (kind or "unknown"))
                return None

            if resp.status_code not in expected:
                resp.failure("unexpected %s on %s %s" %
                             (resp.status_code, method, path))
                return None

            if validate is not None and validate(resp) is False:
                return None

            resp.success()
            return resp

    def _renew(self):
        hdrs = {}
        if self._csrf:
            hdrs["X-CSRF-Token"] = self._csrf
        with self.client.post("/v2/session/renew", name="POST /v2/session/renew",
                              json={}, headers=hdrs, catch_response=True,
                              allow_redirects=False) as resp:
            if resp.status_code == 200:
                data = self._json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self._csrf = data["csrf"]
                resp.success()
                return True
            resp.success()
            return False

    def _recover_cart(self, cart_id):
        hdrs = {}
        if self._csrf:
            hdrs["X-CSRF-Token"] = self._csrf
        with self.client.post("/v2/carts/%s/recover" % cart_id,
                              name="POST /v2/carts/[id]/recover", json={},
                              headers=hdrs, catch_response=True,
                              allow_redirects=False) as resp:
            if resp.status_code in (200, 201, 204):
                data = self._json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self._csrf = data["csrf"]
                resp.success()
                return True
            resp.success()
            return False

    def _recover(self, kind, cart_id):
        if kind == "expired" and self._csrf and self._renew():
            if not cart_id:
                return True
            return self._recover_cart(cart_id)
        if not self._login():
            return False
        if not cart_id:
            return True
        return self._recover_cart(cart_id)

    def _login(self):
        tried = set()
        for _ in range(3):
            with self.client.get("/v2/login-form", name="GET /v2/login-form",
                                 catch_response=True, allow_redirects=False) as resp:
                if resp.status_code != 200:
                    resp.failure("login form status %s" % resp.status_code)
                    return False
                candidates = _csrf_candidates(resp.text)
                resp.success()

            token = None
            for candidate in candidates:
                if candidate not in tried:
                    token = candidate
                    break
            if token is None:
                return False
            tried.add(token)

            self._csrf = None
            payload = {"username": self._account, "password": "bench", "csrf": token}
            with self.client.post("/v2/login", name="POST /v2/login", json=payload,
                                  catch_response=True, allow_redirects=False) as resp:
                status = resp.status_code
                if status == 302:
                    location = resp.headers.get("Location")
                    if not location:
                        resp.failure("login 302 without Location")
                        return False
                    resp.success()
                    target = self._absolute_path("/v2/login", location)
                    with self.client.get(target, name="GET /v2/login redirect",
                                         catch_response=True,
                                         allow_redirects=False) as redirect:
                        if redirect.status_code != 200:
                            redirect.failure("login redirect status %s" %
                                             redirect.status_code)
                            return False
                        data = self._json(redirect)
                        if not isinstance(data, dict) or not data.get("csrf"):
                            redirect.failure("login redirect missing csrf")
                            return False
                        redirect.success()
                        self._csrf = data["csrf"]
                        return True

                if status == 200:
                    data = self._json(resp)
                    if not isinstance(data, dict) or not data.get("csrf"):
                        resp.failure("login response missing csrf")
                        return False
                    resp.success()
                    self._csrf = data["csrf"]
                    return True

                remaining = [c for c in candidates if c not in tried]
                if status in (400, 403, 409, 422) and remaining:
                    resp.success()
                    continue
                resp.failure("login status %s" % status)
                return False
        return False

    def _catalog_fetch(self, path, name):
        resp = self._request("GET", path, name=name, expected=(200,), cart_id=None)
        if resp is None:
            return None, None
        data = self._json(resp)
        if data is None:
            return None, None
        return _pick_variant(data), _next_ref(data)

    def _select_variant(self):
        picked, nxt = self._catalog_fetch("/v2/catalog", "GET /v2/catalog")
        if picked:
            return picked
        path = nxt
        for _ in range(3):
            target = self._absolute_path("/v2/catalog", path) if path else "/v2/catalog/page"
            picked, nxt = self._catalog_fetch(target, "GET /v2/catalog/page")
            if picked:
                return picked
            if not nxt:
                return None
            path = nxt
        return None

    def _get_grant(self):
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form",
                             catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                if resp.status_code >= 500:
                    resp.failure("challenge form status %s" % resp.status_code)
                else:
                    resp.success()
                return None
            action, token = _challenge_form(resp.text)
            resp.success()
        if not action or not token:
            return None

        action_path = self._absolute_path("/v2/challenge-form", action)
        hdrs = {}
        if self._csrf:
            hdrs["X-CSRF-Token"] = self._csrf
        with self.client.post(action_path, name="POST /v2/challenges/[id]",
                              json={"challenge": token}, headers=hdrs,
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 302:
                resp.success()
                return None
            location = resp.headers.get("Location")
            resp.success()
        if not location:
            return None

        target = self._absolute_path(action_path, location)
        with self.client.get(target, name="GET /v2/challenges/[id] grant",
                             catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.success()
                return None
            data = self._json(resp)
            resp.success()
        if not isinstance(data, dict):
            return None
        if data.get("csrf"):
            self._csrf = data["csrf"]
        grant = data.get("grant_id")
        if isinstance(grant, str) and grant:
            return grant
        return None

    def _cart_validate(self, resp):
        if resp.status_code != 201:
            return True
        data = self._json(resp)
        if not isinstance(data, dict) or not data.get("id"):
            resp.failure("cart creation missing id")
            return False
        if data.get("csrf"):
            self._csrf = data["csrf"]
        self._cart_id = data["id"]
        etag = resp.headers.get("ETag")
        if etag:
            self._cart_etag = etag
        return True

    def _create_cart(self, product_id, variant_id):
        base = {"product_id": product_id, "variant_id": variant_id}

        def post(body, final):
            expected = (201,) if final else (201, 400, 403, 409, 422, 428)
            return self._request("POST", "/v2/carts", name="POST /v2/carts",
                                 json_body=body, expected=expected,
                                 validate=self._cart_validate, cart_id=None)

        grant = self._get_grant()
        if not grant:
            resp = post(base, final=True)
            return resp is not None and resp.status_code == 201 and self._cart_id

        body = dict(base)
        body["grant_id"] = grant
        resp = post(body, final=False)
        if resp is not None and resp.status_code == 201:
            return bool(self._cart_id)

        fresh = self._get_grant()
        if fresh:
            body = dict(base)
            body["grant_id"] = fresh
            resp = post(body, final=False)
            if resp is not None and resp.status_code == 201:
                return bool(self._cart_id)

        if resp is not None and resp.status_code in (400, 422):
            resp = post(base, final=True)
            return resp is not None and resp.status_code == 201 and self._cart_id
        return False

    def _verify_cart(self, product_id, variant_id):
        path = "/v2/carts/%s" % self._cart_id

        def validate(resp):
            etag = resp.headers.get("ETag")
            if etag:
                self._cart_etag = etag
            data = self._json(resp)
            if isinstance(data, dict) and data.get("csrf"):
                self._csrf = data["csrf"]
            if data is None:
                return True
            problem = _link_error(data, product_id, variant_id)
            if problem:
                resp.failure("cart linkage broken: %s" % problem)
                return False
            return True

        return self._request("GET", path, name="GET /v2/carts/[id]",
                             expected=(200,), validate=validate,
                             cart_id=self._cart_id) is not None

    def _refresh_cart(self):
        path = "/v2/carts/%s" % self._cart_id

        def validate(resp):
            etag = resp.headers.get("ETag")
            if etag:
                self._cart_etag = etag
            data = self._json(resp)
            if isinstance(data, dict) and data.get("csrf"):
                self._csrf = data["csrf"]
            return True

        return self._request("GET", path, name="GET /v2/carts/[id]",
                             expected=(200,), validate=validate,
                             cart_id=self._cart_id) is not None

    def _patch_cart(self):
        path = "/v2/carts/%s" % self._cart_id

        def validate(resp):
            etag = resp.headers.get("ETag")
            if etag:
                self._cart_etag = etag
            data = self._json(resp)
            if isinstance(data, dict) and data.get("csrf"):
                self._csrf = data["csrf"]
            return True

        def do_patch(expected):
            hdrs = {}
            if self._cart_etag:
                hdrs["If-Match"] = self._cart_etag
            return self._request("PATCH", path, name="PATCH /v2/carts/[id]",
                                 json_body={"quantity": 1}, headers=hdrs,
                                 expected=expected, validate=validate,
                                 cart_id=self._cart_id)

        resp = do_patch((200, 204, 412))
        if resp is None:
            return False
        if resp.status_code == 412:
            if not self._refresh_cart():
                return False
            resp = do_patch((200, 204))
            if resp is None:
                return False
        return True

    def _reserve(self):
        self._reservation_id = None
        self._status_path = None

        def validate(resp):
            data = self._json(resp)
            if not isinstance(data, dict):
                resp.failure("reservation response invalid")
                return False
            if data.get("csrf"):
                self._csrf = data["csrf"]
            found, status_url = _extract(data, "status_url")
            if not found or not isinstance(status_url, str) or not status_url:
                resp.failure("reservation missing status_url")
                return False
            self._status_path = self._absolute_path("/v2/reservations", status_url)
            return True

        resp = self._request("POST", "/v2/reservations",
                             name="POST /v2/reservations",
                             json_body={"cart_id": self._cart_id},
                             expected=(202,), validate=validate,
                             cart_id=self._cart_id)
        if resp is None or not self._status_path:
            return False

        for attempt in range(MAX_POLLS):
            if attempt:
                gevent.sleep(POLL_GAP)
            last = attempt == MAX_POLLS - 1

            def check(resp, final=last):
                data = self._json(resp)
                if not isinstance(data, dict):
                    resp.failure("reservation status invalid")
                    return False
                if data.get("csrf"):
                    self._csrf = data["csrf"]
                found, status = _extract(data, "status")
                status = status if found else None
                if status == "ready":
                    found, rid = _extract(data, "reservation_id")
                    if not found or not rid:
                        resp.failure("ready reservation missing id")
                        return False
                    self._reservation_id = rid
                    return True
                if status in ("pending", "processing", "queued", "waiting"):
                    if final:
                        resp.failure("reservation not ready after %d polls" % MAX_POLLS)
                        return False
                    return True
                resp.failure("reservation status %r" % (status,))
                return False

            resp = self._request("GET", self._status_path,
                                 name="GET /v2/reservations/status",
                                 expected=(200,), validate=check,
                                 cart_id=self._cart_id)
            if resp is None:
                return False
            if self._reservation_id:
                return True
        return False

    def _order_validate(self, resp):
        if resp.status_code == 200:
            resp.failure("order rejected (200 accepted:false)")
            return False
        if resp.status_code in (412, 428):
            return True
        if resp.status_code != 201:
            return True
        data = self._json(resp)
        if not isinstance(data, dict) or data.get("accepted") is not True:
            resp.failure("order not accepted")
            return False
        if data.get("csrf"):
            self._csrf = data["csrf"]
        return True

    def _place_order(self):
        payload = {"cart_id": self._cart_id,
                   "reservation_id": self._reservation_id}
        idem = "order-%s-%s" % (self._cart_id, uuid.uuid4().hex)

        def send(expected):
            hdrs = {"Idempotency-Key": idem}
            if self._cart_etag:
                hdrs["If-Match"] = self._cart_etag
            return self._request("POST", "/v2/orders", name="POST /v2/orders",
                                 json_body=payload, headers=hdrs,
                                 expected=expected,
                                 validate=self._order_validate,
                                 cart_id=self._cart_id)

        resp = send((201, 200, 412, 428))
        if resp is None:
            return False
        if resp.status_code in (412, 428):
            if not self._refresh_cart():
                return False
            resp = send((201, 200))
            if resp is None:
                return False
        return resp.status_code == 201

    def _journey(self):
        self._reset()
        if not self._login():
            return False
        selected = self._select_variant()
        if not selected:
            return False
        product_id, variant_id = selected
        if not self._create_cart(product_id, variant_id):
            return False
        if not self._verify_cart(product_id, variant_id):
            return False
        if not self._patch_cart():
            return False
        if not self._reserve():
            return False
        return self._place_order()

