    private static Iterator<Map<String, Object>> accountFeeder() {
        final List<Map<String, Object>> accounts = new ArrayList<>();
        for (int i = 1; i <= 16; i++) {
            Map<String, Object> m = new HashMap<>();
            m.put("username", "bench-" + i);
            accounts.add(m);
        }
        return new Iterator<Map<String, Object>>() {
            private final AtomicInteger idx = new AtomicInteger(0);

            @Override
            public boolean hasNext() {
                return true;
            }

            @Override
            public Map<String, Object> next() {
                int i = idx.getAndIncrement() % accounts.size();
                return new HashMap<>(accounts.get(i));
            }
        };
    }

    private static Session updateCsrf(Session session, String body) {
        if (body == null || body.isEmpty()) {
            return session;
        }
        try {
            String csrf = Json.getString(Json.parse(body), "csrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
        } catch (Exception ignored) {
        }
        return session;
    }

    private static String extractInputValue(String html, String name) {
        if (html == null) {
            return null;
        }
        Pattern p = Pattern.compile("(?is)<input\\b[^>]*>");
        Matcher m = p.matcher(html);
        while (m.find()) {
            Map<String, String> attrs = parseAttrs(m.group());
            String n = attrs.get("name");
            if (n != null && n.equalsIgnoreCase(name)) {
                String v = attrs.get("value");
                if (v != null) {
                    return v;
                }
            }
        }
        return null;
    }

    private static Map<String, String> parseAttrs(String tag) {
        Map<String, String> map = new HashMap<>();
        Pattern p = Pattern.compile("([a-zA-Z0-9_:-]+)\\s*=\\s*(\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");
        Matcher m = p.matcher(tag);
        while (m.find()) {
            String key = m.group(1).toLowerCase();
            String val = m.group(3) != null ? m.group(3) : (m.group(4) != null ? m.group(4) : m.group(5));
            if (val != null) {
                map.put(key, val);
            }
        }
        return map;
    }

    private static String extractFormAction(String html) {
        if (html == null) {
            return null;
        }
        Pattern p = Pattern.compile("(?is)<form\\b[^>]*>");
        Matcher m = p.matcher(html);
        if (m.find()) {
            return parseAttrs(m.group()).get("action");
        }
        return null;
    }

    private static String extractChallengeAction(String html) {
        if (html == null) {
            return null;
        }
        Pattern p = Pattern.compile("(?i)action\\s*=\\s*[\"']?([^\"'\\s>]*/v2/challenges/[^\"'\\s>]+)");
        Matcher m = p.matcher(html);
        if (m.find()) {
            return m.group(1);
        }
        return extractFormAction(html);
    }

    private static String getNext(Object root) {
        if (root instanceof Map) {
            Map<?, ?> m = (Map<?, ?>) root;
            if (m.containsKey("next")) {
                Object n = m.get("next");
                if (n == null) {
                    return null;
                }
                if (n instanceof String) {
                    return (String) n;
                }
            }
            Object data = m.get("data");
            if (data instanceof Map) {
                Object n = ((Map<?, ?>) data).get("next");
                if (n == null) {
                    return null;
                }
                if (n instanceof String) {
                    return (String) n;
                }
            }
        }
        return null;
    }

    private static Selection findSelection(Object root) {
        if (root instanceof Map) {
            Map<?, ?> m = (Map<?, ?>) root;
            Object variantsObj = m.get("variants");
            if (variantsObj instanceof List && m.containsKey("id")) {
                Object pidObj = m.get("id");
                String pid = pidObj instanceof String ? (String) pidObj : null;
                if (pid != null) {
                    for (Object v : (List<?>) variantsObj) {
                        if (v instanceof Map) {
                            Map<?, ?> vm = (Map<?, ?>) v;
                            Object inStock = vm.get("in_stock");
                            boolean ok = Boolean.TRUE.equals(inStock);
                            if (!ok && inStock instanceof Number) {
                                ok = ((Number) inStock).doubleValue() != 0;
