  const idemKey = 'order-' + cartId + '-' + __VU + '-' + __ITER + '-' + Date.now();
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const url = BASE + '/v2/orders';

  function refreshCart() {
    let getRes = http.get(BASE + '/v2/carts/' + cartId, { redirects: 0 });
    if (getRes.status === 401) {
      const err = parseError(getRes);
      if (err !== 'denied') {
        const newCsrf = recoverSession(username, currentCsrf, cartId);
        if (newCsrf) {
          currentCsrf = newCsrf;
          getRes = http.get(BASE + '/v2/carts/' + cartId, { redirects: 0 });
        }
      }
    }
    if (getRes.status === 200) {
      currentEtag = header(getRes, 'etag') || currentEtag;
      const b = safeJson(getRes);
      currentCsrf = pickCsrf(b, currentCsrf);
    }
  }

  function doPost() {
    const extra = { 'Idempotency-Key': idemKey };
    if (currentEtag) extra['If-Match'] = currentEtag;
    return http.post(url, JSON.stringify(payload), authParams(currentCsrf, extra));
  }

  let res = doPost();

  if (res.status === 401) {
    const err = parseError(res);
    if (err !== 'denied') {
      const newCsrf = recoverSession(username, currentCsrf, cartId);
      if (newCsrf) {
        currentCsrf = newCsrf;
        refreshCart();
        res = doPost();
      }
    }
  }

  const body = safeJson(res);
  currentCsrf = pickCsrf(body, currentCsrf);
  return { res: res, csrf: currentCsrf, body: body };
}

export default function () {
  const perUser = ITERATIONS;
  const username = 'bench-' + (((__VU - 1) * perUser + __ITER) % 16 + 1);

  const loginResult = login(username, true);
  if (!loginResult) return;
  let csrf = loginResult.csrf;

  const eligible = findEligibleAcrossPages();
  if (!eligible) return;

  const grant = acquireGrant(csrf, username);
  csrf = grant.csrf;
  const grantId = grant.grant_id;

  const cartResult = createCart(eligible.product_id, eligible.variant_id, grantId, csrf, username);
  csrf = cartResult.csrf;
  check(cartResult.res, { 'cart created 201': r => r.status === 201 });
  const cartId = cartResult.cart_id;
  if (!cartId) return;

  const patchResult = setCartQuantity(cartId, csrf, username, cartResult.etag);
  csrf = patchResult.csrf;
  check(patchResult.res, { 'cart quantity patched': r => r.status >= 200 && r.status < 300 });
  const etag = patchResult.etag;

  const reservation = createReservation(cartId, csrf, username);
  csrf = reservation.csrf;
  if (!reservation.reservation_id) return;

  const orderResult = placeOrder(cartId, reservation.reservation_id, csrf, username, etag);
  csrf = orderResult.csrf;
  check(orderResult.res, { 'order committed 201': r => r.status === 201 });
  check(orderResult.body, { 'order accepted with id': b => !!(b && b.accepted === true && b.id) });
}
