from locust import HttpUser, task, LoadTestShape, constant
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2
COMPLETED_USERS = 0
USER_COUNTER = 0


def _json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _attrs(tag):
    attrs = {}
    for m in re.finditer(r"([\w:-]+)\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))", tag, re.I | re.S):
        key = m.group(1).lower()
        if m.group(2) is not None:
            val = m.group(2)
        elif m.group(3) is not None:
            val = m.group(3)
        else:
            val = m.group(4)
            if val.endswith("/"):
                val = val[:-1]
        attrs[key] = val
    return attrs


def _find_input(html, name):
    for tag in re.findall(r"<input\b[^>]*>", html or "", re.I | re.S):
        attrs = _attrs(tag)
        if attrs.get("name", "").lower() == name.lower():
            return attrs.get("value")
    return None


def _find_form_action(html, contains):
    for tag in re.findall(r"<form\b[^>]*>", html or "", re.I | re.S):
        attrs = _attrs(tag)
        action = attrs.get("action")
        if action and contains in action:
            return action
    return None


def _find_csrf_json(obj):
    if isinstance(obj, dict):
        if isinstance(obj.get("csrf"), str):
            return obj["csrf"]
        for v in obj.values():
            c = _find_csrf_json(v)
            if c:
                return c
    elif isinstance(obj, list):
        for v in obj:
            c = _find_csrf_json(v)
            if c:
                return c
    return None


def _find_grant(obj):
    if isinstance(obj, dict):
        if isinstance(obj.get("grant_id"), str):
            return obj["grant_id"]
        for v in obj.values():
            g = _find_grant(v)
            if g:
                return g
    elif isinstance(obj, list):
        for v in obj:
            g = _find_grant(v)
            if g:
                return g
    return None


def _find_product(obj):
    if isinstance(obj, dict):
        if "id" in obj and isinstance(obj.get("variants"), list):
            return obj
        for v in obj.values():
            p = _find_product(v)
            if p:
                return p
    elif isinstance(obj, list):
        for v in obj:
            p = _find_product(v)
            if p:
                return p
    return None


def _pick_variant(product):
    for v in product.get("variants", []):
        if isinstance(v, dict) and v.get("in_stock"):
            return v
    return None


def _next_from(obj):
    if isinstance(obj, dict):
        if "next" in obj:
            return obj["next"]
        data = obj.get("data")
        if isinstance(data, dict) and "next" in data:
            return data["next"]
    return None


def _error_code(resp):
    data = _json(resp)
    if isinstance(data, dict):
        err = data.get("error")
        if isinstance(err, dict):
            for key in ("code", "type", "error"):
                value = err.get(key)
                if isinstance(value, str):
                    return value
        elif isinstance(err, str):
            return err
    return None


class ContractShape(LoadTestShape):
    def tick(self):
        global COMPLETED_USERS
        if COMPLETED_USERS >= USERS:
            return None
        return (max(0, USERS - COMPLETED_USERS), USERS)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        global USER_COUNTER
        USER_COUNTER += 1
        self.username = f"bench-{USER_COUNTER}"
        self.csrf = None
        self.cart_etag = None

    @task
    def run_journeys(self):
        global COMPLETED_USERS
        try:
            for i in range(ITERATIONS):
                self.journey(i)
        finally:
            COMPLETED_USERS += 1
            raise StopUser()

    def _update_csrf(self, resp):
        data = _json(resp)
        csrf = _find_csrf_json(data)
        if not csrf:
            csrf = resp.headers.get("X-CSRF-Token") or resp.headers.get("x-csrf-token")
        if csrf:
            self.csrf = csrf

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return None
            csrf = _find_input(r.text, "csrf")
            if not csrf:
                r.failure("login csrf missing")
                return None
            r.success()

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": csrf},
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("login 302 without Location")
                    return None
                r.success()
                with self.client.get(
                    loc,
                    name="/v2/login-redirect",
                    allow_redirects=False,
                    catch_response=True,
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"login redirect status {r2.status_code}")
                        return None
                    data = _json(r2)
                    new_csrf = _find_csrf_json(data) or csrf
                    self.csrf = new_csrf
                    r2.success()
                    return new_csrf
            elif r.status_code in (200, 201):
                data = _json(r)
                new_csrf = _find_csrf_json(data) or csrf
                self.csrf = new_csrf
                r.success()
                return new_csrf
            else:
                r.failure(f"login status {r.status_code}")
                return None

    def _renew(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            name="/v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code in (200, 201):
                self._update_csrf(r)
                r.success()
                return True
            r.failure(f"renew status {r.status_code}")
            return False

    def _fresh_login(self):
        csrf = self._login()
        if csrf:
            self.csrf = csrf
            return True
        return False

    def _recover_cart(self, cart_id):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            f"/v2/carts/{cart_id}/recover",
            json={},
            headers=headers,
            name="/v2/carts/{id}/recover",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code in (200, 201, 204):
                self._update_csrf(r)
                r.success()
                return True
            r.failure(f"recover status {r.status_code}")
            return False

    def _get_grant(self):
        with self.client.get(
            "/v2/challenge-form",
            name="/v2/challenge-form",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return None
            action = _find_form_action(r.text, "/v2/challenges/")
            challenge = _find_input(r.text, "challenge")
            if not action or not challenge:
                r.failure("challenge form missing action/value")
                return None
            r.success()

        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            action,
            json={"challenge": challenge},
            headers=headers,
            name="/v2/challenges/{id}",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 without Location")
                    return None
                r.success()
                with self.client.get(
                    loc,
                    name="/v2/challenge-claim",
                    allow_redirects=False,
                    catch_response=True,
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"challenge claim status {r2.status_code}")
                        return None
                    data = _json(r2)
                    self._update_csrf(r2)
                    grant = _find_grant(data)
                    if not grant:
                        r2.failure("grant_id missing")
                        return None
                    r2.success()
                    return grant
            elif r.status_code in (200, 201):
                data = _json(r)
                self._update_csrf(r)
                grant = _find_grant(data)
                if not grant:
                    r.failure("grant_id missing")
                    return None
                r.success()
                return grant
            else:
                r.failure(f"challenge post status {r.status_code}")
                return None

    def _find_eligible(self):
        next_url = "/v2/catalog/page"
        for page in range(3):
            with self.client.get(
                next_url,
                name="/v2/catalog/page",
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page status {r.status_code}")
                    return None
                data = _json(r)
                product = _find_product(data)
                if product:
                    variant = _pick_variant(product)
                    if variant:
                        r.success()
                        return (product.get("id"), variant.get("id"))
                next_raw = _next_from(data)
                if next_raw in (None, "", False) or page == 2:
                    r.failure("no eligible product within pagination bound")
                    return None
                r.success()
            next_url = next_raw
        return None

    def _create_cart(self, product_id, variant_id, grant_id, retry=True):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=headers,
            name="/v2/carts",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                err = _error_code(r)
                if retry and err in ("expired", "session"):
                    r.success()
                    if err == "expired":
                        ok = self._renew()
                    else:
                        ok = self._fresh_login()
                    if not ok:
                        return None
                    return self._create_cart(product_id, variant_id, grant_id, retry=False)
                r.failure(f"cart 401 {err}")
                return None
            if r.status_code == 201:
                data = _json(r)
                cart_id = data.get("id") if isinstance(data, dict) else None
                if not cart_id:
                    r.failure("cart id missing")
                    return None
                self._update_csrf(r)
                self.cart_etag = r.headers.get("ETag") or r.headers.get("etag")
                r.success()
                return cart_id
            r.failure(f"cart status {r.status_code}")
            return None

    def _get_cart_etag(self, cart_id, retry=True):
        with self.client.get(
            f"/v2/carts/{cart_id}",
            name="/v2/carts/{id}",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                err = _error_code(r)
                if retry and err in ("expired", "session"):
                    r.success()
                    if err == "expired":
                        ok = self._renew()
                    else:
                        ok = self._fresh_login()
                    if not ok:
                        return None
                    self._recover_cart(cart_id)
                    return self._get_cart_etag(cart_id, retry=False)
                r.failure(f"cart get 401 {err}")
                return None
            if r.status_code == 200:
                self._update_csrf(r)
                etag = r.headers.get("ETag") or r.headers.get("etag")
                r.success()
                return etag
            r.failure(f"cart get status {r.status_code}")
            return None

    def _patch_quantity(self, cart_id, quantity=1, retry_412=True, retry_401=True):
        etag = self._get_cart_etag(cart_id)
        if etag:
            self.cart_etag = etag
        else:
            etag = self.cart_etag
        if not etag:
            return False

        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if etag:
            headers["If-Match"] = etag

        with self.client.patch(
            f"/v2/carts/{cart_id}",
            json={"quantity": quantity},
            headers=headers,
            name="/v2/carts/{id}",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                err = _error_code(r)
                if retry_401 and err in ("expired", "session"):
                    r.success()
                    if err == "expired":
                        ok = self._renew()
                    else:
                        ok = self._fresh_login()
                    if not ok:
                        return False
                    self._recover_cart(cart_id)
                    return self._patch_quantity(
                        cart_id,
                        quantity,
                        retry_412=retry_412,
                        retry_401=False,
                    )
                r.failure(f"patch 401 {err}")
                return False
            if r.status_code == 412 and retry_412:
                r.success()
                new_etag = self._get_cart_etag(cart_id)
                if new_etag:
                    self.cart_etag = new_etag
                return self._patch_quantity(
                    cart_id,
                    quantity,
                    retry_412=False,
                    retry_401=retry_401,
                )
            if r.status_code in (200, 204):
                self._update_csrf(r)
                new_etag = r.headers.get("ETag") or r.headers.get("etag")
                if new_etag:
                    self.cart_etag = new_etag
                r.success()
                return True
            r.failure(f"patch status {r.status_code}")
            return False

    def _reserve(self, cart_id, retry=True):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
