                    r.success()
                    if err == "expired":
                        ok = self._renew()
                    else:
                        ok = self._fresh_login()
                    if not ok:
                        return None
                    self._recover_cart(cart_id)
                    return self._reserve(cart_id, retry=False)
                r.failure(f"reservation 401 {err}")
                return None
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return None
            data = _json(r)
            status_url = data.get("status_url") if isinstance(data, dict) else None
            self._update_csrf(r)
            if not status_url:
                r.failure("reservation status_url missing")
                return None
            r.success()

        for attempt in range(5):
            if attempt:
                time.sleep(0.05)
            with self.client.get(
                status_url,
                name="/v2/reservations/{id}",
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code == 401:
                    err = _error_code(r)
                    if err in ("expired", "session"):
                        r.success()
                        if err == "expired":
                            ok = self._renew()
                        else:
                            ok = self._fresh_login()
                        if not ok:
                            return None
                        self._recover_cart(cart_id)
                        continue
                    r.failure(f"reservation poll 401 {err}")
                    return None
                if r.status_code != 200:
                    r.failure(f"reservation poll status {r.status_code}")
                    return None
                data = _json(r)
                status = data.get("status") if isinstance(data, dict) else None
                self._update_csrf(r)
                if status == "ready":
                    reservation_id = data.get("reservation_id") if isinstance(data, dict) else None
                    if not reservation_id:
                        r.failure("reservation_id missing")
                        return None
                    r.success()
                    return reservation_id
                if status == "failed":
                    r.failure("reservation failed")
                    return None
                if status == "pending":
                    if attempt == 4:
                        r.failure("reservation pending after 5 polls")
                        return None
                    r.success()
                    continue
                r.failure(f"reservation unknown status {status}")
                return None
        return None

    def _order(self, cart_id, reservation_id, idem_key, retry_401=True, retry_412=True):
        etag = self._get_cart_etag(cart_id)
        if etag:
            self.cart_etag = etag
        else:
            etag = self.cart_etag

        headers = {"Idempotency-Key": idem_key}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if etag:
            headers["If-Match"] = etag

        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            name="/v2/orders",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 401:
                err = _error_code(r)
                if retry_401 and err in ("expired", "session"):
                    r.success()
                    if err == "expired":
                        ok = self._renew()
                    else:
                        ok = self._fresh_login()
                    if not ok:
                        return None
                    self._recover_cart(cart_id)
                    return self._order(
                        cart_id,
                        reservation_id,
                        idem_key,
                        retry_401=False,
                        retry_412=retry_412,
                    )
                r.failure(f"order 401 {err}")
                return None
            if r.status_code == 412 and retry_412:
                r.success()
                new_etag = self._get_cart_etag(cart_id)
                if new_etag:
                    self.cart_etag = new_etag
                return self._order(
                    cart_id,
                    reservation_id,
                    idem_key,
                    retry_401=retry_401,
                    retry_412=False,
                )
            if r.status_code == 201:
                data = _json(r)
                accepted = data.get("accepted") if isinstance(data, dict) else None
                order_id = data.get("id") if isinstance(data, dict) else None
                if accepted is True and order_id:
                    self._update_csrf(r)
                    r.success()
                    return order_id
                r.failure(f"order 201 not accepted/id: {data}")
                return None
            if r.status_code == 200:
                data = _json(r)
                accepted = data.get("accepted") if isinstance(data, dict) else None
                if accepted is False:
                    r.failure("order business failure accepted:false")
                else:
                    r.failure(f"order status 200 unexpected: {data}")
                return None
            r.failure(f"order status {r.status_code}")
            return None

    def journey(self, iteration):
        csrf = self._login()
        if not csrf:
            return False
        self.csrf = csrf

        item = self._find_eligible()
        if not item:
            return False
        product_id, variant_id = item
        if product_id is None or variant_id is None:
            return False

        grant_id = self._get_grant()
        if grant_id is None:
            return False

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return False

        if not self._patch_quantity(cart_id, 1):
            return False

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return False

        idem_key = f"idem-{cart_id}"
        order_id = self._order(cart_id, reservation_id, idem_key)
        if not order_id:
            return False

        return True
