    private static String extractCsrf(String body) {
        if (body == null) {
            return null;
        }

        Matcher m = INPUT_NAME_FIRST.matcher(body);
        if (m.find()) {
            return m.group(1);
        }

        m = INPUT_VALUE_FIRST.matcher(body);
        if (m.find()) {
            return m.group(1);
        }

        m = META_CSRF.matcher(body);
        if (m.find()) {
            return m.group(1);
        }

        m = JSON_CSRF.matcher(body);
        if (m.find()) {
            return m.group(1);
        }

        return null;
    }

    private static String[] firstInStockProductVariant(String json) {
        if (json == null) {
            return null;
        }

        Matcher pm = PRODUCT_PATTERN.matcher(json);
        while (pm.find()) {
            String productId = pm.group(1);
            String variants = pm.group(2);

            Matcher vm = VARIANT_OBJECT_PATTERN.matcher(variants);
            while (vm.find()) {
                String variant = vm.group();
                if (IN_STOCK_TRUE_PATTERN.matcher(variant).find()) {
                    Matcher im = ID_PATTERN.matcher(variant);
                    if (im.find()) {
                        return new String[]{productId, im.group(1)};
                    }
                }
            }
        }

        return null;
    }
