import http from 'k6/http';
import { check } from 'k6';

function intEnv(name, def) {
  const n = Number(__ENV[name] || def);
  return isFinite(n) && n > 0 ? Math.floor(n) : def;
}

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const USERS = intEnv('USERS', 2);
const ITERATIONS = intEnv('ITERATIONS', 2);
const rawQuantity = Number(__ENV.QUANTITY || 2);
const QUANTITY = isFinite(rawQuantity) ? Math.max(1, Math.min(20, Math.floor(rawQuantity))) : 2;

export const options = {
  scenarios: {
    per_user: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '60s',
    },
  },
};

export default function () {
  const vu = typeof __VU !== 'undefined' ? __VU : 1;
  const userIndex = ((vu - 1) % 16) + 1;
  const state = {
    username: 'bench-' + userIndex,
    csrf: null,
    cartId: null,
    etag: null,
    idempotencyKey: null,
  };

  login(state);
  const selection = getCatalogSelection(state);
  createCart(state, selection.productId, selection.variantId);
  getCart(state);
  updateCartQuantity(state, QUANTITY);
  getCart(state);
  placeOrder(state);
}

function login(state) {
  const formRes = http.get(`${BASE}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  assertStatus(formRes, 'login form 200', (r) => r.status === 200);

  const csrf = extractInputValue(formRes.body, 'csrf');
  if (!csrf) throw new Error('login csrf missing');
  state.csrf = csrf;

  const payload = {
    username: state.username,
    password: 'bench',
    csrf: csrf,
  };

  let res = http.post(`${BASE}/v2/login`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });

  if (res.status === 302) {
    const loc = header(res, 'Location');
    const url = absoluteUrl(BASE, loc);
    if (!url) throw new Error('login redirect missing');
    res = http.get(url, {
      redirects: 0,
      tags: { name: 'login-redirect' },
    });
  }

  assertStatus(res, 'login success 200', (r) => r.status === 200 || r.status === 201);

  const body = safeJson(res);
  if (body && typeof body.csrf === 'string' && body.csrf.length) {
    state.csrf = body.csrf;
  } else {
    const htmlCsrf = extractInputValue(res.body || '', 'csrf');
    if (htmlCsrf) state.csrf = htmlCsrf;
  }
  if (!state.csrf) throw new Error('login did not provide csrf');
}

function getCatalogSelection(state) {
  let res = authRequest('GET', `${BASE}/v2/catalog`, null, {}, state, 'catalog');
  assertStatus(res, 'catalog 200', (r) => r.status === 200);

  let body = safeJson(res);
  let products = extractProducts(body);
  let selected = pickVariantFromProducts(products);
  let next = body && body.next;
  let pages = 0;

  while (!selected && next && pages < 3) {
    const url = absoluteUrl(BASE, next);
    res = authRequest('GET', url, null, {}, state, 'catalog-page');
    assertStatus(res, 'catalog page 200', (r) => r.status === 200);
    body = safeJson(res);
    products = extractProducts(body);
    selected = pickVariantFromProducts(products);
    next = body && body.next;
    pages++;
  }

  if (!selected) throw new Error('no in-stock product variant found');
  return selected;
}

function extractProducts(body) {
  const products = [];
  if (!body) return products;
  if (body.data && Array.isArray(body.data.products)) products.push.apply(products, body.data.products);
  if (body.data && body.data.product) products.push(body.data.product);
  if (body.product) products.push(body.product);
  if (Array.isArray(body.products)) products.push.apply(products, body.products);
  return products;
}

function pickVariantFromProducts(products) {
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || p.id === undefined || p.id === null) continue;
    const variants = p.variants || (p.variant ? [p.variant] : []);
    for (let j = 0; j < variants.length; j++) {
      const v = variants[j];
      if (v && v.id !== undefined && v.id !== null && variantInStock(v)) {
        return { productId: p.id, variantId: v.id };
      }
    }
  }

  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || p.id === undefined || p.id === null) continue;
    const variants = p.variants || (p.variant ? [p.variant] : []);
    for (let j = 0; j < variants.length; j++) {
      const v = variants[j];
      if (v && v.id !== undefined && v.id !== null) {
        return { productId: p.id, variantId: v.id };
      }
    }
  }
  return null;
}

function variantInStock(v) {
  return v.in_stock === true || v.in_stock === 1 || v.in_stock === 'true' || v.in_stock === '1';
}

function createCart(state, productId, variantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId,
  };

  let res = authRequest(
    'POST',
    `${BASE}/v2/carts`,
    payload,
    { headers: { 'Content-Type': 'application/json' } },
    state,
    'create-cart'
  );

  const err = (errorCode(res) || '').toLowerCase();
  if (
    res.status === 403 ||
    res.status === 428 ||
    (res.status === 400 && (err.indexOf('challenge') !== -1 || err.indexOf('grant') !== -1))
  ) {
    const grantId = getGrant(state);
    payload.grant_id = grantId;
    res = authRequest(
      'POST',
      `${BASE}/v2/carts`,
      payload,
      { headers: { 'Content-Type': 'application/json' } },
      state,
      'create-cart-grant'
    );
  }

  assertStatus(res, 'create cart 201', (r) => r.status === 201);
  const body = safeJson(res) || {};
  if (body.id === undefined || body.id === null) throw new Error('cart id missing');

  state.cartId = body.id;
  updateCsrfFromResponse(state, res);
  const etag = header(res, 'ETag');
  if (etag) state.etag = etag;
}

function getGrant(state) {
  let res = http.get(`${BASE}/v2/challenge-form`, {
    redirects: 0,
    tags: { name: 'challenge-form' },
  });
  assertStatus(res, 'challenge form 200', (r) => r.status === 200);

  const action = extractFormAction(res.body);
  const challenge = extractInputValue(res.body, 'challenge');
  if (!action) throw new Error('challenge action missing');
  if (!challenge) throw new Error('challenge value missing');

  const url = absoluteUrl(BASE, action);
  res = http.post(
    url,
    JSON.stringify({ challenge: challenge }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'challenge-submit' },
    }
  );

  if (res.status === 302) {
    const loc = header(res, 'Location');
    const locUrl = absoluteUrl(BASE, loc);
    if (!locUrl) throw new Error('challenge redirect missing');
    res = http.get(locUrl, {
      redirects: 0,
      tags: { name: 'challenge-redirect' },
    });
  }

  assertStatus(res, 'challenge complete 200', (r) => r.status === 200 || r.status === 201);

  const body = safeJson(res);
  if (body && typeof body.csrf === 'string' && body.csrf.length) state.csrf = body.csrf;
  if (body && body.grant_id !== undefined && body.grant_id !== null) return body.grant_id;

  throw new Error('challenge grant_id missing');
}

function getCart(state) {
  if (state.cartId === undefined || state.cartId === null) throw new Error('no cart for getCart');

  const res = authRequest(
    'GET',
    `${BASE}/v2/carts/${encodeURIComponent(state.cartId)}`,
    null,
    {},
    state,
    'get-cart'
  );
  assertStatus(res, 'get cart 200', (r) => r.status === 200);

  const etag = header(res, 'ETag');
  if (etag) state.etag = etag;
  updateCsrfFromResponse(state, res);

  if (!state.etag) throw new Error('cart ETag missing');
  return state.etag;
}

function updateCartQuantity(state, quantity) {
  if (state.cartId === undefined || state.cartId === null) throw new Error('no cart for update');
  if (!state.etag) getCart(state);

  const payload = { quantity: quantity };
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'If-Match': state.etag,
    },
  };

  let res = authRequest(
    'PATCH',
    `${BASE}/v2/carts/${encodeURIComponent(state.cartId)}`,
    payload,
    params,
    state,
    'patch-cart'
  );

  if (res.status === 412) {
    getCart(state);
    params.headers['If-Match'] = state.etag;
    res = authRequest(
      'PATCH',
      `${BASE}/v2/carts/${encodeURIComponent(state.cartId)}`,
      payload,
      params,
      state,
      'patch-cart-retry'
    );
  }

  assertStatus(res, 'patch cart success', (r) => r.status >= 200 && r.status < 300);
  updateCsrfFromResponse(state, res);

  const newEtag = header(res, 'ETag');
  if (newEtag) state.etag = newEtag;
}

function placeOrder(state) {
  if (state.cartId === undefined || state.cartId === null) throw new Error('no cart for order');
  if (!state.etag) getCart(state);

  const payload = { cart_id: state.cartId };
  const idem = state.idempotencyKey || 'order-' + String(state.cartId);
  state.idempotencyKey = idem;

  const params = {
    headers: {
      'Content-Type': 'application/json',
      'Idempotency-Key': idem,
      'If-Match': state.etag,
    },
  };

  let res = authRequest(
    'POST',
    `${BASE}/v2/orders`,
    payload,
    params,
    state,
    'order'
  );

  if (res.status === 412) {
    getCart(state);
    params.headers['If-Match'] = state.etag;
    res = authRequest(
      'POST',
      `${BASE}/v2/orders`,
      payload,
      params,
      state,
      'order-retry'
    );
  }

  const body = safeJson(res);
  assertStatus(
    res,
    'order 201 accepted',
    (r) =>
      r.status === 201 &&
      body &&
      body.accepted === true &&
      body.id !== undefined &&
      body.id !== null
  );

  updateCsrfFromResponse(state, res);
}

function authRequest(method, url, body, extraParams, state, opName) {
  const m = String(method).toUpperCase();
  const params = cloneParams(extraParams);

  if (m !== 'GET' && m !== 'HEAD') {
    if (!state.csrf) throw new Error('missing csrf for ' + opName);
    params.headers['X-CSRF-Token'] = state.csrf;
  }

  const reqBody = body === undefined || body === null ? null : JSON.stringify(body);
  let res = http.request(m, url, reqBody, params);

  if (res.status === 401) {
    const err = errorCode(res);

    if (err === 'expired') {
      renewSession(state);
      if (state.cartId !== undefined && state.cartId !== null) recoverCart(state);
      refreshConditionalHeaders(params, state);
      if (m !== 'GET' && m !== 'HEAD') params.headers['X-CSRF-Token'] = state.csrf;
      res = http.request(m, url, reqBody, params);
      return res;
    }

    if (err === 'session') {
      login(state);
      if (state.cartId !== undefined && state.cartId !== null) recoverCart(state);
      refreshConditionalHeaders(params, state);
      if (m !== 'GET' && m !== 'HEAD') params.headers['X-CSRF-Token'] = state.csrf;
      res = http.request(m, url, reqBody, params);
      return res;
    }

    if (err === 'denied') {
      check(res, { '401 denied is failure': () => false });
      throw new Error('401 denied for ' + opName);
    }
  }

  return res;
}

function renewSession(state) {
  const res = http.post(
    `${BASE}/v2/session/renew`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'renew-session' },
    }
  );

  if (res.status >= 200 && res.status < 300) {
    updateCsrfFromResponse(state, res);
    return;
  }

  login(state);
}

function recoverCart(state) {
  if (state.cartId === undefined || state.cartId === null) return;

  const res = http.post(
    `${BASE}/v2/carts/${encodeURIComponent(state.cartId)}/recover`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'recover-cart' },
    }
  );

  assertStatus(res, 'recover cart success', (r) => r.status >= 200 && r.status < 300);
  updateCsrfFromResponse(state, res);

  const etag = header(res, 'ETag');
  if (etag) state.etag = etag;
}

function updateCsrfFromResponse(state, res) {
  const body = safeJson(res);
  if (body && typeof body.csrf === 'string' && body.csrf.length) {
    state.csrf = body.csrf;
  }
  return body;
}

function cloneParams(params) {
  const p = {};
  if (params) {
    for (const k in params) {
      if (k !== 'headers') p[k] = params[k];
    }
    if (params.headers) {
      p.headers = {};
      for (const h in params.headers) p.headers[h] = params.headers[h];
    }
  }
  if (!p.headers) p.headers = {};
  p.redirects = 0;
  return p;
}

function refreshConditionalHeaders(params, state) {
  if (!params || !params.headers || !state.etag) return;
  for (const k in params.headers) {
    if (k.toLowerCase() === 'if-match') {
      params.headers[k] = state.etag;
    }
  }
}

function assertStatus(res, name, predicate) {
  const ok = predicate(res);
  check(res, { [name]: () => ok });
  if (!ok) {
    throw new Error(
      name + ' failed with status ' + res.status + ' body=' + String(res.body).slice(0, 300)
    );
  }
}

function errorCode(res) {
  const body = safeJson(res);
  if (body && typeof body.error === 'string') return body.error;
  const m = /"error"\s*:\s*"([^"]+)"/.exec(res.body || '');
  return m ? m[1] : null;
}

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const lower = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === lower) {
      const v = res.headers[k];
      return Array.isArray(v) ? v[0] : v;
    }
  }
  return null;
}

function absoluteUrl(base, loc) {
  if (!loc) return null;
  const s = String(loc);
  if (/^https?:\/\//i.test(s)) return s;
  if (s.indexOf('//') === 0) return 'http:' + s;
  if (s.charAt(0) === '/') return base + s;
  return base + '/' + s.replace(/^\.?\//, '');
}

function extractFormAction(html) {
  const formRe = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRe.exec(html || '')) !== null) {
    const attrs = parseAttrsFromTag(m[0]);
    if (attrs.action && String(attrs.action).indexOf('/v2/challenges/') !== -1) {
      return attrs.action;
    }
  }

  const re = /<form[^>]*\saction\s*=\s*["']([^"']*\/v2\/challenges\/[^"']*)["']/i;
  const mm = re.exec(html || '');
  return mm ? mm[1] : null;
}

function extractInputValue(html, targetName) {
  const inputRe = /<input\b[^>]*>/gi;
  const target = String(targetName).toLowerCase();
  let m;

  while ((m = inputRe.exec(html || '')) !== null) {
    const attrs = parseAttrsFromTag(m[0]);
    if (
      attrs.name &&
      String(attrs.name).toLowerCase() === target &&
      attrs.value !== undefined
    ) {
      return attrs.value;
    }
  }

  const esc = String(targetName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const patterns = [
    new RegExp(
      '<input[^>]*\\sname\\s*=\\s*["\']' +
        esc +
        '["\'][^>]*\\svalue\\s*=\\s*["\']([^"\']+)["\']',
      'i'
    ),
    new RegExp(
      '<input[^>]*\\svalue\\s*=\\s*["\']([^"\']+)["\'][^>]*\\sname\\s*=\\s*["\']' +
        esc +
        '["\']',
      'i'
    ),
  ];

  for (let i = 0; i < patterns.length; i++) {
    const mm = patterns[i].exec(html || '');
    if (mm) return mm[1];
  }

  return null;
}

function parseAttrsFromTag(tag) {
  const attrs = {};
  const attrRe = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  let first = true;

  while ((m = attrRe.exec(tag)) !== null) {
    if (first) {
      first = false;
      continue;
    }

    const name = m[1].toLowerCase();
    let value;
    if (m[2] !== undefined) value = m[2];
    else if (m[3] !== undefined) value = m[3];
    else if (m[4] !== undefined) value = m[4];

    attrs[name] = value === undefined ? '' : value;
  }

  return attrs;
}

import os
import re
from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS = 2
QUANTITY = 2
COMPLETED_USERS = 0


def _json(resp):
    try:
        data = resp.json()
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _error(resp):
    data = _json(resp)
    if isinstance(data, dict):
        err = data.get("error")
        if err:
            return str(err).lower()
    text = getattr(resp, "text", "") or ""
    m = re.search(r'"error"\s*:\s*"([^"]+)"', text)
    if m:
        return m.group(1).lower()
    m = re.search(r'\berror\s*=\s*([A-Za-z_-]+)', text)
    if m:
        return m.group(1).lower()
    return ""


def _csrf_from_html(html):
    candidates = []
    for tag in re.findall(r'<input\b[^>]*>', html or "", flags=re.IGNORECASE):
        name_match = re.search(
            r'\bname\s*=\s*(?:"csrf"|\'csrf\'|csrf)(?:\s|/|>)',
            tag,
            flags=re.IGNORECASE,
        )
        if not name_match:
            name_match = re.search(
                r'\bname\s*=\s*(?:"csrf"|\'csrf\'|csrf)\b',
                tag,
                flags=re.IGNORECASE,
            )
        if name_match:
            val_match = re.search(
                r'\bvalue\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s/>]+))',
                tag,
                flags=re.IGNORECASE,
            )
            if val_match:
                val = (
                    val_match.group(1)
                    or val_match.group(2)
                    or val_match.group(3)
                    or ""
                )
                if val:
                    hidden = re.search(
                        r'\btype\s*=\s*(?:"hidden"|\'hidden\'|hidden)\b',
                        tag,
                        flags=re.IGNORECASE,
                    )
                    candidates.append((1 if hidden else 0, val))
    if candidates:
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]
    return ""


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.1, 0.2)
    _user_seq = 0

    def on_start(self):
        type(self)._user_seq += 1
        idx = ((type(self)._user_seq - 1) % 16) + 1
        self.username = f"bench-{idx}"
        self.password = "bench"
        self.csrf = ""
        self.cart_id = None
        self.etag = None

    def login(self):
        with self.client.get(
            "/v2/login-form", catch_response=True, name="/v2/login-form"
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False
            csrf = _csrf_from_html(resp.text)
            if not csrf:
                resp.failure("login-form csrf missing")
                return False
            self.csrf = csrf
            resp.success()

        payload = {
            "username": self.username,
            "password": self.password,
            "csrf": self.csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            catch_response=True,
            allow_redirects=False,
            name="/v2/login",
        ) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("login 302 missing Location")
                    return False
                resp.success()
                with self.client.get(
                    loc,
                    catch_response=True,
                    allow_redirects=False,
                    name="/v2/login-redirect",
                ) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure(f"login redirect status {r2.status_code}")
                        return False
                    data = _json(r2)
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    else:
                        csrf = _csrf_from_html(r2.text)
                        if csrf:
                            self.csrf = csrf
                    r2.success()
                return True
            if resp.status_code not in (200, 201):
                resp.failure(f"login status {resp.status_code}")
                return False
            data = _json(resp)
            if data.get("csrf"):
                self.csrf = data["csrf"]
            resp.success()
            return True

    def renew_session(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            catch_response=True,
            name="/v2/session/renew",
        ) as resp:
            if resp.status_code in (200, 201, 204):
                data = _json(resp)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True
            resp.failure(f"renew status {resp.status_code}")
            return False

    def recover_cart(self, cart_id):
        if not cart_id:
            return True
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            f"/v2/carts/{cart_id}/recover",
            json={},
            headers=headers,
            catch_response=True,
            name="/v2/carts/[id]/recover",
        ) as resp:
            if resp.status_code in (200, 201, 204):
                data = _json(resp)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True
            resp.failure(f"recover status {resp.status_code}")
            return False

    def handle_401(self, resp, cart_id=None):
        err = _error(resp)
        if err == "denied":
            resp.failure("401 denied")
            return False
        if err == "expired":
            resp.success()
            if not self.renew_session():
                if not self.login():
                    return False
            if cart_id and not self.recover_cart(cart_id):
                return False
            return True
        if err == "session":
            resp.success()
            if not self.login():
                return False
            if cart_id and not self.recover_cart(cart_id):
                return False
            return True
        resp.failure(f"401 error={err or 'unknown'}")
        return False

    def get_cart_etag(self, cart_id):
        auth_retried = False
        while True:
            with self.client.get(
                f"/v2/carts/{cart_id}",
                catch_response=True,
                name="/v2/carts/[id]",
            ) as resp:
                if resp.status_code == 401 and not auth_retried:
                    if self.handle_401(resp, cart_id=cart_id):
                        auth_retried = True
                        continue
                    return None
                if resp.status_code != 200:
                    resp.failure(f"get cart status {resp.status_code}")
                    return None
                etag = resp.headers.get("ETag") or resp.headers.get("etag")
                if not etag:
                    resp.failure("get cart missing ETag")
                    return None
                resp.success()
                return etag

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        auth_retried = False
        while True:
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            with self.client.post(
                "/v2/carts",
                json=payload,
                headers=headers,
                catch_response=True,
                name="/v2/carts",
            ) as resp:
                if resp.status_code == 401 and not auth_retried:
                    if self.handle_401(resp, cart_id=None):
                        auth_retried = True
                        continue
                    return None, None
                if resp.status_code != 201:
                    resp.failure(f"create cart status {resp.status_code}")
                    return None, None
                data = _json(resp)
                cart_id = data.get("id")
                if not cart_id:
                    resp.failure("create cart missing id")
                    return None, None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                etag = resp.headers.get("ETag") or resp.headers.get("etag")
                resp.success()
                self.cart_id = cart_id
                if not etag:
                    etag = self.get_cart_etag(cart_id)
                return cart_id, etag

    def patch_cart(self, cart_id, quantity, etag):
        payload = {"quantity": quantity}
        conflict_retried = False
        auth_retried = False
        current_etag = etag
        while True:
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if current_etag:
                headers["If-Match"] = current_etag
            with self.client.patch(
                f"/v2/carts/{cart_id}",
                json=payload,
                headers=headers,
                catch_response=True,
                name="/v2/carts/[id]",
            ) as resp:
                if resp.status_code == 412:
                    if conflict_retried:
                        resp.failure("412 conflict after retry")
                        return False
                    resp.success()
                    conflict_retried = True
                    fresh = self.get_cart_etag(cart_id)
                    if not fresh:
                        return False
                    current_etag = fresh
                    continue
                if resp.status_code == 401 and not auth_retried:
                    if self.handle_401(resp, cart_id=cart_id):
                        auth_retried = True
                        fresh = self.get_cart_etag(cart_id)
                        if fresh:
                            current_etag = fresh
                        continue
                    return False
                if resp.status_code not in (200, 201, 204):
                    resp.failure(f"patch status {resp.status_code}")
                    return False
                data = _json(resp)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                new_etag = resp.headers.get("ETag") or resp.headers.get("etag")
                if new_etag:
                    current_etag = new_etag
                resp.success()
                self.etag = current_etag
                return True

    def place_order(self, cart_id, etag):
        current_etag = self.get_cart_etag(cart_id)
        if not current_etag:
            return False
        payload = {"cart_id": cart_id}
        idem = f"order-cart-{cart_id}"
        auth_retried = False
        conflict_retried = False
        while True:
            headers = {"Idempotency-Key": idem}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if current_etag:
                headers["If-Match"] = current_etag
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                catch_response=True,
                name="/v2/orders",
            ) as resp:
                if resp.status_code == 401 and not auth_retried:
                    if self.handle_401(resp, cart_id=cart_id):
                        auth_retried = True
                        fresh = self.get_cart_etag(cart_id)
                        if fresh:
                            current_etag = fresh
                        continue
                    return False
                if resp.status_code == 412 and not conflict_retried:
                    resp.success()
                    conflict_retried = True
                    fresh = self.get_cart_etag(cart_id)
                    if not fresh:
                        return False
                    current_etag = fresh
                    continue
                if resp.status_code != 201:
                    resp.failure(f"order status {resp.status_code}")
                    return False
                data = _json(resp)
                if data.get("accepted") is not True:
                    resp.failure("order business failure accepted!=true")
                    return False
                if not data.get("id"):
                    resp.failure("order missing id")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True

    def _choose_product(self, products):
        if not isinstance(products, list):
            return None
        for p in products:
            if not isinstance(p, dict):
                continue
            pid = p.get("id")
            if pid is None:
                continue
            variants = p.get("variants") or []
            if not isinstance(variants, list):
                continue
            for v in variants:
                if (
                    isinstance(v, dict)
                    and v.get("in_stock")
                    and v.get("id") is not None
                ):
                    return pid, v.get("id")
        return None

    def get_catalog_choice(self):
        direct_auth_retried = False
        data = None
        direct_ok = False
        while True:
            with self.client.get(
                "/v2/catalog",
                catch_response=True,
                name="/v2/catalog",
            ) as resp:
                if resp.status_code == 401 and not direct_auth_retried:
                    if self.handle_401(resp, cart_id=self.cart_id):
                        direct_auth_retried = True
                        continue
                    return None
                if resp.status_code == 200:
                    data = _json(resp)
                    direct_ok = True
                    resp.success()
                    break
                if resp.status_code == 404:
                    resp.success()
                    break
                resp.failure(f"catalog status {resp.status_code}")
                return None

        next_url = None
        if direct_ok and isinstance(data, dict):
            products = []
            d = data.get("data")
            if isinstance(d, dict) and isinstance(d.get("products"), list):
                products = d["products"]
            elif isinstance(data.get("products"), list):
                products = data["products"]
            choice = self._choose_product(products)
            if choice:
                return choice
            next_url = data.get("next")

        if not next_url:
            next_url = "/v2/catalog/page"

        for _ in range(3):
            if not next_url:
                break
            page_auth_retried = False
            page_data = {}
            while True:
                with self.client.get(
                    next_url,
                    catch_response=True,
                    name="/v2/catalog/page",
                ) as resp:
                    if resp.status_code == 401 and not page_auth_retried:
                        if self.handle_401(resp, cart_id=self.cart_id):
                            page_auth_retried = True
                            continue
                        return None
                    if resp.status_code != 200:
                        resp.failure(f"catalog page status {resp.status_code}")
                        return None
                    page_data = _json(resp)
                    resp.success()
                    break

            products = []
            if isinstance(page_data, dict):
                d = page_data.get("data")
                if isinstance(d, dict):
                    if isinstance(d.get("products"), list):
                        products.extend(d["products"])
                    if isinstance(d.get("product"), dict):
                        products.append(d["product"])
                    if d.get("id") is not None and isinstance(
                        d.get("variants"), list
                    ):
                        products.append(d)
                if isinstance(page_data.get("products"), list):
                    products.extend(page_data["products"])
                if isinstance(page_data.get("product"), dict):
                    products.append(page_data["product"])
                if page_data.get("id") is not None and isinstance(
                    page_data.get("variants"), list
                ):
                    products.append(page_data)

            choice = self._choose_product(products)
            if choice:
                return choice
            next_url = page_data.get("next") if isinstance(page_data, dict) else None

        return None

    def run_journey(self):
        self.cart_id = None
        self.etag = None

        if not self.login():
            return
        choice = self.get_catalog_choice()
        if not choice:
            return

        product_id, variant_id = choice
        cart_id, etag = self.create_cart(product_id, variant_id)
        if not cart_id:
            return
        if not etag:
            etag = self.get_cart_etag(cart_id)
        if not etag:
            return
        if not self.patch_cart(cart_id, QUANTITY, etag):
            return

        final_etag = self.get_cart_etag(cart_id)
        if not final_etag:
            return
        self.place_order(cart_id, final_etag)

    @task
    def journey(self):
        global COMPLETED_USERS
        try:
            for _ in range(ITERATIONS):
                self.run_journey()
        finally:
            COMPLETED_USERS += 1
        raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        global COMPLETED_USERS
        target = 2 - COMPLETED_USERS
        if target <= 0:
            return None
        return (target, 2)

