import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(BASE_URL)
      .disableFollowRedirect()
      .acceptHeader("application/json,text/html;q=0.9,*/*;q=0.8")
      .userAgentHeader("Gatling");

  private final ScenarioBuilder scn = scenario("ModelSimulation")
      .exec(session -> session.set("username", "bench-" + ((session.userId() % 16) + 1)))
      .repeat(2).on(
          exec(flushCookieJar())
          .exec(resetJourney())
          .exec(login())
          .doIf(session -> !session.isFailed()).then(exec(catalog()))
          .doIf(session -> session.contains("productIdJson") && !session.isFailed()).then(exec(challenge()))
          .doIf(session -> session.contains("grantIdJson") && !session.isFailed()).then(exec(createCart()))
          .doIf(session -> session.contains("cartId") && !session.isFailed()).then(
              exec(reserve()),
              doIf(session -> Boolean.TRUE.equals(session.get("reservationReady")) && !session.isFailed()).then(
                  exec(refreshCart()),
                  doIf(session -> !session.isFailed()).then(exec(checkout()))
              )
          )
      );

  {
    setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }

  private ChainBuilder resetJourney() {
    return exec(session -> {
      String[] keys = {
          "csrf", "cartId", "cartIdJson", "productIdJson", "variantIdJson", "grantIdJson",
          "challengeAction", "challengeValue", "challengeRedirect", "statusUrl",
          "reservationIdJson", "reservationStatus", "reservationReady", "orderCommitted",
          "orderNeedsEtagRefresh", "lastError", "cartETag", "idempotencyKey",
          "loginRedirect", "challengeStatus", "catalogStatus", "cartCreateStatus",
          "reservationCreateStatus", "pollStatus", "cartGetStatus", "orderStatus"
      };
      Session s = session;
      for (String k : keys) {
        if (s.contains(k)) s = s.remove(k);
      }
      return s;
    });
  }

  private ChainBuilder login() {
    return exec(http("GET login form").get("/v2/login-form")
        .check(status().is(200), bodyString().saveAs("loginFormBody")))
      .exec(session -> {
        String csrf = extractInputValue(session.getString("loginFormBody"), "csrf");
        if (csrf == null) return session.markAsFailed();
        return session.set("csrf", csrf);
      })
      .exec(http("POST login").post("/v2/login")
          .body(StringBody(session -> {
            String csrf = session.getString("csrf");
            String user = session.getString("username");
            return "{\"username\":" + toJsonLiteral(user) + ",\"password\":\"bench\",\"csrf\":" + toJsonLiteral(csrf) + "}";
          })).asJson()
          .check(status().in(200, 302),
                 status().saveAs("loginStatus"),
                 header("Location").optional().saveAs("loginLocation"),
                 bodyString().saveAs("loginResponseBody")))
      .exec(session -> {
        String loc = session.getString("loginLocation");
        if (loc != null && !loc.isEmpty()) return session.set("loginRedirect", loc);
        return session.remove("loginRedirect");
      })
      .doIf(session -> session.contains("loginRedirect")).then(
          exec(http("GET login redirect").get("#{loginRedirect}")
              .check(status().is(200), bodyString().saveAs("loginResponseBody")))
      )
      .exec(session -> {
        String csrf = jsonStringField(session.getString("loginResponseBody"), "csrf");
        if (csrf == null) return session.markAsFailed();
        return session.set("csrf", csrf);
      });
  }

  private ChainBuilder catalog() {
    return exec(catalogAttempt())
      .doIf(session -> isRecoverable(session, "catalogStatus")).then(
          exec(recoverAuth()),
          doIf(session -> !session.isFailed()).then(exec(catalogAttempt()))
      )
      .doIf(session -> session.getInt("catalogStatus") != 200).then(exec(failAction()))
      .doIf(session -> session.getInt("catalogStatus") == 200).then(exec(parseCatalog()));
  }

  private ChainBuilder catalogAttempt() {
    return exec(http("GET catalog").get("/v2/catalog")
        .check(status().saveAs("catalogStatus"), bodyString().saveAs("catalogBody")))
      .exec(session -> {
        if (session.getInt("catalogStatus") == 401) {
          return session.set("lastError", jsonStringField(session.getString("catalogBody"), "error"));
        }
        return session;
      });
  }

  private ChainBuilder parseCatalog() {
    return exec(session -> {
      Object root = parseJson(session.getString("catalogBody"));
      Object productsObj = getPath(root, "data", "products");
      if (!(productsObj instanceof List)) return session.markAsFailed();

      for (Object po : (List<?>) productsObj) {
        if (!(po instanceof Map)) continue;
        Map<?, ?> pm = (Map<?, ?>) po;
        Object pid = pm.get("id");
        Object variantsObj = pm.get("variants");
        if (pid == null || !(variantsObj instanceof List)) continue;

        for (Object vo : (List<?>) variantsObj) {
          if (!(vo instanceof Map)) continue;
          Map<?, ?> vm = (Map<?, ?>) vo;
          if (Boolean.TRUE.equals(vm.get("in_stock")) && vm.get("id") != null) {
            return session.set("productIdJson", toJsonLiteral(pid))
                .set("variantIdJson", toJsonLiteral(vm.get("id")));
          }
        }
      }
      return session.markAsFailed();
    });
  }

  private ChainBuilder challenge() {
    return exec(challengeAttempt())
      .doIf(session -> isRecoverable(session, "challengeStatus")).then(
          exec(recoverAuth()),
          doIf(session -> !session.isFailed()).then(exec(challengeAttempt()))
      )
      .doIf(session -> session.getInt("challengeStatus") != 200 || !session.contains("grantIdJson"))
      .then(exec(failAction()));
  }

  private ChainBuilder challengeAttempt() {
    return exec(http("GET challenge form").get("/v2/challenge-form")
        .check(status().saveAs("challengeStatus"), bodyString().saveAs("challengeFormBody")))
