      return false;
    }
    if (st != 401) return false;
    String err = session.getString("lastError");
    return "expired".equals(err) || "session".equals(err);
  }

  private static String extractInputValue(String html, String name) {
    if (html == null) return null;
    Pattern tag = Pattern.compile("(?is)<input\\b[^>]*>");
    Matcher m = tag.matcher(html);
    while (m.find()) {
      String t = m.group();
      String n = getAttr(t, "name");
      if (n != null && n.equalsIgnoreCase(name)) {
        String v = getAttr(t, "value");
        if (v != null) return v;
      }
    }
    return null;
  }

  private static String[] extractChallengeForm(String html) {
    if (html == null) return new String[]{null, null};
    Pattern form = Pattern.compile("(?is)<form\\b([^>]*)>(.*?)</form>");
    Matcher m = form.matcher(html);
    while (m.find()) {
      String attrs = m.group(1);
      String body = m.group(2);
      String challenge = extractInputValue(body, "challenge");
      if (challenge != null) {
        String action = getAttr(attrs, "action");
        if (action == null) action = getAttr(m.group(), "action");
        return new String[]{action, challenge};
      }
    }
    return new String[]{getAttr(html, "action"), extractInputValue(html, "challenge")};
  }

  private static String getAttr(String tag, String attr) {
    Pattern p = Pattern.compile("(?is)\\b" + Pattern.quote(attr) + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");
    Matcher m = p.matcher(tag);
    if (m.find()) {
      if (m.group(1) != null) return m.group(1);
      if (m.group(2) != null) return m.group(2);
      if (m.group(3) != null) return m.group(3).replaceAll("[\"']$", "").replaceAll("/$", "");
    }
    return null;
  }

