  private static Object getPath(Object root, String... path) {
    Object cur = root;
    for (String p : path) {
      if (!(cur instanceof Map)) return null;
      cur = ((Map<?, ?>) cur).get(p);
    }
    return cur;
  }

  private static String jsonStringField(String body, String field) {
    Object v = getPath(parseJson(body), field);
    return v == null ? null : String.valueOf(v);
  }

  private static String jsonRawField(String body, String field) {
    Object root = parseJson(body);
    if (!(root instanceof Map)) return null;
    Map<?, ?> m = (Map<?, ?>) root;
    if (!m.containsKey(field)) return null;
    return toJsonLiteral(m.get(field));
  }

  private static String toJsonLiteral(Object v) {
    if (v == null) return "null";
    if (v instanceof Number || v instanceof Boolean) return v.toString();
    String s = String.valueOf(v);
    StringBuilder b = new StringBuilder("\"");
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      switch (c) {
        case '"': b.append("\\\""); break;
        case '\\': b.append("\\\\"); break;
        case '\n': b.append("\\n"); break;
        case '\r': b.append("\\r"); break;
        case '\t': b.append("\\t"); break;
        default: b.append(c);
      }
    }
    b.append("\"");
    return b.toString();
  }

