function extractAttr(tag, attr) {
  const name = attr.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  let re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(["\'])(.*?)\\1', 'i');
  let m = re.exec(tag);
  if (m) return decodeHtml(m[2]);

  re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*([^\\s>]+)', 'i');
  m = re.exec(tag);
