  let loginJson = null;

  if (login.status === 302) {
    const loc = getHeader(login, 'Location');
    if (!loc) throw new Error('login 302 without Location');
    const follow = call('GET', resolveUrl(loc), null, {});
    if (follow.status !== 200) {
      throw new Error('login follow status ' + follow.status + ' body ' + follow.body);
