        cart_id = data.get("id") if isinstance(data, dict) else None
        if cart_id is None:
            raise AssertionError("cart id missing")

        etag = resp.headers.get("ETag") or resp.headers.get("etag")
        return cart_id, etag

    def _get_cart_etag(self, cart_id):
        resp = self._authed(
            "GET",
            f"/v2/carts/{cart_id}",
            cart_id=cart_id,
            expected=(200,)
        )
        if resp.status_code != 200:
            raise AssertionError(
                f"get cart failed status={resp.status_code}"
            )
        self._update_csrf(_json(resp))
        return resp.headers.get("ETag") or resp.headers.get("etag")

    def _patch_quantity(self, cart_id, etag, quantity=2):
        if not etag:
            etag = self._get_cart_etag(cart_id)

        payload = {"quantity": quantity}
        headers = {}
        if etag:
            headers["If-Match"] = etag

        resp = self._authed(
            "PATCH",
            f"/v2/carts/{cart_id}",
            cart_id=cart_id,
            expected=(200, 204, 412),
            headers=headers,
            json=payload
        )

        if resp.status_code == 412:
            etag2 = self._get_cart_etag(cart_id)
            headers2 = {}
            if etag2:
                headers2["If-Match"] = etag2
            resp = self._authed(
                "PATCH",
                f"/v2/carts/{cart_id}",
                cart_id=cart_id,
                expected=(200, 204),
                headers=headers2,
                json=payload
            )

        if resp.status_code not in (200, 204):
            raise AssertionError(
                f"patch quantity failed status={resp.status_code}"
            )

        self._update_csrf(_json(resp))
        new_etag = resp.headers.get("ETag") or resp.headers.get("etag")
        return new_etag or etag

    def _reserve(self, cart_id):
        resp = self._authed(
            "POST",
            "/v2/reservations",
            cart_id=cart_id,
            expected=(202,),
            json={"cart_id": cart_id}
        )
        if resp.status_code != 202:
            raise AssertionError(
                f"reservation failed status={resp.status_code}"
            )

        data = _json(resp)
        self._update_csrf(data)
        status_url = data.get("status_url") if isinstance(data, dict) else None
        if not status_url:
            raise AssertionError("reservation status_url missing")

        reservation_id = None
        for _ in range(5):
            _sleep(0.06)
            r = self._authed(
                "GET",
                status_url,
                cart_id=cart_id,
                expected=(200,)
            )
            if r.status_code != 200:
                raise AssertionError(
                    f"reservation poll failed status={r.status_code}"
                )

            sdata = _json(r)
            self._update_csrf(sdata)
            status = sdata.get("status") if isinstance(sdata, dict) else None

            if status == "ready":
                reservation_id = sdata.get("reservation_id")
                if reservation_id is None:
                    raise AssertionError("reservation ready without id")
                break
            elif status == "failed":
                raise AssertionError("reservation failed")
            elif status == "pending":
                continue
            else:
                raise AssertionError(
                    f"unexpected reservation status {status}"
                )

        if reservation_id is None:
            raise AssertionError("reservation not ready after 5 polls")
        return reservation_id

    def _checkout(self, cart_id, reservation_id, order_key, etag):
        payload = {"cart_id": cart_id}
        if reservation_id is not None:
            payload["reservation_id"] = reservation_id

        headers = {"Idempotency-Key": order_key}
        if etag:
            headers["If-Match"] = etag

        resp = self._authed(
            "POST",
            "/v2/orders",
            cart_id=cart_id,
            expected=(201, 412),
            headers=headers,
            json=payload
        )

        if resp.status_code == 412:
            etag2 = self._get_cart_etag(cart_id)
            headers2 = {"Idempotency-Key": order_key}
            if etag2:
                headers2["If-Match"] = etag2
            resp = self._authed(
                "POST",
                "/v2/orders",
                cart_id=cart_id,
                expected=(201,),
                headers=headers2,
                json=payload
            )

        if resp.status_code != 201:
            raise AssertionError(
                f"order failed status={resp.status_code}"
            )

        data = _json(resp)
        self._update_csrf(data)
        if not (
            isinstance(data, dict)
            and data.get("accepted") is True
            and data.get("id") is not None
        ):
            raise AssertionError("order not accepted")
        return data

    def _journey(self):
        self.username = _next_owner()
        self.csrf = None
        self.user = None

        try:
            self.client.cookies.clear()
        except Exception:
            pass

        self._fresh_login()
        product_id, variant_id = self._choose_variant()
        cart_id, etag = self._create_cart(product_id, variant_id)
        etag = self._patch_quantity(cart_id, etag, 2)
        reservation_id = self._reserve(cart_id)
        etag = self._get_cart_etag(cart_id) or etag
        order_key = f"order-{cart_id}-{uuid.uuid4().hex}"
        self._checkout(cart_id, reservation_id, order_key, etag)

    @task
    def journey_task(self):
        if self.iterations_done >= self.iterations_target:
            while COMPLETED_JOURNEYS < TOTAL_JOURNEYS:
                _sleep(0.1)
            raise StopUser()

        try:
            self._journey()
        except Exception:
            self.iterations_done += 1
            _mark_completed()
            raise

        self.iterations_done += 1
        _mark_completed()

        if COMPLETED_JOURNEYS >= TOTAL_JOURNEYS:
            raise StopUser()


