import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final Duration POLL_PAUSE = Duration.ofMillis(60);

    private static final Pattern CSRF_JSON = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern PRODUCT_VARIANTS = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"variants\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
    private static final Pattern VARIANT_IN_STOCK = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*?\"in_stock\"\\s*:\\s*true", Pattern.DOTALL);
    private static final Pattern NEXT_JSON = Pattern.compile("\"next\"\\s*:\\s*(\\\"[^\\\"]*\\\"|null)");
    private static final Pattern STATUS_URL = Pattern.compile("\"status_url\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern STATUS = Pattern.compile("\"status\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern RESERVATION_ID = Pattern.compile("\"reservation_id\"\\s*:\\s*\"?([^\",}\\s]+)\"?");
    private static final Pattern ID_JSON = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern GRANT_ID = Pattern.compile("\"grant_id\"\\s*:\\s*\"([^\"]+)\"");
    private static final Pattern ATTR = Pattern.compile("([a-zA-Z_:][-a-zA-Z0-9_:.]*)\\s*=\\s*(\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", Pattern.DOTALL);
    private static final Pattern INPUT_TAG = Pattern.compile("<input\\b[^>]*>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern FORM_TAG = Pattern.compile("<form\\b[^>]*>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

    private static String first(Pattern pattern, String body) {
        if (body == null) {
            return null;
        }
        Matcher matcher = pattern.matcher(body);
        return matcher.find() ? matcher.group(1) : null;
    }

    private static String attrValue(Matcher matcher) {
        if (matcher.group(3) != null) {
            return matcher.group(3);
        }
        if (matcher.group(4) != null) {
            return matcher.group(4);
        }
        return matcher.group(5);
    }

    private static String extractInputValue(String body, String targetName) {
        if (body == null) {
            return null;
        }
        Matcher input = INPUT_TAG.matcher(body);
        while (input.find()) {
            String tag = input.group();
            Matcher attrs = ATTR.matcher(tag);
            String name = null;
            String value = null;
            while (attrs.find()) {
                String attrName = attrs.group(1);
                String attrVal = attrValue(attrs);
                if ("name".equalsIgnoreCase(attrName)) {
                    name = attrVal;
                } else if ("value".equalsIgnoreCase(attrName)) {
                    value = attrVal;
                }
            }
            if (name != null && name.equalsIgnoreCase(targetName)) {
                return value;
            }
        }
        return null;
    }

    private static String extractChallengeAction(String body) {
        if (body == null) {
            return null;
        }
        Matcher form = FORM_TAG.matcher(body);
        while (form.find()) {
            String tag = form.group();
            Matcher attrs = ATTR.matcher(tag);
            String action = null;
            while (attrs.find()) {
                if ("action".equalsIgnoreCase(attrs.group(1))) {
                    action = attrValue(attrs);
                }
            }
            if (action != null && action.contains("v2/challenges/")) {
                return action;
            }
        }
        return null;
    }

    private static String extractCsrf(String body) {
        String value = first(CSRF_JSON, body);
        if (value != null) {
            return value;
        }
        return extractInputValue(body, "csrf");
    }

    private static String[] findProductVariant(String body) {
        if (body == null) {
            return null;
        }
        Matcher product = PRODUCT_VARIANTS.matcher(body);
        while (product.find()) {
            String productId = product.group(1);
            String variants = product.group(2);
            Matcher variant = VARIANT_IN_STOCK.matcher(variants);
            if (variant.find()) {
                return new String[] { productId, variant.group(1) };
            }
        }
        return null;
    }

    private static String extractNext(String body) {
        if (body == null) {
            return null;
        }
        Matcher matcher = NEXT_JSON.matcher(body);
        if (!matcher.find()) {
            return null;
        }
        String value = matcher.group(1);
        if ("null".equals(value) || value.length() <= 2) {
            return null;
        }
        return value.substring(1, value.length() - 1);
    }

    private static Session updateCsrfFrom(Session session, String bodyAttribute) {
        String body = session.contains(bodyAttribute) ? session.getString(bodyAttribute) : null;
        String csrf = extractCsrf(body);
        return csrf != null ? session.set("csrf", csrf) : session;
    }

    private static final ChainBuilder initJourney = exec(session -> {
        int iteration = session.getInt("iteration");
        long userId = session.userId();
        int ownerIndex = (int) ((userId * 2 + iteration) % 16) + 1;
        Session updated = session
                .set("username", "bench-" + ownerIndex)
                .set("iteration", iteration + 1);
        return updated
                .remove("csrf")
                .remove("loginLocation")
                .remove("loginBody")
                .remove("loginFormBody")
                .remove("loginLocationBody")
                .remove("productId")
                .remove("variantId")
                .remove("needCatalogPage")
                .remove("catalogPageCount")
                .remove("nextUrl")
                .remove("challengeAction")
                .remove("challengeValue")
                .remove("challengeFormBody")
                .remove("challengeLocation")
                .remove("challengeResultBody")
                .remove("grantId")
                .remove("cartId")
                .remove("cartBody")
                .remove("etag")
                .remove("patchStatus")
                .remove("patchBody")
                .remove("patchRetryBody")
                .remove("statusUrl")
                .remove("reservationBody")
                .remove("pollCount")
                .remove("pollBody")
                .remove("shouldPoll")
                .remove("reservationReady")
                .remove("reservationId")
                .remove("jobFailed")
                .remove("orderBody");
    });

    private static ChainBuilder login() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("loginFormBody")))
                .exitHereIfFailed()
                .exec(session -> {
                    String body = session.contains("loginFormBody") ? session.getString("loginFormBody") : null;
                    String csrf = extractCsrf(body);
                    if (csrf == null) {
                        return session.markAsFailed();
                    }
                    return session.set("csrf", csrf);
                })
                .exec(
                        http("POST /v2/login")
                                .post("/v2/login")
                                .body(StringBody("{\"username\":\"${username}\",\"password\":\"bench\",\"csrf\":\"${csrf}\"}")).asJson()
                                .check(status().in(200, 302))
                                .check(header("Location").optional().saveAs("loginLocation"))
                                .check(bodyString().saveAs("loginBody")))
                .exitHereIfFailed()
                .exec(session -> updateCsrfFrom(session, "loginBody"))
                .doIf(session -> session.contains("loginLocation")).then(
                        exec(
                                http("GET login Location")
                                        .get("${loginLocation}")
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("loginLocationBody")))
                                .exitHereIfFailed()
                                .exec(session -> updateCsrfFrom(session, "loginLocationBody"))
                );
    }

    private static ChainBuilder catalog() {
        return exec(
                http("GET /v2/catalog")
                        .get("/v2/catalog")
                        .check(status().is(200))
                        .check(bodyString().saveAs("catalogBody")))
                .exitHereIfFailed()
                .exec(session -> {
                    String body = session.contains("catalogBody") ? session.getString("catalogBody") : null;
                    String[] productVariant = findProductVariant(body);
                    if (productVariant != null) {
                        return session
                                .set("productId", productVariant[0])
                                .set("variantId", productVariant[1])
                                .set("needCatalogPage", false)
                                .set("catalogPageCount", 0);
                    }
                    return session
                            .set("needCatalogPage", true)
                            .set("catalogPageCount", 0)
                            .set("nextUrl", "/v2/catalog/page");
                })
                .asLongAs(session -> session.getBoolean("needCatalogPage") && session.getInt("catalogPageCount") < 3).on(
                        exec(
                                http("GET /v2/catalog/page")
                                        .get("${nextUrl}")
                                        .check(status().is(200))
                                        .check(bodyString().saveAs("catalogPageBody")))
                                .exitHereIfFailed()
                                .exec(session -> {
                                    String body = session.contains("catalogPageBody") ? session.getString("catalogPageBody") : null;
                                    String[] productVariant = findProductVariant(body);
                                    if (productVariant != null) {
                                        return session
                                                .set("productId", productVariant[0])
                                                .set("variantId", productVariant[1])
                                                .set("needCatalogPage", false);
                                    }
                                    int pageCount = session.getInt("catalogPageCount") + 1;
                                    String next = extractNext(body);
                                    boolean needPage = next != null && pageCount < 3;
                                    Session updated = session
                                            .set("catalogPageCount", pageCount)
                                            .set("needCatalogPage", needPage);
                                    if (next != null) {
                                        updated = updated.set("nextUrl", next);
                                    }
                                    return updated;
                                })
                )
                .exec(session -> {
                    if (!session.contains("productId") || !session.contains("variantId")) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private static ChainBuilder challenge() {
        return exec(
                http("GET /v2/challenge-form")
                        .get("/v2/challenge-form")
                        .check(status().is(200))
                        .check(bodyString().saveAs("challengeFormBody")))
                .exitHereIfFailed()
                .exec(session -> {
                    String body = session.contains("challengeFormBody") ? session.getString("challengeFormBody") : null;
                    String action = extractChallengeAction(body);
                    String challengeValue = extractInputValue(body, "challenge");
                    if (action != null && challengeValue != null) {
                        return session
                                .set("challengeAction", action)
                                .set("challengeValue", challengeValue);
                    }
                    return session
                            .remove("challengeAction")
                            .remove("challengeValue")
                            .remove("grantId");
                })
                .doIf(session -> session.contains("challengeAction") && session.contains("challengeValue")).then(
                        exec(
                                http("POST challenge")
                                        .post("${challengeAction}")
                                        .header("X-CSRF-Token", "${csrf}")
                                        .body(StringBody("{\"challenge\":\"${challengeValue}\"}")).asJson()
                                        .check(status().is(302))
                                        .check(header("Location").saveAs("challengeLocation")))
                                .exitHereIfFailed()
                                .exec(
                                        http("GET challenge Location")
                                                .get("${challengeLocation}")
                                                .check(status().is(200))
                                                .check(bodyString().saveAs("challengeResultBody")))
                                .exitHereIfFailed()
                                .exec(session -> {
                                    String body = session.contains("challengeResultBody") ? session.getString("challengeResultBody") : null;
                                    String grantId = first(GRANT_ID, body);
                                    String csrf = extractCsrf(body);
                                    Session updated = session;
                                    if (csrf != null) {
                                        updated = updated.set("csrf", csrf);
                                    }
                                    if (grantId != null) {
                                        updated = updated.set("grantId", grantId);
                                    } else {
                                        updated = updated.markAsFailed();
                                    }
                                    return updated;
                                })
                );
    }

    private static ChainBuilder createCart() {
        ChainBuilder cartWithGrant = exec(
                http("POST /v2/carts with grant")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", "${csrf}")
                        .body(StringBody("{\"product_id\":\"${productId}\",\"variant_id\":\"${variantId}\",\"grant_id\":\"${grantId}\"}")).asJson()
                        .check(status().is(201))
                        .check(header("ETag").saveAs("etag"))
                        .check(bodyString().saveAs("cartBody")))
                .exitHereIfFailed();

        ChainBuilder cartWithoutGrant = exec(
                http("POST /v2/carts")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", "${csrf}")
                        .body(StringBody("{\"product_id\":\"${productId}\",\"variant_id\":\"${variantId}\"}")).asJson()
                        .check(status().is(201))
                        .check(header("ETag").saveAs("etag"))
                        .check(bodyString().saveAs("cartBody")))
                .exitHereIfFailed();

        return doIf(session -> session.contains("grantId"))
                .then(cartWithGrant)
                .orElse(cartWithoutGrant)
                .exec(session -> {
                    String body = session.contains("cartBody") ? session.getString("cartBody") : null;
                    String cartId = first(ID_JSON, body);
                    String csrf = extractCsrf(body);
                    Session updated = session;
                    if (cartId != null) {
                        updated = updated.set("cartId", cartId);
                    }
                    if (csrf != null) {
                        updated = updated.set("csrf", csrf);
                    }
                    if (cartId == null) {
                        updated = updated.markAsFailed();
                    }
                    return updated;
                });
    }

    private static ChainBuilder patchCart() {
        ChainBuilder firstPatch = exec(
                http("PATCH cart")
                        .patch("/v2/carts/${cartId}")
                        .header("X-CSRF-Token", "${csrf}")
                        .header("If-Match", "${etag}")
                        .body(StringBody("{\"quantity\":1}")).asJson()
                        .check(status().in(200, 412).saveAs("patchStatus"))
                        .check(header("ETag").optional().saveAs("etag"))
                        .check(bodyString().saveAs("patchBody")))
                .exec(session -> updateCsrfFrom(session, "patchBody"));

        ChainBuilder retryPatch = exec(
                http("PATCH cart retry")
                        .patch("/v2/carts/${cartId}")
                        .header("X-CSRF-Token", "${csrf}")
                        .header("If-Match", "${etag}")
                        .body(StringBody("{\"quantity\":1}")).asJson()
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("etag"))
                        .check(bodyString().saveAs("patchRetryBody")))
                .exec(session -> updateCsrfFrom(session, "patchRetryBody"));

        return firstPatch
                .doIf(session -> session.contains("patchStatus") && session.getInt("patchStatus") == 412).then(
                        exec(
                                http("GET cart ETag")
                                        .get("/v2/carts/${cartId}")
                                        .check(status().is(200))
                                        .check(header("ETag").saveAs("etag")))
                                .exitHereIfFailed()
                                .exec(retryPatch)
                );
    }

    private static ChainBuilder reserveAndPoll() {
        ChainBuilder reserve = exec(
                http("POST /v2/reservations")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", "${csrf}")
                        .body(StringBody("{\"cart_id\":\"${cartId}\"}")).asJson()
                        .check(status().is(202))
                        .check(bodyString().saveAs("reservationBody")))
                .exitHereIfFailed()
                .exec(session -> {
                    String body = session.contains("reservationBody") ? session.getString("reservationBody") : null;
                    String statusUrl = first(STATUS_URL, body);
                    String csrf = extractCsrf(body);
                    Session updated = session
                            .set("pollCount", 0)
                            .set("shouldPoll", statusUrl != null)
                            .set("reservationReady", false)
                            .set("jobFailed", false);
                    if (statusUrl != null) {
                        updated = updated.set("statusUrl", statusUrl);
                    }
                    if (csrf != null) {
                        updated = updated.set("csrf", csrf);
                    }
                    if (statusUrl == null) {
                        updated = updated.markAsFailed();
                    }
                    return updated;
                })
                .exitHereIfFailed();

        ChainBuilder poll = pause(POLL_PAUSE)
                .exec(
                        http("Poll reservation status")
                                .get("${statusUrl}")
                                .check(status().is(200))
                                .check(bodyString().saveAs("pollBody")))
                .exitHereIfFailed()
                .exec(session -> {
                    int pollCount = session.getInt("pollCount") + 1;
                    String body = session.contains("pollBody") ? session.getString("pollBody") : null;
                    String status = first(STATUS, body);
                    String reservationId = first(RESERVATION_ID, body);
                    String csrf = extractCsrf(body);

                    Session updated = session.set("pollCount", pollCount);
                    if (csrf != null) {
                        updated = updated.set("csrf", csrf);
                    }

                    if (status != null && status.equalsIgnoreCase("ready") && reservationId != null) {
                        updated = updated
                                .set("reservationReady", true)
                                .set("shouldPoll", false)
                                .set("reservationId", reservationId);
                    } else if (status != null && status.equalsIgnoreCase("failed")) {
                        updated = updated
                                .set("jobFailed", true)
                                .set("reservationReady", false)
                                .set("shouldPoll", false);
                    } else if (status != null && status.equalsIgnoreCase("ready")) {
                        updated = updated
                                .set("jobFailed", true)
                                .set("reservationReady", false)
                                .set("shouldPoll", false);
                    } else if (pollCount >= 5) {
                        updated = updated.set("shouldPoll", false);
                    }

                    return updated;
                });

        return reserve
                .asLongAs(session -> session.getBoolean("shouldPoll") && session.getInt("pollCount") < 5).on(poll)
                .exec(session -> {
                    if (!session.getBoolean("reservationReady") || !session.contains("reservationId")) {
                        return session.markAsFailed();
                    }
                    return session;
                });
    }

    private static ChainBuilder order() {
        return exec(
                http("POST /v2/orders")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", "${csrf}")
                        .header("Idempotency-Key", "${cartId}")
                        .header("If-Match", "${etag}")
                        .body(StringBody("{\"cart_id\":\"${cartId}\",\"reservation_id\":\"${reservationId}\"}")).asJson()
                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is(true))
                        .check(bodyString().saveAs("orderBody")))
                .exec(session -> updateCsrfFrom(session, "orderBody"));
    }

    private HttpProtocolBuilder httpProtocol = http
            .baseUrl(System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000")
            .disableFollowRedirect();

    private ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> session.set("iteration", 0))
            .repeat(2).on(
                    exec(initJourney)
                            .exec(login())
                            .exitHereIfFailed()
                            .exec(catalog())
                            .exitHereIfFailed()
                            .exec(challenge())
                            .exitHereIfFailed()
