function absoluteUrl(url) {
  if (!url) return BASE_URL;
  if (/^https?:\/\//i.test(url)) {
    if (url.indexOf(BASE_URL) === 0) return url;
    const m = url.match(/^https?:\/\/[^\/]+(\/.*)$/i);
    if (m) return BASE_URL + m[1];
    return BASE_URL;
  }
  if (url.charAt(0) === '/') return BASE_URL + url;
  return BASE_URL + '/' + url;
