function extractInputValue(html, name) {
  if (!html) return '';
  const re = /<input\b[^>]*>/gi;
  let m;
  let emptyValue = '';
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const nm = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nm) continue;
    const actual = nm[1] !== undefined ? nm[1] : (nm[2] !== undefined ? nm[2] : nm[3]);
    if (actual !== name) continue;
    const vm = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (vm) {
      const value = vm[1] !== undefined ? vm[1] : (vm[2] !== undefined ? vm[2] : vm[3]);
      if (value !== '') return value;
      emptyValue = value;
    }
  }
  return emptyValue;
