function extractFormAction(html, contains) {
  if (!html) return '';
  const re = /<form\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const am = tag.match(/\baction\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!am) continue;
    const action = am[1] !== undefined ? am[1] : (am[2] !== undefined ? am[2] : am[3]);
