function findStringKey(obj, keys, depth) {
  depth = depth || 0;
  if (!obj || depth > 8) return '';
  if (Array.isArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      const r = findStringKey(obj[i], keys, depth + 1);
      if (r) return r;
    }
    return '';
  }
  if (typeof obj === 'object') {
    for (let i = 0; i < keys.length; i++) {
      if (typeof obj[keys[i]] === 'string') return obj[keys[i]];
    }
    for (const k in obj) {
      if (keys.indexOf(k) !== -1) continue;
      const r = findStringKey(obj[k], keys, depth + 1);
