function getGrant(state) {
  const res = http.get(BASE_URL + '/v2/challenge-form', {
    redirects: 0,
    tags: { name: 'challenge-form' }
  });

  if (res.status === 404) return { ok: true, grant: '' };
  check(res, { 'challenge-form 200': function(r) { return r.status === 200; } });
  if (res.status !== 200) return { ok: false, grant: '' };

  const action = extractFormAction(res.body, '/v2/challenges/');
  const challenge = extractInputValue(res.body, 'challenge');
  check(action, { 'challenge action present': function(v) { return !!v; } });
  check(challenge, { 'challenge value present': function(v) { return !!v; } });
  if (!action || !challenge) return { ok: false, grant: '' };

  const postRes = http.post(absoluteUrl(action), JSON.stringify({ challenge: challenge }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    redirects: 0,
    tags: { name: 'challenge-submit' }
  });

  let body = safeJson(postRes);

  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location');
    check(loc, { 'challenge redirect location present': function(v) { return !!v; } });
    if (!loc) return { ok: false, grant: '' };

    const followRes = http.get(absoluteUrl(loc), {
      redirects: 0,
      tags: { name: 'challenge-location' }
    });
    check(followRes, { 'challenge location 200': function(r) { return r.status === 200; } });
    body = safeJson(followRes);
  } else {
    check(postRes, { 'challenge submit 302': function(r) { return r.status === 302; } });
  }

