  let grant = body && (body.grant_id || (body.data && body.data.grant_id));
  if (!grant) grant = findScalarKey(body, ['grant_id', 'grantId'], 0);
  check(grant, { 'grant_id extracted': function(v) { return !!v; } });
  return { ok: !!grant, grant: grant || '' };
}

function buildHeaders(method, state, extraHeaders, hasBody) {
  const headers = {};
  if (hasBody) headers['Content-Type'] = 'application/json';
  if (method !== 'GET' && method !== 'HEAD') headers['X-CSRF-Token'] = state.csrf;
  if (extraHeaders) {
    for (const k in extraHeaders) {
      if (extraHeaders[k]) headers[k] = extraHeaders[k];
    }
  }
  return headers;
}

function performRequest(method, path, payload, state, extraHeaders, tag) {
  const hasBody = payload !== undefined && payload !== null;
  const headers = buildHeaders(method, state, extraHeaders, hasBody);
  const body = hasBody ? JSON.stringify(payload) : null;
  return http.request(method, absoluteUrl(path), body, {
    headers: headers,
    redirects: 0,
    tags: { name: tag || method }
  });
}

