function authedRequest(method, path, payload, extraHeaders, state, cartId, tag) {
  let res = performRequest(method, path, payload, state, extraHeaders, tag);

  if (res.status === 401) {
    const err = getError(res);
    if (err === 'denied') {
      check(res, { '401 denied not recovered': function() { return false; } });
      return res;
    }
    recoverSession(state, cartId, err);
    res = performRequest(method, path, payload, state, extraHeaders, tag ? tag + '-retry' : 'retry');
  }

  return res;
}

function createCart(state, product, grant) {
  const payload = {
    product_id: product.product_id,
    variant_id: product.variant_id
  };
