function setCartQuantity(state, cartId, etag, quantity) {
  let currentEtag = etag || '';

  if (!currentEtag) {
    const getRes = getCart(state, cartId);
    currentEtag = getHeader(getRes, 'ETag');
  }

  const payload = { quantity: quantity };
  let res = authedRequest('PATCH', '/v2/carts/' + cartId, payload, { 'If-Match': currentEtag }, state, cartId, 'cart-patch');

  if (res.status === 412) {
    const getRes = getCart(state, cartId);
    currentEtag = getHeader(getRes, 'ETag');
    res = authedRequest('PATCH', '/v2/carts/' + cartId, payload, { 'If-Match': currentEtag }, state, cartId, 'cart-patch-retry');
  }

