  updateCsrf(state, safeJson(res));

  const newEtag = getHeader(res, 'ETag');
  if (newEtag) {
    currentEtag = newEtag;
  } else {
    const getRes = getCart(state, cartId);
    const latestEtag = getHeader(getRes, 'ETag');
    if (latestEtag) currentEtag = latestEtag;
  }

  return currentEtag;
}

function createReservation(state, cartId) {
  const res = authedRequest('POST', '/v2/reservations', { cart_id: cartId }, null, state, cartId, 'reservation-create');
  check(res, { 'reservation create 202': function(r) { return r.status === 202; } });

