function pollReservation(state, statusUrl, cartId) {
  let polls = 0;

  while (polls < MAX_POLLS) {
    sleep(POLL_INTERVAL);
    polls++;

    let res = http.get(absoluteUrl(statusUrl), {
      redirects: 0,
      tags: { name: 'reservation-status' }
    });

    if (res.status === 401) {
      const err = getError(res);
      if (err === 'denied') {
        check(res, { 'reservation status denied': function() { return false; } });
        return '';
      }
      recoverSession(state, cartId, err);
      if (polls < MAX_POLLS) {
        sleep(POLL_INTERVAL);
        polls++;
        res = http.get(absoluteUrl(statusUrl), {
          redirects: 0,
          tags: { name: 'reservation-status-retry' }
        });
      }
    }

    check(res, { 'reservation status 200': function(r) { return r.status === 200; } });

    const body = safeJson(res);
    updateCsrf(state, body);

    const status = getStatus(body);

    if (status === 'failed' || status === 'error' || status === 'cancelled') {
      check(body, { 'reservation job did not fail': function() { return false; } });
      return '';
    }

    if (status === 'ready') {
      const rid = getReservationId(body);
      check(rid, { 'reservation_id present when ready': function(v) { return !!v; } });
      return rid || '';
    }
  }

  check(null, { 'reservation ready within 5 polls': function() { return false; } });
  return '';
}

function placeOrder(state, cartId, etag, reservationId) {
  const idempotencyKey = 'order-' + cartId;
  const payload = {
    cart_id: cartId,
    reservation_id: reservationId
  };

  const headers = { 'Idempotency-Key': idempotencyKey };
  if (etag) headers['If-Match'] = etag;

  let res = authedRequest('POST', '/v2/orders', payload, headers, state, cartId, 'order-create');

  if (res.status === 412) {
    const getRes = getCart(state, cartId);
    const newEtag = getHeader(getRes, 'ETag');
    if (newEtag) headers['If-Match'] = newEtag;
    res = authedRequest('POST', '/v2/orders', payload, headers, state, cartId, 'order-create-retry');
  }

  const body = safeJson(res);
  const accepted = body && body.accepted === true;

  check(res, { 'order 201': function(r) { return r.status === 201; } });
  check(res, { 'order accepted true': function() { return accepted; } });

  updateCsrf(state, body);
  return res.status === 201 && accepted;
}

export default function () {
