import os
import itertools
from html.parser import HTMLParser
from urllib.parse import urlparse

import gevent
from locust import HttpUser, task, constant, LoadTestShape
from locust.exception import StopUser

TOTAL_USERS = int(os.environ.get("USERS", "2"))
MAX_ITERATIONS = int(os.environ.get("ITERATIONS", "2"))
POLL_INTERVAL = max(0.05, float(os.environ.get("POLL_INTERVAL", "0.05")))
POLL_MAX = 5

_account_counter = itertools.count(1)
FINISHED_USERS = 0


def _relative_url(url):
    if not url:
        return url
    if url.startswith("http://") or url.startswith("https://"):
        parsed = urlparse(url)
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        return path
    if url.startswith("/"):
        return url
    return "/" + url


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self.current = None
        self.csrf_values = []
        self.challenge_values = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {}
        for k, v in attrs:
            if k:
                attrs_dict[k.lower()] = v if v is not None else ""

        if tag == "form":
            self.current = {"action": attrs_dict.get("action"), "inputs": []}
            self.forms.append(self.current)
        elif tag == "input":
            name = attrs_dict.get("name", "").lower()
            value = attrs_dict.get("value")
            inp = {
                "name": name,
                "value": value,
                "type": attrs_dict.get("type", "").lower(),
            }
            if self.current is not None:
                self.current["inputs"].append(inp)
            if name == "csrf" and value is not None:
                self.csrf_values.append((self.current, value))
            if name == "challenge" and value is not None:
                self.challenge_values.append((self.current, value))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current = None


def _extract_csrf(html):
    parser = _FormParser()
    parser.feed(html)

    for form, value in parser.csrf_values:
        action = (form or {}).get("action") or ""
        if "/v2/login" in action and value:
            return value

    for _, value in parser.csrf_values:
        if value:
            return value

    return None


def _extract_challenge_form(html):
    parser = _FormParser()
    parser.feed(html)

    for form in parser.forms:
        action = form.get("action") or ""
        if "/v2/challenges" in action:
            for inp in form["inputs"]:
                if inp["name"] == "challenge" and inp["value"] is not None:
                    return action, inp["value"]

    action = None
    for form in parser.forms:
        a = form.get("action") or ""
        if "/v2/challenges" in a:
            action = a
            break

    if action:
        for _, value in parser.challenge_values:
            if value is not None:
                return action, value

    return None, None


def _extract_products(data):
    products = []
    if not isinstance(data, dict):
        return products

    inner = data.get("data")
    if isinstance(inner, dict):
        if isinstance(inner.get("products"), list):
            products.extend(inner["products"])
        if isinstance(inner.get("product"), dict):
            products.append(inner["product"])

    if isinstance(data.get("products"), list):
        products.extend(data["products"])
    if isinstance(data.get("product"), dict):
        products.append(data["product"])

    return products


def _extract_next(data):
    if not isinstance(data, dict):
        return None
    if data.get("next") is not None:
        return data["next"]
    inner = data.get("data")
    if isinstance(inner, dict) and inner.get("next") is not None:
        return inner["next"]
    return None


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = constant(0)

    def on_start(self):
        n = next(_account_counter)
        self.username = f"bench-{n}" if n <= 16 else "bench"
        self.iterations_done = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None

    def on_stop(self):
        global FINISHED_USERS
        FINISHED_USERS += 1

    def _json(self, response):
        try:
            return response.json()
        except Exception:
            return {}

    def _renew(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            catch_response=True,
            name="/v2/session/renew",
        ) as response:
            if response.status_code == 200:
                data = self._json(response)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                response.success()
            elif response.status_code >= 500:
                response.failure(f"renew failed {response.status_code}")
            else:
                response.success()

    def _recover_cart(self):
        if not self.cart_id:
            return
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            catch_response=True,
            name="/v2/carts/[id]/recover",
        ) as response:
            if response.status_code == 200:
                data = self._json(response)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                etag = response.headers.get("ETag") or response.headers.get("etag")
                if etag:
                    self.etag = etag
                response.success()
            elif response.status_code >= 500:
                response.failure(f"recover failed {response.status_code}")
            else:
                response.success()

    def _relogin_and_recover(self):
        self._login()
        if self.cart_id:
            self._recover_cart()

    def _get_json(
        self,
        path,
        name,
        expected=(200,),
        allow_redirects=True,
        _retry=False,
        validate=None,
    ):
        path = _relative_url(path)
        with self.client.get(
            path,
            catch_response=True,
            name=name,
            allow_redirects=allow_redirects,
        ) as response:
            status = response.status_code
            data = self._json(response)

            if status == 401:
                err = data.get("error") if isinstance(data, dict) else None
                if not _retry and err == "expired":
                    response.success()
                    self._renew()
                    if self.cart_id:
                        self._recover_cart()
                    return self._get_json(
                        path, name, expected, allow_redirects, True, validate
                    )
                if not _retry and err == "session":
                    response.success()
                    self._relogin_and_recover()
                    return self._get_json(
                        path, name, expected, allow_redirects, True, validate
                    )
                response.failure(f"GET auth failure: {err}")
                return None

            if status not in expected:
                response.failure(f"GET {name} expected {expected}, got {status}")
                return None

            if validate is not None and not validate(
                response, data, dict(response.headers)
            ):
                return None

            response.success()
            return status, data, response.text, dict(response.headers)

    def _post_json(
        self,
        path,
        payload,
        name,
        headers,
        expected=(200,),
        allow_redirects=True,
        _retry=False,
        validate=None,
    ):
        path = _relative_url(path)
        with self.client.post(
            path,
            json=payload,
            headers=headers,
            catch_response=True,
            name=name,
            allow_redirects=allow_redirects,
        ) as response:
            status = response.status_code
            data = self._json(response)

            if status == 401:
                err = data.get("error") if isinstance(data, dict) else None
                if not _retry and err == "expired":
                    response.success()
                    self._renew()
                    if self.cart_id:
                        self._recover_cart()
                    new_headers = dict(headers)
                    if self.csrf:
                        new_headers["X-CSRF-Token"] = self.csrf
                    return self._post_json(
                        path,
                        payload,
                        name,
                        new_headers,
                        expected,
                        allow_redirects,
                        True,
                        validate,
                    )
                if not _retry and err == "session":
                    response.success()
                    self._relogin_and_recover()
                    new_headers = dict(headers)
                    if self.csrf:
                        new_headers["X-CSRF-Token"] = self.csrf
                    return self._post_json(
                        path,
                        payload,
                        name,
                        new_headers,
                        expected,
                        allow_redirects,
                        True,
                        validate,
                    )
                response.failure(f"POST auth failure: {err}")
                return None

            if status not in expected:
                response.failure(f"POST {name} expected {expected}, got {status}")
                return None

            if validate is not None and not validate(
                response, data, dict(response.headers)
            ):
                return None

            response.success()
            return status, data, response.text, dict(response.headers)

    def _login(self):
        csrf = None
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as response:
            if response.status_code != 200:
                response.failure(f"login form failed {response.status_code}")
                return False
            csrf = _extract_csrf(response.text)
            if not csrf:
                response.failure("login csrf not found")
                return False
            response.success()

        self.csrf = csrf
        login_info = {}

        def validate_login(resp, data, resp_headers):
            if resp.status_code == 302:
                loc = resp_headers.get("Location") or resp_headers.get("location")
                if not loc:
                    resp.failure("login 302 missing Location")
                    return False
                login_info["location"] = loc
                if isinstance(data, dict) and data.get("csrf"):
                    login_info["csrf"] = data["csrf"]
                return True

            if resp.status_code == 200:
                new_csrf = None
                if isinstance(data, dict):
                    new_csrf = data.get("csrf")
                if not new_csrf:
                    new_csrf = _extract_csrf(resp.text)
                if new_csrf:
                    login_info["csrf"] = new_csrf
                return True

            return False

        result = self._post_json(
            "/v2/login",
            {"username": self.username, "password": "bench", "csrf": csrf},
            name="/v2/login",
            headers={"X-CSRF-Token": csrf},
            expected=(200, 302),
            allow_redirects=False,
            validate=validate_login,
        )
        if not result:
            return False

        status, data, text, resp_headers = result

        if status == 302:
            loc = _relative_url(login_info["location"])
            with self.client.get(
                loc,
                allow_redirects=False,
                catch_response=True,
                name="login-location",
            ) as loc_resp:
                if loc_resp.status_code not in (200, 204, 302):
                    loc_resp.failure(f"login location failed {loc_resp.status_code}")
                    return False

                loc_data = self._json(loc_resp)
                new_csrf = _extract_csrf(loc_resp.text)
                if not new_csrf and isinstance(loc_data, dict):
                    new_csrf = loc_data.get("csrf")

                loc_resp.success()

            if new_csrf:
                self.csrf = new_csrf
            elif login_info.get("csrf"):
                self.csrf = login_info["csrf"]
            else:
                self.csrf = csrf
            return True

        if login_info.get("csrf"):
            self.csrf = login_info["csrf"]
        else:
            self.csrf = csrf
        return True

    def _get_grant_id(self):
        form_info = {}

        def validate_form(resp, data, resp_headers):
            if resp.status_code == 404:
                return True
            action, challenge_val = _extract_challenge_form(resp.text)
            if not action or challenge_val is None:
                resp.failure("challenge form malformed")
                return False
            form_info["action"] = action
            form_info["challenge"] = challenge_val
            return True

        result = self._get_json(
            "/v2/challenge-form",
            name="/v2/challenge-form",
            expected=(200, 404),
            validate=validate_form,
        )
        if not result:
            return None

        status, data, text, resp_headers = result
        if status == 404:
            return None

        action = _relative_url(form_info["action"])
        challenge_val = form_info["challenge"]
        post_info = {}

        def validate_post(resp, data, resp_headers):
            loc = resp_headers.get("Location") or resp_headers.get("location")
            if not loc:
                resp.failure("challenge missing Location")
                return False
            post_info["location"] = loc
            return True

        result = self._post_json(
            action,
            {"challenge": challenge_val},
            name="/v2/challenges/[id]",
            headers={"X-CSRF-Token": self.csrf},
            expected=(302,),
            allow_redirects=False,
            validate=validate_post,
        )
        if not result:
            return None

        loc = _relative_url(post_info["location"])
        grant_info = {}

        def validate_grant(resp, data, resp_headers):
            if not isinstance(data, dict) or not data.get("grant_id"):
                resp.failure("grant_id missing")
                return False
            grant_info["grant_id"] = data["grant_id"]
            if data.get("csrf"):
                grant_info["csrf"] = data["csrf"]
            return True

        result = self._get_json(
            loc,
            name="challenge-location",
            expected=(200,),
            allow_redirects=False,
            validate=validate_grant,
        )
        if not result:
            return None

        status, data, text, resp_headers = result
        if data.get("csrf"):
            self.csrf = data["csrf"]
        return grant_info["grant_id"]

    def _pick_product(self):
        def find_in_stock(products):
            for product in products:
                if not isinstance(product, dict):
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if isinstance(variant, dict) and variant.get("in_stock"):
                        return product.get("id"), variant.get("id")
            return None

        result = self._get_json("/v2/catalog", name="/v2/catalog", expected=(200,))
        if not result:
            return None, None

        status, data, text, resp_headers = result
        products = _extract_products(data)

        found = find_in_stock(products)
        if found:
            return found

        url = "/v2/catalog/page"
        for _ in range(3):
            result = self._get_json(url, name="/v2/catalog/page", expected=(200,))
            if not result:
                return None, None

            status, data, text, resp_headers = result
            products.extend(_extract_products(data))

            found = find_in_stock(products)
            if found:
                return found

            next_url = _extract_next(data)
            if not next_url:
                break
            url = _relative_url(next_url)

        return None, None

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id

        cart_info = {}

        def validate_cart(resp, data, resp_headers):
            if not isinstance(data, dict) or not data.get("id"):
                resp.failure("cart id missing")
                return False
            cart_info["id"] = data["id"]
            cart_info["csrf"] = data.get("csrf")
            cart_info["etag"] = resp_headers.get("ETag") or resp_headers.get("etag")
            return True

        result = self._post_json(
            "/v2/carts",
            payload,
            name="/v2/carts",
            headers={"X-CSRF-Token": self.csrf},
            expected=(201,),
            validate=validate_cart,
        )
        if not result:
            return False

        self.cart_id = cart_info["id"]
        self.etag = cart_info.get("etag")
        if cart_info.get("csrf"):
            self.csrf = cart_info["csrf"]
        return True

    def _refresh_etag(self):
        if not self.cart_id:
            return
        result = self._get_json(
            f"/v2/carts/{self.cart_id}",
            name="/v2/carts/[id]",
            expected=(200,),
        )
        if result:
            status, data, text, resp_headers = result
            etag = resp_headers.get("ETag") or resp_headers.get("etag")
            if etag:
                self.etag = etag
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]

    def _reserve_and_poll(self):
        res_info = {}

        def validate_reservation(resp, data, resp_headers):
            if not isinstance(data, dict) or not data.get("status_url"):
                resp.failure("status_url missing")
                return False
            res_info["status_url"] = data["status_url"]
            return True

        result = self._post_json(
            "/v2/reservations",
            {"cart_id": self.cart_id},
            name="/v2/reservations",
            headers={"X-CSRF-Token": self.csrf},
            expected=(202,),
            validate=validate_reservation,
        )
        if not result:
            return None

        status, data, text, resp_headers = result
        if data.get("csrf"):
            self.csrf = data["csrf"]

        status_url = _relative_url(res_info["status_url"])
        polls = 0
        retried_401 = False

        while polls < POLL_MAX:
            if polls > 0:
                gevent.sleep(POLL_INTERVAL)
            polls += 1

            with self.client.get(
                status_url,
                catch_response=True,
                name="/v2/reservations/status",
            ) as response:
                if response.status_code == 401:
                    data = self._json(response)
                    err = data.get("error") if isinstance(data, dict) else None
                    if err == "expired" and not retried_401:
                        response.success()
                        retried_401 = True
                        polls -= 1
                        self._renew()
                        continue
                    response.failure(f"status poll auth failure: {err}")
                    return None

                if response.status_code != 200:
                    response.failure(
                        f"status poll failed {response.status_code}"
                    )
                    return None

                data = self._json(response)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]

                job_status = data.get("status") if isinstance(data, dict) else None

                if job_status == "ready":
                    reservation_id = data.get("reservation_id")
                    if not reservation_id:
                        response.failure("reservation_id missing")
                        return None
                    response.success()
                    return reservation_id

                if job_status == "failed":
                    response.failure("reservation job failed")
                    return None

                if job_status == "pending":
                    if polls >= POLL_MAX:
                        response.failure("reservation pending at max polls")
                        return None
                    response.success()
                    continue

                response.failure(f"unexpected reservation status: {job_status}")
                return None

        return None

    def _checkout(self, reservation_id):
        self._refresh_etag()

        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": f"cart-{self.cart_id}-order",
        }
        if self.etag:
            headers["If-Match"] = self.etag

        def validate_order(resp, data, resp_headers):
            if resp.status_code == 201:
                if not isinstance(data, dict) or data.get("accepted") is not True:
                    resp.failure("order 201 but accepted not true")
                    return False
                return True
            if resp.status_code == 200:
                if isinstance(data, dict) and data.get("accepted") is False:
                    resp.failure("order business failure")
                else:
                    resp.failure("unexpected order 200")
                return False
            return False

        result = self._post_json(
            "/v2/orders",
            {"cart_id": self.cart_id, "reservation_id": reservation_id},
            name="/v2/orders",
            headers=headers,
            expected=(201, 200),
            validate=validate_order,
        )
        return bool(result)

    def _run_journey(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None

        if not self._login():
            return

        product_id, variant_id = self._pick_product()
        if not product_id or not variant_id:
            return

        grant_id = self._get_grant_id()

        if not self._create_cart(product_id, variant_id, grant_id):
            return

        reservation_id = self._reserve_and_poll()
        if not reservation_id:
            return

        self._checkout(reservation_id)

    @task
    def journey(self):
        if self.iterations_done >= MAX_ITERATIONS:
            raise StopUser()

        try:
            self._run_journey()
        except Exception:
            pass
        finally:
            self.iterations_done += 1
            if self.iterations_done >= MAX_ITERATIONS:
                raise StopUser()


class OneRunShape(LoadTestShape):
    def tick(self):
        global FINISHED_USERS
        if FINISHED_USERS >= TOTAL_USERS:
            return None

        runner = getattr(self, "runner", None)
        current = 0
        if runner is not None:
            try:
                current = int(runner.user_count)
            except Exception:
                current = 0

        desired = max(current, TOTAL_USERS - FINISHED_USERS)
        if desired < 1:
            desired = 1
        return (desired, 2)

