    } catch (_) {
      return null;
    }
  }

  function headerValue(headers, name) {
    const lname = name.toLowerCase();
    for (const k in headers) {
      if (k.toLowerCase() === lname) {
        const v = headers[k];
        return Array.isArray(v) ? v[0] : v;
      }
    }
    return null;
  }

  function resolveUrl(path) {
    if (!path) return null;
    if (/^https?:\/\//i.test(path)) return path;
    if (path.startsWith('/')) return BASE_URL + path;
    return BASE_URL + '/' + path;
  }

  function extractCsrfFromHtml(html) {
    try {
      const doc = parseHTML(html || '');
      const el = doc.find('input[name="csrf"]');
      const v = el.attr('value');
      if (v) return v;
    } catch (_) {}

    const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
    const m = re.exec(html || '');
    return m ? m[1] : null;
  }

  function getErrorCode(res) {
    const body = safeJson(res);
    return body && typeof body.error === 'string' ? body.error : null;
  }

  function updateCsrfFromResponse(res) {
    const body = safeJson(res);
    if (body && body.csrf) state.csrf = body.csrf;
  }

  function updateEtagFromResponse(res) {
    const etag = headerValue(res.headers, 'ETag');
    if (etag) state.etag = etag;
