    const formCsrf = extractCsrfFromHtml(formRes.body);
    check(formRes, { 'login-form csrf present': () => !!formCsrf });
    if (!formCsrf) throw new Error('missing form csrf');

    const loginPayload = JSON.stringify({
      username: state.username,
      password: state.password,
      csrf: formCsrf,
    });

    let loginRes = http.post(BASE_URL + '/v2/login', loginPayload, {
      redirects: 0,
