      updateCsrfFromResponse(recRes);
      updateEtagFromResponse(recRes);
    }
  }

  function perform(method, path, body, extraHeaders, expectedStatuses, opName) {
    const url = path.startsWith('http') ? path : BASE_URL + path;

    const doReq = () => {
      const params = { redirects: 0, headers: makeHeaders(extraHeaders) };
      if (method === 'GET') return http.get(url, params);
      if (method === 'POST') return http.post(url, body, params);
      if (method === 'PATCH') return http.patch(url, body, params);
      throw new Error('Unsupported method: ' + method);
    };

    let res = doReq();

    if (res.status === 401) {
      const err = getErrorCode(res);
      if (err === 'expired') {
        recoverExpired();
        res = doReq();
      } else if (err === 'session') {
        recoverSession();
        res = doReq();
      }
    }

    check(res, { [`${opName} status`]: (r) => expectedStatuses.indexOf(r.status) !== -1 });
    updateCsrfFromResponse(res);
    updateEtagFromResponse(res);
    return res;
  }

  doLogin();

  const catalogRes = perform('GET', '/v2/catalog', null, {}, [200], 'GET /v2/catalog');
  const catalogBody = safeJson(catalogRes);
  if (catalogBody && catalogBody.csrf) state.csrf = catalogBody.csrf;

  if (catalogBody && catalogBody.data && Array.isArray(catalogBody.data.products)) {
    for (const p of catalogBody.data.products) {
