      }
    }
  }

  check(catalogRes, { 'catalog has in-stock product': () => !!(state.productId && state.variantId) });
  if (!state.productId || !state.variantId) throw new Error('no in-stock product');

  const cartPayload = {
    product_id: state.productId,
    variant_id: state.variantId,
