  const cartRes = perform('POST', '/v2/carts', JSON.stringify(cartPayload), {}, [201], 'POST /v2/carts');
  const cartBody = safeJson(cartRes);
  if (cartBody && cartBody.id) {
    state.cartId = cartBody.id;
    state.hasCart = true;
  }
  if (cartBody && cartBody.csrf) state.csrf = cartBody.csrf;

  check(cartRes, { 'cart response has id': () => !!state.cartId });
  check(cartRes, { 'cart id starts with cart-': () => !!(state.cartId && state.cartId.startsWith('cart-')) });
  if (!state.cartId) throw new Error('missing cart id');

  const orderPayload = JSON.stringify({ cart_id: state.cartId });
  const orderRes = perform(
    'POST',
    '/v2/orders',
    orderPayload,
    { 'Idempotency-Key': state.cartId },
    [201],
    'POST /v2/orders'
  );

  const orderBody = safeJson(orderRes);
  check(orderRes, { 'order accepted true': () => !!(orderBody && orderBody.accepted === true) });
  if (!orderBody || orderBody.accepted !== true) throw new Error('order not accepted');
}
