import os
import itertools
from html.parser import HTMLParser
from urllib.parse import urlparse, urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USERS = 2
ITERATIONS_PER_USER = 2

ACTIVE_USERS = 0
COMPLETED_USERS = 0
USER_COUNTER = itertools.count(1)


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []
        self.forms = []

    def handle_starttag(self, tag, attrs):
        attr_map = {}
        for key, value in attrs:
            if key:
                attr_map[key.lower()] = value
        tag = tag.lower()
        if tag == "input":
            self.inputs.append(attr_map)
        elif tag == "form":
            self.forms.append(attr_map)

    def find_input(self, name):
        wanted = name.lower()
        for attrs in self.inputs:
            attr_name = attrs.get("name")
            if not isinstance(attr_name, str) or attr_name.lower() != wanted:
                continue
            if "disabled" in attrs:
                continue
            value = attrs.get("value")
            if value is not None and value != "":
                return value
        return None

    def challenge(self):
        action = None
        for form in self.forms:
            candidate = form.get("action")
            if isinstance(candidate, str) and "/v2/challenges/" in candidate:
                action = candidate
                break

        challenge_value = None
        for attrs in self.inputs:
            attr_name = attrs.get("name")
            if not isinstance(attr_name, str) or attr_name.lower() != "challenge":
                continue
            if "disabled" in attrs:
                continue
            value = attrs.get("value")
            if value is not None:
                challenge_value = value
                break

        return action, challenge_value


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0, 0)
    network_timeout = 3.0

    def __init__(self, environment):
        super().__init__(environment)
        global ACTIVE_USERS
        ACTIVE_USERS += 1
        n = next(USER_COUNTER)
        self.username = "bench" if n > 16 else f"bench-{n}"
        self.password = "bench"
        self.iterations_done = 0
        self.completed = False

    def on_stop(self):
        global ACTIVE_USERS, COMPLETED_USERS
        if self.completed:
            COMPLETED_USERS += 1
        ACTIVE_USERS = max(0, ACTIVE_USERS - 1)

    @task
    def shop_journey(self):
        try:
            self._run_journey()
        except Exception:
            pass
        finally:
            self.iterations_done += 1
        if self.iterations_done >= ITERATIONS_PER_USER:
            self.completed = True
            raise StopUser()

    def _run_journey(self):
        self.client.cookies.clear()

        csrf = self._get_login_form()
        if not csrf:
            return

        login = self._login(csrf)
        if not login:
            return

        csrf, grant, _ = login
        if not csrf:
            return

        catalog = self._get_catalog(csrf)
        if not catalog:
            return

        csrf = catalog.get("csrf", csrf)
        if catalog.get("session_revoked"):
            grant = catalog.get("grant")
        elif catalog.get("grant"):
            grant = catalog["grant"]

        product_id = catalog.get("product_id")
        variant_id = catalog.get("variant_id")
        if product_id is None or variant_id is None:
