        csrf = cart.get("csrf", csrf)
        cart_id = cart.get("cart_id")
        etag = cart.get("etag")
        if not cart_id:
            return

        self._place_order(cart_id, etag, csrf)

    def _request(self, method, path, *, headers=None, json_body=None, allow_redirects=False, name=None, validator=None):
        with self.client.request(
            method,
            path,
            headers=headers or {},
            json=json_body,
            allow_redirects=allow_redirects,
            catch_response=True,
            name=name,
        ) as response:
            if validator is not None:
                validator(response)
            else:
                if 200 <= response.status_code < 300:
                    response.success()
                else:
                    response.failure(f"unexpected status {response.status_code}")
            return response

    def _json(self, response):
        try:
            return response.json()
        except Exception:
            return None

    def _error(self, response):
        data = self._json(response)
        if isinstance(data, dict):
            return data.get("error")
        return None

    def _auth_headers(self, csrf, extra=None):
        headers = {"Content-Type": "application/json"}
        if csrf:
            headers["X-CSRF-Token"] = csrf
        if extra:
            headers.update(extra)
        return headers

    def _path_from_location(self, loc, base="/"):
        if not loc:
            return "/"
        parsed = urlparse(loc)
        if parsed.scheme or parsed.netloc:
            path = parsed.path or "/"
            if parsed.query:
                path += "?" + parsed.query
        else:
            path = urljoin(base, loc)
        if not path.startswith("/"):
            path = "/" + path
        return path

    def _get_login_form(self):
        state = {"csrf": None}

        def validator(response):
            if response.status_code == 200:
                parser = _FormParser()
                parser.feed(response.text or "")
                token = parser.find_input("csrf")
                if token:
                    state["csrf"] = token
                    response.success()
                else:
                    response.failure("login form missing csrf")
            else:
                response.failure(f"login form status {response.status_code}")

        self._request("GET", "/v2/login-form", validator=validator)
        return state["csrf"]

    def _login(self, csrf):
        state = {}

        def validator(response):
            if response.status_code == 200:
                data = self._json(response)
                if isinstance(data, dict) and data.get("csrf"):
                    state["csrf"] = data["csrf"]
                    if data.get("grant_id"):
                        state["grant"] = data["grant_id"]
                    if data.get("grant"):
                        state["grant"] = data["grant"]
                    response.success()
                else:
                    response.failure("login missing csrf")
            elif response.status_code == 302:
                location = response.headers.get("Location")
                if location:
                    state["location"] = location
                    response.success()
                else:
                    response.failure("login 302 missing Location")
            elif response.status_code == 401:
                response.failure("login 401")
            else:
                response.failure(f"login status {response.status_code}")

        self._request(
            "POST",
            "/v2/login",
            headers={"Content-Type": "application/json"},
            json_body={"username": self.username, "password": self.password, "csrf": csrf},
            allow_redirects=False,
            validator=validator,
        )

        result_csrf = state.get("csrf") or csrf
        result_grant = state.get("grant")

        if "location" in state:
            page = self._get_location_once(self._path_from_location(state["location"], "/v2/login"))
            if page:
                if page.get("csrf"):
                    result_csrf = page["csrf"]
                if page.get("grant_id"):
                    result_grant = page["grant_id"]
                if page.get("grant"):
                    result_grant = page["grant"]
                if page.get("challenge_action") and page.get("challenge") is not None:
                    challenge = self._do_challenge(page["challenge_action"], page["challenge"], result_csrf)
                    if challenge:
                        if challenge.get("csrf"):
                            result_csrf = challenge["csrf"]
                        if challenge.get("grant_id"):
                            result_grant = challenge["grant_id"]
                        if challenge.get("grant"):
                            result_grant = challenge["grant"]

        return result_csrf, result_grant, state.get("location")

    def _get_location_once(self, path):
        state = {}

        def validator(response):
            if response.status_code == 200:
                data = self._json(response)
                if isinstance(data, dict):
                    state.update(data)
                    if data.get("csrf") or data.get("grant_id") or data.get("grant"):
                        response.success()
                    else:
                        response.failure("login location missing csrf/grant")
                    return

                parser = _FormParser()
                parser.feed(response.text or "")
                action, challenge = parser.challenge()
                if action and challenge is not None:
                    state["challenge_action"] = action
                    state["challenge"] = challenge
                    page_csrf = parser.find_input("csrf")
                    if page_csrf:
                        state["csrf"] = page_csrf
                    response.success()
                else:
                    response.failure("login location missing csrf/grant/challenge")
            else:
                response.failure(f"login location status {response.status_code}")

        self._request("GET", path, allow_redirects=False, name="GET login Location", validator=validator)
        return state

    def _do_challenge(self, action, challenge, csrf):
        state = {}
        action_path = self._path_from_location(action, "/v2/challenge-form")

        def validator(response):
            if response.status_code == 302:
                location = response.headers.get("Location")
                if location:
                    state["location"] = location
                    response.success()
                else:
                    response.failure("challenge 302 missing Location")
            elif response.status_code in (200, 201):
                data = self._json(response)
                if isinstance(data, dict) and (data.get("grant_id") or data.get("grant") or data.get("csrf")):
                    state.update(data)
                    response.success()
                else:
                    response.failure("challenge response missing grant/csrf")
            else:
                response.failure(f"challenge status {response.status_code}")

        self._request(
            "POST",
            action_path,
            headers=self._auth_headers(csrf),
            json_body={"challenge": challenge},
            allow_redirects=False,
            name="POST challenge",
            validator=validator,
        )

        if "location" in state:
            page = self._get_location_once(self._path_from_location(state["location"], action_path))
            state.update(page)

        return state

    def _get_catalog(self, csrf):
        state = {}
        recovered = {}

        def attempt(token, retry):
            state.clear()

            def validator(response):
                if response.status_code == 200:
                    data = self._json(response)
                    if not isinstance(data, dict):
                        response.failure("catalog invalid json")
                        return

                    if data.get("csrf"):
                        state["csrf"] = data["csrf"]

                    data_obj = data.get("data")
                    products = data_obj.get("products") if isinstance(data_obj, dict) else None
                    if not isinstance(products, list):
                        response.failure("catalog missing products")
                        return

                    selected = None
                    for product in products:
                        if not isinstance(product, dict):
                            continue
                        product_id = product.get("id")
                        variants = product.get("variants")
                        if not isinstance(variants, list):
                            continue
                        for variant in variants:
                            if not isinstance(variant, dict):
                                continue
                            if variant.get("in_stock") is True and product_id is not None and variant.get("id") is not None:
                                selected = (product_id, variant.get("id"))
                                break
                        if selected:
                            break

                    if selected is None:
                        response.failure("catalog no in-stock variant")
                        return

                    state["product_id"], state["variant_id"] = selected
                    response.success()
                elif response.status_code == 401:
                    error = self._error(response)
                    if error in ("expired", "session") and retry:
                        state["recover"] = error
                        response.success()
                    elif error == "denied":
                        response.failure("catalog denied")
                    else:
                        response.failure(f"catalog 401 {error}")
                else:
                    response.failure(f"catalog status {response.status_code}")

            self._request("GET", "/v2/catalog", validator=validator)

        attempt(csrf, True)

        if state.get("recover"):
            recovery = self._recover(state["recover"], csrf, cart_id=None)
            if not recovery:
                return None
            if recovery.get("session_revoked"):
                recovered["session_revoked"] = True
            if recovery.get("grant"):
                recovered["grant"] = recovery["grant"]
            attempt(recovery.get("csrf", csrf), False)

        if state.get("product_id") is None:
            return None

        state.update(recovered)
        return state

    def _create_cart(self, product_id, variant_id, grant, csrf):
        state = {}

