            state.clear()

            body = {"product_id": product_id, "variant_id": variant_id}
            if grant_token:
                body["grant_id"] = grant_token

            def validator(response):
                if response.status_code == 201:
                    data = self._json(response)
                    if not isinstance(data, dict):
                        response.failure("cart create invalid json")
                        return
                    cart_id = data.get("id")
                    if not isinstance(cart_id, str) or not cart_id.startswith("cart-"):
                        response.failure("cart create invalid id")
                        return

                    state["cart_id"] = cart_id
                    state["csrf"] = data.get("csrf") or token
                    etag = response.headers.get("ETag") or response.headers.get("etag")
                    if etag:
                        state["etag"] = etag
                    response.success()
                elif response.status_code == 401:
                    error = self._error(response)
                    if error in ("expired", "session") and retry:
                        state["recover"] = error
                        response.success()
                    elif error == "denied":
                        response.failure("cart create denied")
                    else:
                        response.failure(f"cart create 401 {error}")
                else:
                    response.failure(f"cart create status {response.status_code}")

            self._request(
                "POST",
                "/v2/carts",
                headers=self._auth_headers(token),
                json_body=body,
                validator=validator,
            )

        attempt(csrf, True, grant)

        if state.get("recover"):
            recovery = self._recover(state["recover"], csrf, cart_id=None)
            if not recovery:
                return None
            if recovery.get("session_revoked"):
                new_grant = recovery.get("grant")
            else:
                new_grant = recovery.get("grant", grant)
            attempt(recovery.get("csrf", csrf), False, new_grant)

        if not state.get("cart_id"):
            return None
        return state

    def _place_order(self, cart_id, etag, csrf):
        state = {}

        def attempt(token, match, retry):
            state.clear()

            extra = {"Idempotency-Key": cart_id}
            if match:
                extra["If-Match"] = match

            def validator(response):
                if response.status_code in (200, 201):
                    data = self._json(response)
                    if isinstance(data, dict) and data.get("accepted") is True:
                        state["accepted"] = True
                        state["csrf"] = data.get("csrf") or token
                        if data.get("id"):
                            state["order_id"] = data["id"]
                        response.success()
                    elif isinstance(data, dict) and data.get("accepted") is False:
                        response.failure("order business failure accepted false")
                    else:
                        response.failure("order missing accepted true")
                elif response.status_code == 401:
                    error = self._error(response)
                    if error in ("expired", "session") and retry:
                        state["recover"] = error
                        response.success()
                    elif error == "denied":
                        response.failure("order denied")
                    else:
                        response.failure(f"order 401 {error}")
                else:
                    response.failure(f"order status {response.status_code}")

            self._request(
                "POST",
                "/v2/orders",
                headers=self._auth_headers(token, extra),
                json_body={"cart_id": cart_id},
                validator=validator,
            )

        attempt(csrf, etag, True)

        if state.get("recover"):
            recovery = self._recover(state["recover"], csrf, cart_id=cart_id)
            if not recovery:
                return None
            attempt(recovery.get("csrf", csrf), recovery.get("etag", etag), False)

        if not state.get("accepted"):
            return None
        return state

    def _recover(self, kind, csrf, cart_id=None):
        result = {}

        if kind == "expired":
            renewed = self._renew_session(csrf)
            if not renewed:
                return None
            result["csrf"] = renewed
        elif kind == "session":
            fresh = self._fresh_login()
            if not fresh:
                return None
            result["csrf"] = fresh["csrf"]
            result["session_revoked"] = True
            if fresh.get("grant"):
                result["grant"] = fresh["grant"]
        else:
            return None

        if cart_id:
            recovered = self._recover_cart(cart_id, result["csrf"])
            if not recovered:
                return None
            if recovered.get("csrf"):
                result["csrf"] = recovered["csrf"]
            if recovered.get("etag"):
                result["etag"] = recovered["etag"]

        return result

    def _renew_session(self, csrf):
        state = {}

        def validator(response):
            if response.status_code == 200:
                data = self._json(response)
                if isinstance(data, dict) and data.get("csrf"):
                    state["csrf"] = data["csrf"]
                    response.success()
                else:
                    response.failure("renew missing csrf")
            elif response.status_code == 401:
                response.failure("renew failed")
            else:
                response.failure(f"renew status {response.status_code}")

        self._request(
            "POST",
            "/v2/session/renew",
            headers=self._auth_headers(csrf),
            json_body={},
            validator=validator,
        )
        return state.get("csrf")

    def _fresh_login(self):
        self.client.cookies.clear()
        form_csrf = self._get_login_form()
        if not form_csrf:
            return None

        login = self._login(form_csrf)
        if not login:
            return None

        csrf, grant, _ = login
        if not csrf:
            return None

        return {"csrf": csrf, "grant": grant}

    def _recover_cart(self, cart_id, csrf):
        state = {"ok": False}

        def validator(response):
            if response.status_code in (200, 201, 204):
                data = self._json(response) if (response.text or "").strip() else None
                if isinstance(data, dict):
                    if data.get("csrf"):
                        state["csrf"] = data["csrf"]
                    if data.get("id"):
                        state["cart_id"] = data["id"]
                etag = response.headers.get("ETag") or response.headers.get("etag")
                if etag:
                    state["etag"] = etag
                state["ok"] = True
                response.success()
            else:
                response.failure(f"cart recover status {response.status_code}")

        self._request(
            "POST",
            f"/v2/carts/{cart_id}/recover",
            headers=self._auth_headers(csrf),
            json_body={},
            validator=validator,
        )
        return state if state.get("ok") else None


class ShopShape(LoadTestShape):
    def tick(self):
        target = USERS - COMPLETED_USERS
        if target <= 0:
            return None
        if ACTIVE_USERS < target:
            return (target, 100)
        return (target, 1)
```

