import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const accounts = JSON.parse(open('/fixtures/accounts.json'));

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      gracefulStop: '30s',
    },
  },
};

function assert(cond, name) {
  const ok = check(cond, { [name]: (v) => v === true });
  if (!ok) throw new Error(name);
}

function parseJson(res) {
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  const target = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === target) return res.headers[k];
  }
  return null;
}

function absoluteUrl(u) {
  if (!u) return u;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.charAt(0) === '/') return BASE_URL + u;
  return BASE_URL + '/' + u;
}

function getAttr(tag, name) {
  const re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = re.exec(tag);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  return m[3];
}

function parseInputValue(html, inputName) {
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    if (getAttr(tag, 'name') === inputName) {
      return getAttr(tag, 'value');
    }
  }
  return null;
}

function updateCsrf(state, body) {
  if (body && typeof body.csrf === 'string') state.csrf = body.csrf;
}

function authHeaders(state) {
  const headers = { 'Content-Type': 'application/json' };
  if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
  return headers;
}

function sendRequest(method, path, body, state, opts) {
  opts = opts || {};
  const url = absoluteUrl(path);
  const headers = Object.assign({}, opts.headers || {});
  if (method !== 'GET' && state.csrf) headers['X-CSRF-Token'] = state.csrf;
  if (body !== null && body !== undefined && method !== 'GET') headers['Content-Type'] = 'application/json';
  const params = {
    headers: headers,
    redirects: opts.redirects !== undefined ? opts.redirects : 0,
  };
  if (method === 'GET') return http.get(url, params);
  if (method === 'POST') return http.post(url, body === undefined ? null : body, params);
  if (method === 'PATCH') return http.patch(url, body, params);
  if (method === 'DELETE') return http.del(url, body, params);
  throw new Error('unsupported method ' + method);
}

function login(state, account) {
  const formRes = http.get(BASE_URL + '/v2/login-form', { redirects: 0 });
  assert(formRes.status === 200, 'login form status');
  const formCsrf = parseInputValue(formRes.body, 'csrf');
  assert(!!formCsrf, 'login form csrf');
  state.csrf = formCsrf;

  const loginRes = http.post(BASE_URL + '/v2/login', JSON.stringify({
    username: account.username,
    password: account.password,
    csrf: formCsrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    assert(!!loc, 'login redirect location');
    const redirectRes = http.get(absoluteUrl(loc), { redirects: 0 });
    assert(redirectRes.status === 200, 'login redirect status');
    const body = parseJson(redirectRes);
    if (body && typeof body.csrf === 'string') state.csrf = body.csrf;
    if (body && typeof body.grant_id === 'string') state.grant = body.grant_id;
    assert(!!state.csrf, 'login redirect csrf');
    return;
  }

  assert(loginRes.status === 200, 'login status');
  const body = parseJson(loginRes);
  if (body && typeof body.csrf === 'string') state.csrf = body.csrf;
  if (body && typeof body.grant_id === 'string') state.grant = body.grant_id;
  assert(!!state.csrf, 'login csrf');
}

function renew(state) {
  const res = http.post(BASE_URL + '/v2/session/renew', '{}', {
    headers: authHeaders(state),
    redirects: 0,
  });
  if (res.status === 200 || res.status === 201) {
    updateCsrf(state, parseJson(res));
    return true;
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId) return;
  const res = http.post(BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover', '{}', {
    headers: authHeaders(state),
    redirects: 0,
  });
  if (res.status === 200 || res.status === 201 || res.status === 204) {
    updateCsrf(state, parseJson(res));
  }
}

function relogin(state, account) {
  http.cookieJar().clear(BASE_URL);
  state.grant = null;
  login(state, account);
}

function sendWithRecovery(method, path, body, state, opts, account) {
  let res = sendRequest(method, path, body, state, opts);
  if (res.status === 401) {
    const parsed = parseJson(res);
    const error = parsed && parsed.error;
    if (error === 'expired') {
      if (renew(state)) {
        if (state.cartId) recoverCart(state);
        return sendRequest(method, path, body, state, opts);
      }
      relogin(state, account);
      if (state.cartId) recoverCart(state);
      return sendRequest(method, path, body, state, opts);
    }
    if (error === 'session') {
      relogin(state, account);
      if (state.cartId) recoverCart(state);
      return sendRequest(method, path, body, state, opts);
    }
  }
  return res;
}

function extractProductVariant(body) {
  if (!body) return null;
  let products = [];
  if (body.data && Array.isArray(body.data.products)) {
    products = body.data.products;
  } else if (Array.isArray(body.products)) {
    products = body.products;
  } else if (body.product) {
    products = [body.product];
  } else if (body.data && body.data.product) {
    products = [body.data.product];
  } else if (body.id && Array.isArray(body.variants)) {
    products = [body];
  }

  for (const p of products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (v && v.in_stock === true) {
        return { product: p.id, variant: v.id };
      }
    }
  }
  return null;
}

function findProductVariant(state, account) {
  let res = sendWithRecovery('GET', '/v2/catalog', null, state, {}, account);
  assert(res.status === 200, 'catalog status');
  let body = parseJson(res);
  let found = extractProductVariant(body);
  if (found) return found;

  let next = body && (body.next || (body.data && body.data.next));
  let pages = 0;
  while (next && pages < 3) {
    const pageRes = sendWithRecovery('GET', absoluteUrl(next), null, state, {}, account);
    assert(pageRes.status === 200, 'catalog page status');
    const pageBody = parseJson(pageRes);
    found = extractProductVariant(pageBody);
    if (found) return found;
    next = pageBody && (pageBody.next || (pageBody.data && pageBody.data.next));
    pages++;
  }
  return null;
}

function sendPatchWith412(state, account, payload) {
  let headers = {};
  if (state.etag) headers['If-Match'] = state.etag;
  let res = sendWithRecovery('PATCH', '/v2/carts/' + encodeURIComponent(state.cartId), payload, state, { headers: headers }, account);
  if (res.status === 412) {
    const getRes = sendWithRecovery('GET', '/v2/carts/' + encodeURIComponent(state.cartId), null, state, {}, account);
    assert(getRes.status === 200, 'cart get on 412');
    state.etag = getHeader(getRes, 'ETag');
    updateCsrf(state, parseJson(getRes));
    headers = {};
    if (state.etag) headers['If-Match'] = state.etag;
    res = sendWithRecovery('PATCH', '/v2/carts/' + encodeURIComponent(state.cartId), payload, state, { headers: headers }, account);
  }
  return res;
}

export default function () {
  const account = accounts[(__VU - 1) % accounts.length];
  http.cookieJar().clear(BASE_URL);

  const state = {
    csrf: null,
    cartId: null,
    etag: null,
    grant: null,
    idemKey: null,
  };

  login(state, account);

  const pv = findProductVariant(state, account);
  assert(!!pv, 'product variant found');

  const cartPayload = { product_id: pv.product, variant_id: pv.variant };
  if (state.grant) cartPayload.grant_id = state.grant;

  let cartRes = sendWithRecovery('POST', '/v2/carts', JSON.stringify(cartPayload), state, {}, account);
  assert(cartRes.status === 201, 'cart create status');
  const cartBody = parseJson(cartRes);
  assert(cartBody && typeof cartBody.id === 'string', 'cart id');
  state.cartId = cartBody.id;
  updateCsrf(state, cartBody);
  state.etag = getHeader(cartRes, 'ETag');
  state.idemKey = String(state.cartId);

  if (!state.etag) {
    const getBeforePatch = sendWithRecovery('GET', '/v2/carts/' + encodeURIComponent(state.cartId), null, state, {}, account);
    assert(getBeforePatch.status === 200, 'cart get before patch');
    state.etag = getHeader(getBeforePatch, 'ETag');
    updateCsrf(state, parseJson(getBeforePatch));
  }

  const patchPayload = JSON.stringify({ quantity: account.quantity });
  const patchRes = sendPatchWith412(state, account, patchPayload);
  assert(patchRes.status === 200 || patchRes.status === 204, 'cart patch status');
  updateCsrf(state, parseJson(patchRes));
  const patchEtag = getHeader(patchRes, 'ETag');
  if (patchEtag) state.etag = patchEtag;

  const cartGet = sendWithRecovery('GET', '/v2/carts/' + encodeURIComponent(state.cartId), null, state, {}, account);
  assert(cartGet.status === 200, 'cart get status');
  state.etag = getHeader(cartGet, 'ETag') || state.etag;
  updateCsrf(state, parseJson(cartGet));

  const orderPayload = JSON.stringify({ cart_id: state.cartId });
  let orderHeaders = { 'Idempotency-Key': state.idemKey };
  if (state.etag) orderHeaders['If-Match'] = state.etag;

  let orderRes = sendWithRecovery('POST', '/v2/orders', orderPayload, state, { headers: orderHeaders }, account);
  if (orderRes.status === 412) {
    const refresh = sendWithRecovery('GET', '/v2/carts/' + encodeURIComponent(state.cartId), null, state, {}, account);
    assert(refresh.status === 200, 'cart get after order 412');
    state.etag = getHeader(refresh, 'ETag') || state.etag;
    updateCsrf(state, parseJson(refresh));
    orderHeaders = { 'Idempotency-Key': state.idemKey };
    if (state.etag) orderHeaders['If-Match'] = state.etag;
    orderRes = sendWithRecovery('POST', '/v2/orders', orderPayload, state, { headers: orderHeaders }, account);
  }

  assert(orderRes.status === 201, 'order status');
  const orderBody = parseJson(orderRes);
  assert(orderBody && orderBody.accepted === true, 'order accepted');
  assert(orderBody && typeof orderBody.id === 'string', 'order id');
  updateCsrf(state, orderBody);
}

