import os
import json
import re
import html
from urllib.parse import urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USERS = 2
ITERATIONS = 2


def _load_accounts():
    for path in ("/fixtures/accounts.json", "/fixtures/m04-accounts.json"):
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
            if isinstance(data, list) and data:
                return data
        except Exception:
            pass

    rows = []
    for path in (
        "/fixtures/account-1.csv",
        "/fixtures/account-2.csv",
        "/fixtures/m04-account-1.csv",
        "/fixtures/m04-account-2.csv",
    ):
        try:
            with open(path, "r", encoding="utf-8") as fh:
                lines = [line.strip() for line in fh if line.strip()]
            if not lines:
                continue
            header = [part.strip() for part in lines[0].split(",")]
            for line in lines[1:]:
                parts = [part.strip() for part in line.split(",")]
                if len(parts) >= len(header):
                    rows.append(dict(zip(header, parts)))
        except Exception:
            pass

    if not rows:
        rows = [
            {"username": "bench-1", "password": "bench", "quantity": 2, "delay": 0},
            {"username": "bench-2", "password": "bench", "quantity": 3, "delay": 500},
        ]
    return rows


ACCOUNTS = _load_accounts()
NEXT_SLOT = 0
COMPLETED_SLOTS = set()

_ATTR_RE = re.compile("([^\\s=/>]+)\\s*=\\s*(?:([\"'])(.*?)\\2|([^\\s>]+))", re.I | re.S)


def _attrs(tag):
    attrs = {}
    for match in _ATTR_RE.finditer(tag):
        key = match.group(1).lower()
        value = match.group(3) if match.group(3) is not None else match.group(4)
        attrs[key] = value
    return attrs


def extract_input_value(text, name):
    wanted = name.lower()
    for match in re.finditer(r"<input\b[^>]*>", text or "", re.I | re.S):
        attrs = _attrs(match.group(0))
        if attrs.get("name", "").lower() == wanted:
            value = attrs.get("value")
            if value:
                return html.unescape(value)
    return None


def extract_form_action(text):
    for match in re.finditer(r"<form\b[^>]*>", text or "", re.I | re.S):
        attrs = _attrs(match.group(0))
        action = attrs.get("action")
        if action:
            return html.unescape(action)
    return None


def json_or_none(response):
    try:
        return response.json()
    except Exception:
        return None


def error_code(response):
    data = json_or_none(response)
    if isinstance(data, dict) and isinstance(data.get("error"), str):
        return data["error"]
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0, 0)

    def on_start(self):
        global NEXT_SLOT

        self.valid_slot = False
        self.skip = False
        self.cart_id = None
        self.etag = None
        self.csrf = None
        self.grant = None

        slot = NEXT_SLOT
        NEXT_SLOT += 1

        if slot >= USERS or slot >= len(ACCOUNTS):
            self.skip = True
            raise StopUser()

        self.valid_slot = True
        self.slot = slot
        self.account = ACCOUNTS[slot]
        self.username = self.account.get("username", f"bench-{slot + 1}")
        self.password = self.account.get("password", "bench")

        quantity = self.account.get("quantity", 2)
        if isinstance(quantity, str):
            try:
                quantity = int(quantity)
            except Exception:
                quantity = 2
        self.quantity = int(quantity)

    def on_stop(self):
        if getattr(self, "valid_slot", False):
            COMPLETED_SLOTS.add(self.slot)

    def _absolute(self, location):
        if location.startswith("http://") or location.startswith("https://"):
            return location
        return urljoin(BASE_URL + "/", location)

    def _update_csrf(self, data):
        if isinstance(data, dict) and isinstance(data.get("csrf"), str):
            self.csrf = data["csrf"]

    def _solve_challenge_html(self, text):
        action = extract_form_action(text)
        challenge = extract_input_value(text, "challenge")
        if not action or not challenge:
            return False

        url = self._absolute(action)
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            url,
            json={"challenge": challenge},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("challenge POST 302 missing Location")
                    return False

                location_url = self._absolute(location)
                with self.client.get(
                    location_url, allow_redirects=False, catch_response=True
                ) as redirect_resp:
                    if redirect_resp.status_code != 200:
                        redirect_resp.failure(
                            f"challenge redirect GET status {redirect_resp.status_code}"
                        )
                        return False
                    data = json_or_none(redirect_resp)
                    if not isinstance(data, dict):
                        redirect_resp.failure("challenge redirect missing JSON")
                        return False
                    self._update_csrf(data)
                    if isinstance(data.get("grant_id"), str):
                        self.grant = data["grant_id"]
                    return bool(self.csrf)

            if resp.status_code == 200:
                data = json_or_none(resp)
                if not isinstance(data, dict):
                    resp.failure("challenge POST missing JSON")
                    return False
                self._update_csrf(data)
                if isinstance(data.get("grant_id"), str):
                    self.grant = data["grant_id"]
                return bool(self.csrf)

            resp.failure(f"challenge POST status {resp.status_code}")
            return False

    def _fetch_challenge(self):
        with self.client.get(
            "/v2/challenge-form", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge-form status {resp.status_code}")
                return False
            return self._solve_challenge_html(resp.text)

    def _login(self, clear_cookies=True):
        if clear_cookies:
            self.client.cookies.clear()

        self.csrf = None
        self.grant = None

        with self.client.get(
            "/v2/login-form", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False
            form_csrf = extract_input_value(resp.text, "csrf")
            if not form_csrf:
                resp.failure("login-form missing csrf input")
                return False

        self.csrf = form_csrf
        payload = {
            "username": self.username,
            "password": self.password,
            "csrf": form_csrf,
        }

        with self.client.post(
            "/v2/login",
            json=payload,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = json_or_none(resp)
                if not isinstance(data, dict) or not isinstance(data.get("csrf"), str):
                    resp.failure("login response missing csrf")
                    return False
                self.csrf = data["csrf"]
                if isinstance(data.get("grant_id"), str):
                    self.grant = data["grant_id"]
                return True

            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 missing Location")
                    return False

                location_url = self._absolute(location)
                with self.client.get(
                    location_url, allow_redirects=False, catch_response=True
                ) as redirect_resp:
                    if redirect_resp.status_code != 200:
                        redirect_resp.failure(
                            f"login redirect GET status {redirect_resp.status_code}"
                        )
                        return False

                    data = json_or_none(redirect_resp)
                    if isinstance(data, dict):
                        self._update_csrf(data)
                        if isinstance(data.get("grant_id"), str):
                            self.grant = data["grant_id"]
                    else:
                        csrf_value = extract_input_value(redirect_resp.text, "csrf")
                        if csrf_value:
                            self.csrf = csrf_value
                        if not self._solve_challenge_html(redirect_resp.text):
                            if not self.csrf:
                                redirect_resp.failure(
                                    "login redirect missing csrf/grant"
                                )
                                return False

                return bool(self.csrf)

            resp.failure(f"login status {resp.status_code}")
            return False

    def _renew_session(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = json_or_none(resp)
                self._update_csrf(data)
                return True
            if resp.status_code == 401:
                return False
            resp.failure(f"session/renew status {resp.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True

        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 201, 204):
                data = json_or_none(resp)
                self._update_csrf(data)
                etag = resp.headers.get("ETag")
                if etag:
                    self.etag = etag
                return True
            if resp.status_code == 401:
                return False
            resp.failure(f"cart/recover status {resp.status_code}")
            return False

    def _recover_401(self, resp):
        err = error_code(resp)
        if err == "denied" or err not in ("expired", "session"):
            return False

        if err == "expired":
            if not self._renew_session():
                if not self._login(clear_cookies=True):
                    return False
        else:
            self._renew_session()
            if not self._login(clear_cookies=True):
                return False

        if self.cart_id:
            return self._recover_cart()
        return True

    def _read_cart(self):
        if not self.cart_id:
            return False

        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET cart status {resp.status_code}")
                return False
            data = json_or_none(resp)
            self._update_csrf(data)
            etag = resp.headers.get("ETag")
            if etag:
                self.etag = etag
            return True

    def _get_catalog_choice(self):
        with self.client.get(
            "/v2/catalog", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog status {resp.status_code}")
                return None

            data = json_or_none(resp)
            if not isinstance(data, dict):
                resp.failure("catalog missing JSON")
                return None

            self._update_csrf(data)

            products = data.get("data", {}).get("products", [])
            if not isinstance(products, list):
                resp.failure("catalog products missing")
                return None

            for product in products:
                if not isinstance(product, dict):
                    continue
                variants = product.get("variants", [])
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if isinstance(variant, dict) and variant.get("in_stock") is True:
                        product_id = product.get("id")
                        variant_id = variant.get("id")
                        if product_id is not None and variant_id is not None:
                            return product_id, variant_id

            resp.failure("catalog has no in-stock product/variant")
            return None

    def _create_cart(self, product_id, variant_id):
        recovered = False
        challenged = False

        for _ in range(3):
            payload = {"product_id": product_id, "variant_id": variant_id}
            if self.grant is not None:
                payload["grant_id"] = self.grant

            headers = {"Content-Type": "application/json"}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            with self.client.post(
                "/v2/carts",
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 201:
                    data = json_or_none(resp)
                    if not isinstance(data, dict) or not data.get("id"):
                        resp.failure("cart creation missing id")
                        return False
                    self.cart_id = data["id"]
                    self._update_csrf(data)
                    etag = resp.headers.get("ETag")
                    if etag:
                        self.etag = etag
                    else:
                        self._read_cart()
                    self.grant = None
                    return True

                if resp.status_code == 401:
                    err = error_code(resp)
                    if err in ("expired", "session") and not recovered:
                        recovered = True
                        if self._recover_401(resp):
                            continue
                    resp.failure(f"cart creation 401 {err}")
                    return False

                if resp.status_code in (400, 403) and not challenged and self.grant is None:
                    if self._fetch_challenge():
                        challenged = True
                        continue
                    resp.failure(
                        f"cart creation {resp.status_code} and challenge failed"
                    )
                    return False

                resp.failure(f"cart creation status {resp.status_code}")
                return False

        return False

    def _patch_cart(self):
        if not self.cart_id:
            return False

        recovered = False
        retried_412 = False

        for _ in range(3):
            headers = {"Content-Type": "application/json"}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if self.etag:
                headers["If-Match"] = self.etag

            with self.client.patch(
                f"/v2/carts/{self.cart_id}",
                json={"quantity": self.quantity},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in (200, 204):
                    data = json_or_none(resp)
                    self._update_csrf(data)
                    etag = resp.headers.get("ETag")
                    if etag:
                        self.etag = etag
                    return True

                if resp.status_code == 412 and not retried_412:
                    retried_412 = True
                    if not self._read_cart():
                        resp.failure("PATCH 412 and cart re-read failed")
                        return False
                    continue

                if resp.status_code == 401:
                    err = error_code(resp)
                    if err in ("expired", "session") and not recovered:
                        recovered = True
                        if self._recover_401(resp):
                            continue
                    resp.failure(f"PATCH 401 {err}")
                    return False

                resp.failure(f"PATCH status {resp.status_code}")
                return False

        return False

    def _checkout(self):
        if not self.cart_id:
            return False

        recovered = False
        retried_412 = False

        for _ in range(3):
            headers = {
                "Content-Type": "application/json",
                "Idempotency-Key": self.cart_id,
            }
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            if self.etag:
                headers["If-Match"] = self.etag

            with self.client.post(
                "/v2/orders",
                json={"cart_id": self.cart_id},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 201:
                    data = json_or_none(resp)
                    if not isinstance(data, dict) or data.get("accepted") is not True:
                        resp.failure("order 201 missing accepted true")
                        return False
                    self._update_csrf(data)
                    return True

                if resp.status_code == 200:
                    data = json_or_none(resp)
                    if isinstance(data, dict) and data.get("accepted") is False:
                        resp.failure("order business failure accepted false")
                    else:
                        resp.failure("order unexpected 200")
                    return False

                if resp.status_code == 401:
                    err = error_code(resp)
                    if err in ("expired", "session") and not recovered:
                        recovered = True
                        if self._recover_401(resp):
                            continue
                    resp.failure(f"order 401 {err}")
                    return False

                if resp.status_code == 412 and not retried_412:
                    retried_412 = True
                    if not self._read_cart():
                        resp.failure("order 412 and cart re-read failed")
                        return False
                    continue

                resp.failure(f"order status {resp.status_code}")
                return False

        return False

    def _run_journey(self):
        self.cart_id = None
        self.etag = None
        self.grant = None

        if not self._login(clear_cookies=True):
            return False

        choice = self._get_catalog_choice()
        if not choice:
            return False

        product_id, variant_id = choice

        if not self._create_cart(product_id, variant_id):
            return False
        if not self._patch_cart():
            return False
        return self._checkout()

    @task
    def journey(self):
        if getattr(self, "skip", False):
            raise StopUser()

        for _ in range(ITERATIONS):
            self._run_journey()

        raise StopUser()


class ContractShape(LoadTestShape):
    def tick(self):
        completed = len(COMPLETED_SLOTS)
        if completed >= USERS:
            return None
        return USERS - completed, 2
