import http from 'k6/http';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const TIMEOUT = '3s';
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    journey: {
      executor: 'constant-arrival-rate',
      rate: 2,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 2,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
};

function absUrl(u) {
  if (!u) return u;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.charAt(0) === '/') return BASE + u;
  return BASE + '/' + u;
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const lower = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === lower) return res.headers[k];
  }
  return null;
}

function parseJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function attrValue(tag, attrName) {
  const re = new RegExp('\\b' + attrName + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  if (m[3] !== undefined) return m[3];
  return null;
}

function inputValue(html, name) {
  if (!html) return null;
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const n = attrValue(tag, 'name');
    if (n !== name) continue;
    const v = attrValue(tag, 'value');
    return v === null ? '' : v;
  }
  return null;
}

function findChallengeAction(html) {
  if (!html) return null;
  const formRe = /<form\b[^>]*>/i;
  const fm = html.match(formRe);
  if (fm) {
    const action = attrValue(fm[0], 'action');
    if (action) return action;
  }
  const m = html.match(/["']([^"']*\/v2\/challenges\/[^"']*)["']/i);
  return m ? m[1] : null;
}

function errorCode(res) {
  if (!res || res.status !== 401) return null;
  const j = parseJson(res);
  if (j && j.error) return j.error;
  if (res.body) {
    const m = res.body.match(/"error"\s*:\s*"([^"]+)"/);
    if (m) return m[1];
  }
  return null;
}

function renewSession(state) {
  if (!state.csrf) return false;
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    redirects: 0,
    timeout: TIMEOUT,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
  });
  if (res.status >= 200 && res.status < 300) {
    const j = parseJson(res);
    if (j && j.csrf) {
      state.csrf = j.csrf;
      return true;
    }
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId || !state.csrf) return false;
  const res = http.post(BASE + '/v2/carts/' + state.cartId + '/recover', '{}', {
    redirects: 0,
    timeout: TIMEOUT,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
  });
  if (res.status >= 200 && res.status < 300) {
    const j = parseJson(res);
    if (j && j.csrf) state.csrf = j.csrf;
    const etag = getHeader(res, 'ETag');
    if (etag) state.etag = etag;
    return true;
  }
  return false;
}

function doLogin(state) {
  state.grantId = null;

  let res = http.get(BASE + '/v2/login-form', { redirects: 0, timeout: TIMEOUT });
  if (res.status !== 200) return false;

  let csrf = inputValue(res.body, 'csrf');
  if (!csrf) return false;
  state.csrf = csrf;

  const username = state.username || ('bench-' + __VU);
  const payload = JSON.stringify({ username: username, password: PASSWORD, csrf: csrf });
  let loginRes = http.post(BASE + '/v2/login', payload, {
    redirects: 0,
    timeout: TIMEOUT,
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });

  if (loginRes.status >= 400) return false;

  if (loginRes.status >= 300 && loginRes.status < 400) {
    const loc = getHeader(loginRes, 'Location');
    if (!loc) return false;

    const locRes = http.get(absUrl(loc), { redirects: 0, timeout: TIMEOUT });
    if (locRes.status >= 400) return false;

