            if (j.grant_id) state.grantId = j.grant_id;
          }
        }
      } else {
        const j = parseJson(chRes);
        if (j) {
          if (j.csrf) state.csrf = j.csrf;
          if (j.grant_id) state.grantId = j.grant_id;
        }
      }
    } else {
      const j = parseJson(locRes);
      if (j) {
        if (j.csrf) state.csrf = j.csrf;
        if (j.grant_id) state.grantId = j.grant_id;
      } else {
        const c = inputValue(locRes.body, 'csrf');
        if (c) state.csrf = c;
        const g = inputValue(locRes.body, 'grant_id');
        if (g) state.grantId = g;
      }
    }
  } else {
    const j = parseJson(loginRes);
    if (j) {
      if (j.csrf) state.csrf = j.csrf;
      if (j.grant_id) state.grantId = j.grant_id;
    } else {
      const c = inputValue(loginRes.body, 'csrf');
      if (c) state.csrf = c;
    }
  }

  return !!state.csrf;
}

function getCatalogSelection(state) {
  function fetchCatalog(url) {
    return http.get(url, {
      redirects: 0,
      timeout: TIMEOUT,
      headers: state.csrf ? { 'X-CSRF-Token': state.csrf } : {},
    });
  }

  let res = fetchCatalog(BASE + '/v2/catalog');
  if (res.status === 401) {
    const code = errorCode(res);
    if (code === 'expired') {
      if (renewSession(state)) res = fetchCatalog(BASE + '/v2/catalog');
    } else if (code === 'session') {
      if (doLogin(state)) res = fetchCatalog(BASE + '/v2/catalog');
    }
  }

  let j = parseJson(res);
  if (j && j.data && j.data.products) {
    for (let i = 0; i < j.data.products.length; i++) {
      const p = j.data.products[i];
      if (!p.variants) continue;
      for (let k = 0; k < p.variants.length; k++) {
        const v = p.variants[k];
        if (v.in_stock === true) {
          return { productId: p.id, variantId: v.id };
        }
      }
    }
  }

  let next = j && j.next;
  let count = 0;
  while (next && count < 3) {
    let nextUrl = null;
    if (typeof next === 'string') nextUrl = next;
    else if (next && next.url) nextUrl = next.url;
    else if (next && next.href) nextUrl = next.href;
    if (!nextUrl) break;

    const pageRes = fetchCatalog(absUrl(nextUrl));
    const pj = parseJson(pageRes);
    if (!pj) break;

    const prod = pj.product || (pj.data && pj.data.product) || (pj.data && pj.data.products && pj.data.products[0]);
    if (prod && prod.variants) {
      for (let k = 0; k < prod.variants.length; k++) {
        if (prod.variants[k].in_stock === true) {
          return { productId: prod.id, variantId: prod.variants[k].id };
        }
      }
    }

    next = pj.next;
    count++;
  }

  return null;
}

function createCart(state, productId, variantId) {
  function send() {
    const payload = { product_id: productId, variant_id: variantId };
    if (state.grantId) payload.grant_id = state.grantId;

    return http.post(BASE + '/v2/carts', JSON.stringify(payload), {
      redirects: 0,
      timeout: TIMEOUT,
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
    });
  }

  let res = send();
  if (res.status === 401) {
    const code = errorCode(res);
    if (code === 'expired') {
      if (renewSession(state)) res = send();
    } else if (code === 'session') {
      if (doLogin(state)) res = send();
    } else if (code === 'denied') {
      return false;
    }
  }

  if (res.status === 201) {
    const j = parseJson(res);
    if (j && j.id) {
      state.cartId = j.id;
      if (j.csrf) state.csrf = j.csrf;
      const etag = getHeader(res, 'ETag');
      if (etag) state.etag = etag;
      state.grantId = null;
      return true;
    }
  }

  return false;
}

function placeOrder(state) {
  function send() {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Idempotency-Key': state.cartId,
    };
    if (state.etag) headers['If-Match'] = state.etag;

    return http.post(BASE + '/v2/orders', JSON.stringify({ cart_id: state.cartId }), {
      redirects: 0,
      timeout: TIMEOUT,
      headers: headers,
    });
  }

  let res = send();
  if (res.status === 401) {
    const code = errorCode(res);
    if (code === 'expired') {
      if (renewSession(state)) {
        recoverCart(state);
        res = send();
      } else if (doLogin(state)) {
        recoverCart(state);
        res = send();
      }
    } else if (code === 'session') {
      if (doLogin(state)) {
        recoverCart(state);
        res = send();
      }
    } else if (code === 'denied') {
      return false;
    }
  }

  if (res.status === 412) {
    if (state.cartId) {
      const cartRes = http.get(BASE + '/v2/carts/' + state.cartId, {
        redirects: 0,
        timeout: TIMEOUT,
        headers: { 'X-CSRF-Token': state.csrf },
      });
      if (cartRes.status === 200) {
        const etag = getHeader(cartRes, 'ETag');
        if (etag) state.etag = etag;
        res = send();
      }
    }
  }

  if (res.status === 201) {
    const j = parseJson(res);
    if (j && j.accepted === true) {
      if (j.csrf) state.csrf = j.csrf;
      return true;
    }
  }

  return false;
}

export default function () {
  const state = {
    csrf: null,
    cartId: null,
    etag: null,
    grantId: null,
    username: 'bench-' + __VU,
  };

  if (!doLogin(state)) return;

  const sel = getCatalogSelection(state);
  if (!sel) return;

  if (!createCart(state, sel.productId, sel.variantId)) return;

  placeOrder(state);
}
