import os
import re
import json
import time
import html as html_lib
from urllib.parse import urljoin

from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ORDER_RATE = 2.0
ORDER_INTERVAL = 1.0 / ORDER_RATE
_next_order_time = 0.0

_ATTR_RE = re.compile(r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))""")


def _resp_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _attrs(tag):
    out = {}
    for m in _ATTR_RE.finditer(tag):
        name = m.group(1).lower()
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
        if val is None:
            val = ""
        out[name] = html_lib.unescape(val)
    return out


def extract_input_value(html_text, wanted):
    for m in re.finditer(r"<input\b[^>]*>", html_text or "", re.I | re.S):
        a = _attrs(m.group(0))
        if a.get("name", "").lower() == wanted.lower():
            return a.get("value")
    return None


def extract_form_action(html_text):
    for m in re.finditer(r"<form\b[^>]*>", html_text or "", re.I | re.S):
        a = _attrs(m.group(0))
        action = a.get("action")
        if action and "/v2/challenges/" in action:
            return action
    for m in re.finditer(r"<form\b[^>]*>", html_text or "", re.I | re.S):
        a = _attrs(m.group(0))
        action = a.get("action")
        if action:
            return action
    return None


def wait_order_slot():
    global _next_order_time
    now = time.monotonic()
    if _next_order_time == 0.0 or now > _next_order_time + 5.0:
        _next_order_time = now
    wait = _next_order_time - now
    if wait < 0:
        wait = 0.0
    _next_order_time = max(_next_order_time, now) + ORDER_INTERVAL
    if wait > 0:
        time.sleep(wait)


class ShopUser(HttpUser):
    host = BASE_URL
    _user_seq = 0

    def on_start(self):
        type(self)._user_seq += 1
        n = type(self)._user_seq
        self.username = f"bench-{n}" if n <= 16 else "bench"
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.iterations_done = 0
        self.max_iterations = 1000

    def get_error(self, resp):
        data = _resp_json(resp)
        if isinstance(data, dict) and "error" in data:
            return data.get("error")
        m = re.search(r'"error"\s*:\s*"([^"]+)"', resp.text or "")
        if m:
            return m.group(1)
        return None

    def login(self):
        with self.client.get("/v2/login-form", name="GET /v2/login-form", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False
            csrf = extract_input_value(resp.text, "csrf")
            if not csrf:
                data = _resp_json(resp)
                if isinstance(data, dict):
                    csrf = data.get("csrf")
            if not csrf:
                resp.failure("login-form missing csrf")
                return False
            self.csrf = csrf
            resp.success()

        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf}
        payload = {"username": self.username, "password": self.password, "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, headers=headers, name="POST /v2/login", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("login 302 without Location")
                    return False
                resp.success()
                with self.client.get(loc, name="GET login redirect", catch_response=True, allow_redirects=False) as loc_resp:
                    if loc_resp.status_code not in (200, 201):
                        loc_resp.failure(f"login redirect status {loc_resp.status_code}")
                        return False
                    data = _resp_json(loc_resp)
                    if isinstance(data, dict):
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        if data.get("grant_id"):
                            self.grant_id = data["grant_id"]
                        loc_resp.success()
                        return True
                    action = extract_form_action(loc_resp.text)
                    challenge = extract_input_value(loc_resp.text, "challenge")
                    if action and challenge:
                        loc_resp.success()
                        return self.submit_challenge(action, challenge)
                    csrf = extract_input_value(loc_resp.text, "csrf")
                    if csrf:
                        self.csrf = csrf
                        loc_resp.success()
                        return True
                    loc_resp.failure("unrecognized login redirect body")
                    return False
            elif resp.status_code in (200, 201):
                data = _resp_json(resp)
                if not isinstance(data, dict):
                    resp.failure("login response not JSON")
                    return False
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True
            else:
                resp.failure(f"login status {resp.status_code}")
                return False

    def submit_challenge(self, action, challenge):
        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf}
        with self.client.post(action, json={"challenge": challenge}, headers=headers, name="POST /v2/challenges/{id}", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 302:
                resp.failure(f"challenge status {resp.status_code}")
                return False
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("challenge 302 without Location")
                return False
            resp.success()
            with self.client.get(loc, name="GET challenge location", catch_response=True, allow_redirects=False) as loc_resp:
                if loc_resp.status_code not in (200, 201):
                    loc_resp.failure(f"challenge location status {loc_resp.status_code}")
                    return False
                data = _resp_json(loc_resp)
                if isinstance(data, dict):
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    if data.get("grant_id"):
                        self.grant_id = data["grant_id"]
                    loc_resp.success()
                    return True
                csrf = extract_input_value(loc_resp.text, "csrf")
                if csrf:
                    self.csrf = csrf
                grant = extract_input_value(loc_resp.text, "grant_id") or extract_input_value(loc_resp.text, "grant")
                if grant:
                    self.grant_id = grant
                loc_resp.success()
                return True

    def acquire_grant(self):
        if self.grant_id:
            return True
        with self.client.get("/v2/challenge-form", name="GET /v2/challenge-form", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge-form status {resp.status_code}")
                return False
            action = extract_form_action(resp.text)
            challenge = extract_input_value(resp.text, "challenge")
            if not action or not challenge:
                resp.failure("challenge-form missing action or challenge")
                return False
            resp.success()
            return self.submit_challenge(action, challenge)

    def find_in_stock(self, data):
        products = []
        d = data.get("data")
        if isinstance(d, dict):
            if isinstance(d.get("products"), list):
                products = d["products"]
            elif isinstance(d.get("product"), dict):
                products = [d["product"]]
        if not products and isinstance(data.get("products"), list):
            products = data["products"]
        if not products and isinstance(data.get("product"), dict):
            products = [data["product"]]
        for p in products:
            if not isinstance(p, dict):
                continue
            pid = p.get("id")
            variants = p.get("variants") or []
            if not isinstance(variants, list):
                continue
            for v in variants:
                if isinstance(v, dict) and v.get("in_stock") is True:
                    return pid, v.get("id")
        return None, None

    def select_product(self):
        url = "/v2/catalog"
        for _ in range(3):
            name = "GET /v2/catalog" if url == "/v2/catalog" else "GET /v2/catalog/page"
            with self.client.get(url, name=name, catch_response=True, allow_redirects=False) as resp:
                if resp.status_code != 200:
                    resp.failure(f"catalog status {resp.status_code}")
                    return None
                data = _resp_json(resp)
                if not isinstance(data, dict):
                    resp.failure("catalog response not JSON")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                product, variant = self.find_in_stock(data)
                if product and variant:
                    resp.success()
                    return product, variant
                next_url = data.get("next")
                if not next_url:
                    resp.failure("no in-stock product")
                    return None
                resp.success()
                url = next_url if not isinstance(next_url, str) else urljoin(self.host, next_url)
        return None

    def read_cart_etag(self):
        if not self.cart_id:
            return False
        with self.client.get(f"/v2/carts/{self.cart_id}", name="GET /v2/carts/{id}", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 200:
                etag = resp.headers.get("ETag")
                if etag:
                    self.etag = etag
                data = _resp_json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True
            resp.failure(f"cart get status {resp.status_code}")
            return False

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
            self.grant_id = None
        for attempt in range(2):
            headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf}
            with self.client.post("/v2/carts", json=payload, headers=headers, name="POST /v2/carts", catch_response=True, allow_redirects=False) as resp:
                if resp.status_code == 201:
                    data = _resp_json(resp)
                    if not isinstance(data, dict) or not data.get("id"):
                        resp.failure("cart response missing id")
                        return False
                    self.cart_id = data["id"]
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    self.etag = resp.headers.get("ETag")
                    resp.success()
                    if not self.etag:
                        self.read_cart_etag()
                    return True
                elif resp.status_code == 401 and attempt == 0:
                    err = self.get_error(resp)
                    if err in ("expired", "session"):
                        resp.success()
                        if self.recover(err, cart_id=None):
                            continue
                        resp.failure("recovery failed")
                        return False
                    resp.failure(f"cart 401 {err}")
                    return False
                elif resp.status_code in (400, 403) and attempt == 0:
                    text = (resp.text or "").lower()
                    if "grant" in text or "challenge" in text:
                        resp.success()
                        if self.acquire_grant():
                            payload["grant_id"] = self.grant_id
                            self.grant_id = None
                            continue
                    resp.failure(f"cart status {resp.status_code}")
                    return False
                else:
                    resp.failure(f"cart status {resp.status_code}")
                    return False
        return False

    def renew_session(self, expect_failure=False):
        if not self.csrf:
            return False
        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf}
        with self.client.post("/v2/session/renew", json={}, headers=headers, name="POST /v2/session/renew", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code in (200, 201):
                data = _resp_json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True
            if expect_failure:
                resp.success()
            else:
                resp.failure(f"renew status {resp.status_code}")
            return False

    def recover_cart(self, cart_id):
        if not cart_id or not self.csrf:
            return True
        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf}
        with self.client.post(f"/v2/carts/{cart_id}/recover", json={}, headers=headers, name="POST /v2/carts/{id}/recover", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code in (200, 201, 204):
                data = _resp_json(resp)
                if isinstance(data, dict):
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    if data.get("ETag"):
                        self.etag = data["ETag"]
                resp.success()
                return True
            resp.failure(f"recover cart status {resp.status_code}")
            return False

    def recover(self, err, cart_id=None):
        if err == "expired":
            if not self.renew_session():
                return False
        elif err == "session":
            if not self.renew_session(expect_failure=True):
                saved_cart = self.cart_id
                saved_etag = self.etag
                if not self.login():
                    return False
                self.cart_id = saved_cart
                self.etag = saved_etag
        else:
            return False
        if cart_id:
            self.recover_cart(cart_id)
        return True

    def place_order(self):
        wait_order_slot()
        payload = {"cart_id": self.cart_id}
        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf, "Idempotency-Key": self.cart_id}
        if self.etag:
            headers["If-Match"] = self.etag
        for attempt in range(2):
            headers["X-CSRF-Token"] = self.csrf
            if self.etag:
                headers["If-Match"] = self.etag
            with self.client.post("/v2/orders", json=payload, headers=headers, name="POST /v2/orders", catch_response=True, allow_redirects=False) as resp:
                if resp.status_code == 201:
                    data = _resp_json(resp)
                    if not isinstance(data, dict) or data.get("accepted") is not True:
                        resp.failure("order 201 without accepted true")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    resp.success()
                    return True
                elif resp.status_code == 200:
                    data = _resp_json(resp)
                    if isinstance(data, dict) and data.get("accepted") is False:
                        resp.failure("order accepted false")
                    else:
                        resp.failure("order http 200")
                    return False
                elif resp.status_code == 401 and attempt == 0:
                    err = self.get_error(resp)
                    if err in ("expired", "session"):
                        resp.success()
                        if self.recover(err, cart_id=self.cart_id):
                            continue
                        resp.failure("recovery failed")
                        return False
                    resp.failure(f"order 401 {err}")
                    return False
                elif resp.status_code == 412 and attempt == 0:
                    resp.success()
                    if self.read_cart_etag():
                        continue
                    resp.failure("order 412 and cart refresh failed")
                    return False
                else:
                    resp.failure(f"order status {resp.status_code}")
                    return False
        return False

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        if not self.login():
            time.sleep(0.25)
            return
        selected = self.select_product()
        if not selected:
            time.sleep(0.25)
            return
        product_id, variant_id = selected
        if not self.create_cart(product_id, variant_id):
            time.sleep(0.25)
            return
        if not self.place_order():
            time.sleep(0.25)
            return
        self.iterations_done += 1


class ShopShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 1:
            global _next_order_time
            _next_order_time = 0.0
        if run_time < 38:
            return {"users": 4, "spawn_rate": 100}
        return None
