            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            token = find_input_value(r.text, "csrf")
            if not token:
                data = safe_json(r)
                if isinstance(data, dict):
                    token = data.get("csrf")
            if not token:
                r.failure("login-form missing csrf")
                return False
            r.success()
        self.csrf = token

        body = {"username": self.username, "password": self.password, "csrf": self.csrf}
        with self.client.post(
            "/v2/login",
            json=body,
            headers=self.headers(),
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            code = r.status_code
            if code in (301, 302, 303, 307, 308):
                loc = r.headers.get("Location")
                r.success()
                if not loc:
                    return False
                return self.follow_location(loc)
            if code not in (200, 201):
                r.failure("login status %s" % code)
                return False
            data = safe_json(r)
            if not isinstance(data, dict):
                r.failure("login body not json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            r.success()
            return True

    def do_select(self):
        path = "/v2/catalog"
        for page in range(3):
            advanced = False
            for attempt in range(2):
                with self.client.get(
                    path,
                    name="GET /v2/catalog" if page == 0 else "GET /v2/catalog/page",
                    catch_response=True,
                    allow_redirects=False,
                ) as r:
                    if r.status_code == 401:
                        err = error_of(r)
                        if err in ("expired", "session") and attempt == 0:
                            r.success()
                            if self.recover(err, None):
                                continue
                            return None
                        r.failure("catalog 401 %s" % err)
                        return None
                    if r.status_code != 200:
                        r.failure("catalog status %s" % r.status_code)
                        return None
                    data = safe_json(r)
                    if not isinstance(data, dict):
                        r.failure("catalog body not json")
                        return None
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    product, variant = pick_stock(data)
                    if product and variant:
                        r.success()
                        return (product, variant)
                    nxt = data.get("next")
                    if not nxt:
                        r.failure("no in-stock variant")
                        return None
                    r.success()
                    path = absolute(nxt)
                    advanced = True
                    break
            if not advanced:
                return None
        return None

    def refresh_cart(self):
        if not self.cart_id:
            return False
        with self.client.get(
            "/v2/carts/%s" % self.cart_id,
            name="GET /v2/carts/{id}",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("cart read status %s" % r.status_code)
                return False
            etag = r.headers.get("ETag")
            if etag:
                self.etag = etag
            data = safe_json(r)
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            r.success()
            return True

    def do_cart(self, product_id, variant_id):
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
            self.grant_id = None
        tried_grant = "grant_id" in body

        for attempt in range(3):
            with self.client.post(
                "/v2/carts",
                json=body,
                headers=self.headers(),
                name="POST /v2/carts",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                code = r.status_code
                if code == 201:
                    data = safe_json(r)
                    if not isinstance(data, dict) or not data.get("id"):
                        r.failure("cart response missing id")
                        return False
                    self.cart_id = data["id"]
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    etag = r.headers.get("ETag")
                    if etag:
                        self.etag = etag
                    r.success()
                    if not self.etag:
                        self.refresh_cart()
                    return True
                if code == 401 and attempt == 0:
                    err = error_of(r)
                    if err in ("expired", "session"):
                        r.success()
                        if self.recover(err, None):
                            continue
                        return False
                    r.failure("cart 401 %s" % err)
                    return False
                if code in (400, 403, 409) and not tried_grant:
                    tried_grant = True
                    r.success()
                    if self.acquire_grant():
                        if self.grant_id:
                            body["grant_id"] = self.grant_id
                            self.grant_id = None
                        continue
                    return False
                r.failure("cart status %s" % code)
                return False
        return False

    def make_reservation(self):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=self.headers(),
            name="POST /v2/reservations",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 202:
                r.failure("reservation status %s" % r.status_code)
                return None
            data = safe_json(r)
            if not isinstance(data, dict):
                r.failure("reservation body not json")
                return None
            if data.get("csrf"):
                self.csrf = data["csrf"]
            status_url = data.get("status_url")
            r.success()
        if not status_url:
            return None
        url = absolute(status_url)
        for _ in range(5):
            time.sleep(0.06)
            with self.client.get(
                url,
                name="GET reservation status",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                data = safe_json(r)
                if not isinstance(data, dict):
                    r.failure("reservation status body not json")
                    return None
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                status = data.get("status")
                if status == "ready":
                    r.success()
                    return data.get("reservation_id")
                if status == "pending":
                    r.success()
                    continue
                r.failure("reservation status %s" % status)
                return None
        return None

    def do_checkout(self):
        pace()
        reservation_id = None
        for attempt in range(3):
            body = {"cart_id": self.cart_id}
            if reservation_id:
                body["reservation_id"] = reservation_id
            extra = {"Idempotency-Key": self.cart_id}
            if self.etag:
                extra["If-Match"] = self.etag
            with self.client.post(
                "/v2/orders",
                json=body,
                headers=self.headers(extra),
                name="POST /v2/orders",
                catch_response=True,
                allow_redirects=False,
            ) as r:
                code = r.status_code
                if code == 201:
                    data = safe_json(r)
                    if not isinstance(data, dict) or data.get("accepted") is not True:
                        r.failure("order not accepted")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    r.success()
                    return True
                if code == 200:
                    data = safe_json(r)
                    accepted = data.get("accepted") if isinstance(data, dict) else None
                    r.failure("order http 200 accepted=%s" % accepted)
                    return False
                if code == 401 and attempt == 0:
                    err = error_of(r)
                    if err in ("expired", "session"):
                        r.success()
                        if self.recover(err, self.cart_id):
                            continue
                        return False
                    r.failure("order 401 %s" % err)
                    return False
                if code in (412, 428) and attempt == 0:
                    r.success()
                    if self.refresh_cart():
                        continue
                    return False
                if code in (400, 409, 422) and attempt == 0 and not reservation_id:
                    if "reservation" in (r.text or "").lower():
                        r.success()
                        reservation_id = self.make_reservation()
                        if reservation_id:
                            continue
                        return False
                    r.failure("order status %s" % code)
                    return False
                r.failure("order status %s" % code)
                return False
        return False

    # ---------------- journey ----------------

    @task
    def journey(self):
        self.iterations += 1
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        if not self.do_login():
            return
        selection = self.do_select()
        if not selection:
            return
        product_id, variant_id = selection
        if not self.do_cart(product_id, variant_id):
            return
        self.do_checkout()


class ShopShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() < RUN_SECONDS:
            return (USERS, USERS)
        return None
