import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';

const businessFailure = new Rate('business_failure');

http.setResponseCallback(http.expectedStatuses({ min: 200, max: 399 }, 401, 429));

export const options = {
  scenarios: {
    per_vu_journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate==0'],
    'http_req_failed{transaction:login_form}': ['rate==0'],
    'http_req_failed{transaction:login}': ['rate==0'],
    'http_req_failed{transaction:login_redirect}': ['rate==0'],
    'http_req_failed{transaction:catalog}': ['rate==0'],
    'http_req_failed{transaction:cart_create}': ['rate==0'],
    'http_req_failed{transaction:order}': ['rate==0'],
    'http_req_failed{transaction:work}': ['rate==0'],
    'http_req_duration{transaction:login_form}': ['p(95)<3000'],
    'http_req_duration{transaction:login}': ['p(95)<3000'],
    'http_req_duration{transaction:catalog}': ['p(95)<3000'],
    'http_req_duration{transaction:cart_create}': ['p(95)<3000'],
    'http_req_duration{transaction:order}': ['p(95)<3000'],
    'http_req_duration{transaction:work}': ['p(95)<3000'],
  },
};

function safeJson(s) {
  if (!s) return null;
  try {
    return JSON.parse(s);
  } catch (e) {
    return null;
  }
}

function getAttr(tag, name) {
  const re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = re.exec(tag);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  return m[3];
}

function extractCsrf(html) {
  if (!html) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const name = getAttr(tag, 'name');
    if (name && String(name).toLowerCase() === 'csrf') {
      const value = getAttr(tag, 'value');
      if (value !== null && value !== undefined) return value;
    }
  }
  return null;
}

function absoluteUrl(loc) {
  if (!loc) return null;
  if (loc.indexOf('http://') === 0 || loc.indexOf('https://') === 0) return loc;
  if (loc.charAt(0) === '/') return BASE + loc;
  return BASE + '/' + loc;
}

function updateStateFromResponse(res, state) {
  if (!res) return;
  const body = safeJson(res.body);
  if (body) {
    if (body.csrf) state.csrf = body.csrf;
    if (body.grant_id) state.grant = body.grant_id;
    if (body.id && typeof body.id === 'string' && body.id.indexOf('cart-') === 0) {
      state.cartId = body.id;
    }
  }
  const etag = res.headers['ETag'] || res.headers['etag'];
  if (etag) state.etag = etag;
}

function login(state) {
  const formRes = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    tags: { transaction: 'login_form', sampler: 'HTTPSamplerProxy-4' },
  });
  check(formRes, {
    'login form status 200': (r) => r.status === 200,
  });

  state.csrf = extractCsrf(formRes.body);
  check(formRes, {
    'login form csrf extracted': () => !!state.csrf,
  });
  if (!state.csrf) return null;

  const payload = JSON.stringify({
    username: state.username,
    password: PASSWORD,
    csrf: state.csrf,
  });

  let res = http.post(BASE + '/v2/login', payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { transaction: 'login', sampler: 'HTTPSamplerProxy-12' },
  });
  updateStateFromResponse(res, state);

  if (res.status >= 300 && res.status < 400) {
    const loc = res.headers['Location'] || res.headers['location'];
    check(res, {
      'login redirect location present': () => !!loc,
    });
    if (loc) {
      const url = absoluteUrl(loc);
      res = http.get(url, {
        redirects: 0,
        tags: { transaction: 'login_redirect', sampler: 'HTTPSamplerProxy-21' },
      });
      updateStateFromResponse(res, state);
    }
  }

  check(res, {
    'login status ok': (r) => r.status === 200,
  });
  check(res, {
    'login response csrf present': () => !!state.csrf,
  });

  return res;
}

function getProduct(state) {
  const res = http.get(BASE + '/v2/catalog', {
    redirects: 0,
    tags: { transaction: 'catalog', sampler: 'HTTPSamplerProxy-26' },
  });
  updateStateFromResponse(res, state);

  check(res, {
    'catalog status 200': (r) => r.status === 200,
  });

  const body = safeJson(res.body);
  check(res, {
    'catalog json structure': () => !!(body && body.data && Array.isArray(body.data.products)),
  });

  let product = null;
  if (body && body.data && Array.isArray(body.data.products)) {
    for (const p of body.data.products) {
      if (!p || !Array.isArray(p.variants)) continue;
      for (const v of p.variants) {
        if (v && v.in_stock === true) {
          product = { product_id: p.id, variant_id: v.id };
          break;
        }
      }
      if (product) break;
    }
  }

  check(res, {
    'catalog in-stock product found': () => !!product,
  });

  return product;
}

function createCart(state, product) {
  const doOnce = () => {
    const payload = {
      product_id: product.product_id,
      variant_id: product.variant_id,
    };
    if (state.grant) payload.grant_id = state.grant;

    return http.post(BASE + '/v2/carts', JSON.stringify(payload), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf || '',
      },
      redirects: 0,
      tags: { transaction: 'cart_create', sampler: 'HTTPSamplerProxy-31' },
    });
  };

  let res = doOnce();
  if (res.status === 401) {
    const retryRes = handle401(res, state, doOnce, 'cart_create');
    if (retryRes) res = retryRes;
  }

  updateStateFromResponse(res, state);
  const body = safeJson(res.body);
  const cartId = body && body.id;
  if (cartId && typeof cartId === 'string' && cartId.indexOf('cart-') === 0) {
    state.cartId = cartId;
  }

  const etag = res.headers['ETag'] || res.headers['etag'];
  if (etag) state.etag = etag;

  state.grant = null;

  check(res, {
    'cart created': (r) => r.status === 201 && !!cartId && String(cartId).indexOf('cart-') === 0,
  });
  check(res, {
    'cart id format': () => !!cartId && String(cartId).indexOf('cart-') === 0,
  });

  return state.cartId;
}

function placeOrder(state) {
  const doOnce = () => {
    const payload = { cart_id: state.cartId };
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
      'Idempotency-Key': state.cartId || ('cart-' + __VU + '-' + __ITER),
    };
    if (state.etag) headers['If-Match'] = state.etag;

    return http.post(BASE + '/v2/orders', JSON.stringify(payload), {
      headers,
      redirects: 0,
      tags: { transaction: 'order', sampler: 'HTTPSamplerProxy-38' },
    });
  };

  let res = doOnce();
  if (res.status === 401) {
    const retryRes = handle401(res, state, doOnce, 'order');
    if (retryRes) res = retryRes;
  }

  updateStateFromResponse(res, state);
  const body = safeJson(res.body);
  const accepted = body && body.accepted === true;

  check(res, {
    'order accepted': (r) => r.status === 201 && accepted,
  });

  return res;
}

function doBusinessWork(state) {
  let retries429 = 0;
  let recovered401 = false;
  let finalRes = null;

  while (true) {
    const res = http.post(BASE + '/v2/work', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf || '',
      },
      redirects: 0,
      tags: { transaction: 'work' },
    });
    updateStateFromResponse(res, state);

    const body = safeJson(res.body);
    const err = body && body.error;
    const expectedExpiry = res.status === 401 && (err === 'expired' || err === 'session');
    const scheduled429 = res.status === 429;
    const ok = res.status === 200 && body && body.ok === true;
    const unexpected = !(scheduled429 || expectedExpiry || ok);

    businessFailure.add(unexpected ? 1 : 0);

    if (expectedExpiry && !recovered401) {
      recovered401 = true;
      if (err === 'expired') {
        renewSession(state);
      } else {
        freshLogin(state);
      }
      if (state.cartId) recoverCart(state);
      continue;
    }

    if (scheduled429 && retries429 < 4) {
      retries429++;
      const ra = res.headers['Retry-After'] || res.headers['retry-after'];
      const seconds = ra ? Number(ra) : 1;
      sleep((isNaN(seconds) ? 1 : seconds) * 1000);
      continue;
    }

    finalRes = res;
    break;
  }

  if (finalRes) {
    const finalBody = safeJson(finalRes.body);
    const finalErr = finalBody && finalBody.error;
    const finalExpected =
      finalRes.status === 429 ||
      (finalRes.status === 401 && (finalErr === 'expired' || finalErr === 'session'));

    if (!finalExpected) {
      check(finalRes, {
        'work ok': (r) => {
          const b = safeJson(r.body);
          return r.status === 200 && b && b.ok === true;
        },
      });
    }
  }
}

function handle401(res, state, retryFn, opName) {
  const body = safeJson(res.body);
  const err = body && body.error;

  if (err === 'denied') return null;
  if (err !== 'expired' && err !== 'session') return null;

  let ok = false;
  if (err === 'expired') {
    ok = renewSession(state);
  } else {
    ok = freshLogin(state);
  }
  if (!ok) return null;

  if (state.cartId) recoverCart(state);

  return retryFn();
}

function renewSession(state) {
  if (!state.csrf) return false;
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
    tags: { transaction: 'session_renew' },
  });
  updateStateFromResponse(res, state);
  return res.status >= 200 && res.status < 300;
}

function freshLogin(state) {
  http.cookieJar().clear(BASE);
  const cartId = state.cartId;
  const etag = state.etag;
  state.csrf = null;
  state.grant = null;
  state.cartId = cartId;
  state.etag = etag;

  login(state);
  return !!state.csrf;
}

function recoverCart(state) {
  if (!state.csrf || !state.cartId) return false;
  const res = http.post(BASE + '/v2/carts/' + state.cartId + '/recover', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
    tags: { transaction: 'cart_recover' },
  });
  updateStateFromResponse(res, state);
  return res.status >= 200 && res.status < 300;
}

export default function () {
  http.cookieJar().clear(BASE);

  const state = {
    username: 'bench-' + __VU,
    csrf: null,
    grant: null,
    cartId: null,
    etag: null,
  };

  login(state);
  if (!state.csrf) return;

  const product = getProduct(state);
  if (!product) return;

  const cartId = createCart(state, product);
  if (!cartId) return;

  placeOrder(state);
  doBusinessWork(state);
}
