import os
import re
import json
import time
from urllib.parse import urljoin
from html.parser import HTMLParser

from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser

_raw_host = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
if not _raw_host.startswith(("http://", "https://")):
    _raw_host = "http://" + _raw_host
BASE_HOST = _raw_host

_USER_SEQ = 0
_COMPLETED_JOURNEYS = 0
_SHAPE_START = None


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None
        self.challenge = None
        self.form_action = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        d = {k.lower(): v for k, v in attrs}
        if tag == "form":
            action = d.get("action")
            if action and not self.form_action:
                self.form_action = action
        elif tag == "input":
            name = d.get("name")
            value = d.get("value")
            if name is None or value is None:
                return
            lname = name.lower()
            if lname == "csrf" and self.csrf is None:
                self.csrf = value
            elif lname == "challenge" and self.challenge is None:
                self.challenge = value


def _parse_form(text):
    p = _FormParser()
    try:
        p.feed(text or "")
    except Exception:
        pass
    return p


def _safe_json(resp):
    try:
        return resp.json()
    except Exception:
        try:
            return json.loads(resp.text or "")
        except Exception:
            return None


def _error_code(resp):
    data = _safe_json(resp)
    if isinstance(data, dict) and data.get("error"):
        return str(data["error"])
    m = re.search(r'"error"\s*:\s*"([^"]+)"', resp.text or "")
    return m.group(1) if m else None


def _iter_products(data):
    if not isinstance(data, dict):
        return
    d = data.get("data")
    if isinstance(d, dict):
        products = d.get("products")
        if isinstance(products, list):
            for p in products:
                yield p
        if isinstance(d.get("product"), dict):
            yield d["product"]
    products = data.get("products")
    if isinstance(products, list):
        for p in products:
            yield p
    if isinstance(data.get("product"), dict):
        yield data["product"]
    if "id" in data and "variants" in data:
        yield data


def _select_product(data):
    for prod in _iter_products(data):
        if not isinstance(prod, dict):
            continue
        pid = prod.get("id")
        variants = prod.get("variants")
        if pid is None or not isinstance(variants, list):
            continue
        for var in variants:
            if isinstance(var, dict) and var.get("in_stock") is True and var.get("id") is not None:
                return str(pid), str(var["id"])
    return None


class ShopUser(HttpUser):
    host = BASE_HOST
    wait_time = lambda self: 0

    def on_start(self):
        global _USER_SEQ
        _USER_SEQ += 1
        self.account_index = _USER_SEQ
        if self.account_index > 2:
            raise StopUser()
        self.username = f"bench-{self.account_index}" if self.account_index <= 16 else "bench"
        self.iterations = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None

    def _csrf_headers(self):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        return headers

    def _update_csrf(self, resp):
        data = _safe_json(resp)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
            return
        p = _parse_form(resp.text)
        if p.csrf:
            self.csrf = p.csrf

    def _join(self, base, url):
        if not url:
            return url
        if url.startswith("http://") or url.startswith("https://"):
            return url
        if url.startswith("/"):
            return self.host + url
        return urljoin(base, url)

    def _get_login_form(self):
        with self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return None
            p = _parse_form(resp.text)
            if not p.csrf:
                resp.failure("login-form missing csrf")
                return None
            resp.success()
            return p.csrf

    def _post_challenge(self, action, challenge, csrf, base_url):
        action_url = self._join(base_url, action)
        headers = {"Content-Type": "application/json"}
        token = csrf or self.csrf
        if token:
            headers["X-CSRF-Token"] = token
        with self.client.post(
            action_url,
            json={"challenge": challenge},
            headers=headers,
            name="POST /v2/challenges/[id]",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 302:
                resp.failure(f"challenge status {resp.status_code}")
                return False
            location = resp.headers.get("Location")
            if not location:
                resp.failure("challenge missing Location")
                return False
            resp.success()
        redirect_url = self._join(action_url, location)
        with self.client.get(
            redirect_url,
            name="GET challenge redirect",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge redirect status {resp.status_code}")
                return False
            data = _safe_json(resp)
            p = _parse_form(resp.text)
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            elif p.csrf:
                self.csrf = p.csrf
            if isinstance(data, dict) and data.get("grant_id"):
                self.grant_id = str(data["grant_id"])
                resp.success()
                return True
            resp.failure("challenge redirect missing grant_id")
            return False

    def _follow_login_location(self, location, fallback_csrf):
        url = self._join(self.host + "/v2/login", location)
        with self.client.get(
            url,
            name="GET login redirect",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login redirect status {resp.status_code}")
                return False
            data = _safe_json(resp)
            p = _parse_form(resp.text)
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            elif p.csrf:
                self.csrf = p.csrf
            else:
                self.csrf = self.csrf or fallback_csrf
            if isinstance(data, dict) and data.get("grant_id"):
                self.grant_id = str(data["grant_id"])
                resp.success()
                return True
            if p.form_action and p.challenge:
                resp.success()
                return self._post_challenge(
                    p.form_action,
                    p.challenge,
                    p.csrf or self.csrf or fallback_csrf,
                    url,
                )
            if self.csrf:
                resp.success()
                return True
            resp.failure("login redirect missing csrf/grant")
            return False

    def _login(self, clear_cookies=False):
        if clear_cookies:
            self.client.cookies.clear()
        self.csrf = None
        self.grant_id = None
        form_csrf = self._get_login_form()
        if not form_csrf:
            return False
        login_csrf = form_csrf
        location = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": login_csrf},
            headers={"Content-Type": "application/json"},
            name="POST /v2/login",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            location = resp.headers.get("Location")
            if status not in (200, 302):
                resp.failure(f"login status {status}")
                return False
            if status == 200:
                data = _safe_json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                else:
                    p = _parse_form(resp.text)
                    if p.csrf:
                        self.csrf = p.csrf
                if not self.csrf and not location:
                    resp.failure("login missing csrf")
                    return False
            else:
                if not location:
                    resp.failure("login 302 missing Location")
                    return False
            resp.success()
        if location:
            if not self._follow_login_location(location, login_csrf):
                return False
        if not self.csrf:
            return False
        return True

    def _renew_session(self):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            name="POST /v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                self._update_csrf(resp)
                resp.success()
                return True
            if resp.status_code == 401:
                code = _error_code(resp)
                if code in ("expired", "session"):
                    resp.success()
                else:
                    resp.failure(f"renew 401 {code}")
                return False
            resp.failure(f"renew status {resp.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        url = f"/v2/carts/{self.cart_id}/recover"
        with self.client.post(
            url,
            json={},
            headers=headers,
            name="POST /v2/carts/[id]/recover",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 201, 204):
                self._update_csrf(resp)
                etag = resp.headers.get("ETag")
                if etag:
                    self.etag = etag
                resp.success()
                return True
            if resp.status_code == 401:
                code = _error_code(resp)
                if code in ("expired", "session"):
                    resp.success()
                else:
                    resp.failure(f"cart recover 401 {code}")
                return False
            resp.failure(f"cart recover status {resp.status_code}")
            return False

    def _recover(self, kind, cart_exists):
        if kind == "expired":
            if self._renew_session():
                if cart_exists and not self._recover_cart():
                    return False
                return True
        if not self._login(clear_cookies=False):
            return False
        if cart_exists and not self._recover_cart():
            return False
        return True

    def _get_json_with_recovery(self, url, name, validator=None):
        for attempt in range(2):
            recovery = None
            with self.client.get(
                url,
                name=name,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    code = _error_code(resp)
                    if code in ("expired", "session") and attempt == 0:
                        resp.success()
                        recovery = code
                    else:
                        resp.failure(f"{name} 401 {code}")
                        return None
                elif resp.status_code != 200:
                    resp.failure(f"{name} status {resp.status_code}")
                    return None
                else:
                    data = _safe_json(resp)
                    if data is None:
                        resp.failure(f"{name} malformed json")
                        return None
                    if validator is not None and not validator(data):
                        resp.failure(f"{name} validation failed")
                        return None
                    self._update_csrf(resp)
                    resp.success()
                    return data
            if recovery:
                if not self._recover(recovery, cart_exists=False):
                    return None
            else:
                return None
        return None

    def _catalog_product(self):
        def ok(d):
            return _select_product(d) is not None or (
                isinstance(d, dict) and bool(d.get("next"))
            )

        data = self._get_json_with_recovery("/v2/catalog", "GET /v2/catalog", validator=ok)
        if data is None:
            return None
        selected = _select_product(data)
        if selected:
            return selected
        next_url = data.get("next") if isinstance(data, dict) else None
        if next_url is not None and not isinstance(next_url, str):
            next_url = str(next_url)
        pages = 0
        current_url = self.host + "/v2/catalog"
        while next_url and pages < 3:
            pages += 1
            if next_url.startswith("http://") or next_url.startswith("https://"):
                page_url = next_url
            elif next_url.startswith("/"):
                page_url = self.host + next_url
            else:
                if current_url.endswith("/v2/catalog") and not next_url.startswith("?"):
                    page_url = urljoin(current_url + "/", next_url)
                else:
                    page_url = urljoin(current_url, next_url)

            require_product = pages >= 3

            def ok_page(d, req=require_product):
                if _select_product(d) is not None:
                    return True
                return (not req) and isinstance(d, dict) and bool(d.get("next"))

            data = self._get_json_with_recovery(
                page_url,
                "GET /v2/catalog/page",
                validator=ok_page,
            )
            if data is None:
                return None
            selected = _select_product(data)
            if selected:
                return selected
            next_url = data.get("next") if isinstance(data, dict) else None
            if next_url is not None and not isinstance(next_url, str):
                next_url = str(next_url)
            current_url = page_url
        return None

    def _create_cart(self, product_id, variant_id):
        for attempt in range(2):
            body = {"product_id": product_id, "variant_id": variant_id}
            if self.grant_id:
                body["grant_id"] = self.grant_id
            headers = self._csrf_headers()
            recovery = None
            with self.client.post(
                "/v2/carts",
                json=body,
                headers=headers,
                name="POST /v2/carts",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    code = _error_code(resp)
                    if code in ("expired", "session") and attempt == 0:
                        resp.success()
                        recovery = code
                    else:
                        resp.failure(f"cart 401 {code}")
                        return False
                elif resp.status_code != 201:
                    resp.failure(f"cart status {resp.status_code}")
                    return False
                else:
                    data = _safe_json(resp)
                    cart_id = data.get("id") if isinstance(data, dict) else None
                    if not cart_id:
                        resp.failure("cart missing id")
                        return False
                    if not str(cart_id).startswith("cart-"):
                        resp.failure("cart id assertion failed")
                        return False
                    self.cart_id = str(cart_id)
                    self.etag = resp.headers.get("ETag")
                    self._update_csrf(resp)
                    self.grant_id = None
                    resp.success()
                    return True
            if recovery:
                if not self._recover(recovery, cart_exists=False):
                    return False
            else:
                return False
        return False

    def _post_order(self):
        if not self.cart_id:
            return False
        for attempt in range(2):
            headers = self._csrf_headers()
            headers["Idempotency-Key"] = self.cart_id
            if self.etag:
                headers["If-Match"] = self.etag
            body = {"cart_id": self.cart_id}
            recovery = None
            with self.client.post(
                "/v2/orders",
                json=body,
                headers=headers,
                name="POST /v2/orders",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    code = _error_code(resp)
                    if code in ("expired", "session") and attempt == 0:
                        resp.success()
                        recovery = code
                    else:
                        resp.failure(f"order 401 {code}")
                        return False
                elif resp.status_code in (200, 201):
                    data = _safe_json(resp)
                    if not isinstance(data, dict):
                        resp.failure("order malformed")
                        return False
                    if data.get("accepted") is True:
                        self._update_csrf(resp)
                        resp.success()
                        return True
                    resp.failure("order not accepted")
                    return False
                else:
                    resp.failure(f"order status {resp.status_code}")
                    return False
            if recovery:
                if not self._recover(recovery, cart_exists=True):
                    return False
            else:
                return False
        return False

    @task
    def shop_journey(self):
        global _COMPLETED_JOURNEYS
        if self.account_index > 2:
            raise StopUser()
        try:
            self.client.cookies.clear()
            self.csrf = None
            self.cart_id = None
            self.etag = None
            self.grant_id = None
            if not self._login(clear_cookies=False):
                return
            product = self._catalog_product()
            if not product:
                return
            product_id, variant_id = product
            if not self._create_cart(product_id, variant_id):
                return
            self._post_order()
        finally:
            self.iterations += 1
            _COMPLETED_JOURNEYS += 1
            if self.iterations >= 2:
                raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        global _SHAPE_START
        now = time.time()
        if _SHAPE_START is None:
            _SHAPE_START = now
        if _COMPLETED_JOURNEYS >= 4:
            return None
        if now - _SHAPE_START > 60:
            return None
        return {"users": 2, "spawn_rate": 2}
