            url,
            name="GET /v2/login (redirect)",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login redirect: status {resp.status_code}")
                return False
            data = _safe_json(resp)
            form = _parse_form(resp.text)
            if isinstance(data, dict):
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                if data.get("grant_id"):
                    self.grant_id = str(data["grant_id"])
            if not self.csrf and form.csrf:
                self.csrf = form.csrf
            if self.grant_id:
                resp.success()
                return True
            if form.form_action and form.challenge:
                resp.success()
                return self._solve_challenge(
                    form.form_action,
                    form.challenge,
                    form.csrf or self.csrf or fallback_csrf,
                    url,
                )
            if self.csrf:
                resp.success()
                return True
            resp.failure("login redirect: no csrf/challenge/grant")
            return False

    def _solve_challenge(self, action, challenge, csrf, base_url):
        action_url = _join(base_url, action)
        headers = {"Content-Type": "application/json"}
        token = csrf or self.csrf
        if token:
            headers["X-CSRF-Token"] = token
        with self.client.post(
            action_url,
            json={"challenge": challenge},
            headers=headers,
            name="POST /v2/challenges/[id]",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 302:
                resp.failure(f"challenge: status {resp.status_code}")
                return False
            location = resp.headers.get("Location")
            if not location:
                resp.failure("challenge: missing Location")
                return False
            resp.success()
        redirect_url = _join(action_url, location)
        with self.client.get(
            redirect_url,
            name="GET /v2/challenges/[id] (redirect)",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"challenge redirect: status {resp.status_code}")
                return False
            data = _safe_json(resp)
            if isinstance(data, dict):
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                if data.get("grant_id"):
                    self.grant_id = str(data["grant_id"])
            if not self.grant_id:
                resp.failure("challenge redirect: missing grant_id")
                return False
            resp.success()
            return True

    # --------------------------------------------------------------- catalog
    def _pick_product(self):
        data = self._catalog_get(BASE_URL + "/v2/catalog", "GET /v2/catalog", False)
        if data is None:
            return None
        chosen = _choose_product(data)
        if chosen:
            return chosen
        next_url = data.get("next")
        current = BASE_URL + "/v2/catalog"
        page = 1
        while next_url and page < 3:
            page += 1
            page_url = _join(current, str(next_url))
            data = self._catalog_get(
                page_url, "GET /v2/catalog/page", page == 3
            )
            if data is None:
                return None
            chosen = _choose_product(data)
            if chosen:
                return chosen
            next_url = data.get("next")
            current = page_url
        return None

    def _catalog_get(self, url, name, require_product):
        with self.client.get(
            url,
            name=name,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"{name}: status {resp.status_code}")
                return None
            data = _safe_json(resp)
            if not isinstance(data, dict):
                resp.failure(f"{name}: malformed json")
                return None
            if _choose_product(data) is None:
                if require_product:
                    resp.failure(f"{name}: no in-stock product")
                    return None
                if not data.get("next"):
                    resp.failure(f"{name}: no product and no next page")
                    return None
            resp.success()
            return data

    # ------------------------------------------------------------------ cart
    def _create_cart(self, product_id, variant_id):
        for attempt in (1, 2):
            body = {"product_id": product_id, "variant_id": variant_id}
            if self.grant_id:
                body["grant_id"] = self.grant_id
            retry = None
            with self.client.post(
                "/v2/carts",
                json=body,
                headers=self._headers(),
                name="POST /v2/carts",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                status = resp.status_code
                if status == 201:
                    data = _safe_json(resp)
                    cart_id = data.get("id") if isinstance(data, dict) else None
                    if not cart_id:
                        resp.failure("cart: missing id")
                        return False
                    if not str(cart_id).startswith("cart-"):
                        resp.failure("cart: id assertion failed")
                        return False
                    self.cart_id = str(cart_id)
                    self.etag = resp.headers.get("ETag")
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                    self.grant_id = None
                    resp.success()
                    return True
                if status == 401:
                    code = _error_code(resp)
                    if code in ("expired", "session") and attempt == 1:
                        resp.success()
                        retry = code
                    else:
                        resp.failure(f"cart: 401 {code}")
                        return False
                else:
                    resp.failure(f"cart: status {status}")
                    return False
            if retry:
                if not self._recover(retry, cart_exists=False):
                    return False
        return False

    # --------------------------------------------------------------- session
    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            name="POST /v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                self._absorb_csrf(resp)
                resp.success()
                return True
            if resp.status_code == 401:
                code = _error_code(resp)
                if code in ("expired", "session"):
                    resp.success()
                else:
                    resp.failure(f"renew: 401 {code}")
                return False
            resp.failure(f"renew: status {resp.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True
        url = f"/v2/carts/{self.cart_id}/recover"
        with self.client.post(
            url,
            json={},
            headers=self._headers(),
            name="POST /v2/carts/[id]/recover",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 201, 204):
                self._absorb_csrf(resp)
                etag = resp.headers.get("ETag")
                if etag:
                    self.etag = etag
                resp.success()
                return True
            if resp.status_code == 401:
                code = _error_code(resp)
                if code in ("expired", "session"):
                    resp.success()
                else:
                    resp.failure(f"cart recover: 401 {code}")
                return False
            resp.failure(f"cart recover: status {resp.status_code}")
            return False

    def _recover(self, kind, cart_exists):
        if kind == "expired":
            if not self._renew():
                if not self._login():
                    return False
        else:
            if not self._login():
                return False
        if cart_exists and not self._recover_cart():
            return False
        return True

    # --------------------------------------------------------------- orders
    def _place_order(self):
        if not self.cart_id:
            return False
        for attempt in (1, 2):
            headers = self._headers()
            headers["Idempotency-Key"] = self.cart_id
            if self.etag:
                headers["If-Match"] = self.etag
            retry = None
            with self.client.post(
                "/v2/orders",
                json={"cart_id": self.cart_id},
                headers=headers,
                name="POST /v2/orders",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                status = resp.status_code
                if status in (200, 201):
                    data = _safe_json(resp)
                    if not isinstance(data, dict):
                        resp.failure("order: malformed json")
                        return False
                    if data.get("accepted") is not True:
                        resp.failure("order: accepted is not true")
                        return False
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    resp.success()
                    return True
                if status == 401:
                    code = _error_code(resp)
                    if code in ("expired", "session") and attempt == 1:
                        resp.success()
                        retry = code
                    else:
                        resp.failure(f"order: 401 {code}")
                        return False
                else:
                    resp.failure(f"order: status {status}")
                    return False
            if retry:
                if not self._recover(retry, cart_exists=True):
                    return False
        return False


