import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String extractAttr(String tag, String attr) {
        Pattern p = Pattern.compile("(?i)(?:^|\\s)" + Pattern.quote(attr)
            + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");
        Matcher m = p.matcher(tag);
        if (m.find()) {
            if (m.group(1) != null) return m.group(1);
            if (m.group(2) != null) return m.group(2);
            return m.group(3);
        }
        return null;
    }

    private static String findCsrfInput(String html) {
        Matcher input = Pattern.compile("(?is)<input\\b[^>]*>").matcher(html);
        String fallback = null;
        while (input.find()) {
            String tag = input.group();
            String name = extractAttr(tag, "name");
            if (name == null || !name.equalsIgnoreCase("csrf")) continue;
            String value = extractAttr(tag, "value");
            if (value == null || value.isEmpty()) continue;
            String type = extractAttr(tag, "type");
            if (type != null && type.equalsIgnoreCase("hidden")) {
                return value;
            }
            if (fallback == null) fallback = value;
        }
        return fallback;
    }

    private static Session parseLoginForm(Session session) {
        String html = session.getString("loginHtml");
        if (html == null) return session;

        Matcher form = Pattern.compile("(?is)<form\\b[^>]*>.*?</form>").matcher(html);
        while (form.find()) {
            String formBlock = form.group();
            Matcher open = Pattern.compile("(?is)^<form\\b[^>]*>").matcher(formBlock);
            if (open.find()) {
                String action = extractAttr(open.group(), "action");
                if (action != null && action.contains("/v2/login")) {
                    String csrf = findCsrfInput(formBlock);
                    if (csrf != null) return session.set("formCsrf", csrf);
                }
            }
        }

        String csrf = findCsrfInput(html);
        if (csrf != null) return session.set("formCsrf", csrf);
        return session;
    }

    private static Session parseLoginResponse(Session session) {
        String body = session.getString("loginBody");
        if (body != null && !body.isBlank()) {
            try {
                JsonNode node = JSON.readTree(body);
                if (node != null && node.hasNonNull("csrf")) {
                    session = session.set("csrf", node.get("csrf").asText());
                }
                if (node != null && node.hasNonNull("grant_id")) {
                    session = session.set("grant", node.get("grant_id").asText());
                }
            } catch (IOException | RuntimeException ignored) {
            }
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .set("csrf", "")
                .set("grant", "")
                .remove("location")
                .remove("cart")
                .remove("etag")
                .remove("product")
                .remove("variant")
                .remove("catalogBody")
                .remove("loginBody")
                .remove("loginHtml")
                .remove("formCsrf"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> parseLoginForm(session))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302), bodyString().saveAs("loginBody"),
                    header("Location").optional().saveAs("location")))
            .exec(session -> parseLoginResponse(session))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(status().is(200), bodyString().saveAs("loginBody")))
                .exec(session -> parseLoginResponse(session))));
    }

    private static Session selectProduct(Session session) {
        try {
            String body = session.getString("catalogBody");
            if (body == null || body.isBlank()) return session;

            JsonNode products = JSON.readTree(body).path("data").path("products");
            for (JsonNode product : products) {
                if (!product.hasNonNull("id")) continue;
                String productId = product.get("id").asText();
                for (JsonNode variant : product.path("variants")) {
                    if (variant.hasNonNull("id") && variant.path("in_stock").asBoolean()) {
                        return session.set("product", productId)
                            .set("variant", variant.get("id").asText());
                    }
                }
            }

            for (JsonNode product : products) {
                if (product.hasNonNull("id") && product.path("variants").size() > 0) {
                    JsonNode variant = product.path("variants").get(0);
                    if (variant.hasNonNull("id")) {
                        return session.set("product", product.get("id").asText())
                            .set("variant", variant.get("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException ignored) {
        }
        return session;
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar())
            .exec(login())
            .exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200), bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> selectProduct(session))
            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> "{\"product_id\":\"" + session.getString("product")
                    + "\",\"variant_id\":\"" + session.getString("variant") + "\"}"))
                .check(status().in(200, 201), jsonPath("$.id").saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(status().is(201), jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        setUp(scenario("flow")
            .exec(repeat(2).on(flow()))
            .injectOpen(atOnceUsers(2)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}
