import http from 'k6/http';
import { check } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const USERS = ['bench-1', 'bench-2'];
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function parseJson(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function decodeHtml(s) {
  return s.replace(/&amp;/g, '&')
          .replace(/&quot;/g, '"')
          .replace(/&#39;/g, "'")
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>');
}

function getAttr(tag, name) {
  const re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = re.exec(tag);
  if (!m) return null;
  const v = m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
  return decodeHtml(v);
}

function cleanHtml(html) {
  return html.replace(/<!--[\s\S]*?-->/g, '')
             .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
             .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '');
}

function inputValue(html, name) {
  const clean = cleanHtml(html);
  const tags = clean.match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const n = getAttr(tags[i], 'name');
    if (n && n.toLowerCase() === name.toLowerCase()) {
      const v = getAttr(tags[i], 'value');
      if (v !== null && v !== '') return v;
    }
  }
  return null;
}

function extractCsrf(html) {
  if (!html) return null;
  const clean = cleanHtml(html);
  const forms = clean.match(/<form\b[^>]*>[\s\S]*?<\/form>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const open = forms[i].match(/<form\b[^>]*>/i);
    const action = open ? (getAttr(open[0], 'action') || '') : '';
    if (action.toLowerCase().indexOf('login') >= 0) {
      const v = inputValue(forms[i], 'csrf');
      if (v) return v;
    }
  }
  for (let i = 0; i < forms.length; i++) {
    const v = inputValue(forms[i], 'csrf');
    if (v) return v;
  }
  return inputValue(clean, 'csrf');
}

function header(r, name) {
  const h = r.headers || {};
  const lower = name.toLowerCase();
  for (const k in h) {
    if (k.toLowerCase() === lower) return h[k];
  }
  return null;
}

function absolute(url) {
  if (!url) return url;
  if (/^https?:\/\//i.test(url)) return url;
  if (url.charAt(0) === '/') return BASE + url;
  return BASE + '/' + url.replace(/^\.?\//, '');
}

function raw(state, path, method, data, extra) {
  const headers = {};
  if (method !== 'GET' && method !== 'HEAD') {
    headers['Content-Type'] = 'application/json';
    if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
  }
  if (extra) {
    for (const k in extra) headers[k] = extra[k];
  }
  const params = {
    headers: headers,
    redirects: 0,
    timeout: '3s',
  };
  const body = data === null || data === undefined ? null : JSON.stringify(data);
  const r = http.request(method, absolute(path), body, params);
  const b = parseJson(r);
  if (r.status < 400 && b && b.csrf) state.csrf = b.csrf;
  return r;
}

function login(state) {
  state.csrf = '';
  const form = raw(state, '/v2/login-form', 'GET', null, null);
  const token = extractCsrf(form.body);
  check(form, { 'login form': r => r.status === 200 && !!token });
  if (form.status !== 200 || !token) return false;
  state.csrf = token;

  let r = raw(state, '/v2/login', 'POST', {
    username: state.username,
    password: state.password,
    csrf: token,
  }, null);

  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (loc) {
      r = raw(state, loc, 'GET', null, null);
      const htmlToken = extractCsrf(r.body);
      if (htmlToken) state.csrf = htmlToken;
    }
  }

  return check(r, { 'login': resp => resp.status === 200 });
}

function recover(state, error) {
  let ok = false;
  if (error === 'expired') {
    const renew = raw(state, '/v2/session/renew', 'POST', {}, null);
    if (renew.status === 200) ok = true;
  }
  if (!ok) {
    ok = login(state);
  }
  if (state.cartId !== '') {
    raw(state, '/v2/carts/' + state.cartId + '/recover', 'POST', {}, null);
  }
  return ok;
}

function request(state, path, method, data, extra) {
  let r = raw(state, path, method, data, extra);
  if (r.status === 401) {
    const b = parseJson(r);
    const err = b && b.error;
    if (err === 'expired' || err === 'session') {
      if (recover(state, err)) {
        r = raw(state, path, method, data, extra);
      }
    }
  }
  return r;
}

function eligibleProduct(products) {
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || !p.variants) continue;
    for (let j = 0; j < p.variants.length; j++) {
      const v = p.variants[j];
      if (v && v.in_stock) return { product: p, variant: v };
    }
  }
  return null;
}

function getCatalog(state) {
  const r = request(state, '/v2/catalog', 'GET', null, null);
  const b = parseJson(r);
  const products = b && b.data && b.data.products ? b.data.products : [];
  return eligibleProduct(products);
}

export default function () {
  const state = {
    username: USERS[(__VU - 1) % USERS.length],
    password: PASSWORD,
    csrf: '',
    cartId: '',
    etag: '',
  };
  try { http.cookieJar().clear(BASE); } catch (_) {}

  if (!login(state)) {
    check(false, { 'journey login': () => false });
    return;
  }

  const chosen = getCatalog(state);
  if (!chosen) {
    check(false, { 'eligible product': () => false });
    return;
  }

  const cartPayload = {
    product_id: chosen.product.id,
    variant_id: chosen.variant.id,
  };
  const cartResp = request(state, '/v2/carts', 'POST', cartPayload, null);
  const cartBody = parseJson(cartResp);
  state.cartId = cartBody && cartBody.id !== undefined && cartBody.id !== null ? cartBody.id : '';
  state.etag = header(cartResp, 'Etag') || '';
  check(cartResp, {
    'cart created': r => r.status === 201 && state.cartId !== '',
  });
  if (state.cartId === '') return;

  const orderExtra = {
    'Idempotency-Key': String(state.cartId),
  };
  if (state.etag) orderExtra['If-Match'] = state.etag;

  let orderResp = request(state, '/v2/orders', 'POST', { cart_id: state.cartId }, orderExtra);
  if (orderResp.status === 412) {
    const cartRead = request(state, '/v2/carts/' + state.cartId, 'GET', null, null);
    const newEtag = header(cartRead, 'Etag');
    if (newEtag) {
      orderExtra['If-Match'] = newEtag;
      orderResp = request(state, '/v2/orders', 'POST', { cart_id: state.cartId }, orderExtra);
    }
  }

  const orderBody = parseJson(orderResp);
  check(orderResp, {
    'order accepted': r => r.status === 201 && orderBody && orderBody.accepted === true,
  });
}
