function decodeEntities(value) {
  return String(value)
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(tag) {
  const attrs = {};
  let s = String(tag);
  s = s.replace(/^<\s*input\b/i, '');
  s = s.replace(/\/?>\s*$/, '');

  let i = 0;
  while (i < s.length) {
    while (i < s.length && /\s/.test(s.charAt(i))) i++;
    if (i >= s.length) break;

    let start = i;
    while (i < s.length && !/[\s=]/.test(s.charAt(i))) i++;
    const name = s.slice(start, i).toLowerCase();

    while (i < s.length && /\s/.test(s.charAt(i))) i++;

    let value = '';
    if (s.charAt(i) === '=') {
      i++;
      while (i < s.length && /\s/.test(s.charAt(i))) i++;

      const quote = s.charAt(i);
      if (quote === '"' || quote === "'") {
        i++;
        start = i;
        while (i < s.length && s.charAt(i) !== quote) i++;
        value = s.slice(start, i);
        if (i < s.length) i++;
      } else {
        start = i;
        while (i < s.length && !/[\s>]/.test(s.charAt(i))) i++;
        value = s.slice(start, i);
      }
    }

    if (name) attrs[name] = decodeEntities(value);
  }

  return attrs;
}

function eachInputTag(html, cb) {
  const s = String(html || '');
  const lower = s.toLowerCase();
  let idx = 0;

  while ((idx = lower.indexOf('<input', idx)) !== -1) {
    const after = lower.charAt(idx + 6);
    if (after !== '>' && after !== '/' && !/\s/.test(after)) {
      idx += 6;
      continue;
    }

    let i = idx + 6;
    let quote = '';
    while (i < s.length) {
      const ch = s.charAt(i);
      if (quote) {
        if (ch === quote) quote = '';
      } else if (ch === '"' || ch === "'") {
        quote = ch;
      } else if (ch === '>') {
        break;
      }
      i++;
    }

    const tag = s.slice(idx, i + 1);
    if (cb(tag) === false) return;
    idx = i + 1;
  }
}

function extractCsrfFromHtml(html) {
  let found = '';
  eachInputTag(html, function (tag) {
    const attrs = parseAttrs(tag);
    const name = attrs.name;
    if (
      name &&
      name.trim().toLowerCase() === 'csrf' &&
      attrs.value !== undefined &&
      attrs.value !== ''
    ) {
      found = attrs.value;
      return false;
    }
  });
  return found;
}

function parseJson(res) {
  if (!res || !res.body) return {};
  try {
    const v = res.json();
    return v && typeof v === 'object' ? v : {};
  } catch (e) {
    return {};
  }
}

function header(res, name) {
  if (!res || !res.headers) return '';
  const target = String(name).toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === target) {
      const v = res.headers[k];
      return Array.isArray(v) ? v[0] : v;
    }
  }
  return '';
}

function resolveUrl(path) {
  if (!path) return base;
  const s = String(path);
  if (/^https?:\/\//i.test(s)) return s;
  if (s.charAt(0) === '/') return base + s;
  return base + '/' + s;
}

function clearCookies() {
  const jar = http.cookieJar();
  if (jar && typeof jar.clear === 'function') {
    try {
      jar.clear(base);
    } catch (e) {}
  }
}

function rawRequest(method, path, body, extraHeaders, state) {
  const m = String(method).toUpperCase();
  const headers = Object.assign({}, extraHeaders || {});

  if (m !== 'GET' && body !== undefined && body !== null) {
    let hasContentType = false;
    for (const k in headers) {
      if (k.toLowerCase() === 'content-type') hasContentType = true;
    }
    if (!hasContentType) headers['Content-Type'] = 'application/json';
  }

  if (state && state.csrf && m !== 'GET') {
    let hasCsrf = false;
    for (const k in headers) {
      if (k.toLowerCase() === 'x-csrf-token') hasCsrf = true;
    }
    if (!hasCsrf) headers['X-CSRF-Token'] = state.csrf;
  }

  const params = {
    headers: headers,
    redirects: 0,
    timeout: '5s'
  };

  const res = http.request(
    m,
    resolveUrl(path),
    body === undefined || body === null ? null : JSON.stringify(body),
    params
  );

  const b = parseJson(res);
  if (state && b.csrf) state.csrf = b.csrf;
  return res;
}

function isExpiry(res) {
  if (!res || res.status !== 401) return false;
  const b = parseJson(res);
  return b.error === 'expired' || b.error === 'session';
}

function renewSession(state) {
  const r = rawRequest('POST', '/v2/session/renew', {}, {}, state);
  const b = parseJson(r);
  if (b.csrf) state.csrf = b.csrf;
  return r.status === 200 && !!state.csrf;
}

function login(state, row) {
  clearCookies();
  state.csrf = '';
  state.user = '';
  state.grant = '';

  let r = rawRequest('GET', '/v2/login-form', null, {}, state);
  check(r, { 'login form': res => res.status === 200 });

  const formCsrf = extractCsrfFromHtml(r.body);
  if (!formCsrf) {
    check(false, { 'login form csrf': () => false });
    return false;
  }

  r = rawRequest(
    'POST',
    '/v2/login',
    { username: row.username, password: row.password, csrf: formCsrf },
    {},
    state
  );

  const b = parseJson(r);
  let csrf = b.csrf || '';
  let user = b.user || '';
  let grant = b.grant_id || '';

  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (!loc) {
      check(false, { 'login redirect': () => false });
      return false;
    }

    const follow = rawRequest('GET', loc, null, {}, state);
    check(follow, { 'login redirect': res => res.status === 200 });

    const fb = parseJson(follow);
    if (fb.csrf) csrf = fb.csrf;
    if (fb.user) user = fb.user;
    if (fb.grant_id) grant = fb.grant_id;

    if (!csrf && follow.body) {
      const htmlCsrf = extractCsrfFromHtml(follow.body);
      if (htmlCsrf) csrf = htmlCsrf;
    }
  } else if (r.status !== 200) {
    check(false, { 'login status': () => false });
    return false;
  }

  if (!csrf && r.body) {
    const htmlCsrf = extractCsrfFromHtml(r.body);
    if (htmlCsrf) csrf = htmlCsrf;
  }

  state.csrf = csrf || '';
  state.user = user || '';
  state.grant = grant || '';

  check(r, { 'login status': res => res.status === 200 || res.status === 302 });
  check(state, { 'login csrf': s => !!s.csrf });

  return !!state.csrf;
}

function recoverFor(state, row, res, cartId, ctx) {
  const b = parseJson(res);

  if (b.error === 'expired') {
    if (!renewSession(state)) {
      if (!login(state, row)) return false;
    }
  } else if (b.error === 'session') {
    if (!login(state, row)) return false;
  } else {
    return false;
  }

  if (cartId) {
    const rr = rawRequest(
      'POST',
      '/v2/carts/' + encodeURIComponent(cartId) + '/recover',
      {},
      {},
      state
    );
    const newEtag = header(rr, 'ETag');
    if (newEtag && ctx) ctx.etag = newEtag;
  }

  return true;
}

function getWithRecovery(state, row, path) {
  let res = rawRequest('GET', path, null, {}, state);
  if (isExpiry(res)) {
    if (recoverFor(state, row, res, null, null)) {
      res = rawRequest('GET', path, null, {}, state);
    }
  }
  return res;
}

function inStock(v) {
  if (!v) return false;
  const x = v.in_stock;
  if (x === false || x === 0 || x === '0' || x === '' || x === null || x === undefined) {
    return false;
  }
  if (typeof x === 'string' && x.toLowerCase() === 'false') return false;
  return true;
}

function findProduct(state, row) {
  let path = '/v2/catalog';

  for (let page = 0; page < 3 && path; page++) {
    const res = getWithRecovery(state, row, path);
    check(res, { 'catalog page': r => r.status === 200 });
    if (res.status !== 200) return null;

    const b = parseJson(res);
    const data = b.data || {};
    const products = data.products
      ? data.products
      : data.product
        ? [data.product]
        : Array.isArray(data)
          ? data
          : [];

    for (let i = 0; i < products.length; i++) {
      const p = products[i] || {};
      const variants = Array.isArray(p.variants) ? p.variants : [];

      for (let j = 0; j < variants.length; j++) {
        const v = variants[j] || {};
        if (
          inStock(v) &&
          p.id !== undefined &&
          p.id !== null &&
          v.id !== undefined &&
          v.id !== null
        ) {
          return { product: p, variant: v };
        }
      }
    }

    path = b.next || null;
  }

  return null;
}

function createCart(state, row, product, variant) {
  function makeBody() {
    const b = { product_id: product.id, variant_id: variant.id };
    if (state.grant) b.grant_id = state.grant;
    return b;
  }

  let res = rawRequest('POST', '/v2/carts', makeBody(), {}, state);
  if (isExpiry(res)) {
    if (recoverFor(state, row, res, null, null)) {
      res = rawRequest('POST', '/v2/carts', makeBody(), {}, state);
    }
  }
  return res;
}

function submitOrder(state, row, cartId, etag) {
  const ctx = { row: row, cartId: cartId, etag: etag || '' };

  function makeHeaders() {
    const h = { 'Idempotency-Key': String(cartId) };
    if (ctx.etag) h['If-Match'] = ctx.etag;
    return h;
  }

  let res = rawRequest(
    'POST',
    '/v2/orders',
    { cart_id: cartId },
    makeHeaders(),
    state
  );

  if (isExpiry(res)) {
    if (recoverFor(state, row, res, cartId, ctx)) {
      res = rawRequest(
        'POST',
        '/v2/orders',
        { cart_id: cartId },
        makeHeaders(),
        state
      );
    }
  }

  return res;
}

export default function () {
  const rowIndex = ((__VU - 1) * cfg.iterations + __ITER) % accounts.length;
  const row = accounts[rowIndex];
  const state = { csrf: '', user: '', grant: '' };

  if (!login(state, row)) return;

  const found = findProduct(state, row);
  if (!found) {
    check(false, { 'catalog product': () => false });
    return;
  }

  const cartRes = createCart(state, row, found.product, found.variant);
  const cartBody = parseJson(cartRes);
  const cartId = cartBody.id;

  check(cartRes, {
    'cart created': res =>
      res.status === 201 &&
      res.body &&
      cartBody.id !== undefined &&
      cartBody.id !== null
  });

  if (cartRes.status !== 201 || cartId === undefined || cartId === null) return;

  const etag = header(cartRes, 'ETag');
  const orderRes = submitOrder(state, row, cartId, etag);
  const orderBody = parseJson(orderRes);

  check(orderRes, {
    'order accepted': res =>
      res.status === 201 &&
      orderBody.accepted === true
  });
}
