PASSWORD = "bench"

USER_LOCK = Semaphore()
NEXT_USER = 0


class _InputParser(HTMLParser):
    def __init__(self, wanted):
        super().__init__(convert_charrefs=True)
        self.wanted = wanted.lower()
        self.value = None

    def _handle(self, tag, attrs):
        if self.value is not None:
            return
        if tag.lower() != "input":
            return
        data = {k.lower(): (v if v is not None else "") for k, v in attrs}
        if data.get("name") == self.wanted:
            self.value = data.get("value", "")

    def handle_starttag(self, tag, attrs):
        self._handle(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._handle(tag, attrs)


def input_value(html, name):
    parser = _InputParser(name)
    try:
        parser.feed(html or "")
    except Exception:
        return None
    return parser.value


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = lambda self: 0

    def on_start(self):
        global NEXT_USER
        with USER_LOCK:
            NEXT_USER += 1
            number = NEXT_USER
        self.username = "bench-" + str((number - 1) % 16 + 1)
        self.password = PASSWORD
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.grant = ""
        self.iteration = 0

    def raw(self, method, path, json=None, headers=None, name=None,
            expected=None, allow_auth=True):
        expected = expected or set()
        request_headers = {"Content-Type": "application/json"}
        if self.csrf and method.upper() != "GET":
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method,
            path,
            json=json,
            headers=request_headers,
            name=name,
            catch_response=True,
            allow_redirects=False,
            timeout=10,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            if body.get("csrf"):
                self.csrf = body["csrf"]

            status = response.status_code
            error = body.get("error")
            ok = status < 400 or status in expected

            if allow_auth and status == 401 and error in ("expired", "session"):
                ok = True

            if status == 429 and path.split("?", 1)[0].endswith("/v2/work"):
                ok = True

            if (
                method.upper() == "POST"
                and path.split("?", 1)[0].endswith("/v2/orders")
                and status < 400
                and body.get("accepted") is not True
            ):
                ok = False

            if ok:
                response.success()
            else:
                response.failure(
                    "unexpected response " + str(status) + " error=" + repr(error)
                )

            return response, body

    def login(self):
        self.csrf = ""
        response, _ = self.raw("GET", "/v2/login-form", expected={200})
        if response.status_code != 200:
            return False

        token = input_value(response.text, "csrf")
        if not token:
            return False

        response, body = self.raw(
            "POST",
            "/v2/login",
            json={
                "username": self.username,
                "password": self.password,
                "csrf": token,
            },
            expected={200, 201, 302},
