        response, body = self.request("GET", "/v2/catalog", expected={200})
        if response.status_code == 200 and isinstance(body, dict):
            products = body.get("data", {}).get("products", [])
            for product in products:
                for variant in product.get("variants", []):
                    if variant.get("in_stock"):
                        return product, variant

        page = "/v2/catalog/page"
        for _ in range(3):
            response, body = self.request("GET", page, expected={200})
            if response.status_code != 200 or not isinstance(body, dict):
                break

            products = body.get("data", {}).get("products", [])
            if not products:
                product = body.get("data", {}).get("product") or body.get("product")
                if product:
                    products = [product]

            for product in products:
