                "GET", "/v2/carts/" + self.cart, expected={200}
            )
            if cart_response.status_code == 200:
                self.etag = cart_response.headers.get("ETag", "")

        return True

    def checkout(self):
        payload = {"cart_id": self.cart}
        headers = {"Idempotency-Key": self.cart}
        if self.etag:
            headers["If-Match"] = self.etag

        response, body = self.request(
            "POST",
            "/v2/orders",
            json=payload,
            headers=headers,
            name="checkout",
            expected={200, 201, 412},
        )

        if response.status_code == 412:
            cart_response, _ = self.request(
                "GET", "/v2/carts/" + self.cart, expected={200}
            )
            if cart_response.status_code == 200:
                self.etag = cart_response.headers.get("ETag", self.etag)

            if self.etag:
                headers["If-Match"] = self.etag
            else:
                headers.pop("If-Match", None)

            response, body = self.request(
                "POST",
                "/v2/orders",
                json=payload,
                headers=headers,
                name="checkout",
                expected={200, 201},
            )

        if response.status_code not in (200, 201):
            return False
        if not isinstance(body, dict) or body.get("accepted") is not True:
            return False
        return True

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.grant = ""

        if not self.login():
            return False

        product, variant = self.get_product()
        if not product or not variant:
            return False

        if not self.create_cart(product, variant):
            return False

        if not self.checkout():
            return False

        return True

    @task
    def run_scenario(self):
        try:
            ok = self.flow()
        except StopUser:
            raise
        except Exception:
            self.environment.process_exit_code = 1
            raise StopUser()

        if not ok:
            self.environment.process_exit_code = 1
            raise StopUser()

        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


