function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function hdr(r, name) {
  if (!r || !r.headers) return '';
  const names = [name, name.toLowerCase(), name.toUpperCase()];
  for (let i = 0; i < names.length; i++) {
    if (r.headers[names[i]] !== undefined) return r.headers[names[i]];
  }
  for (const k in r.headers) {
    if (k.toLowerCase() === name.toLowerCase()) return r.headers[k];
  }
  return '';
}

function urlOf(path) {
  if (!path) return base;
  if (path.indexOf('http') === 0) return path;
  if (path.charAt(0) === '/') return base + path;
  return base + '/' + path;
}

function resolvePath(currentPath, next) {
  if (!next) return null;
  if (next.indexOf('http') === 0) return next;

  let cur = currentPath || '/';
  const m = cur.match(/^https?:\/\/[^\/]+(\/.*)?$/);
  if (m) cur = m[1] || '/';

  if (next.charAt(0) === '/') return next;

  const q = cur.indexOf('?');
  const clean = q >= 0 ? cur.substring(0, q) : cur;

  if (next.charAt(0) === '?') return clean + next;

  const slash = clean.lastIndexOf('/');
  const dir = slash >= 0 ? clean.substring(0, slash + 1) : '/';
  return dir + next;
}

