import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final String CONFIG_JSON = "{\"users\": 2, \"iterations\": 2, \"mode\": \"decline\"}";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = readConfig();
    private static final int USERS = CFG.path("users").asInt(2);
    private static final int ITERATIONS = CFG.path("iterations").asInt(2);

    private static final HttpProtocolBuilder HTTP = http.baseUrl(System.getenv("BASE_URL"))
        .acceptHeader("text/html,application/json;q=0.9,*/*;q=0.8")
        .disableWarmUp();

    private static final Pattern INPUT_TAG = Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern CSRF_NAME =
        Pattern.compile("(?is)(?<![\\w-])name\\s*=\\s*['\"]?csrf['\"]?");
    private static final Pattern VALUE_ATTR =
        Pattern.compile("(?is)(?<![\\w-])value\\s*=\\s*['\"]?([^'\"\\s>]+)");

    private static JsonNode readConfig() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static String safe(String value) {
        return value == null ? "" : value;
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String extractCsrf(String html) {
        if (html == null) {
            return null;
        }
        Matcher tags = INPUT_TAG.matcher(html);
        while (tags.find()) {
            String tag = tags.group();
            if (CSRF_NAME.matcher(tag).find()) {
                Matcher value = VALUE_ATTR.matcher(tag);
                if (value.find()) {
                    return value.group(1);
                }
            }
        }
        return null;
    }

    private static Session parseJsonFields(Session session, String bodyVar) {
        String body = session.getString(bodyVar);
        if (body == null || body.isBlank()) {
            return session;
        }
        try {
            JsonNode node = JSON.readTree(body);
            if (node.hasNonNull("csrf")) {
                session = session.set("csrf", node.get("csrf").asText());
            }
            if (node.hasNonNull("grant_id")) {
                session = session.set("grant", node.get("grant_id").asText());
            }
            if (node.hasNonNull("id")) {
                session = session.set("cart", node.get("id").asText());
            }
            return session;
        } catch (IOException | RuntimeException ignored) {
            return session;
        }
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException ignored) {
            return session;
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "").set("grant", "").remove("location")
                .remove("loginForm").remove("loginBody").remove("redirectBody")
                .remove("formCsrf").remove("catalogBody").remove("product").remove("variant")
                .remove("cart").remove("cartBody").remove("etag").remove("orderId"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginForm")))
            .exec(session -> {
                String csrf = extractCsrf(session.getString("loginForm"));
                return csrf == null ? session : session.set("formCsrf", csrf);
            })
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + safe(session.getString("formCsrf")) + "\"}"))
                .check(status().in(200, 302),
                    header("Location").optional().saveAs("location"),
                    bodyString().saveAs("loginBody")))
            .exec(session -> parseJsonFields(session, "loginBody"))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(status().is(200), bodyString().saveAs("redirectBody")))
                .exec(session -> parseJsonFields(session, "redirectBody"))));
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar())
            .exec(login())
            .exec(http("catalog").get("/v2/catalog")
                .check(status().is(200), bodyString().saveAs("catalogBody")))
            .exec(session -> selectProduct(session))
            .exec(doIf(session -> session.contains("product") && session.contains("variant")).then(
                exec(http("cart").post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session -> {
                        String grant = session.getString("grant");
                        StringBuilder body = new StringBuilder("{\"product_id\":\"")
                            .append(session.getString("product"))
                            .append("\",\"variant_id\":\"")
                            .append(session.getString("variant"))
                            .append("\"");
                        if (grant != null && !grant.isEmpty()) {
                            body.append(",\"grant_id\":\"").append(grant).append("\"");
                        }
                        return body.append("}").toString();
                    }))
                    .check(status().is(201),
                        header("ETag").saveAs("etag"),
                        bodyString().saveAs("cartBody")))
                .exec(session -> parseJsonFields(session, "cartBody"))
                .exec(doIf(session -> session.contains("cart")).then(
                    exec(http("commit").post("/v2/orders")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Idempotency-Key", "#{cart}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                        .check(jsonPath("$.accepted").is(true),
                            status().is(201),
                            jsonPath("$.id").optional().saveAs("orderId"),
                            jsonPath("$.csrf").optional().saveAs("csrf"))))));
    }

    public ModelSimulation() {
        setUp(scenario("decline")
            .exec(repeat(ITERATIONS).on(flow()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}

