            return null;
        }
        for (int group = 1; group <= 3; group++) {
            if (matcher.group(group) != null) {
                return matcher.group(group);
            }
        }
        return null;
    }

    private static String csrfIn(String html) {
        Matcher tags = INPUT_TAG.matcher(text(html));
        while (tags.find()) {
            String tag = tags.group();
            String name = attribute(tag, "name");
            if (name != null && "csrf".equalsIgnoreCase(name.trim())) {
                String value = attribute(tag, "value");
                if (value != null && !value.isEmpty()) {
                    return value;
                }
            }
        }
        return null;
    }

    private static String extractCsrf(String html) {
        if (html == null || html.isEmpty()) {
            return null;
        }
        String fallback = null;
        Matcher forms = FORM_BLOCK.matcher(html);
        while (forms.find()) {
            String token = csrfIn(forms.group(2));
            if (token == null) {
                continue;
            }
            if (fallback == null) {
                fallback = token;
            }
            String action = attribute(forms.group(1), "action");
            if (action != null && action.toLowerCase().contains("login")) {
                return token;
            }
        }
        return fallback != null ? fallback : csrfIn(html);
    }

    private static Session absorb(Session session, String variable) {
        String body = session.getString(variable);
        if (body == null || body.isEmpty()) {
            return session;
        }
        JsonNode node;
        try {
            node = JSON.readTree(body);
        } catch (IOException | RuntimeException error) {
            return session;
        }
        if (node == null || !node.isObject()) {
            return session;
        }
        Session updated = session;
        if (node.hasNonNull("csrf")) {
            updated = updated.set("csrf", node.get("csrf").asText());
        }
        if (node.hasNonNull("grant_id")) {
            updated = updated.set("grant", node.get("grant_id").asText());
        }
        if (node.hasNonNull("id")) {
            updated = updated.set("cart", node.get("id").asText());
        }
        if (node.hasNonNull("order_id")) {
            updated = updated.set("orderId", node.get("order_id").asText());
        }
        return updated;
    }

    private static Session selectProduct(Session session) {
        JsonNode root;
        try {
            root = JSON.readTree(session.getString("catalogBody"));
        } catch (IOException | RuntimeException error) {
            return session;
        }
        if (root == null) {
            return session;
        }
        JsonNode firstProduct = null;
        JsonNode firstVariant = null;
        for (JsonNode product : root.path("data").path("products")) {
            for (JsonNode variant : product.path("variants")) {
                if (firstVariant == null) {
                    firstProduct = product;
                    firstVariant = variant;
                }
                if (variant.path("in_stock").asBoolean(false)) {
                    return session.set("product", product.path("id").asText())
                        .set("variant", variant.path("id").asText());
                }
            }
        }
        if (firstVariant != null) {
            return session.set("product", firstProduct.path("id").asText())
                .set("variant", firstVariant.path("id").asText());
        }
        return session;
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .set("csrf", "")
                .set("grant", "")
                .remove("location")
                .remove("formCsrf")
                .remove("loginForm")
                .remove("loginBody")
                .remove("redirectBody")
                .remove("catalogBody")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("cartBody")
                .remove("etag")
                .remove("orderId"))
            .exec(http("login form")
                .get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginForm")))
            .exec(session -> {
                String csrf = extractCsrf(session.getString("loginForm"));
                return csrf == null ? session : session.set("formCsrf", csrf);
            })
            .exec(http("login")
                .post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + text(session.getString("formCsrf"))
                    + "\"}"))
                .check(status().in(200, 302),
                    header("Location").optional().saveAs("location"),
                    bodyString().saveAs("loginBody")))
            .exec(session -> absorb(session, "loginBody"))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect")
                    .get("#{location}")
                    .check(status().is(200), bodyString().saveAs("redirectBody")))
                .exec(session -> absorb(session, "redirectBody"))));
    }

    private static String cartBody(Session session) {
        StringBuilder body = new StringBuilder("{\"product_id\":\"")
            .append(text(session.getString("product")))
            .append("\",\"variant_id\":\"")
            .append(text(session.getString("variant")))
            .append("\"");
        String grant = session.getString("grant");
        if (grant != null && !grant.isEmpty()) {
            body.append(",\"grant_id\":\"").append(grant).append("\"");
        }
        return body.append("}").toString();
    }

    private static HttpRequestActionBuilder cart() {
        return http("cart")
            .post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(session -> cartBody(session)))
            .check(status().in(200, 201),
                header("ETag").optional().saveAs("etag"),
                bodyString().saveAs("cartBody"));
    }

    private static HttpRequestActionBuilder order(String name) {
        return http(name)
            .post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":\"" + text(session.getString("cart")) + "\"}"))
            .check(jsonPath("$.accepted").is(true),
                status().is(201),
                jsonPath("$.id").optional().saveAs("orderId"),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar())
            .exec(login())
            .exec(http("catalog")
                .get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200), bodyString().saveAs("catalogBody")))
            .exec(session -> selectProduct(session))
            .exec(doIf(session -> session.contains("product") && session.contains("variant")).then(
                exec(cart())
                    .exec(session -> absorb(session, "cartBody"))
                    .exec(doIf(session -> session.contains("cart") && !session.contains("etag")).then(
                        exec(http("cart etag")
                            .get("/v2/carts/#{cart}")
                            .header("X-CSRF-Token", "#{csrf}")
                            .check(status().is(200), header("ETag").saveAs("etag")))))
                    .exec(doIf(session -> session.contains("cart") && session.contains("etag")).then(
                        exec(order("commit"))))));
    }

    public ModelSimulation() {
        setUp(scenario("decline")
            .exec(repeat(ITERATIONS).on(flow()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}
