  {"username": "bench-14", "password": "bench", "quantity": 15},
  {"username": "bench-15", "password": "bench", "quantity": 16},
  {"username": "bench-16", "password": "bench", "quantity": 17}
];

const failure = new Rate('business_failure');
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users || 2,
      iterations: cfg.iterations || 2,
      maxDuration: '30s'
    }
  },
  thresholds: {
    checks: ['rate==1']
  }
};

let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function resolve(path) {
  if (!path) return base;
  if (path.indexOf('http://') === 0 || path.indexOf('https://') === 0) return path;
  if (path.charAt(0) !== '/') path = '/' + path;
  return base + path;
}

function headerValue(r, name) {
  if (!r || !r.headers) return '';
  if (r.headers[name] !== undefined) return r.headers[name];
  const lower = name.toLowerCase();
  for (const k in r.headers) {
    if (k.toLowerCase() === lower) return r.headers[k];
  }
  return '';
}

function etagOf(r) {
  return headerValue(r, 'ETag');
}

function raw(path, method, data, extra) {
  method = method || 'GET';
  extra = extra || {};
  const headers = {'Content-Type': 'application/json'};
  if (csrf) headers['X-CSRF-Token'] = csrf;
  for (const k in extra) headers[k] = extra[k];

  const r = http.request(
    method,
    resolve(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    {
      headers: headers,
      redirects: 0,
      timeout: '3s'
    }
  );

  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;

  if (path === '/v2/work') {
    const expectedExpiry = r.status === 401 && b.error === 'expired';
    const scheduled429 = r.status === 429;
    failure.add(r.status >= 400 && !expectedExpiry && !scheduled429);
  }

  return r;
}

function inputValueFromBody(source, name) {
  if (!source) return '';
  let tagRe;
  if (name === 'csrf') {
    tagRe = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?[^>]*>/i;
  } else if (name === 'challenge') {
    tagRe = /<input\b[^>]*\bname\s*=\s*["']?challenge["']?[^>]*>/i;
  } else {
    return '';
  }
  const m = source.match(tagRe);
  if (!m) return '';
  const v = m[0].match(/\bvalue\s*=\s*["']?([^"'\s>]+)/i);
  return v ? v[1] : '';
}

function loginToken(r) {
  let token = '';
  try {
    token = r.html().find('input[name="csrf"]').first().attr('value') || '';
  } catch (_) {}
  if (!token) token = inputValueFromBody(r.body, 'csrf');
  return token;
}

function challengeActionFromBody(source) {
  if (!source) return '';
  const m = source.match(/<form\b[^>]*\baction\s*=\s*["']?([^"'\s>]*\/v2\/challenges\/[^"'\s>]*)[^>]*>/i);
  return m ? m[1] : '';
}

function challengeDetails(r) {
  let action = '';
  let token = '';
  try {
    const html = r.html();
    const form = html.find('form[action*="/v2/challenges/"]').first();
    action = form.attr('action') || '';
    token = form.find('input[name="challenge"]').first().attr('value') || '';
  } catch (_) {}
  if (!action) action = challengeActionFromBody(r.body);
  if (!token) token = inputValueFromBody(r.body, 'challenge');
  return {action: action, token: token};
}

function login() {
  let r = raw('/v2/login-form');
  const token = loginToken(r);
  check(r, {'login form': x => x.status === 200 && !!token});
  if (!token) return false;

  const row = rows[(__VU - 1) % rows.length] || rows[0];
  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
