    let r = request('/v2/challenge-form');
    const details = challengeDetails(r);
    check(r, {'challenge form': x => x.status === 200 && !!details.action && !!details.token});
    if (!details.action || !details.token) return;

    r = request(details.action, 'POST', {challenge: details.token});
    if (r.status === 302) {
      const loc = headerValue(r, 'Location');
      if (loc) r = request(loc);
    }

