import os
import re

from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'decline'}

USERS = int(CFG.get('users', 2))
ITERATIONS = int(CFG.get('iterations', 2))

USER_SEQ = 0
USER_LOCK = Semaphore()

DONE_COUNT = 0
DONE_LOCK = Semaphore()
DONE_EVENT = Event()


def _attr(tag, name):
    pattern = r'\b' + re.escape(name) + r'\s*=\s*(?:"([^"]*)"|' + r"'([^']*)'" + r'|([^\s>]+))'
    match = re.search(pattern, tag, re.I)
    if not match:
        return None
    for group in match.groups():
        if group is not None:
            return group
    return None


def find_input_value(html, name):
    fallback = None
    for tag in re.findall(r'<input\b[^>]*>', html or '', re.I | re.S):
        input_name = _attr(tag, 'name')
        if input_name is None or input_name.lower() != name.lower():
            continue
        value = _attr(tag, 'value')
        if value:
            return value
        if fallback is None:
            fallback = value or ''
    return fallback


class MatrixUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def wait_time(self):
        return 0

    def on_start(self):
        global USER_SEQ
        with USER_LOCK:
            USER_SEQ += 1
            number = USER_SEQ

        self.username = "bench-%d" % (((number - 1) % 16) + 1)
        self.password = "bench"
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.grant = ""
        self.iteration = 0

    def _headers(self, extra=None):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if extra:
            headers.update(extra)
        return headers

    @staticmethod
    def _body(response):
        try:
            return response.json()
        except Exception:
            return {}

    def raw(self, path, method="GET", data=None, headers=None, name=None,
            validate=None, allow_auth=True, allow_etag=True):
        request_headers = self._headers(headers)
        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            name=name or path,
            catch_response=True,
            allow_redirects=False,
            timeout=5,
        ) as response:
            body = self._body(response)
            error = body.get("error") if isinstance(body, dict) else None

            if response.status_code == 401 and error in ("expired", "session"):
                if allow_auth:
                    response.success()
                    if isinstance(body, dict) and body.get("csrf"):
                        self.csrf = body["csrf"]
                    return response, body
                response.failure("401 %s after retry" % error)
                return response, body

            if response.status_code == 401 and error == "denied":
                response.failure("401 denied")
                return response, body

            if response.status_code == 412 and error in ("etag", "etag_conflict", None):
                if isinstance(body, dict) and body.get("csrf"):
                    self.csrf = body["csrf"]
                if allow_etag:
                    response.success()
                    return response, body
                response.failure("412 etag conflict after retry")
                return response, body

            if response.status_code == 429 and path.split("?", 1)[0] == "/v2/work":
                response.success()
                return response, body

            ok = response.status_code < 400
            message = None

            if validate is not None:
                try:
                    ok, message = validate(response, body)
                except Exception as exc:
                    ok, message = False, "validation error: %s" % exc
            elif response.status_code >= 400:
                ok = False
                message = "unexpected status %s" % response.status_code

            if ok:
                response.success()
            else:
                response.failure(message or ("unexpected status %s" % response.status_code))

            if isinstance(body, dict) and body.get("csrf"):
                self.csrf = body["csrf"]

            return response, body

    def request(self, path, method="GET", data=None, headers=None, name=None,
                validate=None, allow_etag=True):
        response, body = self.raw(
            path,
            method,
            data,
            headers,
            name,
            validate=validate,
            allow_auth=True,
            allow_etag=allow_etag,
        )
        if response.status_code == 401 and body.get("error") in ("expired", "session"):
            self.recover()
            response, body = self.raw(
                path,
                method,
                data,
                headers,
                name,
                validate=validate,
                allow_auth=False,
                allow_etag=allow_etag,
            )
        return response, body

    def login(self):
        self.csrf = ""
        response, _ = self.raw("/v2/login-form", "GET", name="login-form")
        if response.status_code != 200:
            return False

        token = find_input_value(response.text, "csrf")
        if not token:
            return False

        response, body = self.raw(
            "/v2/login",
            "POST",
            {"username": self.username, "password": self.password, "csrf": token},
            name="login",
        )

        if response.status_code == 302:
            location = response.headers.get("Location")
            if location:
                response, body = self.raw(location, "GET", name="login-redirect")

        if isinstance(body, dict) and body.get("csrf"):
            self.csrf = body["csrf"]

        return True

    def recover(self):
        renewed, _ = self.raw("/v2/session/renew", "POST", {}, name="renew")
        if renewed.status_code != 200:
            self.client.cookies.clear()
            self.login()

        if self.cart:
            recovered, _ = self.raw(
                "/v2/carts/%s/recover" % self.cart,
                "POST",
                {},
                name="recover",
            )
            if recovered.status_code < 400:
                self.etag = recovered.headers.get("ETag", self.etag)

    def get_product(self):
        page = "/v2/catalog"
        for _ in range(3):
            response, body = self.request(page, "GET", name="catalog")
            if response.status_code >= 400:
                return None

            data = body.get("data", {}) if isinstance(body, dict) else {}
            for product in data.get("products", []) or []:
                for variant in product.get("variants", []) or []:
                    if variant.get("in_stock"):
                        return product, variant

            next_page = body.get("next") if isinstance(body, dict) else None
            if not next_page:
                break
            page = next_page

        return None

    def order(self):
        if not self.cart:
            return

        payload = {"cart_id": self.cart}
        headers = {"Idempotency-Key": self.cart}
        if self.etag:
            headers["If-Match"] = self.etag

        def validate_order(resp, body):
            if resp.status_code >= 400:
                return False, "order status %s" % resp.status_code
            if isinstance(body, dict) and body.get("accepted") is True:
                return True, None
            if isinstance(body, dict) and body.get("accepted") is False:
                return False, "business decline: accepted=false"
            return False, "order response missing accepted boolean"

        response, _ = self.request(
            "/v2/orders",
            "POST",
            payload,
            headers,
            name="checkout",
            validate=validate_order,
            allow_etag=True,
        )

        if response.status_code == 412:
            cart_response, _ = self.request(
                "/v2/carts/%s" % self.cart,
                "GET",
                name="cart",
            )
            self.etag = cart_response.headers.get("ETag", self.etag)
            headers["If-Match"] = self.etag
            self.request(
                "/v2/orders",
                "POST",
                payload,
                headers,
                name="checkout",
                validate=validate_order,
                allow_etag=False,
            )

    def flow(self):
        self.client.cookies.clear()
        self.cart = ""
        self.etag = ""
        self.grant = ""

        if not self.login():
            return

        found = self.get_product()
        if not found:
            return

        product, variant = found
        cart_data = {
            "product_id": product.get("id"),
            "variant_id": variant.get("id"),
        }
        if self.grant:
            cart_data["grant_id"] = self.grant

        def validate_cart(resp, body):
            if resp.status_code in (200, 201) and isinstance(body, dict) and body.get("id"):
                return True, None
            return False, "cart missing id"

        response, body = self.request(
            "/v2/carts",
            "POST",
            cart_data,
            name="cart",
            validate=validate_cart,
            allow_etag=False,
        )
        if response.status_code not in (200, 201):
            return

        self.cart = body.get("id", "") if isinstance(body, dict) else ""
        self.etag = response.headers.get("ETag", "")
        if not self.cart:
            return

        self.order()

    @task
    def run_scenario(self):
        global DONE_COUNT

        try:
            self.flow()
        except Exception:
            pass
        finally:
            self.iteration += 1
            if self.iteration >= ITERATIONS:
                with DONE_LOCK:
                    DONE_COUNT += 1
                    if DONE_COUNT >= USERS:
                        DONE_EVENT.set()
                DONE_EVENT.wait(timeout=30)
                raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.peak = 0

    def tick(self):
        if self.get_run_time() > 120:
            return None

        count = self.runner.user_count if self.runner else 0
        if count > self.peak:
            self.peak = count

        if self.peak >= USERS and count == 0:
            return None
        if self.peak >= USERS:
            return count, 1
        return USERS, USERS
