let csrf = '';
let cart = '';
let grant = '';
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function header(r, name) {
  const h = r.headers || {};
  const lower = name.toLowerCase();
  for (const k in h) {
    if (k.toLowerCase() === lower) return h[k];
  }
  return undefined;
}

function absolute(path) {
  if (!path) return base;
  if (/^https?:\/\//i.test(path)) return path;
  if (path.charAt(0) === '/') return base + path;
  return base + '/' + path;
}

function raw(path, method, data, headers, tags) {
  method = method || 'GET';
  headers = headers || {};
  tags = tags || {};

  const h = Object.assign({}, headers);
  if (method !== 'GET' && csrf) h['X-CSRF-Token'] = csrf;
  if (data !== null && data !== undefined) {
    h['Content-Type'] = h['Content-Type'] || 'application/json';
  }

  const t = Object.assign({name: path}, tags);
  const r = http.request(
    method,
    absolute(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    {
      headers: h,
      tags: t,
      redirects: 0,
      timeout: '10s'
    }
  );

  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;
  return r;
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value') || '';
  const row = rows[(__VU - 1) % rows.length];

  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
  });

  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (loc) r = raw(loc);
  }

  check(r, {'login': function (x) { return x.status === 200; }});
}

function request(path, method, data, headers, tags) {
  method = method || 'GET';
  headers = headers || {};
  tags = tags || {};

  let r = raw(path, method, data, headers, tags);

  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      let renewed = null;
      if (csrf) renewed = raw('/v2/session/renew', 'POST', {});
      if (!renewed || renewed.status !== 200) login();
      if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
      r = raw(path, method, data, headers, tags);
    }
  }

  return r;
}

function findProduct() {
  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';

  for (let n = 0; n < 3 && page; n++) {
    const r = request(page);
    const b = body(r);
    const products = (b.data && b.data.products) || [];

    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      const variants = p.variants || [];
      for (let j = 0; j < variants.length; j++) {
        if (variants[j].in_stock) {
          return {product_id: p.id, variant_id: variants[j].id};
        }
      }
    }

    page = b.next ? absolute(b.next) : null;
  }

  return null;
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  login();

  const item = findProduct();
  if (!item) {
    check(null, {'eligible product': function () { return false; }});
    return;
  }

  const cartPayload = {
    product_id: item.product_id,
    variant_id: item.variant_id
  };
  if (grant) cartPayload.grant_id = grant;

  let r = request('/v2/carts', 'POST', cartPayload);
  check(r, {'cart': function (x) { return x.status === 201; }});

  const cb = body(r);
  cart = cb.id || '';
  let etag = header(r, 'ETag');
  if (!cart) return;

  const orderPayload = {cart_id: cart};
  const orderHeaders = {'Idempotency-Key': cart};
  if (etag) orderHeaders['If-Match'] = etag;

  r = request('/v2/orders', 'POST', orderPayload, orderHeaders, {name: 'checkout'});

  if (r.status === 412) {
    r = request('/v2/carts/' + cart);
    const fresh = header(r, 'ETag');
    if (fresh) orderHeaders['If-Match'] = fresh;
    r = request('/v2/orders', 'POST', orderPayload, orderHeaders, {name: 'checkout'});
  }

  check(r, {'accepted': function (x) {
    return x.status === 201 && body(x).accepted === true;
  }});
}

export default function () {
  flow();
}
