import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final double TARGET_RATE = 5.0;
    private static final double PEAK_RATE = TARGET_RATE * 3.0;
    private static final int WARMUP_SECONDS = 5;
    private static final int PLATEAU_SECONDS = 10;
    private static final int MAX_RETRIES = 4;

    private static final Pattern INPUT_TAG =
        Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern NAME_CSRF =
        Pattern.compile("(?is)\\sname\\s*=\\s*(?:\"\\s*csrf\\s*\"|'\\s*csrf\\s*'|csrf(?=[\\s/>]))");
    private static final Pattern VALUE_ATTR =
        Pattern.compile("(?is)\\svalue\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String extractCsrf(String html) {
        if (html == null) {
            return null;
        }
        Matcher tags = INPUT_TAG.matcher(html);
        while (tags.find()) {
            String tag = tags.group();
            if (!NAME_CSRF.matcher(tag).find()) {
                continue;
            }
            Matcher value = VALUE_ATTR.matcher(tag);
            if (!value.find()) {
                continue;
            }
            String token = value.group(1) != null ? value.group(1)
                : value.group(2) != null ? value.group(2) : value.group(3);
            if (token != null && !token.trim().isEmpty()) {
                return token.trim();
            }
        }
        return null;
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "").set("formCsrf", "").remove("location"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> {
                String token = extractCsrf(session.getString("loginHtml"));
                return token == null ? session.markAsFailed() : session.set("formCsrf", token);
            })
            .exec(doIf(session -> !session.getString("formCsrf").isEmpty()).then(
                exec(http("login").post("/v2/login")
                    .disableFollowRedirect()
                    .header("Content-Type", "application/json")
                    .body(StringBody(session -> "{\"username\":\"" + username(session)
                        + "\",\"password\":\"bench\",\"csrf\":\""
                        + session.getString("formCsrf") + "\"}"))
                    .check(status().in(200, 302),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        header("Location").optional().saveAs("location")))
                .exec(doIf(session -> session.contains("location")
                        && session.getString("location") != null).then(
                    exec(http("login redirect").get("#{location}")
                        .check(status().is(200),
                            jsonPath("$.csrf").optional().saveAs("csrf")))))));
    }

    private static Duration retryDelay(Session session) {
        String raw = session.contains("retryAfter") ? session.getString("retryAfter") : null;
        if (raw == null || raw.trim().isEmpty()) {
            return Duration.ofMillis(1000);
        }
        String value = raw.trim().toLowerCase();
        if (value.endsWith("s")) {
            value = value.substring(0, value.length() - 1).trim();
        }
        try {
            double seconds = Double.parseDouble(value);
            if (Double.isNaN(seconds) || seconds < 0) {
                seconds = 1;
            }
            return Duration.ofMillis((long) Math.ceil(seconds * 1000) + 20);
        } catch (NumberFormatException error) {
            return Duration.ofMillis(1000);
        }
    }

    private static ChainBuilder workCall(String name) {
        return exec(session -> session.set("workStatus", 0).set("workOk", "")
                .set("workError", "").remove("retryAfter"))
            .exec(http(name).post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401, 429),
                    status().saveAs("workStatus"),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    jsonPath("$.ok").optional().saveAs("workOk"),
                    jsonPath("$.error").optional().saveAs("workError"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> {
                int status = session.getInt("workStatus");
                if (status == 200 && !"true".equals(session.getString("workOk"))) {
                    return session.markAsFailed();
                }
                if (status == 401 && "denied".equals(session.getString("workError"))) {
                    return session.markAsFailed();
                }
                return session;
            });
    }

    private static ChainBuilder renewSession() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 401),
                status().saveAs("renewStatus"),
                jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("renewStatus") != 200).then(login()));
    }

    private static ChainBuilder workOperation() {
        ChainBuilder chain = exec(session -> session.set("renewed", false))
            .exec(workCall("work"));
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            final int current = attempt;
            chain = chain
                .exec(doIf(session -> session.getInt("workStatus") == 401
                        && !"denied".equals(session.getString("workError"))
                        && !session.getBoolean("renewed")).then(
                    renewSession()
                        .exec(session -> session.set("renewed", true))
                        .exec(workCall("work renew retry " + current))))
                .exec(doIf(session -> session.getInt("workStatus") == 429).then(
                    pause(session -> retryDelay(session))
                        .exec(workCall("work 429 retry " + current))));
        }
        return chain;
    }

    public ModelSimulation() {
        ScenarioBuilder journey = scenario("workload")
            .exec(flushCookieJar())
            .exec(login())
            .exec(workOperation());

        setUp(journey.injectOpen(
            constantUsersPerSec(TARGET_RATE)
                .during(Duration.ofSeconds(WARMUP_SECONDS + PLATEAU_SECONDS)),
            constantUsersPerSec(PEAK_RATE)
                .during(Duration.ofSeconds(PLATEAU_SECONDS)),
            constantUsersPerSec(TARGET_RATE)
                .during(Duration.ofSeconds(PLATEAU_SECONDS + 1))
        ).protocols(HTTP));
    }
}
