}

function extractInputValue(html, name) {
  if (!html) return '';
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    const attrs = {};
    const attrRe = /([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g;
