import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final String CONFIG_JSON = "{\"users\": 2, \"iterations\": 2, \"mode\": \"partition\"}";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = readConfig();
    private static final JsonNode ACCOUNTS = readAccounts();
    private static final String MODE = CFG.path("mode").asText("flow");
    private static final int USERS = CFG.path("users").asInt(2);
    private static final int ITERATIONS = CFG.path("iterations").asInt(2);
    private static final HttpProtocolBuilder HTTP = http.baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp().acceptHeader("application/json");

    private static JsonNode readConfig() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static JsonNode readAccounts() {
        try {
            return JSON.readTree(Files.readString(Path.of("/fixtures/accounts.json")));
        } catch (IOException | RuntimeException error) {
            return JSON.createObjectNode();
        }
    }

    private static JsonNode parseJson(String value) {
        if (value == null || value.trim().isEmpty()) return JSON.createObjectNode();
        try {
            return JSON.readTree(value);
        } catch (IOException | RuntimeException error) {
            return JSON.createObjectNode();
        }
    }

    private static String attrValue(String tag, String attr) {
        Pattern pattern = Pattern.compile(
            "(?i)\\b" + Pattern.quote(attr) + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");
        Matcher matcher = pattern.matcher(tag);
        if (matcher.find()) {
            if (matcher.group(1) != null) return matcher.group(1);
            if (matcher.group(2) != null) return matcher.group(2);
            if (matcher.group(3) != null) return matcher.group(3);
        }
        return null;
    }

    private static String findInputValue(String html, String inputName) {
        if (html == null) return null;
        Matcher tag = Pattern.compile("(?is)<input\\b[^>]*>").matcher(html);
        while (tag.find()) {
            String name = attrValue(tag.group(), "name");
            if (name != null && name.equalsIgnoreCase(inputName)) {
                return attrValue(tag.group(), "value");
            }
        }
        return null;
    }

    private static String jsonEscape(String value) {
        if (value == null) return "";
        StringBuilder out = new StringBuilder(value.length() + 8);
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            switch (ch) {
                case '"': out.append("\\\""); break;
                case '\\': out.append("\\\\"); break;
                case '\n': out.append("\\n"); break;
                case '\r': out.append("\\r"); break;
                case '\t': out.append("\\t"); break;
                default: out.append(ch);
            }
        }
        return out.toString();
    }

    private static JsonNode row(Session session) {
        int index = session.userId() - 1;
        if (MODE.equals("partition") || MODE.equals("data")) {
            if (ACCOUNTS.isArray() && index >= 0 && index < ACCOUNTS.size()) {
                return ACCOUNTS.get(index);
            }
        } else if (ACCOUNTS.isArray() && ACCOUNTS.size() > 0) {
            return ACCOUNTS.get(0);
        }
        return JSON.createObjectNode()
            .put("username", "bench-" + ((index % 16) + 1))
            .put("password", "bench")
            .put("quantity", 2)
            .put("delay", 0);
    }

    private static String username(Session session) {
        if (MODE.equals("ownership")) return "bench";
        if (MODE.equals("data") || MODE.equals("partition")) {
            return row(session).path("username").asText();
        }
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String password(Session session) {
        return MODE.equals("data") || MODE.equals("partition")
            ? row(session).path("password").asText("bench") : "bench";
    }

    private static int quantity(Session session) {
        return MODE.equals("data")
            ? row(session).path("quantity").asInt(2)
            : CFG.path("quantity").asInt(2);
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "").set("grant", "")
                .remove("location")
                .remove("loginStatus")
                .remove("loginBody")
                .remove("loginHtml")
                .remove("redirectBody")
                .remove("redirectLocation")
                .remove("product").remove("variant").remove("nextPage").remove("cart").remove("etag")
                .remove("pollUrl").remove("reservation").remove("jobState").remove("patchStatus")
                .remove("catalogStatus").remove("challengeHtml").remove("challengeAction")
                .remove("challengeToken"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> {
                String csrf = findInputValue(session.getString("loginHtml"), "csrf");
                return session.set("formCsrf", csrf == null ? "" : csrf);
            })
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + jsonEscape(username(session))
                    + "\",\"password\":\"" + jsonEscape(password(session))
                    + "\",\"csrf\":\"" + jsonEscape(session.getString("formCsrf")) + "\"}"))
                .check(status().in(200, 302), status().saveAs("loginStatus"),
                    header("Location").optional().saveAs("location"),
