            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> {
                    String grant = session.getString("grant");
                    return "{\"product_id\":\"" + jsonEscape(session.getString("product"))
                        + "\",\"variant_id\":\"" + jsonEscape(session.getString("variant")) + "\""
