                        .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                        .header("If-Match", "#{etag}")
                        .body(StringBody(session -> "{\"quantity\":" + quantity(session) + "}"))
                        .check(status().is(200), header("ETag").optional().saveAs("etag"),
