                .exec(http("reservation poll").get("#{pollUrl}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.status").saveAs("jobState"),
                        jsonPath("$.reservation_id").optional().saveAs("reservation"),
