function getHeader(r, name) {
  if (!r || !r.headers) return '';
  const target = name.toLowerCase();
  for (const k in r.headers) {
    if (k.toLowerCase() === target) return r.headers[k];
  }
  return '';
}

function url(path) {
  if (!path) return base;
  const s = String(path);
  if (s.indexOf('http://') === 0 || s.indexOf('https://') === 0) return s;
  const root = base.replace(/\/+$/, '');
  return s.charAt(0) === '/' ? root + s : root + '/' + s;
}

function raw(path, method, data, extra) {
  method = method || 'GET';
  extra = extra || {};
  const headers = {'Content-Type': 'application/json'};
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;
  Object.assign(headers, extra);

  const r = http.request(
    method,
    url(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    {headers: headers, redirects: 0, timeout: '5s'}
