    const ok = r.status === 200 && b.ok === true;
    const expectedExpiry = r.status === 401 && b.error === 'expired';
    const scheduled = r.status === 429;
    const unexpected = !ok && !expectedExpiry && !scheduled;
    failure.add(unexpected);
