  let m = /<input\b[^>]*\bname=["']?csrf["']?[^>]*\bvalue=["']([^"']+)["']/i.exec(html);
  if (m) return m[1];
  m = /<input\b[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']?csrf["']?/i.exec(html);
  if (m) return m[1];
  m = /<input\b[^>]*\bname=["']?csrf["']?[^>]*\bvalue=([^\s>]+)/i.exec(html);
  return cleanAttr(m ? m[1] : '');
}

