  let m = /<input\b[^>]*\bname=["']?challenge["']?[^>]*\bvalue=["']([^"']+)["']/i.exec(html);
  if (m) return m[1];
  m = /<input\b[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']?challenge["']?/i.exec(html);
  if (m) return m[1];
  m = /<input\b[^>]*\bname=["']?challenge["']?[^>]*\bvalue=([^\s>]+)/i.exec(html);
