                    jsonPath("$.next").optional().saveAs("nextPage")))
            .exec(doIf(session -> session.contains("catalogStatus") && session.getInt("catalogStatus") == 401).then(
                recoverSession()
                    .exec(http("catalog retry")
                        .get("/v2/catalog")
                        .header("X-CSRF-Token", "#{csrf}")
                        .check(status().is(200),
                            bodyString().saveAs("catalogBody")))))
            .exec(session -> selectProduct(session));
    }

