        String grant = session.contains("grant") ? session.getString("grant") : "";
        return "{\"product_id\":\"" + session.getString("product")
            + "\",\"variant_id\":\"" + session.getString("variant") + "\""
            + (grant == null || grant.isEmpty() ? "" : ",\"grant_id\":\"" + grant + "\"")
            + "}";
    }

    private static ChainBuilder createCart() {
        return exec(http("cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> cartPayload(session)))
                .check(status().saveAs("cartStatus"),
                    status().in(201, 401),
                    jsonPath("$.id").optional().saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    bodyString().validate("not denied", (body, session) -> {
                        if (body != null && body.matches("(?s).*\"error\"\\s*:\\s*\"denied\".*")) return "denied";
                        return null;
                    })))
            .exec(doIf(session -> session.contains("cartStatus") && session.getInt("cartStatus") == 401).then(
                recoverSession()
                    .exec(http("cart retry")
                        .post("/v2/carts")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody(session -> cartPayload(session)))
                        .check(status().is(201),
                            jsonPath("$.id").saveAs("cart"),
                            header("ETag").saveAs("etag"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder orderRequest(String name) {
        return exec(http(name)
            .post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
            .check(status().saveAs("orderStatus"),
                status().in(201, 401, 412),
                bodyString().saveAs("orderBody"),
                bodyString().validate("order validation", (body, session) -> {
                    if (body != null && body.matches("(?s).*\"error\"\\s*:\\s*\"denied\".*")) return "denied";
                    if (session.contains("orderStatus") && session.getInt("orderStatus") == 201) {
                        try {
                            JsonNode node = JSON.readTree(body);
                            if (!node.path("accepted").asBoolean(false)) return "accepted false";
                        } catch (Exception e) {
                            return "invalid body";
                        }
                    }
                    return null;
                }),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder commitOrder() {
        ChainBuilder chain = orderRequest("commit");
        chain = chain.exec(doIf(session -> session.contains("orderStatus") && session.getInt("orderStatus") == 401).then(
            recoverSession().exec(orderRequest("commit expiry retry"))));
        chain = chain.exec(doIf(session -> session.contains("orderStatus") && session.getInt("orderStatus") == 412).then(
            exec(http("cart etag refresh")
                .get("/v2/carts/#{cart}")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(orderRequest("commit etag retry"))));
        return chain;
    }

    private static Duration retryDelay(Session session) {
        try {
            String value = session.getString("retryAfter");
            if (value == null || value.isEmpty()) return Duration.ofMillis(1000);
            return Duration.ofMillis(Math.max(10, (long) (Double.parseDouble(value) * 1000 + 10)));
        } catch (Exception e) {
            return Duration.ofMillis(1000);
        }
    }

    private static ChainBuilder workOnce(String name) {
        return exec(http(name)
            .post("/v2/work")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().saveAs("workStatus"),
                status().in(200, 401, 429),
                bodyString().saveAs("workBody"),
                bodyString().validate("not denied", (body, session) -> {
                    if (body != null && body.matches("(?s).*\"error\"\\s*:\\s*\"denied\".*")) return "denied";
                    return null;
                }),
                header("Retry-After").optional().saveAs("retryAfter")));
    }

    private static ChainBuilder work() {
        ChainBuilder chain = workOnce("work");
        chain = chain.exec(doIf(session -> session.contains("workStatus") && session.getInt("workStatus") == 401).then(
            recoverSession().exec(workOnce("work expiry retry"))));
        for (int i = 0; i < 4; i++) {
            chain = chain.exec(doIf(session -> session.contains("workStatus") && session.getInt("workStatus") == 429).then(
                pause(session -> retryDelay(session)).exec(workOnce("work scheduled retry"))));
        }
        return chain;
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session
                .remove("product").remove("variant").remove("cart").remove("etag")
                .remove("catalogStatus").remove("catalogBody").remove("nextPage")
                .remove("cartStatus").remove("orderStatus").remove("renewStatus")
                .remove("workStatus").remove("workBody").remove("retryAfter")
                .remove("location").remove("grant").remove("csrf").remove("formCsrf"))
            .exec(login())
            .exec(repeat(4).on(work()))
            .exec(catalog())
            .exec(createCart())
            .exec(commitOrder());
    }

    public ModelSimulation() {
        setUp(scenario("matrix")
            .exec(repeat(ITERATIONS).on(journey()))
            .injectOpen(atOnceUsers(USERS)))
            .protocols(HTTP);
    }
}
