    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '60s',
    },
  },
  thresholds: thresholds,
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try {
    const b = r.json();
    return b === null ? {} : b;
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  if (!r || !r.headers) return null;
  const low = String(name).toLowerCase();
  for (const k in r.headers) {
    if (String(k).toLowerCase() === low) return r.headers[k];
  }
  return null;
}

function url(path) {
  if (!path) return base;
  if (/^https?:\/\//i.test(path)) return path;
  if (path.charAt(0) === '/') return base + path;
  return base + '/' + path;
}

function isWorkPath(path) {
  if (!path) return false;
  let p = String(path).split('?')[0].split('#')[0];
  if (p.charAt(p.length - 1) === '/') p = p.substring(0, p.length - 1);
  return /(^|\/)v2\/work$/.test(p);
}

function unexpectedWork(r, b) {
  if (r.status === 200 && b && b.ok === true) return false;
  if (r.status === 429) return false;
  if (r.status === 401 && b && b.error === 'expired') return false;
  return true;
}

function raw(path, method, data, extra) {
  method = method || 'GET';
  if (data === undefined) data = null;
  extra = extra || {};

  const headers = {};
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;
  for (const k in extra) headers[k] = extra[k];

  const r = http.request(method, url(path), data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s',
  });

  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;
  if (isWorkPath(path)) failure.add(unexpectedWork(r, b));
  return r;
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z0-9_:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g;
  let m;
  while ((m = re.exec(tag))) {
    attrs[m[1].toLowerCase()] = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : m[4]);
  }
  return attrs;
}

function hasInputNamed(html, names) {
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html))) {
    const attrs = parseAttrs(m[0]);
    if (attrs.name && names.indexOf(String(attrs.name).toLowerCase()) !== -1) return true;
  }
  return false;
}

function extractInputValue(html, name) {
  if (!html) return null;
  const low = String(name).toLowerCase();
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html))) {
    const attrs = parseAttrs(m[0]);
    if (attrs.name && String(attrs.name).toLowerCase() === low) {
      if (attrs.value !== undefined) return attrs.value;
    }
  }
  return null;
}

function loginCsrf(html) {
  if (!html) return null;
  const formRe = /<form\b[^>]*>([\s\S]*?)<\/form>/gi;
  let m;
  while ((m = formRe.exec(html))) {
    const content = m[1];
    if (hasInputNamed(content, ['username', 'password'])) {
      const v = extractInputValue(content, 'csrf');
      if (v !== null) return v;
    }
  }
  return extractInputValue(html, 'csrf');
}

function extractFormAction(html) {
  if (!html) return null;
  const re = /<form\b[^>]*>/gi;
  let m;
  let first = null;
  while ((m = re.exec(html))) {
    const attrs = parseAttrs(m[0]);
    if (attrs.action) {
      if (!first) first = attrs.action;
      if (String(attrs.action).indexOf('/v2/challenges/') !== -1) return attrs.action;
    }
  }
  return first;
}

function inputValue(r, name) {
  let v = extractInputValue(r.body, name);
  if (v !== null) return v;
  try {
    const sel = r.html().find('input[name="' + name + '"]').first();
    if (sel) return sel.attr('value');
  } catch (_) {}
  return null;
}

function formAction(r) {
  let a = extractFormAction(r.body);
  if (a) return a;
  try {
    const sel = r.html().find('form').first();
    if (sel) return sel.attr('action');
  } catch (_) {}
  return null;
}

function login() {
  csrf = '';
  try {
    http.cookieJar().clear(base);
  } catch (_) {}

  let r = raw('/v2/login-form', 'GET');
  const token = loginCsrf(r.body);
  const row = rows[(__VU - 1) % rows.length];

  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token,
  });

  if (r.status === 302 || r.status === 303 || r.status === 307 || r.status === 308) {
    const loc = header(r, 'Location');
    if (loc) r = raw(loc, 'GET');
  }

  const b = body(r);
  if (!csrf && b && b.csrf) csrf = b.csrf;

  check(r, {
    'login succeeds': (resp) => resp.status === 200 && !!body(resp).csrf,
  });
  return r;
}

function request(path, method, data, extra) {
  method = method || 'GET';
  if (data === undefined) data = null;
  extra = extra || {};

  let r = raw(path, method, data, extra);

  if (r.status === 401) {
    const b = body(r);
    const err = b && b.error;

    if (err === 'expired' || err === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});

      if (renewed.status !== 200 || err === 'session') {
        login();
      }

      if (cart) {
        raw('/v2/carts/' + cart + '/recover', 'POST', {});
      }

      r = raw(path, method, data, extra);
    }
  }

  return r;
}

function work(override) {
  if (!csrf) login();

  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});
  let retries = 0;

  while (r.status === 429 && retries < 4) {
    check(r, {
      '429 has Retry-After': (resp) => !!header(resp, 'Retry-After'),
    });

    const ra = header(r, 'Retry-After');
    let wait = ra ? parseFloat(ra) : 1;
    if (isNaN(wait) || wait < 1) wait = 1;

    sleep(wait + 0.01);
    r = request(path, 'POST', {});
    retries++;
  }

  check(r, {
    'operation succeeds': (resp) => resp.status === 200 && body(resp).ok === true,
  });
  return r;
}

function fetchProduct() {
  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const r = request(page, 'GET');
    const b = body(r);
    let products = [];

    if (b) {
      if (b.data) {
        if (Array.isArray(b.data.products) && b.data.products.length) {
          products = b.data.products;
        } else if (b.data.product) {
          products = [b.data.product];
        } else if (Array.isArray(b.data)) {
          products = b.data;
        }
      }
      if (!products.length && b.product) products = [b.product];
      if (!products.length && Array.isArray(b.products)) products = b.products;
    }

    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      if (p && Array.isArray(p.variants) && p.variants.some((v) => v && v.in_stock)) {
        product = p;
        break;
      }
    }

    if (product) break;

    let next = b ? b.next : null;
    if ((next === undefined || next === null) && b && b.data) next = b.data.next;
    if (!next) break;
    page = next;
  }

  return product;
}

function updateCart(quantity, initialEtag) {
  let etag = initialEtag;

  if (!etag) {
    const rr = request('/v2/carts/' + cart, 'GET');
    etag = header(rr, 'ETag');
  }

  const extra1 = {};
  if (etag) extra1['If-Match'] = etag;

  let r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, extra1);

  if (r.status === 412) {
    const rr = request('/v2/carts/' + cart, 'GET');
    etag = header(rr, 'ETag');

    const extra2 = {};
    if (etag) extra2['If-Match'] = etag;

    r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, extra2);
  }

  etag = header(r, 'ETag') || etag;

  check(r, {
    'cart updated': (resp) => resp.status === 200,
  });
  return etag;
}

function reserve() {
  let r = request('/v2/reservations', 'POST', { cart_id: cart });
  const b0 = body(r);

  check(r, {
    'reservation started': (resp) => resp.status === 202 && !!body(resp).status_url,
  });

  const statusUrl = b0.status_url;
  if (!statusUrl) return null;

  for (let n = 0; n < 5; n++) {
    sleep(0.05);
    r = request(statusUrl, 'GET');
    const b = body(r);

    if (b && b.status === 'ready') {
      check(r, {
        'reservation ready': (resp) => resp.status === 200 && !!body(resp).reservation_id,
      });
      return b.reservation_id;
    }

    if (b && b.status === 'failed') {
      check(false, { 'reservation ready': (v) => v });
      return null;
    }
  }

  check(false, { 'reservation ready': (v) => v });
  return null;
}

function placeOrder(etag, reservation) {
  const payload = { cart_id: cart };
  if (reservation) payload.reservation_id = reservation;

  const extra = { 'Idempotency-Key': cart };
  if (etag) extra['If-Match'] = etag;

  const r = request('/v2/orders', 'POST', payload, extra);

  check(r, {
    'order accepted': (resp) => resp.status === 201 && body(resp).accepted === true,
  });
  return r;
}

function solveChallenge() {
  let r = request('/v2/challenge-form', 'GET');
  const action = formAction(r);
  const token = inputValue(r, 'challenge');

  check(r, {
    'challenge form loaded': (resp) => resp.status === 200 && !!action && !!token,
  });
  if (!action || !token) return null;

  r = request(action, 'POST', { challenge: token });

  if (r.status === 302 || r.status === 303 || r.status === 307 || r.status === 308) {
    const loc = header(r, 'Location');
    if (loc) r = request(loc, 'GET');
  }

  const b = body(r);
  grant = b && b.grant_id ? b.grant_id : null;

  check(r, {
    'challenge solved': (resp) => resp.status === 200 && !!body(resp).grant_id,
  });
  return grant;
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  login();

  if (cfg.mode === 'challenge') {
    const g = solveChallenge();
    if (!g) return;
  }

  const product = fetchProduct();
  check(product, {
    'eligible product found': (p) => !!p,
  });
  if (!product) return;

  const variant = product.variants.find((v) => v && v.in_stock);
  check(variant, {
    'eligible variant found': (v) => !!v,
  });
  if (!variant) return;

  const payload = {
    product_id: product.id,
    variant_id: variant.id,
  };
  if (grant) payload.grant_id = grant;

  let r = request('/v2/carts', 'POST', payload);
  cart = body(r).id;
  let etag = header(r, 'ETag');

  check(r, {
    'cart created': (resp) => resp.status === 201 && !!body(resp).id,
  });
  if (!cart) return;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    let quantity = cfg.mode === 'data'
      ? rows[(__VU - 1) % rows.length].quantity
      : (cfg.quantity || 2);
    quantity = Math.max(1, Math.min(20, Math.floor(Number(quantity) || 1)));
    etag = updateCart(quantity, etag);
  }

  if (!etag) {
    const rr = request('/v2/carts/' + cart, 'GET');
    etag = header(rr, 'ETag');
  }

  let reservation = null;
  if (cfg.mode === 'reservation') {
    reservation = reserve();
    if (!reservation) return;
  }

  placeOrder(etag, reservation);

  if (cfg.mode === 'threshold') {
    raw('/v2/health', 'GET');
  }
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    csrf = '';
    cart = '';
    grant = '';
    login();
    for (let n = 0; n < 4; n++) work();
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}
