def _attr(tag, name):
    pattern = r'(?:^|\s)' + re.escape(name) + r'''\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))'''
    match = re.search(pattern, tag, re.IGNORECASE | re.DOTALL)
    if not match:
        return None
    for value in match.groups():
        if value is not None:
            return value
    return None


def _input_value(html, name):
    for tag in _INPUT_RE.findall(html or ''):
        if (_attr(tag, 'name') or '').lower() == name.lower():
            value = _attr(tag, 'value')
            if value is not None:
                return value
    return None


def _form_action(html, prefer=None):
    fallback = None
    for tag in _FORM_RE.findall(html or ''):
        action = _attr(tag, 'action')
        if not action:
            continue
        if prefer and prefer in action:
            return action
        if fallback is None:
            fallback = action
    return fallback


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get('operation') == 'journey' else 0)
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [(self.slot(pool, self.counts[pool['name']]), pool)
                         for pool in POOLS]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
            if not scheduled:
                return None
            slot, pool = min(scheduled, key=lambda item: item[0])
            self.counts[pool['name']] += 1
            deadline = self.started + slot
        sleep(max(0, deadline - time.monotonic()))
        return pool


