        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True, allow_redirects=False,
                                 timeout=3) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            clean_path = path.split('?', 1)[0]
            expected = False
            if response.status_code < 400:
                expected = True
            elif response.status_code == 401 and body.get('error') in ('expired', 'session'):
                expected = recoverable_401
            elif (response.status_code == 412 and method == 'PATCH'
                  and clean_path.startswith('/v2/carts/')):
                expected = recoverable_412
            elif (response.status_code == 429 and expected_429
                  and (clean_path in ('/v2/work', '/v2/browse')
                       or clean_path.endswith('/v2/work')
                       or clean_path.endswith('/v2/browse'))):
