        Matcher m = inputPattern.matcher(html);

        while (m.find()) {
            String tag = m.group();
            if (tag.matches("(?is).*\\bname\\s*=\\s*[\"']?csrf[\"']?.*")) {
                Matcher quotedValue = Pattern
                        .compile("(?is)\\bvalue\\s*=\\s*([\"'])(.*?)\\1")
                        .matcher(tag);
                if (quotedValue.find()) {
                    return quotedValue.group(2);
                }

                Matcher unquotedValue = Pattern
                        .compile("(?is)\\bvalue\\s*=\\s*([^\\s>]+)")
                        .matcher(tag);
                if (unquotedValue.find()) {
                    return unquotedValue.group(1).replaceAll("^[\"']|[\"']$", "");
                }
            }
        }

        return null;
    }
}
