import http from 'k6/http';
import { sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const businessFailure = new Rate('business_failure');

export const options = {
  setupTimeout: '10s',
  gracefulStop: '5s',
  scenarios: {
    work: {
      executor: 'ramping-arrival-rate',
      exec: 'work',
      startTime: '0s',
      startRate: 5,
      timeUnit: '1s',
      preAllocatedVUs: 5,
      maxVUs: 32,
      stages: [
        { target: 5, duration: '5s' },
        { target: 5, duration: '10s' },
        { target: 15, duration: '1ms' },
        { target: 15, duration: '10s' },
        { target: 5, duration: '1ms' },
        { target: 5, duration: '10s' },
      ],
    },
  },
};

function resolveUrl(loc) {
  if (!loc) return BASE_URL;
  if (loc.indexOf('http://') === 0 || loc.indexOf('https://') === 0) return loc;
  if (loc.charAt(0) === '/') return BASE_URL + loc;
  return BASE_URL + '/' + loc;
}

function getAttr(tag, attr) {
  const re = new RegExp('(?:^|\\s)' + attr + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(re);
  if (!m) return '';
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  return m[3] || '';
}

function extractCsrf(body) {
  if (!body) return '';
  const s = String(body);
  try {
    const o = JSON.parse(s);
    if (o && typeof o.csrf === 'string' && o.csrf) return o.csrf;
  } catch (e) {}
  let m = s.match(/"csrf"\s*:\s*"([^"]+)"/);
  if (m) return m[1];
  const inputRe = /<input\b[^>]*>/gi;
  let tag;
  while ((tag = inputRe.exec(s)) !== null) {
    const t = tag[0];
    const name = getAttr(t, 'name');
    if (name && name.toLowerCase() === 'csrf') {
      const value = getAttr(t, 'value');
      if (value) return value;
    }
  }
  m = s.match(/(?:name|id)=["']?csrf["']?[^>]*?value=["']([^"']+)["']/i);
  if (m) return m[1];
  return '';
}

function buildCookieHeader(cookies) {
  return Object.keys(cookies).map(function (k) {
    return k + '=' + cookies[k];
  }).join('; ');
}

function applyCookies(cookies, res) {
  const sc = res.headers['Set-Cookie'] || res.headers['set-cookie'];
  if (!sc) return;
  const s = Array.isArray(sc) ? sc.join('\n') : String(sc);
  const re = /(?:^|[\n,]\s*)([^=;,\s]+)=([^;,\s]*)/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    const name = m[1];
    const value = m[2];
    if (['Path', 'Domain', 'Expires', 'Max-Age', 'Secure', 'HttpOnly', 'SameSite'].indexOf(name) !== -1) continue;
    if (value === '') delete cookies[name];
    else cookies[name] = value;
  }
}

function updateUserCookies(user, res) {
  if (!user.cookies) user.cookies = {};
  applyCookies(user.cookies, res);
  user.cookieHeader = buildCookieHeader(user.cookies);
}

function authHeaders(user) {
  const h = { 'Content-Type': 'application/json' };
  if (user.cookieHeader) h['Cookie'] = user.cookieHeader;
  if (user.csrf) h['X-CSRF-Token'] = user.csrf;
  return h;
}

function getErrorCode(body) {
  if (!body) return '';
  try {
    const o = JSON.parse(body);
    if (o && typeof o.error === 'string') return o.error;
  } catch (e) {}
  const m = String(body).match(/"error"\s*:\s*"([^"]+)"/);
  return m ? m[1] : '';
}

function parseRetryAfter(res) {
  const h = res.headers['Retry-After'] || res.headers['retry-after'];
  if (!h) return 1;
  const s = Array.isArray(h) ? h[0] : String(h);
  const n = parseFloat(s);
  if (!isNaN(n) && n >= 0) return n;
  return 1;
}

function loginUser(username) {
  const cookies = {};
  let cookieHeader = '';

  const formRes = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login_form' },
    timeout: '5s',
  });
  applyCookies(cookies, formRes);
  cookieHeader = buildCookieHeader(cookies);

  let csrf = extractCsrf(formRes.body);

  const headers = { 'Content-Type': 'application/json' };
  if (cookieHeader) headers['Cookie'] = cookieHeader;
  if (csrf) headers['X-CSRF-Token'] = csrf;

  const loginRes = http.post(BASE_URL + '/v2/login', JSON.stringify({
    username: username,
    password: 'bench',
    csrf: csrf,
  }), {
    headers: headers,
    redirects: 0,
    tags: { name: 'login_post' },
    timeout: '5s',
  });
  applyCookies(cookies, loginRes);
  cookieHeader = buildCookieHeader(cookies);

  let finalRes = loginRes;
  if (loginRes.status >= 300 && loginRes.status < 400) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const locHeaders = {};
      if (cookieHeader) locHeaders['Cookie'] = cookieHeader;
      finalRes = http.get(resolveUrl(loc), {
        headers: locHeaders,
        redirects: 0,
        tags: { name: 'login_location' },
        timeout: '5s',
      });
      applyCookies(cookies, finalRes);
      cookieHeader = buildCookieHeader(cookies);
    }
  }

  const sessionCsrf = extractCsrf(finalRes.body) || extractCsrf(loginRes.body) || csrf;

  return {
    username: username,
    password: 'bench',
    csrf: sessionCsrf,
    cookies: cookies,
    cookieHeader: cookieHeader,
  };
}

function renewSession(user) {
  const res = http.post(BASE_URL + '/v2/session/renew', '{}', {
    headers: authHeaders(user),
    redirects: 0,
    tags: { name: 'renew' },
    timeout: '5s',
  });
  updateUserCookies(user, res);
  const c = extractCsrf(res.body);
  if (c) user.csrf = c;
  return res.status >= 200 && res.status < 400 && !!user.csrf;
}

function doWork(user) {
  let recoveryCount = 0;
  let retry429 = 0;

  for (let i = 0; i < 8; i++) {
    const res = http.post(BASE_URL + '/v2/work', '{}', {
      headers: authHeaders(user),
      redirects: 0,
      tags: { name: 'v2_work' },
      timeout: '5s',
    });

    updateUserCookies(user, res);

    const body = res.body || '';
    const freshCsrf = extractCsrf(body);
    if (freshCsrf) user.csrf = freshCsrf;

    const status = res.status;
    let ok = false;
    try {
      ok = JSON.parse(body).ok === true;
    } catch (e) {}

    if (status < 400) {
      if (!ok) {
        businessFailure.add(true);
        return;
      }
      businessFailure.add(false);
      return;
    }

    const err = getErrorCode(body);

    if (status === 429) {
      businessFailure.add(false);
      if (retry429 >= 4) return;
      retry429++;
      sleep(parseRetryAfter(res) * 1000);
      continue;
    }

    if (status === 401 && err === 'expired') {
      if (recoveryCount >= 1) {
        businessFailure.add(true);
        return;
      }
      businessFailure.add(false);
      recoveryCount++;
      if (renewSession(user)) continue;
      const fresh = loginUser(user.username);
      if (fresh && fresh.csrf) {
        user.csrf = fresh.csrf;
        user.cookies = fresh.cookies;
        user.cookieHeader = fresh.cookieHeader;
        continue;
      }
      return;
    }

    if (status === 401 && err === 'session') {
      if (recoveryCount >= 1) {
        businessFailure.add(true);
        return;
      }
      recoveryCount++;
      if (renewSession(user)) {
        businessFailure.add(false);
        continue;
      }
      const fresh = loginUser(user.username);
      if (fresh && fresh.csrf) {
        user.csrf = fresh.csrf;
        user.cookies = fresh.cookies;
        user.cookieHeader = fresh.cookieHeader;
        businessFailure.add(false);
        continue;
      }
      businessFailure.add(true);
      return;
    }

    if (status === 401 && err === 'denied') {
      businessFailure.add(true);
      return;
    }

    businessFailure.add(true);
    return;
  }
}

export function setup() {
  const users = [];
  for (let i = 1; i <= 2; i++) {
    let u;
    for (let attempt = 0; attempt < 2; attempt++) {
      u = loginUser('bench-' + i);
      if (u.csrf) break;
    }
    users.push(u);
  }
  return { users: users };
}

export function work(data) {
  const users = data && data.users;
  if (!users || users.length === 0) return;
  const idx = ((__VU - 1) % users.length);
  const user = users[idx];
  if (!user.cookies) user.cookies = {};
  if (!user.cookieHeader) user.cookieHeader = buildCookieHeader(user.cookies);
  doWork(user);
}
