import os
import re
import json
import time
import math
import itertools
from urllib.parse import urljoin
import gevent
from locust import HttpUser, task, LoadTestShape

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
PASSWORD = "bench"

T0 = None
USER_COUNTER = itertools.count()
SHAPE_START = None


def extract_csrf(html):
    for tag in re.findall(r'<input\b[^>]*>', html, re.I | re.S):
        attrs = {}
        for m in re.finditer(r'([a-zA-Z0-9_:-]+)\s*(?:=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+)))?', tag):
            name = m.group(1).lower()
            if m.group(2) is not None:
                val = m.group(2)
            elif m.group(3) is not None:
                val = m.group(3)
            elif m.group(4) is not None:
                val = m.group(4)
            else:
                val = ""
            attrs[name] = val
        if attrs.get("name", "").lower() == "csrf":
            return attrs.get("value", "")
    return None


def extract_csrf_from_response(resp):
    try:
        data = resp.json()
        if isinstance(data, dict) and "csrf" in data:
            return data["csrf"]
    except Exception:
        pass
    try:
        return extract_csrf(resp.text)
    except Exception:
        return None


def compute_slot(user_index, now):
    global T0
    if T0 is None:
        return None
    e = now - T0
    if e >= 35.0:
        return None
    if e < 15.0:
        phase_start = 0.0
        R = 5.0
        phase_end = 15.0
    elif e < 25.0:
        phase_start = 15.0
        R = 15.0
        phase_end = 25.0
    elif e < 35.0:
        phase_start = 25.0
        R = 5.0
        phase_end = 35.0
    else:
        return None
    if e < phase_start:
        k = 0
    else:
        val = ((e - phase_start) * R - user_index) / 2.0
        k = max(0, math.ceil(val))
    slot_rel = phase_start + (user_index + 2 * k) / R
    if slot_rel >= phase_end:
        return T0 + phase_end
    return T0 + slot_rel


class WorkUser(HttpUser):
    host = BASE_URL

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.global_id = next(USER_COUNTER)
        self.username = f"bench-{(self.global_id % 16) + 1}"
        self.slot_index = self.global_id % 2
        self.csrf = None
        self.logged_in = False
        self.has_sent_work = False

    def on_start(self):
        self.login()

    def login(self):
        self.logged_in = False
        with self.client.get("/v2/login-form", allow_redirects=False, catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"login form status {resp.status_code}")
                return
            csrf = extract_csrf(resp.text)
            if not csrf:
                resp.failure("csrf not found in login form")
                return
            self.csrf = csrf
            resp.success()
        payload = {"username": self.username, "password": PASSWORD, "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, allow_redirects=False, catch_response=True) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                resp.success()
                if loc:
                    url = urljoin(self.host, loc)
                    with self.client.get(url, allow_redirects=False, catch_response=True) as loc_resp:
                        if loc_resp.status_code >= 400:
                            loc_resp.failure(f"login redirect status {loc_resp.status_code}")
                            return
                        new_csrf = extract_csrf_from_response(loc_resp)
                        if new_csrf:
                            self.csrf = new_csrf
                        loc_resp.success()
            elif resp.status_code == 200:
                new_csrf = extract_csrf_from_response(resp)
                if new_csrf:
                    self.csrf = new_csrf
                resp.success()
            else:
                resp.failure(f"login status {resp.status_code}")
                return
        self.logged_in = True

    def renew(self):
        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post("/v2/session/renew", json={}, headers=headers, allow_redirects=False, catch_response=True) as resp:
            if resp.status_code >= 400:
                resp.failure(f"renew status {resp.status_code}")
                return False
            new_csrf = extract_csrf_from_response(resp)
            if new_csrf:
                self.csrf = new_csrf
            resp.success()
            return True

    def send_work(self):
        if not self.logged_in or not self.csrf:
            self.login()
            if not self.logged_in or not self.csrf:
                return False
        headers = {"X-CSRF-Token": self.csrf}
        expired_retried = False
        session_retried = False
        for attempt in range(5):
            req_start = time.monotonic()
            with self.client.post("/v2/work", json={}, headers=headers, allow_redirects=False, catch_response=True) as resp:
                status = resp.status_code
                if status == 429:
                    retry_after = resp.headers.get("Retry-After", "1")
                    try:
                        delay = float(retry_after)
                    except Exception:
                        delay = 1.0
                    resp.success()
                    if attempt < 4:
                        gevent.sleep(delay)
                        continue
                    else:
                        return False
                if status == 401:
                    err = None
                    try:
                        data = resp.json()
                        err = data.get("error")
                    except Exception:
                        pass
                    if err == "expired":
                        resp.success()
                        if expired_retried:
                            resp.failure("expired retry exhausted")
                            return False
                        expired_retried = True
                        if self.renew():
                            headers["X-CSRF-Token"] = self.csrf
                            continue
                        else:
                            self.logged_in = False
                            self.login()
                            if self.logged_in:
                                headers["X-CSRF-Token"] = self.csrf
                                continue
                            else:
                                resp.failure("renew and relogin failed")
                                return False
                    elif err == "session":
                        resp.failure("401 session revoked")
                        if session_retried:
                            return False
                        session_retried = True
                        self.logged_in = False
                        self.login()
                        if self.logged_in:
                            headers["X-CSRF-Token"] = self.csrf
                            continue
                        else:
                            return False
                    elif err == "denied":
                        resp.failure("401 denied")
                        return False
                    else:
                        resp.failure(f"401 error={err}")
                        return False
                if status >= 400:
                    resp.failure(f"work status {status}")
                    return False
                try:
                    data = resp.json()
                except Exception:
                    resp.failure("work response not json")
                    return False
                if not isinstance(data, dict) or not data.get("ok"):
                    resp.failure("work ok false")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                global T0
                if T0 is None:
                    T0 = req_start
                resp.success()
                return True
        return False

    def wait_time(self):
        if not self.has_sent_work:
            if T0 is None:
                return 0.1
            now = time.monotonic()
            slot = compute_slot(self.slot_index, now)
            if slot is None:
                return 60.0
            return max(0.0, slot - now)
        else:
            now = time.monotonic()
            slot = compute_slot(self.slot_index, now)
            if slot is None:
                return 60.0
            return max(0.0, slot - now)

    @task
    def do_work(self):
        if not self.has_sent_work:
            if self.slot_index == 0:
                if T0 is None:
                    if self.send_work():
                        self.has_sent_work = True
                    return
                else:
                    now = time.monotonic()
                    slot = compute_slot(self.slot_index, now)
                    if slot is not None and now >= slot - 0.001:
                        if self.send_work():
                            self.has_sent_work = True
                    return
            else:
                if T0 is None:
                    return
                now = time.monotonic()
                slot = compute_slot(self.slot_index, now)
                if slot is not None and now >= slot - 0.001:
                    if self.send_work():
                        self.has_sent_work = True
                return
        else:
            now = time.monotonic()
            slot = compute_slot(self.slot_index, now)
            if slot is None:
                return
            if now < slot - 0.001:
                return
            self.send_work()


class WorkloadShape(LoadTestShape):
    def tick(self):
        global SHAPE_START
        if SHAPE_START is None:
            SHAPE_START = time.monotonic()
        now = time.monotonic()
        if T0 is not None:
            if now - T0 >= 40.0:
                return None
        else:
            if now - SHAPE_START >= 20.0:
                return None
        return (2, 100)
