import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .acceptHeader("application/json, text/html, */*")
        .disableFollowRedirect()
        .userAgentHeader("Gatling/ModelSimulation");

    private static ChainBuilder login() {
        return exec(
            http("login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name=csrf]", "value").saveAs("csrf"))
        )
        .exec(
            http("login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{csrf}\"}")).asJson()
                .check(status().in(200, 201, 302))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        )
        .doIf(session -> session.contains("loginLocation")
                && session.getString("loginLocation") != null
                && !session.getString("loginLocation").isEmpty())
        .then(
            exec(
                http("login-redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200))
                    .check(css("input[name=csrf]", "value").optional().saveAs("csrfHtml"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrfJson"))
            )
            .exec(session -> {
                String c = session.contains("csrfJson") ? session.getString("csrfJson") : null;
                if (c == null || c.isEmpty()) {
                    c = session.contains("csrfHtml") ? session.getString("csrfHtml") : null;
                }
                if (c != null && !c.isEmpty()) {
                    return session.set("csrf", c);
                }
                return session;
            })
        );
    }

    private static Iterator<Map<String, Object>> accountFeeder() {
        AtomicInteger counter = new AtomicInteger(0);
        return new Iterator<Map<String, Object>>() {
            @Override
            public boolean hasNext() {
                return true;
            }

            @Override
            public Map<String, Object> next() {
                int n = counter.getAndIncrement() % 17;
                String username = (n == 16) ? "bench" : "bench-" + (n + 1);
                Map<String, Object> m = new HashMap<>();
                m.put("username", username);
                m.put("password", "bench");
                return m;
            }
        };
    }

    private static final Iterator<Map<String, Object>> FEEDER = accountFeeder();

    ScenarioBuilder scn = scenario("ModelSimulation")
        .feed(FEEDER)
        .exec(login())
        .exec(session -> session.set("workRetry", 0).set("workDone", 0))
        .asLongAs(session -> session.getInt("workDone") == 0 && session.getInt("workRetry") < 5)
        .on(
            exec(
                http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("Content-Type", "application/json")
                    .body(StringBody("{}")).asJson()
                    .check(status().saveAs("workStatus"))
                    .check(jsonPath("$.ok").optional().saveAs("workOk"))
                    .check(jsonPath("$.error").optional().saveAs("workError"))
                    .check(jsonPath("$.csrf").optional().saveAs("workCsrf"))
            )
            .exec(session -> {
                String newCsrf = session.contains("workCsrf") ? session.getString("workCsrf") : null;
                if (newCsrf != null && !newCsrf.isEmpty()) {
                    return session.set("csrf", newCsrf);
                }
                return session;
            })
            .doIf(session -> session.getInt("workStatus") == 200)
            .then(
                exec(session -> {
                    Object okObj = session.contains("workOk") ? session.get("workOk") : null;
                    String ok = okObj == null ? null : okObj.toString();
                    if (!"true".equals(ok)) {
                        throw new RuntimeException("work success missing ok=true");
                    }
                    return session.set("workDone", 1);
                })
            )
            .doIf(session -> session.getInt("workStatus") == 429)
            .then(
                pause(1)
                    .exec(session -> session.set("workRetry", session.getInt("workRetry") + 1))
            )
            .doIf(session -> session.getInt("workStatus") == 401)
            .then(
                exec(
                    http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{}")).asJson()
                        .check(status().saveAs("renewStatus"))
                        .check(jsonPath("$.csrf").optional().saveAs("renewCsrf"))
                )
                .exec(session -> {
                    String c = session.contains("renewCsrf") ? session.getString("renewCsrf") : null;
                    if (c != null && !c.isEmpty()) {
                        return session.set("csrf", c);
                    }
                    return session;
                })
                .doIf(session -> session.getInt("renewStatus") == 401)
                .then(
                    exec(login())
                )
                .exec(session -> session.set("workRetry", session.getInt("workRetry") + 1))
            )
            .doIf(session -> {
                int s = session.getInt("workStatus");
                return s >= 400 && s != 401 && s != 429;
            })
