import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const lname = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === lname) return res.headers[k];
  }
  return null;
}

function parseJson(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function extractInputValue(html, name) {
  if (!html) return null;
  const inputs = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of inputs) {
    const nameMatch = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameMatch) continue;
    const actualName = nameMatch[1] || nameMatch[2] || nameMatch[3];
    if (actualName !== name) continue;
    const valueMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (valueMatch) {
      return valueMatch[1] || valueMatch[2] || valueMatch[3];
    }
  }
  const esc = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re1 = new RegExp('name\\s*=\\s*["\\\']?' + esc + '["\\\']?[^>]*?value\\s*=\\s*["\\\']([^"\\\']*)["\\\']', 'i');
  let m = html.match(re1);
  if (m) return m[1];
  const re2 = new RegExp('value\\s*=\\s*["\\\']([^"\\\']*)["\\\'][^>]*?name\\s*=\\s*["\\\']?' + esc + '["\\\']?', 'i');
  m = html.match(re2);
  if (m) return m[1];
  return null;
}

function clearJar() {
  try {
    http.cookieJar().clear(BASE);
  } catch (e) {}
}

function collectCookies() {
  const out = [];
  try {
    const jar = http.cookieJar();
    const cookies = jar.cookiesForURL(BASE);
    for (const name in cookies) {
      for (const c of cookies[name]) {
        out.push({ name: c.name, value: c.value });
      }
    }
  } catch (e) {}
  return out;
}

function setCookies(cookies) {
  const jar = http.cookieJar();
  for (const c of cookies) {
    try {
      jar.set(BASE, c.name, c.value, { path: '/' });
    } catch (e) {
      try {
        jar.set(BASE, c.name, c.value);
      } catch (e2) {}
    }
  }
}

function getError(res) {
  const obj = parseJson(res.body);
  if (obj && obj.error) return String(obj.error);
  return null;
}

function loginUser(username) {
  clearJar();

  const formRes = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login_form' },
  });

  const csrf = extractInputValue(formRes.body, 'csrf');
  if (!csrf) throw new Error('login csrf missing');

  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username, password: PASSWORD, csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );

  let body = loginRes.body;
  const location = getHeader(loginRes, 'Location');
  if (loginRes.status === 302 && location) {
    let loc = location;
    if (loc.startsWith('/')) loc = BASE + loc;
    else if (!/^https?:\/\//.test(loc)) loc = BASE + '/' + loc;
    const follow = http.get(loc, {
      redirects: 0,
      tags: { name: 'login_redirect' },
    });
    body = follow.body;
  }

  let token = null;
  const obj = parseJson(body);
  if (obj && obj.csrf) token = obj.csrf;
  if (!token) {
    const obj2 = parseJson(loginRes.body);
    if (obj2 && obj2.csrf) token = obj2.csrf;
  }
  if (!token) token = extractInputValue(body, 'csrf');
  if (!token) throw new Error('login csrf response missing');

  return {
    username,
    csrf: token,
    cookies: collectCookies(),
  };
}

export function setup() {
  const sessions = [];
  sessions.push(loginUser('bench-1'));
  sessions.push(loginUser('bench-2'));
  return { sessions };
}

let vuState = null;

function ensureState(data) {
  if (!vuState) {
    const session = data.sessions[(__VU - 1) % data.sessions.length];
    setCookies(session.cookies);
    vuState = {
      username: session.username,
      csrf: session.csrf,
    };
  }
}

function renew() {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': vuState.csrf,
    },
    redirects: 0,
    tags: { name: 'renew' },
  });

  if (res.status === 200) {
    const obj = parseJson(res.body);
    if (obj && obj.csrf) vuState.csrf = obj.csrf;
    return true;
  }
  return false;
}

function relogin() {
  try {
    const s = loginUser(vuState.username);
    setCookies(s.cookies);
    vuState.csrf = s.csrf;
    return true;
  } catch (e) {
    return false;
  }
}

function recover401(res) {
  const err = getError(res);
  if (err === 'expired') {
    return renew() || relogin();
  }
  if (err === 'session') {
    return relogin();
  }
  return false;
}

function doWork() {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': vuState.csrf,
  };

  let res = http.post(BASE + '/v2/work', '{}', {
    headers,
    redirects: 0,
    tags: { name: 'work' },
  });

  if (res.status === 401) {
    if (recover401(res)) {
      headers['X-CSRF-Token'] = vuState.csrf;
      res = http.post(BASE + '/v2/work', '{}', {
        headers,
        redirects: 0,
        tags: { name: 'work' },
      });
    }
  }

  let retries = 0;
  while (res.status === 429 && retries < 4) {
    let wait = 1;
    const ra = getHeader(res, 'Retry-After');
    if (ra) {
      const n = parseInt(ra, 10);
      if (isFinite(n) && n > 0) wait = n;
    }
    sleep(wait);

    headers['X-CSRF-Token'] = vuState.csrf;
    res = http.post(BASE + '/v2/work', '{}', {
      headers,
      redirects: 0,
      tags: { name: 'work' },
    });

    if (res.status === 401) {
      if (recover401(res)) {
        headers['X-CSRF-Token'] = vuState.csrf;
        res = http.post(BASE + '/v2/work', '{}', {
          headers,
          redirects: 0,
          tags: { name: 'work' },
        });
      }
    }

    retries++;
  }

  const obj = parseJson(res.body);
  const success = res.status === 200 && obj && obj.ok === true;

  check(res, {
    'work success': () => success,
    'work no unexpected 500': (r) => r.status !== 500,
  });

  return res;
}

export function work(data) {
  ensureState(data);
  doWork();
}

export default function (data) {
