import os
import re
import time
from html.parser import HTMLParser

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
_LAUNCH = time.time()
_T0 = None
_NEXT_START = None
_SCHED_LOCK = Semaphore(1)
_ACCOUNT_LOCK = Semaphore(1)
_ACCOUNT_NEXT = 0
_MAX_LOOKAHEAD = 0.25


class _InputParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            d = {}
            for k, v in attrs:
                d[k.lower()] = v
            self.inputs.append(d)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def _extract_csrf(html):
    if not html:
        return None
    parser = _InputParser()
    try:
        parser.feed(html)
    except Exception:
        pass
    for attrs in parser.inputs:
        name = attrs.get("name")
        if isinstance(name, str) and name.lower() == "csrf":
            val = attrs.get("value")
            if val is not None and val != "":
                return val
    patterns = [
        r'<input\b[^>]*\bname\s*=\s*["\']?csrf["\']?[^>]*\bvalue\s*=\s*["\']([^"\']+)["\']',
        r'<input\b[^>]*\bvalue\s*=\s*["\']([^"\']+)["\'][^>]*\bname\s*=\s*["\']?csrf["\']?',
    ]
    for pat in patterns:
        m = re.search(pat, html, re.I | re.S)
        if m:
            return m.group(1)
    return None


def _safe_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _next_account():
    global _ACCOUNT_NEXT
    with _ACCOUNT_LOCK:
        n = _ACCOUNT_NEXT
        _ACCOUNT_NEXT += 1
    if n < 16:
        return "bench-{}".format(n + 1)
    return "bench"


def _current_target():
    t0 = _T0
    if t0 is None:
        return 5.0
    elapsed = time.time() - t0
    if elapsed < 15.0:
        return 5.0
    if elapsed < 25.0:
        return 15.0
    if elapsed < 35.0:
        return 5.0
    return 0.0


def _record_success_start(start_ts):
    global _T0
    with _SCHED_LOCK:
        if _T0 is None or start_ts < _T0:
            _T0 = start_ts


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        self.account = _next_account()
        self.password = "bench"
        self.csrf = None
        self.authenticated = False

    def _ensure_auth(self, force=False):
        if force:
            self.authenticated = False
        if not force and self.authenticated and self.csrf:
            return True
        for _ in range(3):
            if self._login():
                return True
            sleep(0.5)
        return False

    def _login(self):
        form_csrf = None
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
            name="/v2/login-form",
        ) as r:
            if r.status_code != 200:
                r.failure("login form status {}".format(r.status_code))
                return False
            form_csrf = _extract_csrf(r.text)
            if not form_csrf:
                r.failure("csrf not found")
                return False
            r.success()

        self.csrf = form_csrf
        payload = {
            "username": self.account,
            "password": self.password,
            "csrf": form_csrf,
        }
        location = None
        login_status = None
        login_data = None

        with self.client.post(
            "/v2/login",
            json=payload,
            catch_response=True,
            allow_redirects=False,
            name="/v2/login",
        ) as r:
            login_status = r.status_code
            location = r.headers.get("Location")
            if login_status in (301, 302, 303, 307, 308):
                r.success()
            elif 200 <= login_status < 300:
                login_data = _safe_json(r)
                if isinstance(login_data, dict) and login_data.get("csrf"):
                    self.csrf = login_data["csrf"]
                r.success()
            else:
                r.failure("login status {}".format(login_status))
                return False

        if login_status in (301, 302, 303, 307, 308):
            if not location:
                return False
            with self.client.get(
                location,
                catch_response=True,
                allow_redirects=False,
                name="/v2/login-location",
            ) as r:
                if not (200 <= r.status_code < 300):
                    r.failure("login location status {}".format(r.status_code))
                    return False
                data = _safe_json(r)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                else:
                    html_csrf = _extract_csrf(r.text)
                    if html_csrf:
                        self.csrf = html_csrf
                r.success()
        elif isinstance(login_data, dict) and login_data.get("csrf"):
            self.csrf = login_data["csrf"]

        if not self.csrf:
            return False
        self.authenticated = True
        return True

    def _renew(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
            name="/v2/session/renew",
        ) as r:
            if 200 <= r.status_code < 300:
                data = _safe_json(r)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()
                return True
            if r.status_code == 401:
                r.success()
                return False
            r.failure("renew status {}".format(r.status_code))
            return False

    def _work_once(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/work",
            json={},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
            name="/v2/work",
        ) as r:
            status = r.status_code
            data = _safe_json(r)

            if status == 429:
                wait = 1.0
                ra = r.headers.get("Retry-After")
                if ra:
                    try:
                        wait = float(ra)
                    except Exception:
                        wait = 1.0
                r.success()
                return ("429", wait)

            if status == 401:
                err = data.get("error") if isinstance(data, dict) else None
                if err == "expired":
                    r.success()
                    return ("expired", 0.0)
                if err == "session":
                    r.success()
                    return ("session", 0.0)
                if err == "denied":
                    r.failure("401 denied")
                    return ("denied", 0.0)
                r.failure("401 unknown")
                return ("fail", 0.0)

            if 200 <= status < 300:
                if not isinstance(data, dict) or data.get("ok") is not True:
                    r.failure("work missing ok")
                    return ("fail", 0.0)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()
                return ("ok", 0.0)

            r.failure("work status {}".format(status))
            return ("fail", 0.0)

    def _wait_for_slot(self):
        global _NEXT_START
        while True:
            target = _current_target()
            if target <= 0:
                return False
            with _SCHED_LOCK:
                now = time.time()
                if _NEXT_START is None or _NEXT_START < now:
                    _NEXT_START = now
                start = _NEXT_START
                if start <= now + _MAX_LOOKAHEAD:
                    _NEXT_START = start + (1.0 / target)
                    reserved = True
                else:
                    reserved = False
            if not reserved:
                sleep(min(0.05, max(0.001, start - now)))
                continue
            delay = start - time.time()
            if delay > 0:
                sleep(delay)
            if _current_target() <= 0:
                return False
            return True

    def _do_work(self):
        t0 = _T0
        now = time.time()
        if t0 is None:
            if now - _LAUNCH > 15.0:
                return False
        elif now >= t0 + 35.0:
            return False

        recovery_attempts = 0
        retries_429 = 0
        while True:
            t0 = _T0
            now = time.time()
            if t0 is None:
                if now - _LAUNCH > 15.0:
                    return False
            elif now >= t0 + 35.0:
                return False

            if not self._wait_for_slot():
                return False

            start_ts = time.time()
            kind, wait = self._work_once()

            if kind == "ok":
                _record_success_start(start_ts)
                return True
            if kind == "429":
                if retries_429 >= 4:
                    return False
                retries_429 += 1
                sleep(wait if wait and wait > 0 else 1.0)
                continue
            if kind == "expired":
                if recovery_attempts >= 1:
                    return False
                recovery_attempts += 1
                if not self._renew():
                    if not self._ensure_auth(force=True):
                        return False
                continue
            if kind == "session":
                if recovery_attempts >= 1:
                    return False
                recovery_attempts += 1
                if not self._ensure_auth(force=True):
                    return False
                continue
            return False

    @task
    def work_loop(self):
        while True:
            t0 = _T0
            now = time.time()
            if t0 is None:
                if now - _LAUNCH > 15.0:
                    raise StopUser()
            else:
                if now >= t0 + 37.0:
                    raise StopUser()
                if now >= t0 + 35.0:
                    sleep(max(0.0, min(2.0, t0 + 36.0 - now)))
                    raise StopUser()

            if not self.authenticated or not self.csrf:
                if not self._ensure_auth():
                    sleep(0.5)
                    continue

            self._do_work()


class ContractShape(LoadTestShape):
    def tick(self):
        now = time.time()
        t0 = _T0
        if t0 is None:
            if now - _LAUNCH > 15.0:
                return None
            return (16, 16)
        elapsed = now - t0
        if elapsed < 37.0:
            return (16, 16)
        return None

