import os
import re
import time
from html.parser import HTMLParser

from gevent import sleep as gsleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_HOST = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class _CSRFInputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.all_csrf = []
        self.login_csrf = []
        self.current_form_action = None

    def handle_starttag(self, tag, attrs):
        d = {}
        for k, v in attrs:
            d[k.lower()] = v if v is not None else ""

        if tag.lower() == "form":
            self.current_form_action = (d.get("action") or "").lower()
        elif tag.lower() == "input":
            name = (d.get("name") or "").strip().lower()
            if name == "csrf":
                value = d.get("value")
                if value:
                    self.all_csrf.append(value)
                    if "login" in (self.current_form_action or ""):
                        self.login_csrf.append(value)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form_action = None


def _extract_csrf(text):
    if not text:
        return None

    parser = _CSRFInputParser()
    try:
        parser.feed(text)
    except Exception:
        pass

    if parser.login_csrf:
        return parser.login_csrf[0]
    if parser.all_csrf:
        return parser.all_csrf[0]

    for form_match in re.finditer(
        r'<form\b[^>]*action\s*=\s*["\']?[^"\'>]*login[^>]*>(.*?)</form>',
        text,
        re.I | re.S,
    ):
        body = form_match.group(1)
        for input_match in re.finditer(r'<input\b[^>]*>', body, re.I | re.S):
            tag = input_match.group(0)
            if re.search(r'name\s*=\s*["\']?csrf["\']?', tag, re.I):
                vm = re.search(r'value\s*=\s*(["\'])(.*?)\1', tag, re.I | re.S)
                if not vm:
                    vm = re.search(r'value\s*=\s*([^\s>]+)', tag, re.I)
                if vm:
                    return vm.group(2) if len(vm.groups()) >= 2 else vm.group(1)

    for input_match in re.finditer(r'<input\b[^>]*>', text, re.I | re.S):
        tag = input_match.group(0)
        if re.search(r'name\s*=\s*["\']?csrf["\']?', tag, re.I):
            vm = re.search(r'value\s*=\s*(["\'])(.*?)\1', tag, re.I | re.S)
            if not vm:
                vm = re.search(r'value\s*=\s*([^\s>]+)', tag, re.I)
            if vm:
                return vm.group(2) if len(vm.groups()) >= 2 else vm.group(1)

    return None


def _json(resp):
    try:
        return resp.json()
    except Exception:
        return None


_USER_COUNTER = 0
_USER_LOCK = Semaphore(1)
_PID_OFFSET = (os.getpid() * 7) % 16


def _next_username():
    global _USER_COUNTER
    with _USER_LOCK:
        _USER_COUNTER += 1
        idx = ((_USER_COUNTER + _PID_OFFSET - 1) % 16) + 1
    return "bench-%d" % idx


class _Pacer:
    def __init__(self):
        self.lock = Semaphore(1)
        self.t0 = None
        self.next_time = None
        self.last_phase = None
        self.raw_cap = 12.0

    def _target(self, rel):
        if rel < 0:
            return 0.0
        if rel < 15.0:
            return 5.0
        if rel < 25.0:
            return 15.0
        if rel < 35.0:
            return 5.0
        return 0.0

    def acquire(self):
        with self.lock:
            now = time.monotonic()

            if self.t0 is None:
                self.t0 = now
                self.next_time = now

            rel = now - self.t0
            target = self._target(rel)

            if target <= 0:
                return False

            if rel < 15.0:
                phase = 0
            elif rel < 25.0:
                phase = 1
            else:
                phase = 2

            if phase != self.last_phase:
                self.last_phase = phase
                if self.next_time < now:
                    self.next_time = now

            allowed = max(now, self.next_time)
            rate = min(target, self.raw_cap)
            interval = 1.0 / rate
            self.next_time = allowed + interval
            delay = allowed - now

        if delay > 0:
            gsleep(delay)

        return True


PACER = _Pacer()


class WorkUser(HttpUser):
    host = BASE_HOST
    wait_time = constant(0)

    def on_start(self):
        self.username = _next_username()
        self.csrf = None
        self.logged_in = False

    def login(self):
        for _ in range(5):
            csrf = None

            with self.client.get(
                "/v2/login-form",
                name="login-form",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in (301, 302, 303, 307, 308):
                    loc = resp.headers.get("Location")
                    if not loc:
                        resp.failure("login-form redirect missing Location")
                        gsleep(0.5)
                        continue

                    with self.client.get(
                        loc,
                        name="login-form-redirect",
                        allow_redirects=False,
                        catch_response=True,
                    ) as r2:
                        if r2.status_code >= 400:
                            r2.failure("login-form redirect status %s" % r2.status_code)
                            resp.success()
                            gsleep(0.5)
                            continue

                        data = _json(r2)
                        if isinstance(data, dict) and data.get("csrf"):
                            csrf = data["csrf"]
                        else:
                            csrf = _extract_csrf(r2.text) or _extract_csrf(resp.text)

                        r2.success()

                    resp.success()

                elif resp.status_code >= 400:
                    resp.failure("login-form status %s" % resp.status_code)
                    gsleep(0.5)
                    continue

                else:
                    data = _json(resp)
                    if isinstance(data, dict) and data.get("csrf"):
                        csrf = data["csrf"]
                    else:
                        csrf = _extract_csrf(resp.text)
                    resp.success()

            if not csrf:
                gsleep(0.2)
                continue

            payload = {
                "username": self.username,
                "password": "bench",
                "csrf": csrf,
            }

            with self.client.post(
                "/v2/login",
                json=payload,
                name="login",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in (301, 302, 303, 307, 308):
                    loc = resp.headers.get("Location")
                    if not loc:
                        resp.failure("login redirect missing Location")
                        gsleep(0.5)
                        continue

                    with self.client.get(
                        loc,
                        name="login-redirect",
                        allow_redirects=False,
                        catch_response=True,
                    ) as r2:
                        if r2.status_code >= 400:
                            r2.failure("login redirect status %s" % r2.status_code)
                            resp.success()
                            gsleep(0.5)
                            continue

                        data = _json(r2)
                        new_csrf = None
                        if isinstance(data, dict):
                            new_csrf = data.get("csrf")
                        if not new_csrf:
                            new_csrf = _extract_csrf(r2.text)

                        self.csrf = new_csrf or csrf
                        r2.success()

                    resp.success()

                elif resp.status_code >= 400:
                    resp.failure("login status %s" % resp.status_code)
                    gsleep(0.5)
                    continue

                else:
                    data = _json(resp)
                    new_csrf = None
                    if isinstance(data, dict):
                        new_csrf = data.get("csrf")
                    self.csrf = new_csrf or csrf
                    resp.success()

            if self.csrf:
                self.logged_in = True
                return True

            gsleep(0.2)

        return False

    def renew_session(self):
        if not self.csrf:
            return False

        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="renew",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = _json(resp)
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return True

            resp.success()
            return False

    def do_work(self):
        if not self.csrf:
            self.logged_in = False
            if not self.login():
                return False

        rate_retries = 0
        expiry_retries = 0

        while True:
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                name="/v2/work",
