                        delay = 1.0

                    resp.success()
                    rate_retries += 1
                    if rate_retries > 4:
                        return False

                    gsleep(max(0.0, delay))
                    if not PACER.acquire():
                        return False
                    continue

                elif code == 401:
                    data = _json(resp)
                    err = data.get("error") if isinstance(data, dict) else None

                    if err == "expired":
                        resp.success()
                        expiry_retries += 1
                        if expiry_retries > 1:
                            return False

                        if not self.renew_session():
                            self.logged_in = False
                            if not self.login():
                                return False

                        if not PACER.acquire():
                            return False
                        continue

                    elif err == "session":
                        resp.success()
                        expiry_retries += 1
                        if expiry_retries > 1:
                            return False

                        self.logged_in = False
                        self.renew_session()
                        if not self.login():
                            return False

                        if not PACER.acquire():
                            return False
                        continue

                    elif err == "denied":
                        resp.failure("401 denied")
                        return False

                    else:
                        resp.failure("401 %r" % err)
                        return False

                elif code >= 400:
                    resp.failure("work status %s" % code)
                    return False

                else:
                    resp.failure("work unexpected status %s" % code)
                    return False

    @task
    def run_workload(self):
        if not self.logged_in:
            while not self.login():
                gsleep(0.5)

        while True:
            if not PACER.acquire():
                if PACER.t0 is not None:
                    end = PACER.t0 + 40.0
                    while time.monotonic() < end:
                        gsleep(0.5)
                raise StopUser()

            self.do_work()


class PhasedShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.monotonic()

    def tick(self):
        now = time.monotonic()

        if PACER.t0 is not None:
            rel = now - PACER.t0
            if rel >= 40.0:
                return None
            return (8, 4)

        if now - self.start_time >= 12.0:
            return None

        return (8, 4)
